// Nuvemath — 8-sinf, I qism (Algebra 8, Sh.A. Alimov va boshq.) nazariyasi, t1–t10. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t1. Algebraik ifodalar. Kasrlarni qisqartirish ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Harflar bilan ishlaydigan kasrlar', 'Дроби, в которых есть буквы', 'Fractions that contain letters'), p: [
      L('7-sinfda biz birhad va ko‘phadlar bilan ishladik: ularni qo‘shdik, ko‘paytirdik, ko‘paytuvchilarga ajratdik. Endi navbat yangi turdagi ifodalarga keldi — <b>algebraik kasrlarga</b>. Masalan, <sup>3</sup>/<sub>x</sub>, <sup>a + b</sup>/<sub>a − b</sub>, <sup>x<sup>2</sup> − 4</sup>/<sub>x − 2</sub>. Ularda maxrajda harf, ya’ni o‘zgaruvchi qatnashadi.', 'В 7 классе мы работали с одночленами и многочленами: складывали, умножали, раскладывали на множители. Теперь очередь за новым видом выражений — <b>алгебраическими дробями</b>. Например, <sup>3</sup>/<sub>x</sub>, <sup>a + b</sup>/<sub>a − b</sub>, <sup>x<sup>2</sup> − 4</sup>/<sub>x − 2</sub>. В их знаменателе стоит буква, то есть переменная.', 'In grade 7 we worked with monomials and polynomials: we added them, multiplied them and factorised them. Now it is time for a new kind of expression — <b>algebraic fractions</b>, such as <sup>3</sup>/<sub>x</sub>, <sup>a + b</sup>/<sub>a − b</sub>, <sup>x<sup>2</sup> − 4</sup>/<sub>x − 2</sub>. Their denominator contains a letter, that is, a variable.'),
      L('Bunday kasrlar hayotda juda tez-tez uchraydi. Agar 120 km yo‘lni v km/soat tezlik bilan bossak, sarflangan vaqt <sup>120</sup>/<sub>v</sub> soat bo‘ladi. Agar 5 kg mevani n kishi teng bo‘lib olsa, har biriga <sup>5</sup>/<sub>n</sub> kg tegadi. Formulalar fizika, kimyo va iqtisodda ham aynan shunday ko‘rinishda yoziladi.', 'Такие дроби постоянно встречаются в жизни. Если проехать 120 км со скоростью v км/ч, то время в пути равно <sup>120</sup>/<sub>v</sub> ч. Если 5 кг фруктов поровну делят n человек, каждому достаётся <sup>5</sup>/<sub>n</sub> кг. Формулы физики, химии и экономики записываются именно так.', 'Such fractions appear all the time in real life. If you drive 120 km at v km/h, the travel time is <sup>120</sup>/<sub>v</sub> hours. If n people share 5 kg of fruit equally, each gets <sup>5</sup>/<sub>n</sub> kg. Formulas in physics, chemistry and economics are written in exactly this form.'),
      L('Bu mavzuda biz ikki muhim savolga javob beramiz. Birinchisi: o‘zgaruvchi qanday qiymatlarni qabul qilishi mumkin, ya’ni ifodaning <b>aniqlanish sohasi</b> qanday? Ikkinchisi: kasrni qanday qilib soddaroq ko‘rinishga keltirish, ya’ni <b>qisqartirish</b> mumkin? Bu ikki ko‘nikma keyingi barcha mavzular — kasrlarni qo‘shish, ko‘paytirish va tenglamalar yechish uchun asos bo‘ladi.', 'В этой теме мы ответим на два важных вопроса. Первый: какие значения может принимать переменная, то есть какова <b>область определения</b> выражения? Второй: как упростить дробь, то есть <b>сократить</b> её? Эти два навыка — основа всех следующих тем: сложения и умножения дробей, решения уравнений.', 'In this topic we answer two important questions. First: which values may the variable take, that is, what is the <b>domain</b> of the expression? Second: how can a fraction be made simpler, that is, how do we <b>cancel</b> it? These two skills are the basis of everything that follows — adding and multiplying fractions and solving equations.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), p: [
      L('Sonlar va harflardan qo‘shish, ayirish, ko‘paytirish, bo‘lish va darajaga ko‘tarish amallari yordamida tuzilgan yozuv <b>algebraik ifoda</b> deyiladi. Agar ifodada harfli ifodaga bo‘lish bo‘lmasa, u <b>butun ifoda</b> deyiladi: 3a<sup>2</sup> − 5b, (x + 1)(x − 2). Agar harfli ifodaga bo‘lish bo‘lsa, u <b>kasr ifoda</b> deyiladi: <sup>2</sup>/<sub>x</sub> + 1.', 'Запись, составленная из чисел и букв с помощью сложения, вычитания, умножения, деления и возведения в степень, называется <b>алгебраическим выражением</b>. Если в нём нет деления на выражение с буквами, оно называется <b>целым</b>: 3a<sup>2</sup> − 5b, (x + 1)(x − 2). Если такое деление есть — <b>дробным</b>: <sup>2</sup>/<sub>x</sub> + 1.', 'A record built from numbers and letters using addition, subtraction, multiplication, division and powers is called an <b>algebraic expression</b>. If it contains no division by an expression with letters, it is a <b>whole (integral) expression</b>: 3a<sup>2</sup> − 5b, (x + 1)(x − 2). If it does, it is a <b>fractional expression</b>: <sup>2</sup>/<sub>x</sub> + 1.'),
      L('<sup>P</sup>/<sub>Q</sub> ko‘rinishidagi ifoda, bunda P va Q — ko‘phadlar, <b>algebraik kasr</b> deyiladi. P — surat, Q — maxraj. O‘zgaruvchilarning ifoda ma’noga ega bo‘ladigan barcha qiymatlari <b>ruxsat etilgan qiymatlar</b> yoki ifodaning <b>aniqlanish sohasi</b> deyiladi. Nolga bo‘lish mumkin emas, shuning uchun algebraik kasr uchun yagona shart: <b>Q ≠ 0</b>.', 'Выражение вида <sup>P</sup>/<sub>Q</sub>, где P и Q — многочлены, называется <b>алгебраической дробью</b>; P — числитель, Q — знаменатель. Все значения переменных, при которых выражение имеет смысл, называются <b>допустимыми значениями</b>, или <b>областью определения</b>. На нуль делить нельзя, поэтому для алгебраической дроби единственное условие: <b>Q ≠ 0</b>.', 'An expression of the form <sup>P</sup>/<sub>Q</sub>, where P and Q are polynomials, is an <b>algebraic fraction</b>; P is the numerator and Q the denominator. All values of the variables for which the expression makes sense are its <b>permitted values</b>, or its <b>domain</b>. Division by zero is impossible, so the only condition for an algebraic fraction is <b>Q ≠ 0</b>.')
    ], list: [
      L('<sup>5</sup>/<sub>x − 3</sub>: x ≠ 3, chunki x = 3 da maxraj 0 ga aylanadi.', '<sup>5</sup>/<sub>x − 3</sub>: x ≠ 3, так как при x = 3 знаменатель обращается в 0.', '<sup>5</sup>/<sub>x − 3</sub>: x ≠ 3, because at x = 3 the denominator becomes 0.'),
      L('<sup>x</sup>/<sub>x<sup>2</sup> + 1</sub>: x istalgan son, chunki x<sup>2</sup> + 1 ≥ 1 hech qachon nol bo‘lmaydi.', '<sup>x</sup>/<sub>x<sup>2</sup> + 1</sub>: x — любое число, так как x<sup>2</sup> + 1 ≥ 1 никогда не равно нулю.', '<sup>x</sup>/<sub>x<sup>2</sup> + 1</sub>: x may be any number, since x<sup>2</sup> + 1 ≥ 1 is never zero.'),
      L('<sup>1</sup>/<sub>x(x + 4)</sub>: x ≠ 0 va x ≠ −4 (ko‘paytma nolga teng bo‘lishi uchun ko‘paytuvchilardan biri nol bo‘lishi kerak).', '<sup>1</sup>/<sub>x(x + 4)</sub>: x ≠ 0 и x ≠ −4 (произведение равно нулю, когда один из множителей равен нулю).', '<sup>1</sup>/<sub>x(x + 4)</sub>: x ≠ 0 and x ≠ −4 (a product is zero exactly when one of its factors is zero).')
    ] },
    { kind: 'history', h: L('Tarixdan: «al-jabr»dan harfli formulalargacha', 'Из истории: от «аль-джабр» к буквенным формулам', 'From history: from “al-jabr” to letter formulas'), p: [
      L('IX asrda Bag‘doddagi «Bayt ul-hikma»da ishlagan vatandoshimiz <b>Muhammad ibn Muso al-Xorazmiy</b> tenglamalarni yechish haqida kitob yozdi. Uning nomidagi «al-jabr» so‘zi keyinchalik butun fanga — <b>algebra</b>ga nom bo‘ldi. Ammo Xorazmiy davrida harfli belgilar yo‘q edi: barcha masalalar so‘z bilan yozilardi, masalan, «mol» (noma’lumning kvadrati) va «jazr» (ildiz).', 'В IX веке наш земляк <b>Мухаммад ибн Муса аль-Хорезми</b>, работавший в багдадском «Доме мудрости», написал книгу о решении уравнений. Слово «аль-джабр» из её названия дало имя всей науке — <b>алгебре</b>. Но во времена Хорезми буквенных обозначений не было: задачи записывались словами, например «маль» (квадрат неизвестного) и «джизр» (корень).', 'In the 9th century <b>Muhammad ibn Musa al-Khwarizmi</b>, a scholar from Khorezm working at the House of Wisdom in Baghdad, wrote a book on solving equations. The word “al-jabr” in its title later gave its name to the whole science — <b>algebra</b>. But in his time there were no letter symbols: problems were written in words, such as “mal” (the square of the unknown) and “jidhr” (the root).'),
      L('Kasrlarni qisqartirish g‘oyasi esa juda qadimiy: Misr va Bobil hisobchilari, keyin esa Yevklid (miloddan avvalgi III asr) ikki sonning eng katta umumiy bo‘luvchisini topish usulini bilgan. Harflar bilan yozish XVI asr oxirida fransuz <b>Fransua Viyet</b> tufayli paydo bo‘ldi: u noma’lum va ma’lum kattaliklarni harflar bilan belgilashni taklif qildi. XVII asrda <b>Rene Dekart</b> bugungi odatni o‘rnatdi: alifbo boshidagi a, b, c — ma’lum, oxiridagi x, y, z — noma’lum kattaliklar.', 'Идея сокращения дробей очень древняя: египетские и вавилонские вычислители, а затем Евклид (III в. до н. э.) умели находить наибольший общий делитель двух чисел. Буквенная запись появилась в конце XVI века благодаря французу <b>Франсуа Виету</b>: он предложил обозначать буквами и неизвестные, и известные величины. В XVII веке <b>Рене Декарт</b> ввёл привычный обычай: первые буквы алфавита a, b, c — известные, последние x, y, z — неизвестные.', 'The idea of cancelling fractions is ancient: Egyptian and Babylonian calculators, and later Euclid (3rd century BC), knew how to find the greatest common divisor of two numbers. Writing with letters appeared at the end of the 16th century thanks to the Frenchman <b>François Viète</b>, who used letters for both unknown and known quantities. In the 17th century <b>René Descartes</b> set today’s habit: the first letters a, b, c for known quantities and the last letters x, y, z for unknowns.')
    ] },
    { kind: 'rule', h: L('Kasrning asosiy xossasi', 'Основное свойство дроби', 'The basic property of a fraction'), p: [
      L('Oddiy kasrlardan bilamizki, <sup>6</sup>/<sub>9</sub> = <sup>2</sup>/<sub>3</sub>: surat va maxrajni bir xil songa bo‘lsak, kasr qiymati o‘zgarmaydi. Algebraik kasrlar uchun ham xuddi shunday qoida bor: <b>agar kasrning surati va maxrajini nolga teng bo‘lmagan bir xil ifodaga ko‘paytirsak yoki bo‘lsak, kasrga teng kasr hosil bo‘ladi</b>:', 'Из обыкновенных дробей мы знаем, что <sup>6</sup>/<sub>9</sub> = <sup>2</sup>/<sub>3</sub>: если числитель и знаменатель разделить на одно и то же число, значение дроби не изменится. Для алгебраических дробей верно то же: <b>если числитель и знаменатель дроби умножить или разделить на одно и то же ненулевое выражение, получится дробь, равная данной</b>:', 'From ordinary fractions we know that <sup>6</sup>/<sub>9</sub> = <sup>2</sup>/<sub>3</sub>: dividing top and bottom by the same number leaves the value unchanged. The same holds for algebraic fractions: <b>if the numerator and denominator are multiplied or divided by the same non-zero expression, the result is a fraction equal to the given one</b>:'),
      L('<b><sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub>, bunda b ≠ 0, c ≠ 0.</b>', '<b><sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub>, где b ≠ 0, c ≠ 0.</b>', '<b><sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub>, where b ≠ 0, c ≠ 0.</b>'),
      L('<b>Nega bu to‘g‘ri?</b> <sup>a</sup>/<sub>b</sub> = q deb belgilaylik. Bu a = bq degani. Ikki tomonni c ga ko‘paytirsak, ac = (bc)q bo‘ladi, ya’ni <sup>ac</sup>/<sub>bc</sub> = q. Demak, ikkala kasr bir xil q songa teng. Surat va maxrajdagi umumiy ko‘paytuvchini tashlab yuborish <b>kasrni qisqartirish</b> deyiladi. Muhim: faqat <b>ko‘paytuvchi</b>ni qisqartirish mumkin, qo‘shiluvchini emas!', '<b>Почему это верно?</b> Обозначим <sup>a</sup>/<sub>b</sub> = q. Это значит a = bq. Умножив обе части на c, получим ac = (bc)q, то есть <sup>ac</sup>/<sub>bc</sub> = q. Значит, обе дроби равны одному и тому же числу q. Удаление общего множителя числителя и знаменателя называется <b>сокращением дроби</b>. Важно: сокращать можно только <b>множитель</b>, а не слагаемое!', '<b>Why is it true?</b> Let <sup>a</sup>/<sub>b</sub> = q. This means a = bq. Multiplying both sides by c gives ac = (bc)q, so <sup>ac</sup>/<sub>bc</sub> = q. Both fractions equal the same number q. Removing a common factor from the numerator and denominator is called <b>cancelling</b> (simplifying) the fraction. Important: you may cancel only a <b>factor</b>, never a term that is being added!')
    ] },
    { kind: 'steps', h: L('Kasrni qisqartirish algoritmi', 'Алгоритм сокращения дроби', 'How to cancel a fraction'), p: [
      L('Algebraik kasrni qisqartirishda quyidagi tartibga amal qiling:', 'Сокращая алгебраическую дробь, действуйте по порядку:', 'To cancel an algebraic fraction, follow these steps:')
    ], list: [
      L('<b>1. Aniqlanish sohasini yozing.</b> Maxrajni nolga tenglashtiring va taqiqlangan qiymatlarni toping. Bu qiymatlar qisqartirishdan keyin ham taqiqlangan bo‘lib qoladi.', '<b>1. Запишите область определения.</b> Приравняйте знаменатель к нулю и найдите запрещённые значения. Они остаются запрещёнными и после сокращения.', '<b>1. Write down the domain.</b> Set the denominator equal to zero and find the forbidden values. They stay forbidden after cancelling too.'),
      L('<b>2. Surat va maxrajni ko‘paytuvchilarga ajrating.</b> Umumiy ko‘paytuvchini qavsdan chiqaring, qisqa ko‘paytirish formulalarini (a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b), a<sup>2</sup> ± 2ab + b<sup>2</sup> = (a ± b)<sup>2</sup>) yoki guruhlash usulini qo‘llang.', '<b>2. Разложите числитель и знаменатель на множители.</b> Вынесите общий множитель, примените формулы сокращённого умножения (a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b), a<sup>2</sup> ± 2ab + b<sup>2</sup> = (a ± b)<sup>2</sup>) или группировку.', '<b>2. Factorise the numerator and the denominator.</b> Take out common factors, use the special products (a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b), a<sup>2</sup> ± 2ab + b<sup>2</sup> = (a ± b)<sup>2</sup>) or grouping.'),
      L('<b>3. Umumiy ko‘paytuvchilarni toping</b> va ularni surat ham, maxrajdan ham o‘chiring. Sonli koeffitsiyentlarni EKUB ga bo‘ling, harflarning darajalarini a<sup>m</sup> : a<sup>n</sup> = a<sup>m − n</sup> qoidasi bilan kamaytiring.', '<b>3. Найдите общие множители</b> и уберите их из числителя и знаменателя. Числовые коэффициенты делите на НОД, степени букв уменьшайте по правилу a<sup>m</sup> : a<sup>n</sup> = a<sup>m − n</sup>.', '<b>3. Find the common factors</b> and remove them from top and bottom. Divide the numerical coefficients by their GCD and reduce powers using a<sup>m</sup> : a<sup>n</sup> = a<sup>m − n</sup>.'),
      L('<b>4. Tekshiring.</b> Ruxsat etilgan biror qiymatni (masalan, x = 1) dastlabki va yakuniy ifodaga qo‘yib, natijalar tengligini tekshiring.', '<b>4. Проверьте.</b> Подставьте какое-нибудь допустимое значение (например, x = 1) в исходное и итоговое выражения и убедитесь, что результаты равны.', '<b>4. Check.</b> Substitute some permitted value (for example x = 1) into the original and the final expression and make sure the results agree.')
    ], after: [
      L('Agar surat va maxrajdagi qavslar faqat ishorasi bilan farq qilsa, masalan (a − b) va (b − a), ulardan birini −1 ga ko‘paytirib tenglashtiring: b − a = −(a − b).', 'Если скобки в числителе и знаменателе различаются только знаком, например (a − b) и (b − a), используйте b − a = −(a − b).', 'If the brackets on top and bottom differ only in sign, like (a − b) and (b − a), use b − a = −(a − b).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), p: [
      L('Har bir namunada avval aniqlanish sohasini, so‘ng ko‘paytuvchilarga ajratishni ko‘ring.', 'В каждом примере сначала смотрим область определения, затем раскладываем на множители.', 'In each example we first look at the domain and then factorise.')
    ], ex: [
      { q: L('Qisqartiring: <sup>12a<sup>3</sup>b<sup>2</sup></sup>/<sub>18a<sup>2</sup>b<sup>5</sup></sub>.', 'Сократите: <sup>12a<sup>3</sup>b<sup>2</sup></sup>/<sub>18a<sup>2</sup>b<sup>5</sup></sub>.', 'Simplify <sup>12a<sup>3</sup>b<sup>2</sup></sup>/<sub>18a<sup>2</sup>b<sup>5</sup></sub>.'),
        s: L('Shart: a ≠ 0, b ≠ 0. EKUB(12, 18) = 6. Umumiy ko‘paytuvchi 6a<sup>2</sup>b<sup>2</sup>. Suratda qoladi 2a, maxrajda 3b<sup>3</sup>. Javob: <sup>2a</sup>/<sub>3b<sup>3</sup></sub>.', 'Условие: a ≠ 0, b ≠ 0. НОД(12, 18) = 6. Общий множитель 6a<sup>2</sup>b<sup>2</sup>. В числителе остаётся 2a, в знаменателе 3b<sup>3</sup>. Ответ: <sup>2a</sup>/<sub>3b<sup>3</sup></sub>.', 'Condition: a ≠ 0, b ≠ 0. GCD(12, 18) = 6. The common factor is 6a<sup>2</sup>b<sup>2</sup>. What remains is 2a on top and 3b<sup>3</sup> below. Answer: <sup>2a</sup>/<sub>3b<sup>3</sup></sub>.') },
      { q: L('Qisqartiring: <sup>x<sup>2</sup> − 9</sup>/<sub>x<sup>2</sup> + 3x</sub>.', 'Сократите: <sup>x<sup>2</sup> − 9</sup>/<sub>x<sup>2</sup> + 3x</sub>.', 'Simplify <sup>x<sup>2</sup> − 9</sup>/<sub>x<sup>2</sup> + 3x</sub>.'),
        s: L('Maxraj x(x + 3), demak x ≠ 0, x ≠ −3. Surat: x<sup>2</sup> − 9 = (x − 3)(x + 3). Kasr = <sup>(x − 3)(x + 3)</sup>/<sub>x(x + 3)</sub> = <sup>x − 3</sup>/<sub>x</sub>. Tekshirish: x = 1 da dastlabki ifoda <sup>−8</sup>/<sub>4</sub> = −2, javob <sup>−2</sup>/<sub>1</sub> = −2. To‘g‘ri.', 'Знаменатель x(x + 3), значит x ≠ 0, x ≠ −3. Числитель: x<sup>2</sup> − 9 = (x − 3)(x + 3). Дробь = <sup>(x − 3)(x + 3)</sup>/<sub>x(x + 3)</sub> = <sup>x − 3</sup>/<sub>x</sub>. Проверка: при x = 1 исходное <sup>−8</sup>/<sub>4</sub> = −2, ответ <sup>−2</sup>/<sub>1</sub> = −2. Верно.', 'The denominator is x(x + 3), so x ≠ 0, x ≠ −3. Numerator: x<sup>2</sup> − 9 = (x − 3)(x + 3). The fraction is <sup>(x − 3)(x + 3)</sup>/<sub>x(x + 3)</sub> = <sup>x − 3</sup>/<sub>x</sub>. Check at x = 1: the original gives <sup>−8</sup>/<sub>4</sub> = −2, the answer gives −2. Correct.') },
      { q: L('Qisqartiring: <sup>a<sup>2</sup> − 10a + 25</sup>/<sub>15 − 3a</sub>.', 'Сократите: <sup>a<sup>2</sup> − 10a + 25</sup>/<sub>15 − 3a</sub>.', 'Simplify <sup>a<sup>2</sup> − 10a + 25</sup>/<sub>15 − 3a</sub>.'),
        s: L('Surat: (a − 5)<sup>2</sup>. Maxraj: 15 − 3a = 3(5 − a) = −3(a − 5); a ≠ 5. Kasr = <sup>(a − 5)<sup>2</sup></sup>/<sub>−3(a − 5)</sub> = −<sup>a − 5</sup>/<sub>3</sub> = <sup>5 − a</sup>/<sub>3</sub>.', 'Числитель: (a − 5)<sup>2</sup>. Знаменатель: 15 − 3a = 3(5 − a) = −3(a − 5); a ≠ 5. Дробь = <sup>(a − 5)<sup>2</sup></sup>/<sub>−3(a − 5)</sub> = −<sup>a − 5</sup>/<sub>3</sub> = <sup>5 − a</sup>/<sub>3</sub>.', 'Numerator: (a − 5)<sup>2</sup>. Denominator: 15 − 3a = 3(5 − a) = −3(a − 5); a ≠ 5. The fraction is <sup>(a − 5)<sup>2</sup></sup>/<sub>−3(a − 5)</sub> = −<sup>a − 5</sup>/<sub>3</sub> = <sup>5 − a</sup>/<sub>3</sub>.') },
      { q: L('Qisqartiring: <sup>ax − ay + 2x − 2y</sup>/<sub>x<sup>2</sup> − y<sup>2</sup></sub>.', 'Сократите: <sup>ax − ay + 2x − 2y</sup>/<sub>x<sup>2</sup> − y<sup>2</sup></sub>.', 'Simplify <sup>ax − ay + 2x − 2y</sup>/<sub>x<sup>2</sup> − y<sup>2</sup></sub>.'),
        s: L('Suratni guruhlaymiz: a(x − y) + 2(x − y) = (x − y)(a + 2). Maxraj: (x − y)(x + y), shart x ≠ ±y. Natija: <sup>a + 2</sup>/<sub>x + y</sub>.', 'Группируем числитель: a(x − y) + 2(x − y) = (x − y)(a + 2). Знаменатель: (x − y)(x + y), условие x ≠ ±y. Результат: <sup>a + 2</sup>/<sub>x + y</sub>.', 'Group the numerator: a(x − y) + 2(x − y) = (x − y)(a + 2). Denominator: (x − y)(x + y), with x ≠ ±y. Result: <sup>a + 2</sup>/<sub>x + y</sub>.') }
    ] },
    { kind: 'table', h: L('Ko‘paytuvchilarga ajratish uchun yordamchi jadval', 'Таблица-помощник для разложения', 'A factorising cheat sheet'), p: [
      L('Kasrni qisqartirish deyarli har doim ko‘paytuvchilarga ajratishga keladi. Quyidagi jadvalda eng ko‘p ishlatiladigan usullar to‘plangan.', 'Сокращение дроби почти всегда сводится к разложению на множители. В таблице собраны самые нужные приёмы.', 'Cancelling a fraction almost always comes down to factorising. The table collects the most useful methods.')
    ], table: { head: [L('Usul', 'Приём', 'Method'), L('Formula', 'Формула', 'Formula'), L('Misol', 'Пример', 'Example')], rows: [
      [L('Umumiy ko‘paytuvchi', 'Общий множитель', 'Common factor'), L('ab + ac = a(b + c)', 'ab + ac = a(b + c)', 'ab + ac = a(b + c)'), L('6x<sup>2</sup> − 9x = 3x(2x − 3)', '6x<sup>2</sup> − 9x = 3x(2x − 3)', '6x<sup>2</sup> − 9x = 3x(2x − 3)')],
      [L('Kvadratlar ayirmasi', 'Разность квадратов', 'Difference of squares'), L('a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b)', 'a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b)', 'a<sup>2</sup> − b<sup>2</sup> = (a − b)(a + b)'), L('y<sup>2</sup> − 16 = (y − 4)(y + 4)', 'y<sup>2</sup> − 16 = (y − 4)(y + 4)', 'y<sup>2</sup> − 16 = (y − 4)(y + 4)')],
      [L('To‘la kvadrat', 'Полный квадрат', 'Perfect square'), L('a<sup>2</sup> ± 2ab + b<sup>2</sup> = (a ± b)<sup>2</sup>', 'a<sup>2</sup> ± 2ab + b<sup>2</sup> = (a ± b)<sup>2</sup>', 'a<sup>2</sup> ± 2ab + b<sup>2</sup> = (a ± b)<sup>2</sup>'), L('x<sup>2</sup> + 6x + 9 = (x + 3)<sup>2</sup>', 'x<sup>2</sup> + 6x + 9 = (x + 3)<sup>2</sup>', 'x<sup>2</sup> + 6x + 9 = (x + 3)<sup>2</sup>')],
      [L('Kublar yig‘indisi/ayirmasi', 'Сумма/разность кубов', 'Sum/difference of cubes'), L('a<sup>3</sup> ± b<sup>3</sup> = (a ± b)(a<sup>2</sup> ∓ ab + b<sup>2</sup>)', 'a<sup>3</sup> ± b<sup>3</sup> = (a ± b)(a<sup>2</sup> ∓ ab + b<sup>2</sup>)', 'a<sup>3</sup> ± b<sup>3</sup> = (a ± b)(a<sup>2</sup> ∓ ab + b<sup>2</sup>)'), L('x<sup>3</sup> − 8 = (x − 2)(x<sup>2</sup> + 2x + 4)', 'x<sup>3</sup> − 8 = (x − 2)(x<sup>2</sup> + 2x + 4)', 'x<sup>3</sup> − 8 = (x − 2)(x<sup>2</sup> + 2x + 4)')],
      [L('Guruhlash', 'Группировка', 'Grouping'), L('ax + bx + ay + by = (a + b)(x + y)', 'ax + bx + ay + by = (a + b)(x + y)', 'ax + bx + ay + by = (a + b)(x + y)'), L('x<sup>3</sup> + x<sup>2</sup> + x + 1 = (x + 1)(x<sup>2</sup> + 1)', 'x<sup>3</sup> + x<sup>2</sup> + x + 1 = (x + 1)(x<sup>2</sup> + 1)', 'x<sup>3</sup> + x<sup>2</sup> + x + 1 = (x + 1)(x<sup>2</sup> + 1)')]
    ] }, after: [
      L('Maslahat: avval har doim umumiy ko‘paytuvchini qavsdan chiqaring, so‘ngra qavs ichidagi ifodaga formulalarni qo‘llang. Masalan, 2x<sup>2</sup> − 8 = 2(x<sup>2</sup> − 4) = 2(x − 2)(x + 2).', 'Совет: сначала всегда выносите общий множитель, потом применяйте формулы к выражению в скобках. Например, 2x<sup>2</sup> − 8 = 2(x<sup>2</sup> − 4) = 2(x − 2)(x + 2).', 'Tip: always take out the common factor first, then apply formulas to what is left in the brackets. For example, 2x<sup>2</sup> − 8 = 2(x<sup>2</sup> − 4) = 2(x − 2)(x + 2).')
    ] },
    { kind: 'example', h: L('Kasr qiymatini hisoblash', 'Вычисление значения дроби', 'Evaluating a fraction'), p: [
      L('Qisqartirish faqat chiroyli yozuv uchun emas — u hisoblashni ancha osonlashtiradi. Ba’zan esa dastlabki ifodaga qiymat qo‘yib bo‘lmaydi, lekin qisqartirilgan ifoda u qiymatda ma’noga ega bo‘ladi. Bu holda aniqlanish sohasini unutmaslik kerak.', 'Сокращение нужно не только для красоты — оно сильно облегчает вычисления. Иногда сокращённое выражение имеет смысл там, где исходное — нет. Поэтому область определения забывать нельзя.', 'Cancelling is not just for neatness — it makes calculations much easier. Sometimes the simplified expression makes sense at a value where the original does not, so the domain must not be forgotten.')
    ], ex: [
      { q: L('<sup>x<sup>2</sup> − 4x + 4</sup>/<sub>x<sup>2</sup> − 4</sub> ifodaning x = 98 dagi qiymatini toping.', 'Найдите значение <sup>x<sup>2</sup> − 4x + 4</sup>/<sub>x<sup>2</sup> − 4</sub> при x = 98.', 'Find the value of <sup>x<sup>2</sup> − 4x + 4</sup>/<sub>x<sup>2</sup> − 4</sub> at x = 98.'),
        s: L('<sup>(x − 2)<sup>2</sup></sup>/<sub>(x − 2)(x + 2)</sub> = <sup>x − 2</sup>/<sub>x + 2</sub>. x = 98 da: <sup>96</sup>/<sub>100</sub> = 0,96. Katta sonlarni kvadratga ko‘tarish shart bo‘lmadi!', '<sup>(x − 2)<sup>2</sup></sup>/<sub>(x − 2)(x + 2)</sub> = <sup>x − 2</sup>/<sub>x + 2</sub>. При x = 98: <sup>96</sup>/<sub>100</sub> = 0,96. Возводить большие числа в квадрат не пришлось!', '<sup>(x − 2)<sup>2</sup></sup>/<sub>(x − 2)(x + 2)</sub> = <sup>x − 2</sup>/<sub>x + 2</sub>. At x = 98: <sup>96</sup>/<sub>100</sub> = 0.96. No need to square big numbers!') },
      { q: L('<sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> ifoda x = 1 da nimaga teng?', 'Чему равно <sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> при x = 1?', 'What is <sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> at x = 1?'),
        s: L('Hech nimaga: x = 1 da maxraj nol, ifoda ma’noga ega emas. Qisqartirilgan x + 1 ifoda faqat x ≠ 1 da dastlabki kasrga teng. To‘g‘ri yozuv: <sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> = x + 1, x ≠ 1.', 'Ничему: при x = 1 знаменатель равен нулю, выражение не имеет смысла. Сокращённое x + 1 равно исходной дроби только при x ≠ 1. Правильная запись: <sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> = x + 1, x ≠ 1.', 'Nothing: at x = 1 the denominator is zero and the expression is meaningless. The simplified x + 1 equals the original only for x ≠ 1. The correct record is <sup>x<sup>2</sup> − 1</sup>/<sub>x − 1</sub> = x + 1, x ≠ 1.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), p: [
      L('Kasrlarni qisqartirishda o‘quvchilar ko‘pincha bir xil xatolarni takrorlaydi. Ularni oldindan bilib olsangiz, nazorat ishida ball yo‘qotmaysiz.', 'При сокращении дробей ученики часто повторяют одни и те же ошибки. Зная их заранее, вы не потеряете баллы на контрольной.', 'When cancelling fractions, students tend to repeat the same mistakes. Knowing them in advance will save you marks in a test.')
    ], list: [
      L('<b>Qo‘shiluvchini qisqartirish.</b> <sup>x + 5</sup>/<sub>x + 7</sub> ≠ <sup>5</sup>/<sub>7</sub>! x bu yerda ko‘paytuvchi emas. Tekshiring: x = 1 da <sup>6</sup>/<sub>8</sub> ≠ <sup>5</sup>/<sub>7</sub>.', '<b>Сокращение слагаемых.</b> <sup>x + 5</sup>/<sub>x + 7</sub> ≠ <sup>5</sup>/<sub>7</sub>! x здесь не множитель. Проверка: при x = 1 <sup>6</sup>/<sub>8</sub> ≠ <sup>5</sup>/<sub>7</sub>.', '<b>Cancelling terms.</b> <sup>x + 5</sup>/<sub>x + 7</sub> ≠ <sup>5</sup>/<sub>7</sub>! Here x is not a factor. Check: at x = 1, <sup>6</sup>/<sub>8</sub> ≠ <sup>5</sup>/<sub>7</sub>.'),
      L('<b>Qisqartirgandan keyin «1» ni yo‘qotish.</b> <sup>a</sup>/<sub>a(a + 1)</sub> = <sup>1</sup>/<sub>a + 1</sub>, «0» emas: surat butunlay qisqarsa, u yerda 1 qoladi.', '<b>Потеря «1» после сокращения.</b> <sup>a</sup>/<sub>a(a + 1)</sub> = <sup>1</sup>/<sub>a + 1</sub>, а не «0»: если числитель сократился целиком, там остаётся 1.', '<b>Losing the “1”.</b> <sup>a</sup>/<sub>a(a + 1)</sub> = <sup>1</sup>/<sub>a + 1</sub>, not “0”: when the whole numerator cancels, a 1 remains.'),
      L('<b>Ishorani unutish.</b> <sup>a − b</sup>/<sub>b − a</sub> = −1, 1 emas, chunki b − a = −(a − b).', '<b>Забытый знак.</b> <sup>a − b</sup>/<sub>b − a</sub> = −1, а не 1, ведь b − a = −(a − b).', '<b>Forgetting the sign.</b> <sup>a − b</sup>/<sub>b − a</sub> = −1, not 1, because b − a = −(a − b).'),
      L('<b>Aniqlanish sohasini yo‘qotish.</b> Qisqartirishdan oldin taqiqlangan qiymatlarni yozib qo‘ying; ular javobda ham saqlanadi.', '<b>Потеря области определения.</b> Запишите запрещённые значения до сокращения; они сохраняются и в ответе.', '<b>Losing the domain.</b> Write the forbidden values down before cancelling; they still apply to the answer.'),
      L('<b>Darajani noto‘g‘ri qisqartirish.</b> <sup>x<sup>6</sup></sup>/<sub>x<sup>2</sup></sub> = x<sup>4</sup>, x<sup>3</sup> emas: darajalar bo‘linmaydi, ayiriladi.', '<b>Неверное сокращение степеней.</b> <sup>x<sup>6</sup></sup>/<sub>x<sup>2</sup></sub> = x<sup>4</sup>, а не x<sup>3</sup>: показатели вычитаются, а не делятся.', '<b>Cancelling powers wrongly.</b> <sup>x<sup>6</sup></sup>/<sub>x<sup>2</sup></sub> = x<sup>4</sup>, not x<sup>3</sup>: exponents are subtracted, not divided.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda uchraydi?', 'Где это встречается в жизни?', 'Where is it used?'), p: [
      L('<b>Fizika.</b> O‘rtacha tezlik formulasi v = <sup>s</sup>/<sub>t</sub>, zichlik ρ = <sup>m</sup>/<sub>V</sub>, bosim p = <sup>F</sup>/<sub>S</sub> — barchasi algebraik kasrlar. Ularda maxraj nolga teng bo‘lolmaydi va bu fizik ma’noga ham ega: vaqt nol bo‘lsa, harakat bo‘lmaydi.', '<b>Физика.</b> Средняя скорость v = <sup>s</sup>/<sub>t</sub>, плотность ρ = <sup>m</sup>/<sub>V</sub>, давление p = <sup>F</sup>/<sub>S</sub> — всё это алгебраические дроби. Знаменатель не может быть нулём, и это имеет физический смысл: при нулевом времени движения нет.', '<b>Physics.</b> Average speed v = <sup>s</sup>/<sub>t</sub>, density ρ = <sup>m</sup>/<sub>V</sub>, pressure p = <sup>F</sup>/<sub>S</sub> are all algebraic fractions. The denominator cannot be zero, and that has a physical meaning: with zero time there is no motion.'),
      L('<b>Narxlar.</b> Do‘kon n ta daftarni jami S so‘mga sotsa, bitta daftar narxi <sup>S</sup>/<sub>n</sub>. Ulgurji xaridda 2n daftar 2S so‘m tursa, narx <sup>2S</sup>/<sub>2n</sub> = <sup>S</sup>/<sub>n</sub> — qisqartirish aynan shuni ko‘rsatadi: narx o‘zgarmagan.', '<b>Цены.</b> Если n тетрадей стоят S сумов, одна стоит <sup>S</sup>/<sub>n</sub>. Если 2n тетрадей стоят 2S, цена <sup>2S</sup>/<sub>2n</sub> = <sup>S</sup>/<sub>n</sub> — сокращение показывает, что цена не изменилась.', '<b>Prices.</b> If n notebooks cost S sum in total, one costs <sup>S</sup>/<sub>n</sub>. If 2n notebooks cost 2S, the price is <sup>2S</sup>/<sub>2n</sub> = <sup>S</sup>/<sub>n</sub> — cancelling shows the price has not changed.'),
      L('<b>Dasturlash.</b> Kompyuter dasturida nolga bo‘lish xatoga olib keladi. Shuning uchun dasturchilar formulani yozishdan oldin xuddi biz kabi «maxraj nol bo‘lishi mumkinmi?» degan savolni berishadi va alohida tekshiruv qo‘yishadi.', '<b>Программирование.</b> В программе деление на нуль вызывает ошибку. Поэтому программисты, как и мы, сначала спрашивают «может ли знаменатель быть нулём?» и ставят отдельную проверку.', '<b>Programming.</b> In a computer program, division by zero causes an error. So programmers, just like us, first ask “can the denominator be zero?” and add a separate check.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('«Kasr» so‘zi arabcha «kasr» — «sindirish» so‘zidan kelgan. Rus tilidagi «дробь» ham «дробить» — «maydalash» fe’lidan.', 'Слово «дробь» происходит от «дробить», а арабское «касрун» тоже означает «ломать».', 'The English word “fraction” comes from Latin “fractio” — “breaking”, and the Arabic “kasr” also means “to break”.'),
      L('Kasr chizig‘ini (suratni maxrajdan ajratuvchi gorizontal chiziqni) arab matematiklari, xususan XII asrda al-Hassar ishlatgan; Yevropaga uni Leonardo Fibonachchi olib kirgan.', 'Дробную черту использовали арабские математики, в частности аль-Хассар в XII веке; в Европу её принёс Леонардо Фибоначчи.', 'The fraction bar was used by Arab mathematicians such as al-Hassar in the 12th century; Leonardo Fibonacci brought it to Europe.'),
      L('«Kulgili qisqartirish»: <sup>16</sup>/<sub>64</sub> da 6 larni «o‘chirsak», <sup>1</sup>/<sub>4</sub> chiqadi va bu tasodifan to‘g‘ri! Ammo bu usul noto‘g‘ri — <sup>12</sup>/<sub>24</sub> da 2 ni o‘chirsak, <sup>1</sup>/<sub>4</sub> chiqadi, aslida esa <sup>1</sup>/<sub>2</sub>.', '«Смешное сокращение»: если в <sup>16</sup>/<sub>64</sub> «зачеркнуть» шестёрки, получится <sup>1</sup>/<sub>4</sub> — и это случайно верно! Но приём ошибочен: в <sup>12</sup>/<sub>24</sub> зачёркивание двоек даёт <sup>1</sup>/<sub>4</sub>, а на самом деле <sup>1</sup>/<sub>2</sub>.', '“Silly cancelling”: crossing out the 6s in <sup>16</sup>/<sub>64</sub> gives <sup>1</sup>/<sub>4</sub>, which happens to be right! But the trick is wrong: crossing out the 2s in <sup>12</sup>/<sub>24</sub> gives <sup>1</sup>/<sub>4</sub>, while the true value is <sup>1</sup>/<sub>2</sub>.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), p: [
      L('Avval o‘zingiz yeching, keyin javob bilan solishtiring.', 'Сначала решите сами, потом сравните с ответом.', 'Solve first, then compare with the answer.')
    ], ex: [
      { q: L('<sup>7</sup>/<sub>x<sup>2</sup> − 25</sub> qaysi x larda ma’noga ega emas?', 'При каких x не имеет смысла <sup>7</sup>/<sub>x<sup>2</sup> − 25</sub>?', 'For which x is <sup>7</sup>/<sub>x<sup>2</sup> − 25</sub> undefined?'), s: L('x = 5 va x = −5 da.', 'При x = 5 и x = −5.', 'At x = 5 and x = −5.') },
      { q: L('Qisqartiring: <sup>3m − 6</sup>/<sub>m<sup>2</sup> − 4</sub>.', 'Сократите: <sup>3m − 6</sup>/<sub>m<sup>2</sup> − 4</sub>.', 'Simplify <sup>3m − 6</sup>/<sub>m<sup>2</sup> − 4</sub>.'), s: L('<sup>3(m − 2)</sup>/<sub>(m − 2)(m + 2)</sub> = <sup>3</sup>/<sub>m + 2</sub>, m ≠ ±2.', '<sup>3(m − 2)</sup>/<sub>(m − 2)(m + 2)</sub> = <sup>3</sup>/<sub>m + 2</sub>, m ≠ ±2.', '<sup>3(m − 2)</sup>/<sub>(m − 2)(m + 2)</sub> = <sup>3</sup>/<sub>m + 2</sub>, m ≠ ±2.') },
      { q: L('Qisqartiring: <sup>y<sup>3</sup> + 1</sup>/<sub>y<sup>2</sup> − y + 1</sub>.', 'Сократите: <sup>y<sup>3</sup> + 1</sup>/<sub>y<sup>2</sup> − y + 1</sub>.', 'Simplify <sup>y<sup>3</sup> + 1</sup>/<sub>y<sup>2</sup> − y + 1</sub>.'), s: L('y<sup>3</sup> + 1 = (y + 1)(y<sup>2</sup> − y + 1), javob: y + 1. Maxraj hech qachon nol bo‘lmaydi, shuning uchun y — istalgan son.', 'y<sup>3</sup> + 1 = (y + 1)(y<sup>2</sup> − y + 1), ответ: y + 1. Знаменатель никогда не равен нулю, поэтому y — любое.', 'y<sup>3</sup> + 1 = (y + 1)(y<sup>2</sup> − y + 1), answer: y + 1. The denominator is never zero, so y can be anything.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Algebraik kasr — <sup>P</sup>/<sub>Q</sub>, bunda P, Q ko‘phadlar; shart Q ≠ 0.', 'Алгебраическая дробь — <sup>P</sup>/<sub>Q</sub>, где P, Q — многочлены; условие Q ≠ 0.', 'An algebraic fraction is <sup>P</sup>/<sub>Q</sub> with polynomials P, Q; condition Q ≠ 0.'),
      L('Aniqlanish sohasi — ifoda ma’noga ega bo‘ladigan barcha qiymatlar; uni har doim birinchi topamiz.', 'Область определения — все значения, при которых выражение имеет смысл; её находим первой.', 'The domain is the set of values where the expression makes sense; find it first.'),
      L('Asosiy xossa: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub> (c ≠ 0).', 'Основное свойство: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub> (c ≠ 0).', 'Basic property: <sup>ac</sup>/<sub>bc</sub> = <sup>a</sup>/<sub>b</sub> (c ≠ 0).'),
      L('Qisqartirish uchun surat va maxrajni ko‘paytuvchilarga ajratamiz va umumiy ko‘paytuvchilarni o‘chiramiz.', 'Для сокращения раскладываем числитель и знаменатель на множители и убираем общие.', 'To cancel, factorise top and bottom and remove the common factors.'),
      L('Faqat ko‘paytuvchilar qisqaradi, qo‘shiluvchilar hech qachon qisqarmaydi.', 'Сокращаются только множители, слагаемые — никогда.', 'Only factors cancel, never terms.'),
      L('b − a = −(a − b) ayniyati ishorani to‘g‘ri saqlashga yordam beradi.', 'Тождество b − a = −(a − b) помогает не потерять знак.', 'The identity b − a = −(a − b) helps keep the sign right.')
    ] }
  ] });

  // ---------- t2. Umumiy maxraj. Kasrlarni qo'shish va ayirish ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Turli bo‘laklarni birlashtirish', 'Как сложить разные доли', 'Putting different parts together'), p: [
      L('Tasavvur qiling: bir quvur hovuzni x soatda, ikkinchisi esa x + 2 soatda to‘ldiradi. Ikkalasi birga ishlasa, bir soatda hovuzning qancha qismi to‘ladi? Birinchi quvur soatiga <sup>1</sup>/<sub>x</sub> qismini, ikkinchisi <sup>1</sup>/<sub>x + 2</sub> qismini to‘ldiradi. Javob — bu ikki kasrning yig‘indisi. Uni bitta kasr ko‘rinishida yozish uchun <b>umumiy maxraj</b> kerak.', 'Представьте: одна труба наполняет бассейн за x часов, другая — за x + 2 часа. Какую часть бассейна они наполнят за час вместе? Первая — <sup>1</sup>/<sub>x</sub>, вторая — <sup>1</sup>/<sub>x + 2</sub>. Ответ — сумма этих дробей. Чтобы записать её одной дробью, нужен <b>общий знаменатель</b>.', 'Imagine one pipe fills a pool in x hours and another in x + 2 hours. What part of the pool do they fill together in one hour? The first fills <sup>1</sup>/<sub>x</sub>, the second <sup>1</sup>/<sub>x + 2</sub>. The answer is the sum of these fractions, and to write it as one fraction we need a <b>common denominator</b>.'),
      L('Oddiy kasrlarda siz bu ishni ko‘p marta qilgansiz: <sup>1</sup>/<sub>4</sub> + <sup>1</sup>/<sub>6</sub> = <sup>3</sup>/<sub>12</sub> + <sup>2</sup>/<sub>12</sub> = <sup>5</sup>/<sub>12</sub>. Algebraik kasrlarda ham g‘oya aynan shu: maxrajlarni bir xil qilamiz, so‘ng suratlarni qo‘shamiz yoki ayiramiz. Farqi shundaki, sonlar o‘rnida ko‘phadlar turadi va EKUK ni topish uchun ularni ko‘paytuvchilarga ajratish kerak.', 'С обыкновенными дробями вы делали это много раз: <sup>1</sup>/<sub>4</sub> + <sup>1</sup>/<sub>6</sub> = <sup>3</sup>/<sub>12</sub> + <sup>2</sup>/<sub>12</sub> = <sup>5</sup>/<sub>12</sub>. С алгебраическими дробями идея та же: делаем знаменатели одинаковыми, затем складываем или вычитаем числители. Разница в том, что вместо чисел стоят многочлены, и для поиска НОК их нужно раскладывать на множители.', 'You have done this many times with ordinary fractions: <sup>1</sup>/<sub>4</sub> + <sup>1</sup>/<sub>6</sub> = <sup>3</sup>/<sub>12</sub> + <sup>2</sup>/<sub>12</sub> = <sup>5</sup>/<sub>12</sub>. With algebraic fractions the idea is the same: make the denominators equal, then add or subtract the numerators. The difference is that polynomials stand in place of numbers, and to find the LCM we have to factorise them.'),
      L('Bu mavzuda siz eng kichik umumiy maxrajni topishni, har bir kasr uchun qo‘shimcha ko‘paytuvchini aniqlashni va natijani qisqartirishni o‘rganasiz.', 'В этой теме вы научитесь находить наименьший общий знаменатель, определять дополнительный множитель для каждой дроби и сокращать результат.', 'In this topic you will learn to find the lowest common denominator, work out the extra factor for each fraction and simplify the result.')
    ] },
    { kind: 'def', h: L('Umumiy maxraj va qo‘shimcha ko‘paytuvchi', 'Общий знаменатель и дополнительный множитель', 'Common denominator and extra factor'), p: [
      L('Bir nechta kasrning <b>umumiy maxraji</b> — har bir maxrajga bo‘linadigan ifoda. Ulardan eng soddasi (eng kam ko‘paytuvchiga ega bo‘lgani) <b>eng kichik umumiy maxraj</b> deyiladi. U maxrajlarning EKUK iga o‘xshab topiladi: barcha maxrajlarni ko‘paytuvchilarga ajratamiz va har bir ko‘paytuvchini eng katta daraja bilan bir martadan olamiz.', '<b>Общий знаменатель</b> нескольких дробей — выражение, которое делится на каждый знаменатель. Самый простой из них называется <b>наименьшим общим знаменателем</b>. Он находится как НОК знаменателей: раскладываем все знаменатели на множители и берём каждый множитель один раз в наибольшей степени.', 'A <b>common denominator</b> of several fractions is an expression divisible by each denominator. The simplest one is the <b>lowest common denominator</b>. It is found like the LCM of the denominators: factorise them all and take each factor once, with its highest power.'),
      L('Umumiy maxrajni kasrning o‘z maxrajiga bo‘lganda hosil bo‘ladigan ifoda shu kasr uchun <b>qo‘shimcha ko‘paytuvchi</b> deyiladi. Kasrning surati va maxrajini shu ko‘paytuvchiga ko‘paytiramiz — asosiy xossaga ko‘ra kasr qiymati o‘zgarmaydi.', 'Выражение, получаемое при делении общего знаменателя на знаменатель дроби, называется <b>дополнительным множителем</b> этой дроби. Числитель и знаменатель дроби умножаем на него — по основному свойству значение не меняется.', 'The expression obtained by dividing the common denominator by a fraction’s own denominator is that fraction’s <b>extra factor</b>. We multiply the numerator and denominator by it — by the basic property, the value does not change.')
    ], list: [
      L('<sup>1</sup>/<sub>6a<sup>2</sup></sub> va <sup>1</sup>/<sub>4ab</sub>: umumiy maxraj 12a<sup>2</sup>b; qo‘shimcha ko‘paytuvchilar 2b va 3a.', '<sup>1</sup>/<sub>6a<sup>2</sup></sub> и <sup>1</sup>/<sub>4ab</sub>: общий знаменатель 12a<sup>2</sup>b; дополнительные множители 2b и 3a.', '<sup>1</sup>/<sub>6a<sup>2</sup></sub> and <sup>1</sup>/<sub>4ab</sub>: common denominator 12a<sup>2</sup>b; extra factors 2b and 3a.'),
      L('<sup>1</sup>/<sub>x − 2</sub> va <sup>1</sup>/<sub>x<sup>2</sup> − 4</sub>: x<sup>2</sup> − 4 = (x − 2)(x + 2) birinchisiga bo‘linadi, shuning uchun umumiy maxraj (x − 2)(x + 2).', '<sup>1</sup>/<sub>x − 2</sub> и <sup>1</sup>/<sub>x<sup>2</sup> − 4</sub>: x<sup>2</sup> − 4 = (x − 2)(x + 2) делится на первый знаменатель, поэтому общий знаменатель (x − 2)(x + 2).', '<sup>1</sup>/<sub>x − 2</sub> and <sup>1</sup>/<sub>x<sup>2</sup> − 4</sub>: x<sup>2</sup> − 4 = (x − 2)(x + 2) is divisible by the first denominator, so the common denominator is (x − 2)(x + 2).')
    ] },
    { kind: 'history', h: L('Tarixdan: Misr kasrlaridan o‘nli kasrlargacha', 'Из истории: от египетских дробей до десятичных', 'From history: from Egyptian to decimal fractions'), p: [
      L('Qadimgi Misrda deyarli barcha kasrlar <b>birlik kasrlar</b> yig‘indisi ko‘rinishida yozilgan: masalan, <sup>2</sup>/<sub>5</sub> = <sup>1</sup>/<sub>3</sub> + <sup>1</sup>/<sub>15</sub>. Rind papirusida (miloddan avvalgi XVII asr) shunday yoyilmalar jadvali bor. Bobilliklar esa 60 lik sanoq sistemasidan foydalangan — 60 ko‘p bo‘luvchiga ega bo‘lgani uchun umumiy maxrajga keltirish oson edi. Soatda 60 daqiqa bo‘lishi aynan shu an’anadan qolgan.', 'В Древнем Египте почти все дроби записывали как сумму <b>единичных дробей</b>: например, <sup>2</sup>/<sub>5</sub> = <sup>1</sup>/<sub>3</sub> + <sup>1</sup>/<sub>15</sub>. В папирусе Ринда (XVII в. до н. э.) есть таблица таких разложений. Вавилоняне пользовались шестидесятеричной системой — у 60 много делителей, и приводить дроби к общему знаменателю было удобно. 60 минут в часе — наследие этой традиции.', 'In ancient Egypt almost every fraction was written as a sum of <b>unit fractions</b>, for example <sup>2</sup>/<sub>5</sub> = <sup>1</sup>/<sub>3</sub> + <sup>1</sup>/<sub>15</sub>. The Rhind Papyrus (17th century BC) contains a table of such expansions. The Babylonians used base 60 — since 60 has many divisors, bringing fractions to a common denominator was easy. The 60 minutes in an hour are a legacy of that tradition.'),
      L('XV asrda Samarqanddagi <b>Mirzo Ulug‘bek</b> rasadxonasida ishlagan <b>G‘iyosiddin Jamshid al-Koshiy</b> «Arifmetika kaliti» (1427) asarida <b>o‘nli kasrlar</b>ni batafsil bayon qildi. O‘nli kasrlarning maxraji doimo 10, 100, 1000…, shuning uchun ularni qo‘shish juda oson. Al-Koshiy π sonini 16 ta to‘g‘ri xona bilan hisoblagan — bu rekord deyarli 150 yil buzilmagan. Ulug‘bekning yulduzlar jadvali esa o‘z davrining eng aniq jadvali edi.', 'В XV веке <b>Гияс ад-Дин Джамшид аль-Каши</b>, работавший в самаркандской обсерватории <b>Мирзо Улугбека</b>, подробно изложил <b>десятичные дроби</b> в трактате «Ключ арифметики» (1427). Знаменатель десятичной дроби — всегда 10, 100, 1000…, поэтому их легко складывать. Аль-Каши вычислил π с 16 верными знаками — рекорд продержался почти 150 лет. А звёздный каталог Улугбека был самым точным в своё время.', 'In the 15th century <b>Ghiyath al-Din Jamshid al-Kashi</b>, who worked at <b>Ulugh Beg’s</b> observatory in Samarkand, described <b>decimal fractions</b> in detail in “The Key to Arithmetic” (1427). Decimal fractions always have denominator 10, 100, 1000…, so adding them is easy. Al-Kashi computed π to 16 correct digits — a record that stood for almost 150 years. Ulugh Beg’s star catalogue was the most accurate of its time.')
    ] },
    { kind: 'rule', h: L('Qo‘shish va ayirish qoidalari', 'Правила сложения и вычитания', 'Rules for adding and subtracting'), p: [
      L('<b>1. Maxrajlari bir xil kasrlar:</b> <sup>a</sup>/<sub>c</sub> ± <sup>b</sup>/<sub>c</sub> = <sup>a ± b</sup>/<sub>c</sub>. Suratlar qo‘shiladi (ayiriladi), maxraj o‘zgarmaydi.', '<b>1. Дроби с одинаковыми знаменателями:</b> <sup>a</sup>/<sub>c</sub> ± <sup>b</sup>/<sub>c</sub> = <sup>a ± b</sup>/<sub>c</sub>. Числители складываются (вычитаются), знаменатель остаётся.', '<b>1. Same denominators:</b> <sup>a</sup>/<sub>c</sub> ± <sup>b</sup>/<sub>c</sub> = <sup>a ± b</sup>/<sub>c</sub>. Add (subtract) the numerators and keep the denominator.'),
      L('<b>Isbot g‘oyasi.</b> Kasr — bo‘lish natijasi: <sup>a</sup>/<sub>c</sub> = a · <sup>1</sup>/<sub>c</sub>. Shunda a · <sup>1</sup>/<sub>c</sub> + b · <sup>1</sup>/<sub>c</sub> = (a + b) · <sup>1</sup>/<sub>c</sub> — bu oddiy taqsimot qonuni.', '<b>Идея доказательства.</b> Дробь — результат деления: <sup>a</sup>/<sub>c</sub> = a · <sup>1</sup>/<sub>c</sub>. Тогда a · <sup>1</sup>/<sub>c</sub> + b · <sup>1</sup>/<sub>c</sub> = (a + b) · <sup>1</sup>/<sub>c</sub> — обычный распределительный закон.', '<b>Proof idea.</b> A fraction is a quotient: <sup>a</sup>/<sub>c</sub> = a · <sup>1</sup>/<sub>c</sub>. Then a · <sup>1</sup>/<sub>c</sub> + b · <sup>1</sup>/<sub>c</sub> = (a + b) · <sup>1</sup>/<sub>c</sub> — just the distributive law.'),
      L('<b>2. Maxrajlari har xil kasrlar:</b> avval umumiy maxrajga keltiramiz. Eng umumiy holda <sup>a</sup>/<sub>b</sub> ± <sup>c</sup>/<sub>d</sub> = <sup>ad ± bc</sup>/<sub>bd</sub>. Ammo maxrajlarda umumiy ko‘paytuvchi bo‘lsa, bd o‘rniga eng kichik umumiy maxrajni olish hisobni ancha qisqartiradi.', '<b>2. Разные знаменатели:</b> сначала приводим к общему знаменателю. В самом общем виде <sup>a</sup>/<sub>b</sub> ± <sup>c</sup>/<sub>d</sub> = <sup>ad ± bc</sup>/<sub>bd</sub>. Но если у знаменателей есть общий множитель, наименьший общий знаменатель вместо bd сильно сокращает работу.', '<b>2. Different denominators:</b> first bring them to a common denominator. In general <sup>a</sup>/<sub>b</sub> ± <sup>c</sup>/<sub>d</sub> = <sup>ad ± bc</sup>/<sub>bd</sub>. But if the denominators share a factor, using the lowest common denominator instead of bd saves a lot of work.'),
      L('<b>Diqqat:</b> ayirishda ikkinchi kasrning surati butunligicha ayiriladi, shuning uchun uni qavsga oling: <sup>a</sup>/<sub>c</sub> − <sup>b − d</sup>/<sub>c</sub> = <sup>a − (b − d)</sup>/<sub>c</sub> = <sup>a − b + d</sup>/<sub>c</sub>.', '<b>Внимание:</b> при вычитании числитель второй дроби вычитается целиком, поэтому берите его в скобки: <sup>a</sup>/<sub>c</sub> − <sup>b − d</sup>/<sub>c</sub> = <sup>a − (b − d)</sup>/<sub>c</sub> = <sup>a − b + d</sup>/<sub>c</sub>.', '<b>Careful:</b> when subtracting, the whole numerator of the second fraction is subtracted, so put it in brackets: <sup>a</sup>/<sub>c</sub> − <sup>b − d</sup>/<sub>c</sub> = <sup>a − (b − d)</sup>/<sub>c</sub> = <sup>a − b + d</sup>/<sub>c</sub>.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich', 'Пошагово', 'Step by step'), list: [
      L('<b>1.</b> Har bir maxrajni ko‘paytuvchilarga ajrating. Kerak bo‘lsa, (b − a) ni −(a − b) ko‘rinishiga keltiring.', '<b>1.</b> Разложите каждый знаменатель на множители. При необходимости замените (b − a) на −(a − b).', '<b>1.</b> Factorise each denominator. If needed, rewrite (b − a) as −(a − b).'),
      L('<b>2.</b> Eng kichik umumiy maxrajni tuzing: barcha turli ko‘paytuvchilar, har biri eng katta darajada.', '<b>2.</b> Составьте наименьший общий знаменатель: все различные множители, каждый в наибольшей степени.', '<b>2.</b> Build the lowest common denominator: all distinct factors, each to its highest power.'),
      L('<b>3.</b> Har bir kasr uchun qo‘shimcha ko‘paytuvchini toping (umumiy maxraj : o‘z maxraji) va uni kasr ustiga yozib qo‘ying.', '<b>3.</b> Найдите для каждой дроби дополнительный множитель (общий знаменатель : свой знаменатель) и надпишите его над дробью.', '<b>3.</b> Find each fraction’s extra factor (common denominator ÷ its own denominator) and write it above the fraction.'),
      L('<b>4.</b> Suratlarni qo‘shimcha ko‘paytuvchilarga ko‘paytirib, bitta kasr qilib yozing; ayirishda qavslarni unutmang.', '<b>4.</b> Умножьте числители на дополнительные множители и запишите одной дробью; при вычитании не забывайте скобки.', '<b>4.</b> Multiply the numerators by their extra factors and write a single fraction; remember brackets when subtracting.'),
      L('<b>5.</b> Suratdagi qavslarni ochib, o‘xshash hadlarni ixchamlang.', '<b>5.</b> Раскройте скобки в числителе и приведите подобные.', '<b>5.</b> Expand the brackets in the numerator and collect like terms.'),
      L('<b>6.</b> Natijaviy suratni ko‘paytuvchilarga ajratib ko‘ring — ehtimol, kasr qisqaradi.', '<b>6.</b> Попробуйте разложить полученный числитель — возможно, дробь сократится.', '<b>6.</b> Try to factorise the resulting numerator — the fraction may cancel.')
    ], after: [
      L('Maxrajdagi qavslarni ochmasdan, ko‘paytma ko‘rinishida qoldirish odatda qulayroq: shunda qisqartirish imkoniyati ko‘rinib turadi.', 'Знаменатель удобнее оставлять в виде произведения, не раскрывая скобок: так видно, можно ли сократить.', 'It is usually better to leave the denominator as a product without expanding: then you can see whether anything cancels.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('<sup>5</sup>/<sub>6a<sup>2</sup></sub> + <sup>3</sup>/<sub>4ab</sub> ni soddalashtiring.', 'Упростите <sup>5</sup>/<sub>6a<sup>2</sup></sub> + <sup>3</sup>/<sub>4ab</sub>.', 'Simplify <sup>5</sup>/<sub>6a<sup>2</sup></sub> + <sup>3</sup>/<sub>4ab</sub>.'),
        s: L('Umumiy maxraj 12a<sup>2</sup>b. Qo‘shimcha ko‘paytuvchilar: 2b va 3a. <sup>5 · 2b + 3 · 3a</sup>/<sub>12a<sup>2</sup>b</sub> = <sup>10b + 9a</sup>/<sub>12a<sup>2</sup>b</sub>.', 'Общий знаменатель 12a<sup>2</sup>b. Дополнительные множители: 2b и 3a. <sup>5 · 2b + 3 · 3a</sup>/<sub>12a<sup>2</sup>b</sub> = <sup>10b + 9a</sup>/<sub>12a<sup>2</sup>b</sub>.', 'Common denominator 12a<sup>2</sup>b. Extra factors 2b and 3a. <sup>5 · 2b + 3 · 3a</sup>/<sub>12a<sup>2</sup>b</sub> = <sup>10b + 9a</sup>/<sub>12a<sup>2</sup>b</sub>.') },
      { q: L('<sup>1</sup>/<sub>x − 1</sub> − <sup>1</sup>/<sub>x + 1</sub> ni hisoblang.', 'Вычислите <sup>1</sup>/<sub>x − 1</sub> − <sup>1</sup>/<sub>x + 1</sub>.', 'Compute <sup>1</sup>/<sub>x − 1</sub> − <sup>1</sup>/<sub>x + 1</sub>.'),
        s: L('Umumiy maxraj (x − 1)(x + 1) = x<sup>2</sup> − 1. <sup>(x + 1) − (x − 1)</sup>/<sub>x<sup>2</sup> − 1</sub> = <sup>2</sup>/<sub>x<sup>2</sup> − 1</sub>, x ≠ ±1.', 'Общий знаменатель (x − 1)(x + 1) = x<sup>2</sup> − 1. <sup>(x + 1) − (x − 1)</sup>/<sub>x<sup>2</sup> − 1</sub> = <sup>2</sup>/<sub>x<sup>2</sup> − 1</sub>, x ≠ ±1.', 'Common denominator (x − 1)(x + 1) = x<sup>2</sup> − 1. <sup>(x + 1) − (x − 1)</sup>/<sub>x<sup>2</sup> − 1</sub> = <sup>2</sup>/<sub>x<sup>2</sup> − 1</sub>, x ≠ ±1.') },
      { q: L('<sup>x</sup>/<sub>x − 3</sub> + <sup>3</sup>/<sub>3 − x</sub> ni soddalashtiring.', 'Упростите <sup>x</sup>/<sub>x − 3</sub> + <sup>3</sup>/<sub>3 − x</sub>.', 'Simplify <sup>x</sup>/<sub>x − 3</sub> + <sup>3</sup>/<sub>3 − x</sub>.'),
        s: L('3 − x = −(x − 3), shuning uchun <sup>3</sup>/<sub>3 − x</sub> = −<sup>3</sup>/<sub>x − 3</sub>. Yig‘indi: <sup>x − 3</sup>/<sub>x − 3</sub> = 1 (x ≠ 3).', '3 − x = −(x − 3), поэтому <sup>3</sup>/<sub>3 − x</sub> = −<sup>3</sup>/<sub>x − 3</sub>. Сумма: <sup>x − 3</sup>/<sub>x − 3</sub> = 1 (x ≠ 3).', '3 − x = −(x − 3), so <sup>3</sup>/<sub>3 − x</sub> = −<sup>3</sup>/<sub>x − 3</sub>. The sum is <sup>x − 3</sup>/<sub>x − 3</sub> = 1 (x ≠ 3).') },
      { q: L('<sup>2a</sup>/<sub>a<sup>2</sup> − 4</sub> − <sup>1</sup>/<sub>a − 2</sub> ni soddalashtiring.', 'Упростите <sup>2a</sup>/<sub>a<sup>2</sup> − 4</sub> − <sup>1</sup>/<sub>a − 2</sub>.', 'Simplify <sup>2a</sup>/<sub>a<sup>2</sup> − 4</sub> − <sup>1</sup>/<sub>a − 2</sub>.'),
        s: L('a<sup>2</sup> − 4 = (a − 2)(a + 2) — umumiy maxraj. Ikkinchi kasrning qo‘shimcha ko‘paytuvchisi (a + 2). <sup>2a − (a + 2)</sup>/<sub>(a − 2)(a + 2)</sub> = <sup>a − 2</sup>/<sub>(a − 2)(a + 2)</sub> = <sup>1</sup>/<sub>a + 2</sub>, a ≠ ±2.', 'a<sup>2</sup> − 4 = (a − 2)(a + 2) — общий знаменатель. Дополнительный множитель второй дроби (a + 2). <sup>2a − (a + 2)</sup>/<sub>(a − 2)(a + 2)</sub> = <sup>a − 2</sup>/<sub>(a − 2)(a + 2)</sub> = <sup>1</sup>/<sub>a + 2</sub>, a ≠ ±2.', 'a<sup>2</sup> − 4 = (a − 2)(a + 2) is the common denominator. The second fraction’s extra factor is (a + 2). <sup>2a − (a + 2)</sup>/<sub>(a − 2)(a + 2)</sub> = <sup>a − 2</sup>/<sub>(a − 2)(a + 2)</sub> = <sup>1</sup>/<sub>a + 2</sub>, a ≠ ±2.') }
    ] },
    { kind: 'example', h: L('Butun ifoda va kasr', 'Целое выражение и дробь', 'A whole expression plus a fraction'), p: [
      L('Butun ifodani maxraji 1 bo‘lgan kasr deb qarash mumkin: a = <sup>a</sup>/<sub>1</sub>. Shuning uchun uni ham umumiy maxrajga keltiramiz.', 'Целое выражение можно считать дробью со знаменателем 1: a = <sup>a</sup>/<sub>1</sub>. Поэтому его тоже приводят к общему знаменателю.', 'A whole expression can be treated as a fraction with denominator 1: a = <sup>a</sup>/<sub>1</sub>. So it too is brought to the common denominator.')
    ], ex: [
      { q: L('x + 2 − <sup>4</sup>/<sub>x + 2</sub> ni bitta kasr ko‘rinishida yozing.', 'Запишите x + 2 − <sup>4</sup>/<sub>x + 2</sub> одной дробью.', 'Write x + 2 − <sup>4</sup>/<sub>x + 2</sub> as a single fraction.'),
        s: L('<sup>(x + 2)<sup>2</sup> − 4</sup>/<sub>x + 2</sub> = <sup>x<sup>2</sup> + 4x</sup>/<sub>x + 2</sub> = <sup>x(x + 4)</sup>/<sub>x + 2</sub>, x ≠ −2.', '<sup>(x + 2)<sup>2</sup> − 4</sup>/<sub>x + 2</sub> = <sup>x<sup>2</sup> + 4x</sup>/<sub>x + 2</sub> = <sup>x(x + 4)</sup>/<sub>x + 2</sub>, x ≠ −2.', '<sup>(x + 2)<sup>2</sup> − 4</sup>/<sub>x + 2</sub> = <sup>x<sup>2</sup> + 4x</sup>/<sub>x + 2</sub> = <sup>x(x + 4)</sup>/<sub>x + 2</sub>, x ≠ −2.') },
      { q: L('Ikki quvur masalasi: <sup>1</sup>/<sub>x</sub> + <sup>1</sup>/<sub>x + 2</sub> ni soddalashtiring va x = 4 da hisoblang.', 'Задача о трубах: упростите <sup>1</sup>/<sub>x</sub> + <sup>1</sup>/<sub>x + 2</sub> и вычислите при x = 4.', 'The two-pipe problem: simplify <sup>1</sup>/<sub>x</sub> + <sup>1</sup>/<sub>x + 2</sub> and evaluate at x = 4.'),
        s: L('<sup>x + 2 + x</sup>/<sub>x(x + 2)</sub> = <sup>2x + 2</sup>/<sub>x(x + 2)</sub>. x = 4 da: <sup>10</sup>/<sub>24</sub> = <sup>5</sup>/<sub>12</sub>. Demak, bir soatda hovuzning <sup>5</sup>/<sub>12</sub> qismi to‘ladi, butun hovuz esa <sup>12</sup>/<sub>5</sub> = 2,4 soatda.', '<sup>x + 2 + x</sup>/<sub>x(x + 2)</sub> = <sup>2x + 2</sup>/<sub>x(x + 2)</sub>. При x = 4: <sup>10</sup>/<sub>24</sub> = <sup>5</sup>/<sub>12</sub>. Значит, за час наполняется <sup>5</sup>/<sub>12</sub> бассейна, а весь бассейн — за <sup>12</sup>/<sub>5</sub> = 2,4 ч.', '<sup>x + 2 + x</sup>/<sub>x(x + 2)</sub> = <sup>2x + 2</sup>/<sub>x(x + 2)</sub>. At x = 4: <sup>10</sup>/<sub>24</sub> = <sup>5</sup>/<sub>12</sub>. So in one hour <sup>5</sup>/<sub>12</sub> of the pool fills, and the whole pool in <sup>12</sup>/<sub>5</sub> = 2.4 hours.') }
    ] },
    { kind: 'table', h: L('Umumiy maxrajni tanlash', 'Выбор общего знаменателя', 'Choosing the common denominator'), table: { head: [L('Maxrajlar', 'Знаменатели', 'Denominators'), L('Eng kichik umumiy maxraj', 'Наименьший общий знаменатель', 'Lowest common denominator'), L('Izoh', 'Комментарий', 'Comment')], rows: [
      [L('x va y', 'x и y', 'x and y'), L('xy', 'xy', 'xy'), L('umumiy ko‘paytuvchi yo‘q — ko‘paytiramiz', 'общих множителей нет — перемножаем', 'no common factor — multiply')],
      [L('3x<sup>2</sup> va 6x', '3x<sup>2</sup> и 6x', '3x<sup>2</sup> and 6x'), L('6x<sup>2</sup>', '6x<sup>2</sup>', '6x<sup>2</sup>'), L('EKUK(3, 6) = 6, x ning eng katta darajasi 2', 'НОК(3, 6) = 6, наибольшая степень x — 2', 'LCM(3, 6) = 6, highest power of x is 2')],
      [L('a − b va a<sup>2</sup> − b<sup>2</sup>', 'a − b и a<sup>2</sup> − b<sup>2</sup>', 'a − b and a<sup>2</sup> − b<sup>2</sup>'), L('(a − b)(a + b)', '(a − b)(a + b)', '(a − b)(a + b)'), L('ikkinchisi birinchisiga bo‘linadi', 'второй делится на первый', 'the second is divisible by the first')],
      [L('x − 5 va 5 − x', 'x − 5 и 5 − x', 'x − 5 and 5 − x'), L('x − 5', 'x − 5', 'x − 5'), L('5 − x = −(x − 5)', '5 − x = −(x − 5)', '5 − x = −(x − 5)')],
      [L('x<sup>2</sup> + 2x va x<sup>2</sup> − 4', 'x<sup>2</sup> + 2x и x<sup>2</sup> − 4', 'x<sup>2</sup> + 2x and x<sup>2</sup> − 4'), L('x(x + 2)(x − 2)', 'x(x + 2)(x − 2)', 'x(x + 2)(x − 2)'), L('x(x + 2) va (x − 2)(x + 2)', 'x(x + 2) и (x − 2)(x + 2)', 'x(x + 2) and (x − 2)(x + 2)')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Maxrajlarni ham qo‘shish:</b> <sup>1</sup>/<sub>a</sub> + <sup>1</sup>/<sub>b</sub> ≠ <sup>2</sup>/<sub>a + b</sub>. To‘g‘risi: <sup>a + b</sup>/<sub>ab</sub>. Tekshiring: a = b = 1 da 2 ≠ 1.', '<b>Сложение знаменателей:</b> <sup>1</sup>/<sub>a</sub> + <sup>1</sup>/<sub>b</sub> ≠ <sup>2</sup>/<sub>a + b</sub>. Верно: <sup>a + b</sup>/<sub>ab</sub>. Проверка: при a = b = 1 2 ≠ 1.', '<b>Adding denominators:</b> <sup>1</sup>/<sub>a</sub> + <sup>1</sup>/<sub>b</sub> ≠ <sup>2</sup>/<sub>a + b</sub>. Correct: <sup>a + b</sup>/<sub>ab</sub>. Check with a = b = 1: 2 ≠ 1.'),
      L('<b>Ayirishda qavsni unutish:</b> <sup>3x</sup>/<sub>y</sub> − <sup>x − 2</sup>/<sub>y</sub> = <sup>3x − x + 2</sup>/<sub>y</sub> = <sup>2x + 2</sup>/<sub>y</sub>, <sup>2x − 2</sup>/<sub>y</sub> emas.', '<b>Забытые скобки при вычитании:</b> <sup>3x</sup>/<sub>y</sub> − <sup>x − 2</sup>/<sub>y</sub> = <sup>3x − x + 2</sup>/<sub>y</sub> = <sup>2x + 2</sup>/<sub>y</sub>, а не <sup>2x − 2</sup>/<sub>y</sub>.', '<b>Forgetting brackets when subtracting:</b> <sup>3x</sup>/<sub>y</sub> − <sup>x − 2</sup>/<sub>y</sub> = <sup>3x − x + 2</sup>/<sub>y</sub> = <sup>2x + 2</sup>/<sub>y</sub>, not <sup>2x − 2</sup>/<sub>y</sub>.'),
      L('<b>Suratni qo‘shimcha ko‘paytuvchiga ko‘paytirmaslik:</b> maxrajni o‘zgartirsangiz, suratni ham shu ifodaga ko‘paytirish shart.', '<b>Не умножить числитель:</b> изменив знаменатель, числитель обязательно умножают на тот же множитель.', '<b>Not multiplying the numerator:</b> whenever you change the denominator, the numerator must be multiplied by the same factor.'),
      L('<b>Juda katta umumiy maxraj:</b> maxrajlarni shunchaki ko‘paytirish xato emas, lekin hisob uzayadi va oxirida qisqartirish qiyinlashadi.', '<b>Слишком большой общий знаменатель:</b> просто перемножить знаменатели не ошибка, но вычисления удлиняются и сокращать потом труднее.', '<b>Too big a common denominator:</b> simply multiplying the denominators is not wrong, but the work gets longer and cancelling at the end becomes harder.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Birgalikdagi ish.</b> Bir usta devorni a kunda, ikkinchisi b kunda bo‘yaydi. Birga ular kuniga <sup>1</sup>/<sub>a</sub> + <sup>1</sup>/<sub>b</sub> = <sup>a + b</sup>/<sub>ab</sub> qismni bo‘yaydi, butun devorni esa <sup>ab</sup>/<sub>a + b</sub> kunda. Masalan, a = 3, b = 6 bo‘lsa — 2 kunda.', '<b>Совместная работа.</b> Один мастер красит стену за a дней, другой — за b. Вместе они за день красят <sup>1</sup>/<sub>a</sub> + <sup>1</sup>/<sub>b</sub> = <sup>a + b</sup>/<sub>ab</sub> стены, а всю — за <sup>ab</sup>/<sub>a + b</sub> дней. Например, при a = 3, b = 6 — за 2 дня.', '<b>Working together.</b> One painter paints a wall in a days, another in b days. Together they paint <sup>1</sup>/<sub>a</sub> + <sup>1</sup>/<sub>b</sub> = <sup>a + b</sup>/<sub>ab</sub> of it per day, and the whole wall in <sup>ab</sup>/<sub>a + b</sub> days. For a = 3, b = 6 that is 2 days.'),
      L('<b>Elektr zanjiri.</b> Parallel ulangan ikki rezistorning umumiy qarshiligi <sup>1</sup>/<sub>R</sub> = <sup>1</sup>/<sub>R<sub>1</sub></sub> + <sup>1</sup>/<sub>R<sub>2</sub></sub> formula bilan topiladi — xuddi shu umumiy maxraj hisobi. <b>Optika:</b> linza formulasi <sup>1</sup>/<sub>F</sub> = <sup>1</sup>/<sub>d</sub> + <sup>1</sup>/<sub>f</sub> ham shunday.', '<b>Электрическая цепь.</b> Сопротивление двух параллельных резисторов находят по формуле <sup>1</sup>/<sub>R</sub> = <sup>1</sup>/<sub>R<sub>1</sub></sub> + <sup>1</sup>/<sub>R<sub>2</sub></sub> — тот же общий знаменатель. <b>Оптика:</b> формула линзы <sup>1</sup>/<sub>F</sub> = <sup>1</sup>/<sub>d</sub> + <sup>1</sup>/<sub>f</sub> устроена так же.', '<b>Electric circuits.</b> Two resistors in parallel have total resistance given by <sup>1</sup>/<sub>R</sub> = <sup>1</sup>/<sub>R<sub>1</sub></sub> + <sup>1</sup>/<sub>R<sub>2</sub></sub> — the same common-denominator work. <b>Optics:</b> the lens formula <sup>1</sup>/<sub>F</sub> = <sup>1</sup>/<sub>d</sub> + <sup>1</sup>/<sub>f</sub> works the same way.'),
      L('<b>O‘rtacha tezlik.</b> Toshkentdan Samarqandgacha v<sub>1</sub>, qaytishda v<sub>2</sub> tezlik bilan yursangiz, o‘rtacha tezlik <sup>2v<sub>1</sub>v<sub>2</sub></sup>/<sub>v<sub>1</sub> + v<sub>2</sub></sub> ga teng — u ham kasrlarni qo‘shishdan kelib chiqadi.', '<b>Средняя скорость.</b> Если ехать из Ташкента в Самарканд со скоростью v<sub>1</sub>, а обратно — v<sub>2</sub>, средняя скорость равна <sup>2v<sub>1</sub>v<sub>2</sub></sup>/<sub>v<sub>1</sub> + v<sub>2</sub></sub> — это тоже результат сложения дробей.', '<b>Average speed.</b> If you drive from Tashkent to Samarkand at v<sub>1</sub> and back at v<sub>2</sub>, the average speed is <sup>2v<sub>1</sub>v<sub>2</sub></sup>/<sub>v<sub>1</sub> + v<sub>2</sub></sub> — again the result of adding fractions.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Har qanday oddiy kasrni turli birlik kasrlar yig‘indisi ko‘rinishida yozish mumkin — bu Misr usulining kafolati. Masalan, <sup>3</sup>/<sub>4</sub> = <sup>1</sup>/<sub>2</sub> + <sup>1</sup>/<sub>4</sub>.', 'Любую обыкновенную дробь можно записать как сумму различных единичных дробей — это гарантирует египетский метод. Например, <sup>3</sup>/<sub>4</sub> = <sup>1</sup>/<sub>2</sub> + <sup>1</sup>/<sub>4</sub>.', 'Every ordinary fraction can be written as a sum of different unit fractions — the Egyptian method always works. For example, <sup>3</sup>/<sub>4</sub> = <sup>1</sup>/<sub>2</sub> + <sup>1</sup>/<sub>4</sub>.'),
      L('<sup>1</sup>/<sub>n</sub> − <sup>1</sup>/<sub>n + 1</sub> = <sup>1</sup>/<sub>n(n + 1)</sub> ayniyati yordamida <sup>1</sup>/<sub>1·2</sub> + <sup>1</sup>/<sub>2·3</sub> + … + <sup>1</sup>/<sub>99·100</sub> yig‘indisini bir zumda hisoblash mumkin: u 1 − <sup>1</sup>/<sub>100</sub> = 0,99 ga teng.', 'С помощью тождества <sup>1</sup>/<sub>n</sub> − <sup>1</sup>/<sub>n + 1</sub> = <sup>1</sup>/<sub>n(n + 1)</sub> сумма <sup>1</sup>/<sub>1·2</sub> + <sup>1</sup>/<sub>2·3</sub> + … + <sup>1</sup>/<sub>99·100</sub> считается мгновенно: она равна 1 − <sup>1</sup>/<sub>100</sub> = 0,99.', 'Using the identity <sup>1</sup>/<sub>n</sub> − <sup>1</sup>/<sub>n + 1</sub> = <sup>1</sup>/<sub>n(n + 1)</sub>, the sum <sup>1</sup>/<sub>1·2</sub> + <sup>1</sup>/<sub>2·3</sub> + … + <sup>1</sup>/<sub>99·100</sub> takes a second: it equals 1 − <sup>1</sup>/<sub>100</sub> = 0.99.'),
      L('Ulug‘bek rasadxonasining sekstanti radiusi taxminan 40 metr bo‘lgan — bu o‘rta asrlardagi eng katta astronomik asboblardan biri.', 'Радиус секстанта обсерватории Улугбека был около 40 метров — один из крупнейших астрономических инструментов Средневековья.', 'The sextant of Ulugh Beg’s observatory had a radius of about 40 metres — one of the largest astronomical instruments of the Middle Ages.')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('<sup>a</sup>/<sub>3</sub> + <sup>a</sup>/<sub>6</sub> = ?', '<sup>a</sup>/<sub>3</sub> + <sup>a</sup>/<sub>6</sub> = ?', '<sup>a</sup>/<sub>3</sub> + <sup>a</sup>/<sub>6</sub> = ?'), s: L('<sup>2a + a</sup>/<sub>6</sub> = <sup>3a</sup>/<sub>6</sub> = <sup>a</sup>/<sub>2</sub>.', '<sup>2a + a</sup>/<sub>6</sub> = <sup>3a</sup>/<sub>6</sub> = <sup>a</sup>/<sub>2</sub>.', '<sup>2a + a</sup>/<sub>6</sub> = <sup>3a</sup>/<sub>6</sub> = <sup>a</sup>/<sub>2</sub>.') },
      { q: L('<sup>1</sup>/<sub>x</sub> − <sup>1</sup>/<sub>x + 1</sub> = ?', '<sup>1</sup>/<sub>x</sub> − <sup>1</sup>/<sub>x + 1</sub> = ?', '<sup>1</sup>/<sub>x</sub> − <sup>1</sup>/<sub>x + 1</sub> = ?'), s: L('<sup>1</sup>/<sub>x(x + 1)</sub>, x ≠ 0, x ≠ −1.', '<sup>1</sup>/<sub>x(x + 1)</sub>, x ≠ 0, x ≠ −1.', '<sup>1</sup>/<sub>x(x + 1)</sub>, x ≠ 0, x ≠ −1.') },
      { q: L('<sup>b<sup>2</sup></sup>/<sub>b − 1</sub> − <sup>1</sup>/<sub>b − 1</sub> ni soddalashtiring.', 'Упростите <sup>b<sup>2</sup></sup>/<sub>b − 1</sub> − <sup>1</sup>/<sub>b − 1</sub>.', 'Simplify <sup>b<sup>2</sup></sup>/<sub>b − 1</sub> − <sup>1</sup>/<sub>b − 1</sub>.'), s: L('<sup>b<sup>2</sup> − 1</sup>/<sub>b − 1</sub> = b + 1, b ≠ 1.', '<sup>b<sup>2</sup> − 1</sup>/<sub>b − 1</sub> = b + 1, b ≠ 1.', '<sup>b<sup>2</sup> − 1</sup>/<sub>b − 1</sub> = b + 1, b ≠ 1.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Bir xil maxrajda: suratlar qo‘shiladi yoki ayiriladi, maxraj saqlanadi.', 'При одинаковом знаменателе числители складываются или вычитаются, знаменатель сохраняется.', 'With equal denominators, add or subtract the numerators and keep the denominator.'),
      L('Har xil maxrajda: avval eng kichik umumiy maxrajni topamiz (maxrajlarni ko‘paytuvchilarga ajratib).', 'При разных знаменателях сначала находим наименьший общий знаменатель (разложив знаменатели на множители).', 'With different denominators, first find the lowest common denominator (by factorising the denominators).'),
      L('Qo‘shimcha ko‘paytuvchi = umumiy maxraj : kasrning o‘z maxraji.', 'Дополнительный множитель = общий знаменатель : свой знаменатель.', 'Extra factor = common denominator ÷ own denominator.'),
      L('Ayirishda ikkinchi suratni qavsga olamiz.', 'При вычитании второй числитель берём в скобки.', 'When subtracting, put the second numerator in brackets.'),
      L('b − a = −(a − b) almashtirishi maxrajlarni bir xil qilishga yordam beradi.', 'Замена b − a = −(a − b) помогает уравнять знаменатели.', 'Rewriting b − a = −(a − b) helps make the denominators equal.'),
      L('Natijani har doim qisqartirishga harakat qiling va aniqlanish sohasini ko‘rsating.', 'Результат всегда пытайтесь сократить и указывайте область определения.', 'Always try to simplify the result and state the domain.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t3. Kasrlarni ko'paytirish va bo'lish. Ayniy almashtirishlar ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Ko‘paytirish — qo‘shishdan ham oson', 'Умножать — даже проще, чем складывать', 'Multiplying is even easier than adding'), p: [
      L('Kasrlarni qo‘shish uchun umumiy maxraj qidirish kerak edi. Ko‘paytirishda esa bunga hojat yo‘q: suratni suratga, maxrajni maxrajga ko‘paytiramiz, xolos. Bo‘lish esa ko‘paytirishga keltiriladi. Shu sababli ko‘paytirish va bo‘lish amallari algebraik kasrlar bilan ishlashning eng qulay qismi hisoblanadi.', 'Чтобы складывать дроби, нужно было искать общий знаменатель. При умножении это не нужно: числитель умножаем на числитель, знаменатель — на знаменатель. А деление сводится к умножению. Поэтому умножение и деление — самая удобная часть работы с алгебраическими дробями.', 'To add fractions we had to find a common denominator. Multiplying needs none of that: numerator times numerator, denominator times denominator. And division reduces to multiplication. That is why multiplying and dividing are the friendliest part of working with algebraic fractions.'),
      L('Bu mavzuning ikkinchi qismi — <b>ayniy almashtirishlar</b>. Biz bir nechta amallar qatnashgan uzun ifodalarni bosqichma-bosqich soddalashtirishni va <b>ayniyatlarni isbotlashni</b> o‘rganamiz. Ayniyat — o‘zgaruvchilarning barcha ruxsat etilgan qiymatlarida to‘g‘ri bo‘ladigan tenglik. Masalan, (a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup> — ayniyat, x + 2 = 5 esa ayniyat emas, u faqat x = 3 da to‘g‘ri.', 'Вторая часть темы — <b>тождественные преобразования</b>. Мы научимся пошагово упрощать длинные выражения с несколькими действиями и <b>доказывать тождества</b>. Тождество — равенство, верное при всех допустимых значениях переменных. Например, (a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup> — тождество, а x + 2 = 5 — нет: оно верно только при x = 3.', 'The second part of the topic is <b>identity transformations</b>. We learn to simplify long expressions with several operations step by step and to <b>prove identities</b>. An identity is an equality that holds for all permitted values of the variables. For example, (a + b)<sup>2</sup> = a<sup>2</sup> + 2ab + b<sup>2</sup> is an identity, while x + 2 = 5 is not — it holds only for x = 3.'),
      L('Bu ko‘nikmalar fizik formulalarni o‘zgartirishda, tenglamalarni yechishda va keyinchalik funksiyalarni o‘rganishda doimo kerak bo‘ladi.', 'Эти навыки постоянно нужны при преобразовании физических формул, решении уравнений и дальнейшем изучении функций.', 'These skills are needed all the time when rearranging physics formulas, solving equations and later studying functions.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), p: [
      L('<b>Teskari kasr.</b> <sup>a</sup>/<sub>b</sub> kasrga teskari kasr <sup>b</sup>/<sub>a</sub> dir (a ≠ 0, b ≠ 0). Ularning ko‘paytmasi 1 ga teng: <sup>a</sup>/<sub>b</sub> · <sup>b</sup>/<sub>a</sub> = 1. Masalan, <sup>x − 1</sup>/<sub>x + 2</sub> ga teskari kasr <sup>x + 2</sup>/<sub>x − 1</sub>, butun ifoda 3y ga teskari esa <sup>1</sup>/<sub>3y</sub>.', '<b>Обратная дробь.</b> Дробь, обратная <sup>a</sup>/<sub>b</sub>, — это <sup>b</sup>/<sub>a</sub> (a ≠ 0, b ≠ 0). Их произведение равно 1: <sup>a</sup>/<sub>b</sub> · <sup>b</sup>/<sub>a</sub> = 1. Например, обратная к <sup>x − 1</sup>/<sub>x + 2</sub> — <sup>x + 2</sup>/<sub>x − 1</sub>, а к выражению 3y — <sup>1</sup>/<sub>3y</sub>.', '<b>Reciprocal.</b> The reciprocal of <sup>a</sup>/<sub>b</sub> is <sup>b</sup>/<sub>a</sub> (a ≠ 0, b ≠ 0). Their product is 1: <sup>a</sup>/<sub>b</sub> · <sup>b</sup>/<sub>a</sub> = 1. For example, the reciprocal of <sup>x − 1</sup>/<sub>x + 2</sub> is <sup>x + 2</sup>/<sub>x − 1</sub>, and the reciprocal of 3y is <sup>1</sup>/<sub>3y</sub>.'),
      L('<b>Ayniyat.</b> O‘zgaruvchilarning barcha ruxsat etilgan qiymatlarida to‘g‘ri bo‘ladigan tenglik. Bir ifodani unga aynan teng ifoda bilan almashtirish <b>ayniy almashtirish</b> deyiladi: qavslarni ochish, ko‘paytuvchilarga ajratish, kasrni qisqartirish, umumiy maxrajga keltirish — bularning barchasi ayniy almashtirishlardir.', '<b>Тождество.</b> Равенство, верное при всех допустимых значениях переменных. Замена выражения тождественно равным ему называется <b>тождественным преобразованием</b>: раскрытие скобок, разложение на множители, сокращение, приведение к общему знаменателю — всё это тождественные преобразования.', '<b>Identity.</b> An equality true for all permitted values of the variables. Replacing an expression with one identically equal to it is an <b>identity transformation</b>: expanding brackets, factorising, cancelling, bringing to a common denominator — all of these are identity transformations.')
    ] },
    { kind: 'history', h: L('Tarixdan: bo‘lishning «ag‘darish» qoidasi', 'Из истории: правило «переворота» при делении', 'From history: the “flip” rule for division'), p: [
      L('Hind matematigi <b>Braxmagupta</b> (VII asr) kasrlarni bo‘lish uchun bo‘luvchining surati va maxrajini o‘rnini almashtirib, so‘ng ko‘paytirishni tavsiya qilgan. Keyinchalik bu qoida IX–XII asrlarda Bag‘dod, Xorazm va Andalusiya olimlari asarlarida keng tarqaldi. <b>Abu Rayhon Beruniy</b> (973–1048) astronomik hisoblarida kasrlar bilan murakkab amallarni bajargan: u Yer radiusini tog‘ cho‘qqisidan ufqqa qarab o‘lchash usulini ishlab chiqib, natijani nisbat va proporsiyalar orqali hisoblagan.', 'Индийский математик <b>Брахмагупта</b> (VII век) советовал при делении дробей поменять местами числитель и знаменатель делителя и затем умножить. Позже это правило распространилось в трудах учёных Багдада, Хорезма и Андалусии IX–XII веков. <b>Абу Райхан Беруни</b> (973–1048) выполнял сложные действия с дробями в астрономических расчётах: он придумал способ измерить радиус Земли, глядя с вершины горы на горизонт, и вычислял результат через отношения и пропорции.', 'The Indian mathematician <b>Brahmagupta</b> (7th century) advised dividing by a fraction by swapping its numerator and denominator and then multiplying. The rule then spread through the works of scholars in Baghdad, Khorezm and Andalusia in the 9th–12th centuries. <b>Abu Rayhan al-Biruni</b> (973–1048) carried out complicated work with fractions in his astronomical calculations: he devised a way to measure the Earth’s radius by looking from a mountain top at the horizon and computed the result through ratios and proportions.'),
      L('Beruniy olgan natija — Yer radiusi taxminan 6340 km — hozirgi 6371 km ga juda yaqin. Bu hisob kasrlar bilan ehtiyotkorlik bilan ishlash qanchalik muhimligini ko‘rsatadi.', 'Результат Беруни — радиус Земли около 6340 км — очень близок к современному значению 6371 км. Этот расчёт показывает, как важна аккуратная работа с дробями.', 'Al-Biruni’s result — an Earth radius of about 6340 km — is remarkably close to the modern 6371 km. His calculation shows how much careful work with fractions matters.')
    ] },
    { kind: 'rule', h: L('Ko‘paytirish va bo‘lish qoidalari', 'Правила умножения и деления', 'Rules for multiplying and dividing'), p: [
      L('<b>Ko‘paytirish:</b> <sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>. <b>Isbot g‘oyasi:</b> <sup>a</sup>/<sub>b</sub> = p, <sup>c</sup>/<sub>d</sub> = q bo‘lsin, ya’ni a = bp, c = dq. Ko‘paytirsak, ac = (bd)(pq), demak <sup>ac</sup>/<sub>bd</sub> = pq.', '<b>Умножение:</b> <sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>. <b>Идея доказательства:</b> пусть <sup>a</sup>/<sub>b</sub> = p, <sup>c</sup>/<sub>d</sub> = q, то есть a = bp, c = dq. Перемножив, получим ac = (bd)(pq), значит <sup>ac</sup>/<sub>bd</sub> = pq.', '<b>Multiplication:</b> <sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>. <b>Proof idea:</b> let <sup>a</sup>/<sub>b</sub> = p and <sup>c</sup>/<sub>d</sub> = q, i.e. a = bp and c = dq. Multiplying, ac = (bd)(pq), so <sup>ac</sup>/<sub>bd</sub> = pq.'),
      L('<b>Bo‘lish:</b> <sup>a</sup>/<sub>b</sub> : <sup>c</sup>/<sub>d</sub> = <sup>a</sup>/<sub>b</sub> · <sup>d</sup>/<sub>c</sub> = <sup>ad</sup>/<sub>bc</sub> (c ≠ 0). Bo‘lish — teskari kasrga ko‘paytirish. Sababi: bo‘linmani bo‘luvchiga ko‘paytirsak, bo‘linuvchi chiqishi kerak: <sup>ad</sup>/<sub>bc</sub> · <sup>c</sup>/<sub>d</sub> = <sup>a</sup>/<sub>b</sub>.', '<b>Деление:</b> <sup>a</sup>/<sub>b</sub> : <sup>c</sup>/<sub>d</sub> = <sup>a</sup>/<sub>b</sub> · <sup>d</sup>/<sub>c</sub> = <sup>ad</sup>/<sub>bc</sub> (c ≠ 0). Деление — умножение на обратную дробь. Причина: частное, умноженное на делитель, даёт делимое: <sup>ad</sup>/<sub>bc</sub> · <sup>c</sup>/<sub>d</sub> = <sup>a</sup>/<sub>b</sub>.', '<b>Division:</b> <sup>a</sup>/<sub>b</sub> : <sup>c</sup>/<sub>d</sub> = <sup>a</sup>/<sub>b</sub> · <sup>d</sup>/<sub>c</sub> = <sup>ad</sup>/<sub>bc</sub> (c ≠ 0). Dividing means multiplying by the reciprocal. Reason: the quotient times the divisor must give the dividend: <sup>ad</sup>/<sub>bc</sub> · <sup>c</sup>/<sub>d</sub> = <sup>a</sup>/<sub>b</sub>.'),
      L('<b>Darajaga ko‘tarish:</b> (<sup>a</sup>/<sub>b</sub>)<sup>n</sup> = <sup>a<sup>n</sup></sup>/<sub>b<sup>n</sup></sub>, chunki bu n ta bir xil kasrning ko‘paytmasi. Masalan, (<sup>2x</sup>/<sub>y<sup>2</sup></sub>)<sup>3</sup> = <sup>8x<sup>3</sup></sup>/<sub>y<sup>6</sup></sub>.', '<b>Возведение в степень:</b> (<sup>a</sup>/<sub>b</sub>)<sup>n</sup> = <sup>a<sup>n</sup></sup>/<sub>b<sup>n</sup></sub>, так как это произведение n одинаковых дробей. Например, (<sup>2x</sup>/<sub>y<sup>2</sup></sub>)<sup>3</sup> = <sup>8x<sup>3</sup></sup>/<sub>y<sup>6</sup></sub>.', '<b>Powers:</b> (<sup>a</sup>/<sub>b</sub>)<sup>n</sup> = <sup>a<sup>n</sup></sup>/<sub>b<sup>n</sup></sub>, because it is a product of n equal fractions. For example, (<sup>2x</sup>/<sub>y<sup>2</sup></sub>)<sup>3</sup> = <sup>8x<sup>3</sup></sup>/<sub>y<sup>6</sup></sub>.')
    ] },
    { kind: 'steps', h: L('Qanday tartibda ishlash kerak', 'Как действовать', 'How to proceed'), list: [
      L('<b>1.</b> Bo‘lishni teskari kasrga ko‘paytirish bilan almashtiring.', '<b>1.</b> Замените деление умножением на обратную дробь.', '<b>1.</b> Replace division by multiplication by the reciprocal.'),
      L('<b>2.</b> Barcha surat va maxrajlarni ko‘paytuvchilarga ajrating — qavslarni ochmang!', '<b>2.</b> Разложите все числители и знаменатели на множители — не раскрывайте скобки!', '<b>2.</b> Factorise every numerator and denominator — do not expand!'),
      L('<b>3.</b> Hammasini bitta kasr chizig‘i ostiga yozing va surat bilan maxrajdagi umumiy ko‘paytuvchilarni qisqartiring.', '<b>3.</b> Запишите всё под одной чертой и сократите общие множители числителя и знаменателя.', '<b>3.</b> Write everything over one fraction bar and cancel the common factors of top and bottom.'),
      L('<b>4.</b> Qolgan ko‘paytuvchilarni ko‘paytiring. Uzun ifodalarda amallar tartibiga rioya qiling: qavs ichidagilar, so‘ng ko‘paytirish va bo‘lish, oxirida qo‘shish va ayirish.', '<b>4.</b> Перемножьте оставшиеся множители. В длинных выражениях соблюдайте порядок действий: скобки, затем умножение и деление, в конце сложение и вычитание.', '<b>4.</b> Multiply the remaining factors. In long expressions keep the order of operations: brackets, then multiplication and division, finally addition and subtraction.')
    ], after: [
      L('Qisqartirishni ko‘paytirishdan <b>oldin</b> bajarish — eng muhim sir. Avval ko‘paytirib, keyin qisqartirmoqchi bo‘lsangiz, katta ko‘phadlarni qayta ko‘paytuvchilarga ajratishga to‘g‘ri keladi.', 'Главный секрет — сокращать <b>до</b> перемножения. Если сначала перемножить, потом придётся снова раскладывать большие многочлены.', 'The key secret is to cancel <b>before</b> multiplying out. If you multiply first, you will have to factorise large polynomials all over again.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('<sup>4x</sup>/<sub>y<sup>3</sup></sub> · <sup>y<sup>2</sup></sup>/<sub>10x<sup>2</sup></sub> = ?', '<sup>4x</sup>/<sub>y<sup>3</sup></sub> · <sup>y<sup>2</sup></sup>/<sub>10x<sup>2</sup></sub> = ?', '<sup>4x</sup>/<sub>y<sup>3</sup></sub> · <sup>y<sup>2</sup></sup>/<sub>10x<sup>2</sup></sub> = ?'),
        s: L('<sup>4x · y<sup>2</sup></sup>/<sub>y<sup>3</sup> · 10x<sup>2</sup></sub>. 2xy<sup>2</sup> ga qisqartiramiz: <sup>2</sup>/<sub>5xy</sub>.', '<sup>4x · y<sup>2</sup></sup>/<sub>y<sup>3</sup> · 10x<sup>2</sup></sub>. Сокращаем на 2xy<sup>2</sup>: <sup>2</sup>/<sub>5xy</sub>.', '<sup>4x · y<sup>2</sup></sup>/<sub>y<sup>3</sup> · 10x<sup>2</sup></sub>. Cancel 2xy<sup>2</sup>: <sup>2</sup>/<sub>5xy</sub>.') },
      { q: L('<sup>x<sup>2</sup> − 9</sup>/<sub>x</sub> : <sup>x − 3</sup>/<sub>x<sup>2</sup></sub> = ?', '<sup>x<sup>2</sup> − 9</sup>/<sub>x</sub> : <sup>x − 3</sup>/<sub>x<sup>2</sup></sub> = ?', '<sup>x<sup>2</sup> − 9</sup>/<sub>x</sub> : <sup>x − 3</sup>/<sub>x<sup>2</sup></sub> = ?'),
        s: L('<sup>(x − 3)(x + 3)</sup>/<sub>x</sub> · <sup>x<sup>2</sup></sup>/<sub>x − 3</sub> = x(x + 3), bunda x ≠ 0, x ≠ 3.', '<sup>(x − 3)(x + 3)</sup>/<sub>x</sub> · <sup>x<sup>2</sup></sup>/<sub>x − 3</sub> = x(x + 3), где x ≠ 0, x ≠ 3.', '<sup>(x − 3)(x + 3)</sup>/<sub>x</sub> · <sup>x<sup>2</sup></sup>/<sub>x − 3</sub> = x(x + 3), where x ≠ 0, x ≠ 3.') },
      { q: L('<sup>a<sup>2</sup> + 2a + 1</sup>/<sub>a<sup>2</sup> − 1</sub> · <sup>a − 1</sup>/<sub>3a + 3</sub> = ?', '<sup>a<sup>2</sup> + 2a + 1</sup>/<sub>a<sup>2</sup> − 1</sub> · <sup>a − 1</sup>/<sub>3a + 3</sub> = ?', '<sup>a<sup>2</sup> + 2a + 1</sup>/<sub>a<sup>2</sup> − 1</sub> · <sup>a − 1</sup>/<sub>3a + 3</sub> = ?'),
        s: L('<sup>(a + 1)<sup>2</sup></sup>/<sub>(a − 1)(a + 1)</sub> · <sup>a − 1</sup>/<sub>3(a + 1)</sub>. (a + 1)<sup>2</sup>(a − 1) qisqaradi, qoladi <sup>1</sup>/<sub>3</sub> (a ≠ ±1). Javob o‘zgaruvchiga bog‘liq emas!', '<sup>(a + 1)<sup>2</sup></sup>/<sub>(a − 1)(a + 1)</sub> · <sup>a − 1</sup>/<sub>3(a + 1)</sub>. Сокращается (a + 1)<sup>2</sup>(a − 1), остаётся <sup>1</sup>/<sub>3</sub> (a ≠ ±1). Ответ не зависит от переменной!', '<sup>(a + 1)<sup>2</sup></sup>/<sub>(a − 1)(a + 1)</sub> · <sup>a − 1</sup>/<sub>3(a + 1)</sub>. The factor (a + 1)<sup>2</sup>(a − 1) cancels, leaving <sup>1</sup>/<sub>3</sub> (a ≠ ±1). The answer does not depend on the variable!') }
    ] },
    { kind: 'example', h: L('Ayniyatni isbotlash', 'Доказательство тождества', 'Proving an identity'), p: [
      L('Ayniyatni isbotlashning odatiy usuli: chap tomonni ayniy almashtirishlar bilan o‘ng tomonga keltirish (yoki ikkala tomonni bir xil ifodaga keltirish). Har bir qadam ayniy bo‘lishi, ya’ni ruxsat etilgan qiymatlarda tenglikni saqlashi kerak.', 'Обычный способ доказать тождество — тождественными преобразованиями привести левую часть к правой (или обе части к одному выражению). Каждый шаг должен быть тождественным, то есть сохранять равенство при допустимых значениях.', 'The usual way to prove an identity is to transform the left side into the right side (or both sides into one expression) using identity transformations. Each step must keep equality for all permitted values.')
    ], ex: [
      { q: L('Isbotlang: (<sup>a</sup>/<sub>b</sub> − <sup>b</sup>/<sub>a</sub>) : <sup>a + b</sup>/<sub>ab</sub> = a − b.', 'Докажите: (<sup>a</sup>/<sub>b</sub> − <sup>b</sup>/<sub>a</sub>) : <sup>a + b</sup>/<sub>ab</sub> = a − b.', 'Prove: (<sup>a</sup>/<sub>b</sub> − <sup>b</sup>/<sub>a</sub>) ÷ <sup>a + b</sup>/<sub>ab</sub> = a − b.'),
        s: L('Qavs ichida: <sup>a<sup>2</sup> − b<sup>2</sup></sup>/<sub>ab</sub>. So‘ng: <sup>(a − b)(a + b)</sup>/<sub>ab</sub> · <sup>ab</sup>/<sub>a + b</sub> = a − b (a, b ≠ 0, a ≠ −b). Isbotlandi.', 'В скобках: <sup>a<sup>2</sup> − b<sup>2</sup></sup>/<sub>ab</sub>. Затем: <sup>(a − b)(a + b)</sup>/<sub>ab</sub> · <sup>ab</sup>/<sub>a + b</sub> = a − b (a, b ≠ 0, a ≠ −b). Доказано.', 'Inside the brackets: <sup>a<sup>2</sup> − b<sup>2</sup></sup>/<sub>ab</sub>. Then <sup>(a − b)(a + b)</sup>/<sub>ab</sub> · <sup>ab</sup>/<sub>a + b</sub> = a − b (a, b ≠ 0, a ≠ −b). Proved.') },
      { q: L('Soddalashtiring: (1 + <sup>1</sup>/<sub>x</sub>) · <sup>x<sup>2</sup></sup>/<sub>x<sup>2</sup> − 1</sub>.', 'Упростите: (1 + <sup>1</sup>/<sub>x</sub>) · <sup>x<sup>2</sup></sup>/<sub>x<sup>2</sup> − 1</sub>.', 'Simplify (1 + <sup>1</sup>/<sub>x</sub>) · <sup>x<sup>2</sup></sup>/<sub>x<sup>2</sup> − 1</sub>.'),
        s: L('<sup>x + 1</sup>/<sub>x</sub> · <sup>x<sup>2</sup></sup>/<sub>(x − 1)(x + 1)</sub> = <sup>x</sup>/<sub>x − 1</sub>, x ≠ 0, x ≠ ±1.', '<sup>x + 1</sup>/<sub>x</sub> · <sup>x<sup>2</sup></sup>/<sub>(x − 1)(x + 1)</sub> = <sup>x</sup>/<sub>x − 1</sub>, x ≠ 0, x ≠ ±1.', '<sup>x + 1</sup>/<sub>x</sub> · <sup>x<sup>2</sup></sup>/<sub>(x − 1)(x + 1)</sub> = <sup>x</sup>/<sub>x − 1</sub>, x ≠ 0, x ≠ ±1.') }
    ] },
    { kind: 'table', h: L('Amallar jadvali', 'Сводная таблица действий', 'Table of operations'), table: { head: [L('Amal', 'Действие', 'Operation'), L('Qoida', 'Правило', 'Rule'), L('Nima qilamiz', 'Что делаем', 'What we do')], rows: [
      [L('Qo‘shish', 'Сложение', 'Addition'), L('<sup>a</sup>/<sub>c</sub> + <sup>b</sup>/<sub>c</sub> = <sup>a + b</sup>/<sub>c</sub>', '<sup>a</sup>/<sub>c</sub> + <sup>b</sup>/<sub>c</sub> = <sup>a + b</sup>/<sub>c</sub>', '<sup>a</sup>/<sub>c</sub> + <sup>b</sup>/<sub>c</sub> = <sup>a + b</sup>/<sub>c</sub>'), L('umumiy maxraj kerak', 'нужен общий знаменатель', 'common denominator needed')],
      [L('Ko‘paytirish', 'Умножение', 'Multiplication'), L('<sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>', '<sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>', '<sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>'), L('surat · surat, maxraj · maxraj', 'числитель · числитель, знаменатель · знаменатель', 'top × top, bottom × bottom')],
      [L('Bo‘lish', 'Деление', 'Division'), L('<sup>a</sup>/<sub>b</sub> : <sup>c</sup>/<sub>d</sub> = <sup>ad</sup>/<sub>bc</sub>', '<sup>a</sup>/<sub>b</sub> : <sup>c</sup>/<sub>d</sub> = <sup>ad</sup>/<sub>bc</sub>', '<sup>a</sup>/<sub>b</sub> ÷ <sup>c</sup>/<sub>d</sub> = <sup>ad</sup>/<sub>bc</sub>'), L('teskari kasrga ko‘paytiramiz', 'умножаем на обратную', 'multiply by the reciprocal')],
      [L('Daraja', 'Степень', 'Power'), L('(<sup>a</sup>/<sub>b</sub>)<sup>n</sup> = <sup>a<sup>n</sup></sup>/<sub>b<sup>n</sup></sub>', '(<sup>a</sup>/<sub>b</sub>)<sup>n</sup> = <sup>a<sup>n</sup></sup>/<sub>b<sup>n</sup></sub>', '(<sup>a</sup>/<sub>b</sub>)<sup>n</sup> = <sup>a<sup>n</sup></sup>/<sub>b<sup>n</sup></sub>'), L('surat va maxraj alohida darajaga', 'числитель и знаменатель в степень', 'raise top and bottom separately')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Bo‘lishda birinchi kasrni ag‘darish.</b> Faqat <b>bo‘luvchi</b> (ikkinchi kasr) teskarisiga almashtiriladi.', '<b>Переворот не той дроби.</b> Переворачивается только <b>делитель</b> (вторая дробь).', '<b>Flipping the wrong fraction.</b> Only the <b>divisor</b> (the second fraction) is flipped.'),
      L('<b>Ko‘paytirishda umumiy maxrajga keltirish.</b> Bu xato emas, lekin ortiqcha ish: ko‘paytirishda umumiy maxraj kerak emas.', '<b>Приведение к общему знаменателю при умножении.</b> Не ошибка, но лишняя работа: при умножении общий знаменатель не нужен.', '<b>Finding a common denominator to multiply.</b> Not wrong, but wasted effort: multiplication needs no common denominator.'),
      L('<b>Avval qavslarni ochish.</b> Ko‘paytirishdan oldin qavslarni ochib yuborsangiz, umumiy ko‘paytuvchilar ko‘rinmay qoladi.', '<b>Раскрытие скобок раньше времени.</b> Если раскрыть скобки до сокращения, общие множители станут незаметны.', '<b>Expanding too early.</b> If you expand before cancelling, the common factors disappear from view.'),
      L('<b>Bo‘luvchining nollarini unutish.</b> <sup>a</sup>/<sub>b</sub> : <sup>x − 2</sup>/<sub>3</sub> da x ≠ 2 sharti ham kerak, chunki nolga bo‘lib bo‘lmaydi.', '<b>Забытые нули делителя.</b> В <sup>a</sup>/<sub>b</sub> : <sup>x − 2</sup>/<sub>3</sub> нужно ещё условие x ≠ 2: на нуль делить нельзя.', '<b>Forgetting zeros of the divisor.</b> In <sup>a</sup>/<sub>b</sub> ÷ <sup>x − 2</sup>/<sub>3</sub> we also need x ≠ 2, since we cannot divide by zero.'),
      L('<b>Darajada maxrajni unutish:</b> (<sup>x</sup>/<sub>3</sub>)<sup>2</sup> = <sup>x<sup>2</sup></sup>/<sub>9</sub>, <sup>x<sup>2</sup></sup>/<sub>3</sub> emas.', '<b>Забытый знаменатель при возведении в степень:</b> (<sup>x</sup>/<sub>3</sub>)<sup>2</sup> = <sup>x<sup>2</sup></sup>/<sub>9</sub>, а не <sup>x<sup>2</sup></sup>/<sub>3</sub>.', '<b>Forgetting the denominator in a power:</b> (<sup>x</sup>/<sub>3</sub>)<sup>2</sup> = <sup>x<sup>2</sup></sup>/<sub>9</sub>, not <sup>x<sup>2</sup></sup>/<sub>3</sub>.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Birliklarni almashtirish.</b> 72 km/soatni m/s ga o‘tkazish — bu kasrlarni ko‘paytirish: 72 · <sup>1000 m</sup>/<sub>1 km</sub> · <sup>1 soat</sup>/<sub>3600 s</sub> = 20 m/s. Birliklar xuddi harflar kabi qisqaradi!', '<b>Перевод единиц.</b> Перевести 72 км/ч в м/с — значит умножить дроби: 72 · <sup>1000 м</sup>/<sub>1 км</sub> · <sup>1 ч</sup>/<sub>3600 с</sub> = 20 м/с. Единицы сокращаются, как буквы!', '<b>Converting units.</b> Turning 72 km/h into m/s is fraction multiplication: 72 · <sup>1000 m</sup>/<sub>1 km</sub> · <sup>1 h</sup>/<sub>3600 s</sub> = 20 m/s. Units cancel just like letters!'),
      L('<b>Formulani o‘zgartirish.</b> Fizikada E = <sup>mv<sup>2</sup></sup>/<sub>2</sub> formulasidan massani topish uchun ikki tomonni <sup>v<sup>2</sup></sup>/<sub>2</sub> ga bo‘lamiz: m = <sup>2E</sup>/<sub>v<sup>2</sup></sub>. Bu ham kasrga bo‘lish.', '<b>Преобразование формул.</b> Чтобы из E = <sup>mv<sup>2</sup></sup>/<sub>2</sub> выразить массу, делим обе части на <sup>v<sup>2</sup></sup>/<sub>2</sub>: m = <sup>2E</sup>/<sub>v<sup>2</sup></sub>. Это тоже деление на дробь.', '<b>Rearranging formulas.</b> To get the mass from E = <sup>mv<sup>2</sup></sup>/<sub>2</sub>, divide both sides by <sup>v<sup>2</sup></sup>/<sub>2</sub>: m = <sup>2E</sup>/<sub>v<sup>2</sup></sub>. That too is dividing by a fraction.'),
      L('<b>Masshtab.</b> Xaritaning masshtabi 1 : 50 000 bo‘lsa, xaritadagi 3 sm joydagi 3 · 50 000 = 150 000 sm = 1,5 km ga teng. Ikkita masshtabni ketma-ket qo‘llash esa kasrlarni ko‘paytirishdir.', '<b>Масштаб.</b> При масштабе 1 : 50 000 три сантиметра на карте — это 150 000 см = 1,5 км на местности. Последовательное применение двух масштабов — это умножение дробей.', '<b>Scale.</b> On a 1 : 50,000 map, 3 cm stands for 150,000 cm = 1.5 km on the ground. Applying two scales one after another is multiplying fractions.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('«Ayniyat» belgisi ≡ ni 1857-yilda nemis matematigi Bernhard Riman taklif qilgan; ba’zan (a + b)<sup>2</sup> ≡ a<sup>2</sup> + 2ab + b<sup>2</sup> deb yoziladi.', 'Знак тождества ≡ предложил в 1857 году немецкий математик Бернхард Риман; иногда пишут (a + b)<sup>2</sup> ≡ a<sup>2</sup> + 2ab + b<sup>2</sup>.', 'The identity sign ≡ was introduced by the German mathematician Bernhard Riemann in 1857; sometimes we write (a + b)<sup>2</sup> ≡ a<sup>2</sup> + 2ab + b<sup>2</sup>.'),
      L('Bo‘lish belgisi «:» ni Gotfrid Leybnits 1684-yilda ommalashtirgan, «÷» belgisini esa shveytsariyalik Iogann Ran 1659-yilda ishlatgan.', 'Знак деления «:» популяризовал Готфрид Лейбниц в 1684 году, а знак «÷» использовал швейцарец Иоганн Ран в 1659 году.', 'The division sign “:” was popularised by Gottfried Leibniz in 1684, while the “÷” sign was used by the Swiss Johann Rahn in 1659.'),
      L('Teleskop kattalashtirishi ham kasrlar nisbati: obyektiv va okulyar fokus masofalarining nisbati. 1200 mm va 20 mm bo‘lsa — 60 marta.', 'Увеличение телескопа — тоже отношение: фокусных расстояний объектива и окуляра. При 1200 мм и 20 мм — в 60 раз.', 'A telescope’s magnification is also a ratio: objective focal length over eyepiece focal length. 1200 mm and 20 mm give 60×.')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('<sup>3a</sup>/<sub>b</sub> : <sup>9a<sup>2</sup></sup>/<sub>b<sup>2</sup></sub> = ?', '<sup>3a</sup>/<sub>b</sub> : <sup>9a<sup>2</sup></sup>/<sub>b<sup>2</sup></sub> = ?', '<sup>3a</sup>/<sub>b</sub> ÷ <sup>9a<sup>2</sup></sup>/<sub>b<sup>2</sup></sub> = ?'), s: L('<sup>3a · b<sup>2</sup></sup>/<sub>b · 9a<sup>2</sup></sub> = <sup>b</sup>/<sub>3a</sub>.', '<sup>3a · b<sup>2</sup></sup>/<sub>b · 9a<sup>2</sup></sub> = <sup>b</sup>/<sub>3a</sub>.', '<sup>3a · b<sup>2</sup></sup>/<sub>b · 9a<sup>2</sup></sub> = <sup>b</sup>/<sub>3a</sub>.') },
      { q: L('<sup>x<sup>2</sup> − 16</sup>/<sub>x + 4</sub> : (x − 4) = ?', '<sup>x<sup>2</sup> − 16</sup>/<sub>x + 4</sub> : (x − 4) = ?', '<sup>x<sup>2</sup> − 16</sup>/<sub>x + 4</sub> ÷ (x − 4) = ?'), s: L('<sup>(x − 4)(x + 4)</sup>/<sub>(x + 4)(x − 4)</sub> = 1, x ≠ ±4.', '<sup>(x − 4)(x + 4)</sup>/<sub>(x + 4)(x − 4)</sub> = 1, x ≠ ±4.', '<sup>(x − 4)(x + 4)</sup>/<sub>(x + 4)(x − 4)</sub> = 1, x ≠ ±4.') },
      { q: L('(<sup>3x</sup>/<sub>2y</sub>)<sup>2</sup> · <sup>4y</sup>/<sub>9x</sub> = ?', '(<sup>3x</sup>/<sub>2y</sub>)<sup>2</sup> · <sup>4y</sup>/<sub>9x</sub> = ?', '(<sup>3x</sup>/<sub>2y</sub>)<sup>2</sup> · <sup>4y</sup>/<sub>9x</sub> = ?'), s: L('<sup>9x<sup>2</sup></sup>/<sub>4y<sup>2</sup></sub> · <sup>4y</sup>/<sub>9x</sub> = <sup>x</sup>/<sub>y</sub>.', '<sup>9x<sup>2</sup></sup>/<sub>4y<sup>2</sup></sub> · <sup>4y</sup>/<sub>9x</sub> = <sup>x</sup>/<sub>y</sub>.', '<sup>9x<sup>2</sup></sup>/<sub>4y<sup>2</sup></sub> · <sup>4y</sup>/<sub>9x</sub> = <sup>x</sup>/<sub>y</sub>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ko‘paytirish: <sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>; umumiy maxraj kerak emas.', 'Умножение: <sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>; общий знаменатель не нужен.', 'Multiplication: <sup>a</sup>/<sub>b</sub> · <sup>c</sup>/<sub>d</sub> = <sup>ac</sup>/<sub>bd</sub>; no common denominator needed.'),
      L('Bo‘lish — teskari kasrga ko‘paytirish: <sup>a</sup>/<sub>b</sub> : <sup>c</sup>/<sub>d</sub> = <sup>ad</sup>/<sub>bc</sub>.', 'Деление — умножение на обратную: <sup>a</sup>/<sub>b</sub> : <sup>c</sup>/<sub>d</sub> = <sup>ad</sup>/<sub>bc</sub>.', 'Division is multiplication by the reciprocal: <sup>a</sup>/<sub>b</sub> ÷ <sup>c</sup>/<sub>d</sub> = <sup>ad</sup>/<sub>bc</sub>.'),
      L('Darajaga ko‘tarishda surat ham, maxraj ham darajaga ko‘tariladi.', 'При возведении в степень возводятся и числитель, и знаменатель.', 'In a power, both numerator and denominator are raised.'),
      L('Avval ko‘paytuvchilarga ajratib qisqartiramiz, keyin ko‘paytiramiz.', 'Сначала раскладываем и сокращаем, потом перемножаем.', 'Factorise and cancel first, multiply afterwards.'),
      L('Ayniyat barcha ruxsat etilgan qiymatlarda to‘g‘ri; uni bir tomonni ikkinchisiga ayniy almashtirishlar bilan keltirib isbotlaymiz.', 'Тождество верно при всех допустимых значениях; доказываем его, приводя одну часть к другой.', 'An identity holds for all permitted values; we prove it by transforming one side into the other.')
    ] }
  ] });

  // ---------- t4. y = k/x funksiya ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Biri oshsa, ikkinchisi kamayadi', 'Одно растёт — другое убывает', 'One goes up, the other goes down'), p: [
      L('Sinfingiz 24 ta olmani teng bo‘lib olmoqchi. 2 kishi bo‘lsa, har biriga 12 ta, 3 kishi bo‘lsa — 8 ta, 6 kishi bo‘lsa — 4 ta, 8 kishi bo‘lsa — 3 ta tegadi. Odamlar soni necha marta oshsa, har biriga tegadigan olma shuncha marta kamayadi. Bu bog‘lanish <b>teskari proporsionallik</b> deyiladi va y = <sup>24</sup>/<sub>x</sub> formula bilan yoziladi.', 'Класс хочет поровну разделить 24 яблока. Если людей 2 — каждому по 12, если 3 — по 8, если 6 — по 4, если 8 — по 3. Во сколько раз больше людей, во столько раз меньше яблок у каждого. Такая зависимость называется <b>обратной пропорциональностью</b> и записывается формулой y = <sup>24</sup>/<sub>x</sub>.', 'Your class wants to share 24 apples equally. With 2 people each gets 12, with 3 — 8, with 6 — 4, with 8 — 3. However many times the number of people grows, each share shrinks by the same factor. This relationship is called <b>inverse proportion</b> and is written y = <sup>24</sup>/<sub>x</sub>.'),
      L('7-sinfda siz y = kx (to‘g‘ri proporsionallik) funksiyasini o‘rgangansiz — uning grafigi koordinatalar boshidan o‘tuvchi to‘g‘ri chiziq. y = <sup>k</sup>/<sub>x</sub> funksiyaning grafigi esa butunlay boshqacha: u ikki bo‘lakdan iborat egri chiziq — <b>giperbola</b>. Bu mavzuda uning xossalarini, grafik chizishni va hayotdagi misollarini o‘rganamiz.', 'В 7 классе вы изучали функцию y = kx (прямую пропорциональность) — её график прямая через начало координат. График функции y = <sup>k</sup>/<sub>x</sub> совсем другой: это кривая из двух частей — <b>гипербола</b>. В этой теме изучим её свойства, построение графика и примеры из жизни.', 'In grade 7 you studied y = kx (direct proportion), whose graph is a straight line through the origin. The graph of y = <sup>k</sup>/<sub>x</sub> is completely different: a curve made of two pieces — a <b>hyperbola</b>. In this topic we study its properties, how to draw it and real-life examples.')
    ] },
    { kind: 'def', h: L('Ta’rif', 'Определение', 'Definition'), p: [
      L('y = <sup>k</sup>/<sub>x</sub> formula bilan berilgan funksiya, bunda k ≠ 0 — berilgan son, <b>teskari proporsionallik</b> deyiladi. k soni <b>proporsionallik koeffitsiyenti</b> deyiladi. Formuladan xy = k kelib chiqadi: x va y ning ko‘paytmasi doim o‘zgarmas.', 'Функция, заданная формулой y = <sup>k</sup>/<sub>x</sub>, где k ≠ 0 — заданное число, называется <b>обратной пропорциональностью</b>. Число k — <b>коэффициент обратной пропорциональности</b>. Из формулы следует xy = k: произведение x и y постоянно.', 'The function given by y = <sup>k</sup>/<sub>x</sub>, where k ≠ 0 is a fixed number, is called <b>inverse proportion</b>. The number k is the <b>coefficient of proportionality</b>. The formula gives xy = k: the product of x and y is constant.'),
      L('<b>Aniqlanish sohasi:</b> x ≠ 0 bo‘lgan barcha sonlar. <b>Qiymatlar sohasi:</b> y ≠ 0 bo‘lgan barcha sonlar, chunki <sup>k</sup>/<sub>x</sub> kasr k ≠ 0 bo‘lganda hech qachon nolga teng bo‘lmaydi. Grafigi <b>giperbola</b> deyiladi; u ikkita <b>tarmoq</b>dan iborat.', '<b>Область определения:</b> все числа, кроме x = 0. <b>Область значений:</b> все числа, кроме y = 0, так как дробь <sup>k</sup>/<sub>x</sub> при k ≠ 0 никогда не равна нулю. График называется <b>гиперболой</b> и состоит из двух <b>ветвей</b>.', '<b>Domain:</b> all numbers except x = 0. <b>Range:</b> all numbers except y = 0, because <sup>k</sup>/<sub>x</sub> with k ≠ 0 is never zero. The graph is called a <b>hyperbola</b> and has two <b>branches</b>.')
    ] },
    { kind: 'history', h: L('Tarixdan: konus kesimlaridan koordinatalargacha', 'Из истории: от конических сечений к координатам', 'From history: from conic sections to coordinates'), p: [
      L('«Giperbola» so‘zi yunoncha «hyperbolē» — «oshib ketish» degani. Bu nomni miloddan avvalgi III asrda <b>Apolloniy Pergskiy</b> «Konus kesimlari» kitobida bergan: giperbola konusni tekislik bilan kesganda hosil bo‘ladigan chiziqlardan biri. O‘rta asrlarda konus kesimlarini Sharq olimlari ham o‘rgangan: <b>Umar Xayyom</b> (XI–XII asrlar) kubik tenglamalarni aynan giperbola va parabolaning kesishish nuqtasi orqali geometrik yechgan.', 'Слово «гипербола» по-гречески означает «превышение». Это название дал в III веке до н. э. <b>Аполлоний Пергский</b> в книге «Конические сечения»: гипербола — одна из линий, получающихся при сечении конуса плоскостью. В Средние века конические сечения изучали и учёные Востока: <b>Омар Хайям</b> (XI–XII вв.) решал кубические уравнения геометрически — как точку пересечения гиперболы и параболы.', 'The word “hyperbola” comes from the Greek for “excess”. The name was given in the 3rd century BC by <b>Apollonius of Perga</b> in his “Conics”: the hyperbola is one of the curves obtained by cutting a cone with a plane. In the Middle Ages, scholars of the East studied conic sections too: <b>Omar Khayyam</b> (11th–12th centuries) solved cubic equations geometrically, as the intersection point of a hyperbola and a parabola.'),
      L('XVII asrda <b>Rene Dekart</b> koordinatalar usulini yaratgach, egri chiziqlarni tenglamalar bilan ifodalash mumkin bo‘ldi: giperbola xy = k tenglama bilan yoziladi. 1662-yilda ingliz olimi <b>Robert Boyl</b> gaz hajmi va bosimi o‘rtasidagi pV = const qonunini kashf etdi — tabiatdagi eng mashhur teskari proporsionallik.', 'В XVII веке, когда <b>Рене Декарт</b> создал метод координат, кривые стало можно задавать уравнениями: гипербола записывается как xy = k. В 1662 году англичанин <b>Роберт Бойль</b> открыл закон pV = const для объёма и давления газа — самую известную обратную пропорциональность в природе.', 'In the 17th century, after <b>René Descartes</b> created coordinate geometry, curves could be described by equations: a hyperbola is written xy = k. In 1662 the English scientist <b>Robert Boyle</b> discovered the law pV = const for the pressure and volume of a gas — the most famous inverse proportion in nature.')
    ] },
    { kind: 'rule', h: L('Funksiyaning xossalari', 'Свойства функции', 'Properties of the function'), list: [
      L('<b>k &gt; 0</b> bo‘lsa, grafik I va III choraklarda joylashadi (x va y bir xil ishorali); har bir oraliqda (x &lt; 0 va x &gt; 0) funksiya <b>kamayadi</b>.', '<b>При k &gt; 0</b> график лежит в I и III четвертях (x и y одного знака); на каждом промежутке (x &lt; 0 и x &gt; 0) функция <b>убывает</b>.', '<b>If k &gt; 0</b>, the graph lies in quadrants I and III (x and y have the same sign); on each interval (x &lt; 0 and x &gt; 0) the function <b>decreases</b>.'),
      L('<b>k &lt; 0</b> bo‘lsa, grafik II va IV choraklarda (x va y har xil ishorali); har bir oraliqda funksiya <b>o‘sadi</b>.', '<b>При k &lt; 0</b> график во II и IV четвертях (x и y разных знаков); на каждом промежутке функция <b>возрастает</b>.', '<b>If k &lt; 0</b>, the graph is in quadrants II and IV (x and y of opposite signs); on each interval the function <b>increases</b>.'),
      L('Grafik koordinata o‘qlarini kesmaydi: x = 0 da funksiya aniqlanmagan, y esa 0 ga teng bo‘lolmaydi. x katta bo‘lgani sari tarmoq Ox o‘qiga cheksiz yaqinlashadi, x nolga yaqinlashganda esa Oy o‘qiga. Bu o‘qlar giperbolaning <b>asimptotalari</b> deyiladi.', 'График не пересекает оси: при x = 0 функция не определена, а y не может быть 0. С ростом |x| ветвь неограниченно приближается к оси Ox, а при x → 0 — к оси Oy. Эти оси называются <b>асимптотами</b> гиперболы.', 'The graph never meets the axes: at x = 0 the function is undefined and y can never be 0. As |x| grows, a branch gets arbitrarily close to the x-axis, and as x approaches 0 it hugs the y-axis. These axes are the hyperbola’s <b>asymptotes</b>.'),
      L('Funksiya <b>toq</b>: <sup>k</sup>/<sub>−x</sub> = −<sup>k</sup>/<sub>x</sub>. Shuning uchun giperbola koordinatalar boshiga nisbatan <b>simmetrik</b>: (a; b) nuqta grafikda bo‘lsa, (−a; −b) ham grafikda.', 'Функция <b>нечётная</b>: <sup>k</sup>/<sub>−x</sub> = −<sup>k</sup>/<sub>x</sub>. Поэтому гипербола <b>симметрична</b> относительно начала координат: если (a; b) на графике, то и (−a; −b) тоже.', 'The function is <b>odd</b>: <sup>k</sup>/<sub>−x</sub> = −<sup>k</sup>/<sub>x</sub>. So the hyperbola is <b>symmetric</b> about the origin: if (a; b) is on the graph, so is (−a; −b).')
    ], after: [
      L('<b>Nega k &gt; 0 da kamayadi?</b> 0 &lt; x<sub>1</sub> &lt; x<sub>2</sub> bo‘lsin. y<sub>1</sub> − y<sub>2</sub> = <sup>k</sup>/<sub>x<sub>1</sub></sub> − <sup>k</sup>/<sub>x<sub>2</sub></sub> = <sup>k(x<sub>2</sub> − x<sub>1</sub>)</sup>/<sub>x<sub>1</sub>x<sub>2</sub></sub> &gt; 0, chunki surat va maxraj musbat. Demak, y<sub>1</sub> &gt; y<sub>2</sub>.', '<b>Почему при k &gt; 0 убывает?</b> Пусть 0 &lt; x<sub>1</sub> &lt; x<sub>2</sub>. y<sub>1</sub> − y<sub>2</sub> = <sup>k</sup>/<sub>x<sub>1</sub></sub> − <sup>k</sup>/<sub>x<sub>2</sub></sub> = <sup>k(x<sub>2</sub> − x<sub>1</sub>)</sup>/<sub>x<sub>1</sub>x<sub>2</sub></sub> &gt; 0, так как числитель и знаменатель положительны. Значит, y<sub>1</sub> &gt; y<sub>2</sub>.', '<b>Why does it decrease when k &gt; 0?</b> Let 0 &lt; x<sub>1</sub> &lt; x<sub>2</sub>. Then y<sub>1</sub> − y<sub>2</sub> = <sup>k</sup>/<sub>x<sub>1</sub></sub> − <sup>k</sup>/<sub>x<sub>2</sub></sub> = <sup>k(x<sub>2</sub> − x<sub>1</sub>)</sup>/<sub>x<sub>1</sub>x<sub>2</sub></sub> &gt; 0, as top and bottom are positive. Hence y<sub>1</sub> &gt; y<sub>2</sub>.')
    ] },
    { kind: 'steps', h: L('Giperbolani qanday chizish kerak', 'Как построить гиперболу', 'How to draw a hyperbola'), list: [
      L('<b>1.</b> k ning ishorasiga qarab, tarmoqlar qaysi choraklarda bo‘lishini aniqlang.', '<b>1.</b> По знаку k определите, в каких четвертях будут ветви.', '<b>1.</b> Use the sign of k to decide which quadrants the branches occupy.'),
      L('<b>2.</b> x &gt; 0 uchun qiymatlar jadvalini tuzing; k ning bo‘luvchilarini tanlash qulay (y butun chiqadi).', '<b>2.</b> Составьте таблицу значений для x &gt; 0; удобно брать делители k (тогда y целое).', '<b>2.</b> Make a table of values for x &gt; 0; divisors of k are convenient (y comes out whole).'),
      L('<b>3.</b> Nuqtalarni belgilab, ularni silliq egri chiziq bilan tutashtiring — siniq chiziq bilan emas! Chiziq o‘qlarga yaqinlashadi, lekin ularga tegmaydi.', '<b>3.</b> Отметьте точки и соедините их плавной кривой — не ломаной! Кривая приближается к осям, но не касается их.', '<b>3.</b> Plot the points and join them with a smooth curve — not a broken line! The curve approaches the axes but never touches them.'),
      L('<b>4.</b> Ikkinchi tarmoqni simmetriya bo‘yicha chizing: har bir (a; b) nuqtaga (−a; −b) mos keladi.', '<b>4.</b> Вторую ветвь постройте по симметрии: каждой точке (a; b) соответствует (−a; −b).', '<b>4.</b> Draw the second branch by symmetry: each point (a; b) has a partner (−a; −b).')
    ] },
    { kind: 'table', h: L('y = 6/x uchun qiymatlar jadvali', 'Таблица значений для y = 6/x', 'Table of values for y = 6/x'), table: { head: [L('x', 'x', 'x'), L('y = <sup>6</sup>/<sub>x</sub>', 'y = <sup>6</sup>/<sub>x</sub>', 'y = <sup>6</sup>/<sub>x</sub>'), L('Nuqta', 'Точка', 'Point')], rows: [
      ['0,5', '12', L('(0,5; 12)', '(0,5; 12)', '(0.5; 12)')], ['1', '6', '(1; 6)'], ['2', '3', '(2; 3)'], ['3', '2', '(3; 2)'], ['6', '1', '(6; 1)'], ['12', '0,5', L('(12; 0,5)', '(12; 0,5)', '(12; 0.5)')], ['−2', '−3', '(−2; −3)'], ['−6', '−1', '(−6; −1)']
    ] }, after: [
      L('Har bir qatorda x · y = 6. x ikki marta oshganda (1 → 2), y ikki marta kamayadi (6 → 3) — teskari proporsionallikning asosiy belgisi.', 'В каждой строке x · y = 6. Когда x увеличивается вдвое (1 → 2), y уменьшается вдвое (6 → 3) — главный признак обратной пропорциональности.', 'In every row x · y = 6. When x doubles (1 → 2), y halves (6 → 3) — the hallmark of inverse proportion.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Giperbola A(−3; 4) nuqtadan o‘tadi. k ni toping va funksiyaning x = 6 dagi qiymatini hisoblang.', 'Гипербола проходит через A(−3; 4). Найдите k и значение функции при x = 6.', 'A hyperbola passes through A(−3; 4). Find k and the value of the function at x = 6.'),
        s: L('k = xy = (−3) · 4 = −12. y = −<sup>12</sup>/<sub>x</sub>; x = 6 da y = −2. k &lt; 0, grafik II va IV choraklarda.', 'k = xy = (−3) · 4 = −12. y = −<sup>12</sup>/<sub>x</sub>; при x = 6 y = −2. k &lt; 0, график во II и IV четвертях.', 'k = xy = (−3) · 4 = −12. y = −<sup>12</sup>/<sub>x</sub>; at x = 6, y = −2. Since k &lt; 0, the graph is in quadrants II and IV.') },
      { q: L('B(5; −1,6) nuqta y = −<sup>8</sup>/<sub>x</sub> grafigiga tegishlimi?', 'Принадлежит ли точка B(5; −1,6) графику y = −<sup>8</sup>/<sub>x</sub>?', 'Does B(5; −1.6) lie on y = −<sup>8</sup>/<sub>x</sub>?'),
        s: L('x = 5 da y = −<sup>8</sup>/<sub>5</sub> = −1,6. Ha, tegishli. Boshqa usul: xy = 5 · (−1,6) = −8 = k.', 'При x = 5 y = −<sup>8</sup>/<sub>5</sub> = −1,6. Да, принадлежит. Другой способ: xy = 5 · (−1,6) = −8 = k.', 'At x = 5, y = −<sup>8</sup>/<sub>5</sub> = −1.6. Yes, it does. Another way: xy = 5 · (−1.6) = −8 = k.') },
      { q: L('6 ta ishchi ishni 10 kunda bajaradi. 15 ta ishchi uni necha kunda bajaradi?', '6 рабочих выполняют работу за 10 дней. За сколько дней её выполнят 15 рабочих?', '6 workers finish a job in 10 days. How many days will 15 workers need?'),
        s: L('Ish hajmi o‘zgarmas: n · t = 6 · 10 = 60 (kishi-kun). t = <sup>60</sup>/<sub>n</sub>; n = 15 da t = 4 kun.', 'Объём работы постоянен: n · t = 6 · 10 = 60 (человеко-дней). t = <sup>60</sup>/<sub>n</sub>; при n = 15 t = 4 дня.', 'The amount of work is fixed: n · t = 6 · 10 = 60 worker-days. t = <sup>60</sup>/<sub>n</sub>; for n = 15, t = 4 days.') },
      { q: L('y = <sup>4</sup>/<sub>x</sub> va y = x grafiklarining kesishish nuqtalarini toping.', 'Найдите точки пересечения графиков y = <sup>4</sup>/<sub>x</sub> и y = x.', 'Find where y = <sup>4</sup>/<sub>x</sub> and y = x meet.'),
        s: L('<sup>4</sup>/<sub>x</sub> = x ⇒ x<sup>2</sup> = 4 ⇒ x = ±2. Nuqtalar: (2; 2) va (−2; −2). Ular simmetrik — giperbolaning simmetriyasiga mos.', '<sup>4</sup>/<sub>x</sub> = x ⇒ x<sup>2</sup> = 4 ⇒ x = ±2. Точки: (2; 2) и (−2; −2). Они симметричны — как и сама гипербола.', '<sup>4</sup>/<sub>x</sub> = x ⇒ x<sup>2</sup> = 4 ⇒ x = ±2. Points: (2; 2) and (−2; −2). They are symmetric — just like the hyperbola itself.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Grafikni o‘q bilan kesishtirish.</b> Giperbola hech qachon Ox va Oy o‘qlariga tegmaydi; x = 0 da nuqta yo‘q.', '<b>Пересечение графика с осями.</b> Гипербола никогда не касается осей Ox и Oy; при x = 0 точки нет.', '<b>Making the graph cross the axes.</b> A hyperbola never touches the x- or y-axis; there is no point at x = 0.'),
      L('<b>Ikki tarmoqni tutashtirish.</b> Chap va o‘ng tarmoqlar alohida; ularni chiziq bilan ulash xato.', '<b>Соединение двух ветвей.</b> Левая и правая ветви отдельны; соединять их линией — ошибка.', '<b>Joining the two branches.</b> The left and right branches are separate; connecting them with a line is wrong.'),
      L('<b>«Butun sohada kamayadi».</b> y = <sup>1</sup>/<sub>x</sub> uchun −1 &lt; 1, lekin y(−1) = −1 &lt; y(1) = 1. Funksiya har bir oraliqda alohida kamayadi, butun aniqlanish sohasida emas.', '<b>«Убывает на всей области».</b> Для y = <sup>1</sup>/<sub>x</sub>: −1 &lt; 1, но y(−1) = −1 &lt; y(1) = 1. Функция убывает на каждом промежутке отдельно, но не на всей области.', '<b>“Decreasing everywhere.”</b> For y = <sup>1</sup>/<sub>x</sub>: −1 &lt; 1 yet y(−1) = −1 &lt; y(1) = 1. The function decreases on each interval separately, not on the whole domain.'),
      L('<b>Teskari va to‘g‘ri proporsionallikni chalkashtirish.</b> «Biri kamayadi, ikkinchisi ham kamayadi» — bu to‘g‘ri proporsionallik. Teskarida esa ko‘paytma o‘zgarmaydi.', '<b>Путаница прямой и обратной пропорциональности.</b> «Одно уменьшается — и другое уменьшается» — это прямая. В обратной постоянно произведение.', '<b>Mixing up direct and inverse proportion.</b> “Both decrease together” is direct proportion. In inverse proportion the product stays constant.')
    ] },
    { kind: 'life', h: L('Hayotdagi teskari proporsionallik', 'Обратная пропорциональность в жизни', 'Inverse proportion in life'), p: [
      L('<b>Yo‘l va tezlik.</b> Toshkentdan Samarqandgacha taxminan 300 km. Vaqt t = <sup>300</sup>/<sub>v</sub>: 60 km/soat tezlikda 5 soat, «Afrosiyob» poyezdida o‘rtacha 150 km/soat bilan 2 soat.', '<b>Путь и скорость.</b> От Ташкента до Самарканда около 300 км. Время t = <sup>300</sup>/<sub>v</sub>: при 60 км/ч — 5 часов, на поезде «Афросиаб» со средней скоростью 150 км/ч — 2 часа.', '<b>Distance and speed.</b> Tashkent to Samarkand is about 300 km. Time t = <sup>300</sup>/<sub>v</sub>: 5 hours at 60 km/h, 2 hours on the “Afrosiyob” train at an average of 150 km/h.'),
      L('<b>Gaz qonuni.</b> Velosiped nasosida porshenni bosganingizda havo hajmi kamayadi, bosim esa oshadi: pV = const (Boyl–Mariott qonuni). <b>Richag:</b> muvozanatda F · l = const — uzunroq dastak bilan kamroq kuch kerak. <b>Yorug‘lik:</b> fotoapparatda ekspozitsiya vaqti diafragma yuzasiga teskari proporsional.', '<b>Газовый закон.</b> Когда вы нажимаете на поршень велосипедного насоса, объём воздуха уменьшается, а давление растёт: pV = const (закон Бойля — Мариотта). <b>Рычаг:</b> в равновесии F · l = const — с длинной рукояткой нужна меньшая сила. <b>Свет:</b> в фотоаппарате выдержка обратно пропорциональна площади отверстия диафрагмы.', '<b>Gas law.</b> When you push a bicycle pump, the air volume drops and the pressure rises: pV = const (Boyle’s law). <b>Levers:</b> in balance, F · l = const — a longer handle needs less force. <b>Light:</b> in a camera, exposure time is inversely proportional to the aperture area.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Giperbola shaklini ko‘rish oson: lampa abajurining soyasi devorda ko‘pincha giperbola bo‘lib tushadi.', 'Форму гиперболы легко увидеть: тень от абажура лампы на стене часто имеет форму гиперболы.', 'You can easily see a hyperbola: the shadow of a lampshade on a wall is often a hyperbola.'),
      L('Ba’zi kometalar Quyosh atrofida giperbola bo‘ylab harakatlanadi va Quyosh sistemasini butunlay tark etadi. 2017-yilda topilgan «Oumuamua» aynan shunday mehmon edi.', 'Некоторые кометы движутся вокруг Солнца по гиперболе и навсегда покидают Солнечную систему. Найденный в 2017 году «Оумуамуа» был именно таким гостем.', 'Some comets move past the Sun along a hyperbola and leave the Solar System for good. ‘Oumuamua, found in 2017, was exactly such a visitor.'),
      L('Atom elektr stansiyalarining sovutish minoralari «giperboloid» shaklida quriladi — bu shakl mustahkam va kam material talab qiladi. Bunday konstruksiyalarni birinchi bo‘lib rus muhandisi Vladimir Shuxov qurgan.', 'Градирни электростанций строят в форме «гиперболоида» — она прочная и экономит материал. Первым такие конструкции строил русский инженер Владимир Шухов.', 'Cooling towers of power stations are built as “hyperboloids” — a strong shape that saves material. The Russian engineer Vladimir Shukhov was the first to build such structures.')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('y = <sup>15</sup>/<sub>x</sub>, x = −5. y = ?', 'y = <sup>15</sup>/<sub>x</sub>, x = −5. y = ?', 'y = <sup>15</sup>/<sub>x</sub>, x = −5. y = ?'), s: L('y = −3.', 'y = −3.', 'y = −3.') },
      { q: L('y = <sup>k</sup>/<sub>x</sub> grafigi (2; −7) dan o‘tadi. Qaysi choraklarda joylashgan?', 'График y = <sup>k</sup>/<sub>x</sub> проходит через (2; −7). В каких он четвертях?', 'The graph of y = <sup>k</sup>/<sub>x</sub> passes through (2; −7). Which quadrants is it in?'), s: L('k = −14 &lt; 0, II va IV choraklarda.', 'k = −14 &lt; 0, во II и IV четвертях.', 'k = −14 &lt; 0, quadrants II and IV.') },
      { q: L('y = <sup>2</sup>/<sub>x</sub> funksiyada x = 1 dan x = 4 ga o‘tganda y qanday o‘zgaradi?', 'Как изменится y = <sup>2</sup>/<sub>x</sub> при переходе от x = 1 к x = 4?', 'How does y = <sup>2</sup>/<sub>x</sub> change when x goes from 1 to 4?'), s: L('2 dan 0,5 ga — 4 marta kamayadi.', 'С 2 до 0,5 — уменьшится в 4 раза.', 'From 2 to 0.5 — it becomes 4 times smaller.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('y = <sup>k</sup>/<sub>x</sub> (k ≠ 0) — teskari proporsionallik; xy = k.', 'y = <sup>k</sup>/<sub>x</sub> (k ≠ 0) — обратная пропорциональность; xy = k.', 'y = <sup>k</sup>/<sub>x</sub> (k ≠ 0) is inverse proportion; xy = k.'),
      L('Aniqlanish sohasi x ≠ 0, qiymatlar sohasi y ≠ 0.', 'Область определения x ≠ 0, область значений y ≠ 0.', 'Domain x ≠ 0, range y ≠ 0.'),
      L('Grafik — giperbola: k &gt; 0 da I va III, k &lt; 0 da II va IV choraklarda.', 'График — гипербола: при k &gt; 0 в I и III, при k &lt; 0 во II и IV четвертях.', 'The graph is a hyperbola: in quadrants I and III if k &gt; 0, in II and IV if k &lt; 0.'),
      L('k &gt; 0 da har bir oraliqda kamayadi, k &lt; 0 da o‘sadi.', 'При k &gt; 0 убывает на каждом промежутке, при k &lt; 0 — возрастает.', 'For k &gt; 0 it decreases on each interval; for k &lt; 0 it increases.'),
      L('Giperbola koordinatalar boshiga nisbatan simmetrik, o‘qlar — uning asimptotalari.', 'Гипербола симметрична относительно начала координат, оси — её асимптоты.', 'The hyperbola is symmetric about the origin, and the axes are its asymptotes.'),
      L('k ni bitta nuqta orqali topamiz: k = x<sub>0</sub>y<sub>0</sub>.', 'k находим по одной точке: k = x<sub>0</sub>y<sub>0</sub>.', 'Find k from one point: k = x<sub>0</sub>y<sub>0</sub>.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t5. Natural ko'rsatkichli arifmetik ildiz ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Darajaga teskari amal', 'Действие, обратное степени', 'Undoing a power'), p: [
      L('Qo‘shishga teskari amal — ayirish, ko‘paytirishga teskari amal — bo‘lish. Darajaga ko‘tarishga teskari amal nima? Agar kubning hajmi 64 sm<sup>3</sup> bo‘lsa, uning qirrasi qancha? Bizga shunday son kerakki, uning kubi 64 bo‘lsin: 4<sup>3</sup> = 64, demak qirra 4 sm. Bu amal <b>ildiz chiqarish</b> deyiladi va ∛64 = 4 deb yoziladi.', 'Обратное действие к сложению — вычитание, к умножению — деление. А что обратно возведению в степень? Если объём куба 64 см<sup>3</sup>, какое у него ребро? Нужно число, куб которого равен 64: 4<sup>3</sup> = 64, значит ребро 4 см. Это действие называется <b>извлечением корня</b> и записывается ∛64 = 4.', 'The inverse of addition is subtraction, the inverse of multiplication is division. What undoes raising to a power? If a cube has volume 64 cm<sup>3</sup>, how long is its edge? We need a number whose cube is 64: 4<sup>3</sup> = 64, so the edge is 4 cm. This operation is called <b>taking a root</b> and is written ∛64 = 4.'),
      L('Kvadrat ildizni siz avval ham uchratgansiz: kvadrat yuzi 49 m<sup>2</sup> bo‘lsa, tomoni √49 = 7 m. Endi ildiz tushunchasini istalgan natural darajaga umumlashtiramiz: kub ildiz, to‘rtinchi daraja ildizi va hokazo. Shuningdek, ildizlarning xossalarini isbotlaymiz va ular yordamida ifodalarni soddalashtirishni o‘rganamiz.', 'С квадратным корнем вы уже встречались: если площадь квадрата 49 м<sup>2</sup>, то сторона √49 = 7 м. Теперь обобщим понятие корня на любую натуральную степень: кубический корень, корень четвёртой степени и так далее. Мы также докажем свойства корней и научимся с их помощью упрощать выражения.', 'You have met the square root already: a square of area 49 m<sup>2</sup> has side √49 = 7 m. Now we extend the idea to any natural power: cube roots, fourth roots and so on. We also prove the properties of roots and learn to use them to simplify expressions.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), p: [
      L('a sonning <b>n-darajali ildizi</b> deb, n-darajasi a ga teng bo‘lgan songa aytiladi (n ≥ 2 — natural son). Masalan, 3 va −3 sonlari 81 ning to‘rtinchi darajali ildizlari, chunki 3<sup>4</sup> = (−3)<sup>4</sup> = 81.', '<b>Корнем n-й степени</b> из числа a называется число, n-я степень которого равна a (n ≥ 2 — натуральное). Например, 3 и −3 — корни четвёртой степени из 81, так как 3<sup>4</sup> = (−3)<sup>4</sup> = 81.', 'An <b>n-th root</b> of a number a is a number whose n-th power equals a (n ≥ 2 is natural). For example, 3 and −3 are fourth roots of 81, because 3<sup>4</sup> = (−3)<sup>4</sup> = 81.'),
      L('Bir ma’nolilik uchun <b>arifmetik ildiz</b> kiritiladi: manfiy bo‘lmagan a sonning n-darajali arifmetik ildizi — n-darajasi a ga teng bo‘lgan <b>manfiy bo‘lmagan</b> son. U <sup>n</sup>√a bilan belgilanadi; n — <b>ildiz ko‘rsatkichi</b>, a — <b>ildiz ostidagi ifoda</b>. Demak, <sup>4</sup>√81 = 3 (−3 emas). Ta’rifdan: a ≥ 0 da <sup>n</sup>√a ≥ 0 va (<sup>n</sup>√a)<sup>n</sup> = a.', 'Для однозначности вводят <b>арифметический корень</b>: арифметический корень n-й степени из неотрицательного a — это <b>неотрицательное</b> число, n-я степень которого равна a. Обозначение <sup>n</sup>√a; n — <b>показатель корня</b>, a — <b>подкоренное выражение</b>. Значит, <sup>4</sup>√81 = 3 (а не −3). Из определения: при a ≥ 0 <sup>n</sup>√a ≥ 0 и (<sup>n</sup>√a)<sup>n</sup> = a.', 'To make the answer unique we define the <b>arithmetic root</b>: the arithmetic n-th root of a non-negative a is the <b>non-negative</b> number whose n-th power is a. It is written <sup>n</sup>√a; n is the <b>index</b> and a the <b>radicand</b>. So <sup>4</sup>√81 = 3 (not −3). By definition, for a ≥ 0: <sup>n</sup>√a ≥ 0 and (<sup>n</sup>√a)<sup>n</sup> = a.'),
      L('<b>Toq ko‘rsatkichli ildiz</b> manfiy sondan ham chiqariladi: ∛(−8) = −2, chunki (−2)<sup>3</sup> = −8. Umuman, toq n uchun <sup>n</sup>√(−a) = −<sup>n</sup>√a. <b>Juft ko‘rsatkichli</b> ildiz esa manfiy sondan mavjud emas: hech qanday sonning kvadrati −4 ga teng emas.', '<b>Корень нечётной степени</b> извлекается и из отрицательного числа: ∛(−8) = −2, так как (−2)<sup>3</sup> = −8. Вообще, при нечётном n <sup>n</sup>√(−a) = −<sup>n</sup>√a. <b>Корня чётной степени</b> из отрицательного числа не существует: квадрат никакого числа не равен −4.', 'A <b>root of odd index</b> can be taken of a negative number: ∛(−8) = −2, since (−2)<sup>3</sup> = −8. In general, for odd n, <sup>n</sup>√(−a) = −<sup>n</sup>√a. A <b>root of even index</b> of a negative number does not exist: no number squared gives −4.')
    ] },
    { kind: 'history', h: L('Tarixdan: ildiz belgisi qanday paydo bo‘lgan', 'Из истории: как появился знак корня', 'From history: where the root sign came from'), p: [
      L('Bobilliklar 4000 yil oldin √2 ni 1,414213 aniqlikda bilgan — bu YBC 7289 loy taxtachasida saqlangan. <b>Al-Xorazmiy</b> ildizni arabcha «jazr» — «o‘simlik ildizi» deb atagan: son go‘yo o‘z kvadratidan «o‘sib chiqadi». Bu so‘z lotinchaga «radix» deb tarjima qilindi, «radikal» atamasi shundan.', 'Вавилоняне 4000 лет назад знали √2 с точностью 1,414213 — это сохранилось на глиняной табличке YBC 7289. <b>Аль-Хорезми</b> называл корень арабским словом «джизр» — «корень растения»: число как бы «вырастает» из своего квадрата. На латынь это перевели как «radix», отсюда термин «радикал».', 'The Babylonians knew √2 as 1.414213 some 4000 years ago — it is preserved on the clay tablet YBC 7289. <b>Al-Khwarizmi</b> called the root “jidhr”, the root of a plant: the number seems to “grow out” of its square. This was translated into Latin as “radix”, which gives us the word “radical”.'),
      L('O‘rta asrlarda ildizni «r» harfi bilan belgilashgan. 1525-yilda nemis matematigi <b>Kristof Rudolf</b> «Coss» kitobida bugungi √ belgisiga o‘xshash belgini ishlatdi — u, ehtimol, kichik «r» harfining o‘zgargan shakli. 1637-yilda <b>Rene Dekart</b> belgiga ustki chiziq qo‘shib, ildiz ostidagi ifodani ajratib ko‘rsatdi. <b>Al-Koshiy</b> esa XV asrda Samarqandda istalgan darajadagi ildizni chiqarish algoritmini bayon qilgan.', 'В Средние века корень обозначали буквой «r». В 1525 году немецкий математик <b>Кристоф Рудольф</b> в книге «Coss» использовал знак, похожий на современный √, — вероятно, видоизменённую маленькую «r». В 1637 году <b>Рене Декарт</b> добавил к нему черту сверху, выделяющую подкоренное выражение. А <b>аль-Каши</b> в XV веке в Самарканде описал алгоритм извлечения корня любой степени.', 'In the Middle Ages the root was marked with the letter “r”. In 1525 the German mathematician <b>Christoph Rudolff</b> used a sign like today’s √ in his book “Coss” — probably a modified small “r”. In 1637 <b>René Descartes</b> added the bar on top to mark off the radicand. And in 15th-century Samarkand, <b>al-Kashi</b> described an algorithm for extracting roots of any degree.')
    ] },
    { kind: 'rule', h: L('Arifmetik ildizning xossalari', 'Свойства арифметического корня', 'Properties of arithmetic roots'), p: [
      L('a ≥ 0, b ≥ 0 (bo‘lishda b &gt; 0), n, m, k — natural sonlar (n, m ≥ 2) bo‘lsin. U holda:', 'Пусть a ≥ 0, b ≥ 0 (при делении b &gt; 0), n, m, k — натуральные (n, m ≥ 2). Тогда:', 'Let a ≥ 0, b ≥ 0 (b &gt; 0 when dividing), and n, m, k natural (n, m ≥ 2). Then:')
    ], list: [
      L('<b>1.</b> <sup>n</sup>√(ab) = <sup>n</sup>√a · <sup>n</sup>√b — ko‘paytmaning ildizi.', '<b>1.</b> <sup>n</sup>√(ab) = <sup>n</sup>√a · <sup>n</sup>√b — корень из произведения.', '<b>1.</b> <sup>n</sup>√(ab) = <sup>n</sup>√a · <sup>n</sup>√b — root of a product.'),
      L('<b>2.</b> <sup>n</sup>√(<sup>a</sup>/<sub>b</sub>) = <sup>n</sup>√a / <sup>n</sup>√b — bo‘linmaning ildizi.', '<b>2.</b> <sup>n</sup>√(<sup>a</sup>/<sub>b</sub>) = <sup>n</sup>√a / <sup>n</sup>√b — корень из частного.', '<b>2.</b> <sup>n</sup>√(<sup>a</sup>/<sub>b</sub>) = <sup>n</sup>√a / <sup>n</sup>√b — root of a quotient.'),
      L('<b>3.</b> (<sup>n</sup>√a)<sup>k</sup> = <sup>n</sup>√(a<sup>k</sup>) — ildizni darajaga ko‘tarish.', '<b>3.</b> (<sup>n</sup>√a)<sup>k</sup> = <sup>n</sup>√(a<sup>k</sup>) — возведение корня в степень.', '<b>3.</b> (<sup>n</sup>√a)<sup>k</sup> = <sup>n</sup>√(a<sup>k</sup>) — power of a root.'),
      L('<b>4.</b> <sup>m</sup>√(<sup>n</sup>√a) = <sup>mn</sup>√a — ildizdan ildiz.', '<b>4.</b> <sup>m</sup>√(<sup>n</sup>√a) = <sup>mn</sup>√a — корень из корня.', '<b>4.</b> <sup>m</sup>√(<sup>n</sup>√a) = <sup>mn</sup>√a — root of a root.'),
      L('<b>5.</b> <sup>nk</sup>√(a<sup>mk</sup>) = <sup>n</sup>√(a<sup>m</sup>) — ko‘rsatkichlarni bir xil songa qisqartirish mumkin.', '<b>5.</b> <sup>nk</sup>√(a<sup>mk</sup>) = <sup>n</sup>√(a<sup>m</sup>) — показатели можно сократить на одно число.', '<b>5.</b> <sup>nk</sup>√(a<sup>mk</sup>) = <sup>n</sup>√(a<sup>m</sup>) — both indices can be divided by the same number.'),
      L('<b>6.</b> Har qanday a uchun √(a<sup>2</sup>) = |a|; umuman, juft n da <sup>n</sup>√(a<sup>n</sup>) = |a|, toq n da <sup>n</sup>√(a<sup>n</sup>) = a.', '<b>6.</b> Для любого a √(a<sup>2</sup>) = |a|; вообще, при чётном n <sup>n</sup>√(a<sup>n</sup>) = |a|, при нечётном n <sup>n</sup>√(a<sup>n</sup>) = a.', '<b>6.</b> For any a, √(a<sup>2</sup>) = |a|; in general, for even n, <sup>n</sup>√(a<sup>n</sup>) = |a|, and for odd n, <sup>n</sup>√(a<sup>n</sup>) = a.')
    ], after: [
      L('<b>1-xossaning isboti.</b> x = <sup>n</sup>√a · <sup>n</sup>√b bo‘lsin. U manfiy emas va x<sup>n</sup> = (<sup>n</sup>√a)<sup>n</sup> · (<sup>n</sup>√b)<sup>n</sup> = ab. Demak, x — n-darajasi ab ga teng bo‘lgan manfiy bo‘lmagan son, ya’ni ta’rif bo‘yicha x = <sup>n</sup>√(ab). Qolgan xossalar ham xuddi shu g‘oya bilan isbotlanadi: ifodani n-darajaga ko‘taramiz va ta’rifga murojaat qilamiz.', '<b>Доказательство свойства 1.</b> Пусть x = <sup>n</sup>√a · <sup>n</sup>√b. Оно неотрицательно, и x<sup>n</sup> = (<sup>n</sup>√a)<sup>n</sup> · (<sup>n</sup>√b)<sup>n</sup> = ab. Значит, x — неотрицательное число, n-я степень которого равна ab, то есть по определению x = <sup>n</sup>√(ab). Остальные свойства доказываются той же идеей: возводим в n-ю степень и обращаемся к определению.', '<b>Proof of property 1.</b> Let x = <sup>n</sup>√a · <sup>n</sup>√b. It is non-negative and x<sup>n</sup> = (<sup>n</sup>√a)<sup>n</sup> · (<sup>n</sup>√b)<sup>n</sup> = ab. So x is the non-negative number whose n-th power is ab, i.e. by definition x = <sup>n</sup>√(ab). The other properties are proved with the same idea: raise to the n-th power and use the definition.')
    ] },
    { kind: 'steps', h: L('Ildiz ostidan chiqarish va kiritish', 'Вынесение множителя из-под корня и внесение', 'Taking factors out of and into a root'), p: [
      L('Xossalarning eng ko‘p ishlatiladigan natijasi — ko‘paytuvchini ildiz ostidan chiqarish. Algoritm:', 'Самое частое применение свойств — вынесение множителя из-под корня. Алгоритм:', 'The most common use of the properties is taking a factor out of a root. The algorithm:')
    ], list: [
      L('<b>1.</b> Ildiz ostidagi sonni ko‘paytuvchilarga ajrating, ulardan biri to‘la n-daraja bo‘lsin: 72 = 36 · 2.', '<b>1.</b> Разложите подкоренное число так, чтобы один множитель был полной n-й степенью: 72 = 36 · 2.', '<b>1.</b> Split the radicand so that one factor is a perfect n-th power: 72 = 36 · 2.'),
      L('<b>2.</b> Ko‘paytmaning ildizi xossasini qo‘llang: √72 = √36 · √2.', '<b>2.</b> Примените свойство корня из произведения: √72 = √36 · √2.', '<b>2.</b> Use the product rule: √72 = √36 · √2.'),
      L('<b>3.</b> To‘la darajadan ildizni hisoblang: √72 = 6√2.', '<b>3.</b> Извлеките корень из полной степени: √72 = 6√2.', '<b>3.</b> Take the root of the perfect power: √72 = 6√2.'),
      L('<b>Kiritish</b> — teskari jarayon: 3∛2 = ∛(27 · 2) = ∛54. Musbat ko‘paytuvchini juft ko‘rsatkichli ildiz ostiga kiritishda uni n-darajaga ko‘taramiz; manfiy ko‘paytuvchida minus tashqarida qoladi: −2√3 = −√12.', '<b>Внесение</b> — обратный процесс: 3∛2 = ∛(27 · 2) = ∛54. Положительный множитель вносим под корень чётной степени, возводя в n-ю степень; у отрицательного минус остаётся снаружи: −2√3 = −√12.', '<b>Bringing in</b> is the reverse: 3∛2 = ∛(27 · 2) = ∛54. A positive factor goes under an even root after raising it to the n-th power; for a negative factor the minus stays outside: −2√3 = −√12.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Hisoblang: ∛(−125), <sup>4</sup>√(<sup>16</sup>/<sub>81</sub>), <sup>5</sup>√0,00032.', 'Вычислите: ∛(−125), <sup>4</sup>√(<sup>16</sup>/<sub>81</sub>), <sup>5</sup>√0,00032.', 'Compute ∛(−125), <sup>4</sup>√(<sup>16</sup>/<sub>81</sub>), <sup>5</sup>√0.00032.'),
        s: L('∛(−125) = −5, chunki (−5)<sup>3</sup> = −125. <sup>4</sup>√(<sup>16</sup>/<sub>81</sub>) = <sup>2</sup>/<sub>3</sub>, chunki (<sup>2</sup>/<sub>3</sub>)<sup>4</sup> = <sup>16</sup>/<sub>81</sub>. 0,00032 = 0,2<sup>5</sup>, shuning uchun <sup>5</sup>√0,00032 = 0,2.', '∛(−125) = −5, так как (−5)<sup>3</sup> = −125. <sup>4</sup>√(<sup>16</sup>/<sub>81</sub>) = <sup>2</sup>/<sub>3</sub>, так как (<sup>2</sup>/<sub>3</sub>)<sup>4</sup> = <sup>16</sup>/<sub>81</sub>. 0,00032 = 0,2<sup>5</sup>, поэтому <sup>5</sup>√0,00032 = 0,2.', '∛(−125) = −5, since (−5)<sup>3</sup> = −125. <sup>4</sup>√(<sup>16</sup>/<sub>81</sub>) = <sup>2</sup>/<sub>3</sub>, since (<sup>2</sup>/<sub>3</sub>)<sup>4</sup> = <sup>16</sup>/<sub>81</sub>. 0.00032 = 0.2<sup>5</sup>, so <sup>5</sup>√0.00032 = 0.2.') },
      { q: L('Hisoblang: ∛4 · ∛16 va <sup>4</sup>√48 : <sup>4</sup>√3.', 'Вычислите: ∛4 · ∛16 и <sup>4</sup>√48 : <sup>4</sup>√3.', 'Compute ∛4 · ∛16 and <sup>4</sup>√48 ÷ <sup>4</sup>√3.'),
        s: L('∛4 · ∛16 = ∛64 = 4. <sup>4</sup>√48 : <sup>4</sup>√3 = <sup>4</sup>√16 = 2. Alohida ildizlarni hisoblash shart emas edi — xossalar ishni osonlashtirdi.', '∛4 · ∛16 = ∛64 = 4. <sup>4</sup>√48 : <sup>4</sup>√3 = <sup>4</sup>√16 = 2. Вычислять корни по отдельности не понадобилось — свойства облегчили работу.', '∛4 · ∛16 = ∛64 = 4. <sup>4</sup>√48 ÷ <sup>4</sup>√3 = <sup>4</sup>√16 = 2. No need to compute each root separately — the properties did the work.') },
      { q: L('Soddalashtiring: √50 + √18 − √8.', 'Упростите: √50 + √18 − √8.', 'Simplify √50 + √18 − √8.'),
        s: L('√50 = 5√2, √18 = 3√2, √8 = 2√2. Yig‘indi: (5 + 3 − 2)√2 = 6√2. «O‘xshash ildizlar» xuddi o‘xshash hadlar kabi qo‘shiladi.', '√50 = 5√2, √18 = 3√2, √8 = 2√2. Сумма: (5 + 3 − 2)√2 = 6√2. «Подобные корни» складываются как подобные слагаемые.', '√50 = 5√2, √18 = 3√2, √8 = 2√2. Sum: (5 + 3 − 2)√2 = 6√2. “Like roots” combine just like like terms.') },
      { q: L('Soddalashtiring: √((2 − √5)<sup>2</sup>).', 'Упростите: √((2 − √5)<sup>2</sup>).', 'Simplify √((2 − √5)<sup>2</sup>).'),
        s: L('√(a<sup>2</sup>) = |a|. √5 ≈ 2,24 &gt; 2, shuning uchun 2 − √5 &lt; 0 va |2 − √5| = √5 − 2. Javob: √5 − 2.', '√(a<sup>2</sup>) = |a|. √5 ≈ 2,24 &gt; 2, поэтому 2 − √5 &lt; 0 и |2 − √5| = √5 − 2. Ответ: √5 − 2.', '√(a<sup>2</sup>) = |a|. Since √5 ≈ 2.24 &gt; 2, 2 − √5 &lt; 0 and |2 − √5| = √5 − 2. Answer: √5 − 2.') }
    ] },
    { kind: 'table', h: L('Foydali ildizlar jadvali', 'Таблица полезных корней', 'A table of useful roots'), table: { head: [L('Daraja', 'Степень', 'Power'), L('Qiymatlar', 'Значения', 'Values'), L('Ildizlar', 'Корни', 'Roots')], rows: [
      [L('Kvadratlar', 'Квадраты', 'Squares'), L('121, 144, 169, 196, 225', '121, 144, 169, 196, 225', '121, 144, 169, 196, 225'), L('√ = 11, 12, 13, 14, 15', '√ = 11, 12, 13, 14, 15', '√ = 11, 12, 13, 14, 15')],
      [L('Kublar', 'Кубы', 'Cubes'), L('8, 27, 64, 125, 216, 343, 1000', '8, 27, 64, 125, 216, 343, 1000', '8, 27, 64, 125, 216, 343, 1000'), L('∛ = 2, 3, 4, 5, 6, 7, 10', '∛ = 2, 3, 4, 5, 6, 7, 10', '∛ = 2, 3, 4, 5, 6, 7, 10')],
      [L('4-darajalar', '4-е степени', '4th powers'), L('16, 81, 256, 625', '16, 81, 256, 625', '16, 81, 256, 625'), L('<sup>4</sup>√ = 2, 3, 4, 5', '<sup>4</sup>√ = 2, 3, 4, 5', '<sup>4</sup>√ = 2, 3, 4, 5')],
      [L('5-darajalar', '5-е степени', '5th powers'), L('32, 243, 1024', '32, 243, 1024', '32, 243, 1024'), L('<sup>5</sup>√ = 2, 3, 4', '<sup>5</sup>√ = 2, 3, 4', '<sup>5</sup>√ = 2, 3, 4')],
      [L('Taqribiy', 'Приближённо', 'Approximate'), L('√2, √3, √5, ∛2', '√2, √3, √5, ∛2', '√2, √3, √5, ∛2'), L('1,414; 1,732; 2,236; 1,260', '1,414; 1,732; 2,236; 1,260', '1.414; 1.732; 2.236; 1.260')]
    ] }, after: [
      L('Bu jadvalni yod bilish ildizlarni tez hisoblashga va ildiz ostidan ko‘paytuvchi chiqarishga katta yordam beradi.', 'Знание этой таблицы наизусть очень помогает быстро вычислять корни и выносить множители.', 'Knowing this table by heart helps a lot with quick root calculations and taking factors out.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Yig‘indining ildizi:</b> √(9 + 16) ≠ √9 + √16. Chap tomon √25 = 5, o‘ng tomon 3 + 4 = 7. Xossa faqat ko‘paytma va bo‘linma uchun!', '<b>Корень из суммы:</b> √(9 + 16) ≠ √9 + √16. Слева √25 = 5, справа 3 + 4 = 7. Свойство верно только для произведения и частного!', '<b>Root of a sum:</b> √(9 + 16) ≠ √9 + √16. The left side is √25 = 5, the right side 3 + 4 = 7. The rule holds only for products and quotients!'),
      L('<b>Arifmetik ildizni manfiy deb olish:</b> √49 = 7, ±7 emas. ±7 — bu x<sup>2</sup> = 49 tenglamaning ildizlari.', '<b>Отрицательный арифметический корень:</b> √49 = 7, а не ±7. ±7 — это корни уравнения x<sup>2</sup> = 49.', '<b>Taking the arithmetic root as negative:</b> √49 = 7, not ±7. ±7 are the solutions of x<sup>2</sup> = 49.'),
      L('<b>Modulni unutish:</b> √(x<sup>2</sup>) = |x|, x emas. x = −3 da √9 = 3 = |−3|.', '<b>Забытый модуль:</b> √(x<sup>2</sup>) = |x|, а не x. При x = −3: √9 = 3 = |−3|.', '<b>Forgetting the absolute value:</b> √(x<sup>2</sup>) = |x|, not x. At x = −3: √9 = 3 = |−3|.'),
      L('<b>Juft ildizni manfiy sondan chiqarish:</b> √(−16) haqiqiy sonlarda mavjud emas; ∛(−27) = −3 esa mavjud.', '<b>Чётный корень из отрицательного:</b> √(−16) среди действительных чисел не существует, а ∛(−27) = −3 существует.', '<b>Even root of a negative:</b> √(−16) does not exist among real numbers, while ∛(−27) = −3 does.'),
      L('<b>Har xil ko‘rsatkichli ildizlarni ko‘paytirish:</b> √2 · ∛2 ≠ <sup>5</sup>√4. Avval umumiy ko‘rsatkichga keltiring: <sup>6</sup>√8 · <sup>6</sup>√4 = <sup>6</sup>√32.', '<b>Умножение корней разных степеней:</b> √2 · ∛2 ≠ <sup>5</sup>√4. Сначала приведите к общему показателю: <sup>6</sup>√8 · <sup>6</sup>√4 = <sup>6</sup>√32.', '<b>Multiplying roots of different indices:</b> √2 · ∛2 ≠ <sup>5</sup>√4. First bring them to a common index: <sup>6</sup>√8 · <sup>6</sup>√4 = <sup>6</sup>√32.')
    ] },
    { kind: 'life', h: L('Hayotda ildizlar', 'Корни в жизни', 'Roots in real life'), p: [
      L('<b>Qurilish va dizayn.</b> Kvadrat xonaning yuzi 30 m<sup>2</sup> bo‘lsa, devor uzunligi √30 ≈ 5,48 m. Kub shaklidagi 1000 litrli (1 m<sup>3</sup>) suv idishining qirrasi ∛1 = 1 m, 8000 litrli idishniki esa ∛8 = 2 m — hajm 8 marta oshsa, o‘lcham atigi 2 marta oshadi.', '<b>Строительство и дизайн.</b> Если площадь квадратной комнаты 30 м<sup>2</sup>, длина стены √30 ≈ 5,48 м. Ребро кубического бака на 1000 литров (1 м<sup>3</sup>) — 1 м, а на 8000 литров — ∛8 = 2 м: объём вырос в 8 раз, а размер — лишь в 2.', '<b>Building and design.</b> A square room of area 30 m<sup>2</sup> has walls √30 ≈ 5.48 m long. A cubic 1000-litre tank (1 m<sup>3</sup>) has a 1 m edge, and an 8000-litre one an edge of ∛8 = 2 m: the volume grew 8 times, the size only 2 times.'),
      L('<b>Musiqa.</b> Zamonaviy pianinoda oktava 12 ta teng yarim tonga bo‘lingan: qo‘shni notalar chastotalari nisbati <sup>12</sup>√2 ≈ 1,0595. <b>Fizika:</b> erkin tushish vaqti t = √(<sup>2h</sup>/<sub>g</sub>); 20 m balandlikdan tosh taxminan 2 soniyada tushadi. <b>Moliya:</b> 3 yilda pul 1,331 marta oshgan bo‘lsa, yillik o‘sish ∛1,331 = 1,1, ya’ni 10%.', '<b>Музыка.</b> На фортепиано октава делится на 12 равных полутонов: отношение частот соседних нот <sup>12</sup>√2 ≈ 1,0595. <b>Физика:</b> время свободного падения t = √(<sup>2h</sup>/<sub>g</sub>); с высоты 20 м камень падает около 2 секунд. <b>Финансы:</b> если за 3 года сумма выросла в 1,331 раза, годовой рост ∛1,331 = 1,1, то есть 10%.', '<b>Music.</b> On a piano the octave is split into 12 equal semitones: neighbouring notes have frequency ratio <sup>12</sup>√2 ≈ 1.0595. <b>Physics:</b> free-fall time is t = √(<sup>2h</sup>/<sub>g</sub>); a stone dropped from 20 m falls for about 2 seconds. <b>Finance:</b> if money grew 1.331 times in 3 years, the yearly growth is ∛1.331 = 1.1, i.e. 10%.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('√2 irratsional son — uni hech qanday oddiy kasr ko‘rinishida yozib bo‘lmaydi. Buni qadimgi yunonlar, Pifagor maktabi isbotlagan va bu kashfiyot ularni hayratga solgan.', '√2 — иррациональное число: его нельзя записать обыкновенной дробью. Это доказали ещё древние греки школы Пифагора, и открытие их потрясло.', '√2 is irrational: it cannot be written as an ordinary fraction. The ancient Greeks of Pythagoras’ school proved this, and the discovery shocked them.'),
      L('A4 qog‘oz varag‘ining tomonlari nisbati √2 ga teng. Shuning uchun uni o‘rtasidan buklasangiz, xuddi shunday shakldagi A5 varaq hosil bo‘ladi.', 'Отношение сторон листа A4 равно √2. Поэтому, сложив его пополам, получают лист A5 точно такой же формы.', 'The sides of an A4 sheet are in the ratio √2. That is why folding it in half gives an A5 sheet of exactly the same shape.'),
      L('Al-Koshiy ildiz chiqarish uchun bugun «Ruffini–Horner sxemasi» deb ataladigan usulga juda yaqin usulni Yevropadan 350 yil oldin qo‘llagan.', 'Аль-Каши для извлечения корней применял способ, очень близкий к так называемой «схеме Руффини — Горнера», почти на 350 лет раньше европейцев.', 'Al-Kashi used a method for extracting roots very close to what is now called the Ruffini–Horner scheme, some 350 years before it appeared in Europe.')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('<sup>3</sup>√(−0,001) = ?', '<sup>3</sup>√(−0,001) = ?', '<sup>3</sup>√(−0.001) = ?'), s: L('−0,1.', '−0,1.', '−0.1.') },
      { q: L('√98 ni soddalashtiring.', 'Упростите √98.', 'Simplify √98.'), s: L('√(49 · 2) = 7√2.', '√(49 · 2) = 7√2.', '√(49 · 2) = 7√2.') },
      { q: L('√(<sup>4</sup>√256) = ?', '√(<sup>4</sup>√256) = ?', '√(<sup>4</sup>√256) = ?'), s: L('<sup>8</sup>√256 = 2 (chunki 2<sup>8</sup> = 256).', '<sup>8</sup>√256 = 2 (так как 2<sup>8</sup> = 256).', '<sup>8</sup>√256 = 2 (since 2<sup>8</sup> = 256).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('<sup>n</sup>√a (a ≥ 0) — n-darajasi a ga teng bo‘lgan manfiy bo‘lmagan son.', '<sup>n</sup>√a (a ≥ 0) — неотрицательное число, n-я степень которого равна a.', '<sup>n</sup>√a (a ≥ 0) is the non-negative number whose n-th power is a.'),
      L('Toq ko‘rsatkichli ildiz manfiy sondan ham mavjud, juftlisi — yo‘q.', 'Корень нечётной степени существует и из отрицательного числа, чётной — нет.', 'Odd roots of negative numbers exist; even roots do not.'),
      L('Ko‘paytma va bo‘linmaning ildizi ildizlarning ko‘paytmasi va bo‘linmasiga teng.', 'Корень из произведения и частного равен произведению и частному корней.', 'The root of a product or quotient is the product or quotient of the roots.'),
      L('Yig‘indining ildizi ildizlar yig‘indisiga teng EMAS.', 'Корень из суммы НЕ равен сумме корней.', 'The root of a sum is NOT the sum of the roots.'),
      L('√(a<sup>2</sup>) = |a|; juft n da <sup>n</sup>√(a<sup>n</sup>) = |a|.', '√(a<sup>2</sup>) = |a|; при чётном n <sup>n</sup>√(a<sup>n</sup>) = |a|.', '√(a<sup>2</sup>) = |a|; for even n, <sup>n</sup>√(a<sup>n</sup>) = |a|.'),
      L('Ko‘paytuvchini ildiz ostidan chiqarish: √72 = 6√2.', 'Вынесение множителя: √72 = 6√2.', 'Taking out a factor: √72 = 6√2.')
    ] }
  ] });

  // ---------- t6. Ratsional ko'rsatkichli daraja ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Kasr darajami? Ha, mumkin!', 'Дробная степень? Да, бывает!', 'A fractional power? Yes, really!'), p: [
      L('Biz 2<sup>3</sup> = 2 · 2 · 2 ekanini bilamiz: ko‘rsatkich nechta ko‘paytuvchi borligini aytadi. Lekin 2<sup>1/2</sup> yoki 8<sup>−2/3</sup> nimani anglatadi? «Ikkini yarim marta ko‘paytirish» ma’nosiz tuyuladi. Shunga qaramay, matematiklar bunday yozuvlarga aniq ma’no berishgan — va bu ma’no shunchalik qulayki, bugun kalkulyatorlar, fizika formulalari va moliya hisoblari undan keng foydalanadi.', 'Мы знаем, что 2<sup>3</sup> = 2 · 2 · 2: показатель говорит, сколько множителей. Но что означает 2<sup>1/2</sup> или 8<sup>−2/3</sup>? «Умножить двойку на себя полтора раза» звучит бессмысленно. Тем не менее математики придали таким записям точный смысл — и он настолько удобен, что им повсюду пользуются калькуляторы, формулы физики и финансовые расчёты.', 'We know that 2<sup>3</sup> = 2 · 2 · 2: the exponent counts the factors. But what does 2<sup>1/2</sup> or 8<sup>−2/3</sup> mean? “Multiplying 2 by itself one and a half times” sounds meaningless. Yet mathematicians gave such expressions a precise meaning — one so convenient that calculators, physics formulas and financial calculations use it everywhere.'),
      L('G‘oya oddiy: yangi ta’rif shunday tanlanadiki, darajaning eski xossalari (a<sup>m</sup> · a<sup>n</sup> = a<sup>m + n</sup>, (a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup>) o‘z kuchini saqlasin. Bu mavzuda avval nol va manfiy butun ko‘rsatkichni, keyin kasr ko‘rsatkichni ta’riflaymiz va ular bilan hisoblashni o‘rganamiz.', 'Идея проста: новое определение выбирают так, чтобы старые свойства степени (a<sup>m</sup> · a<sup>n</sup> = a<sup>m + n</sup>, (a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup>) остались верными. В этой теме сначала определим нулевой и отрицательный целый показатель, затем дробный, и научимся с ними считать.', 'The idea is simple: the new definition is chosen so that the old power laws (a<sup>m</sup> · a<sup>n</sup> = a<sup>m + n</sup>, (a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup>) still hold. In this topic we first define zero and negative whole exponents, then fractional ones, and learn to calculate with them.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), p: [
      L('<b>Nol ko‘rsatkich:</b> a ≠ 0 uchun a<sup>0</sup> = 1. <b>Manfiy butun ko‘rsatkich:</b> a ≠ 0, n natural bo‘lsa, a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub>. Masalan, 5<sup>0</sup> = 1, 2<sup>−3</sup> = <sup>1</sup>/<sub>8</sub>, (<sup>2</sup>/<sub>3</sub>)<sup>−2</sup> = <sup>9</sup>/<sub>4</sub>. 0<sup>0</sup> va 0<sup>−n</sup> ifodalar ma’noga ega emas.', '<b>Нулевой показатель:</b> при a ≠ 0 a<sup>0</sup> = 1. <b>Отрицательный целый:</b> при a ≠ 0 и натуральном n a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub>. Например, 5<sup>0</sup> = 1, 2<sup>−3</sup> = <sup>1</sup>/<sub>8</sub>, (<sup>2</sup>/<sub>3</sub>)<sup>−2</sup> = <sup>9</sup>/<sub>4</sub>. Выражения 0<sup>0</sup> и 0<sup>−n</sup> не имеют смысла.', '<b>Zero exponent:</b> for a ≠ 0, a<sup>0</sup> = 1. <b>Negative whole exponent:</b> for a ≠ 0 and natural n, a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub>. For example, 5<sup>0</sup> = 1, 2<sup>−3</sup> = <sup>1</sup>/<sub>8</sub>, (<sup>2</sup>/<sub>3</sub>)<sup>−2</sup> = <sup>9</sup>/<sub>4</sub>. The expressions 0<sup>0</sup> and 0<sup>−n</sup> are undefined.'),
      L('<b>Ratsional ko‘rsatkich:</b> a &gt; 0, m — butun son, n ≥ 2 — natural son bo‘lsa, <b>a<sup>m/n</sup> = <sup>n</sup>√(a<sup>m</sup>)</b>. Xususan, a<sup>1/n</sup> = <sup>n</sup>√a. Masalan, 9<sup>1/2</sup> = √9 = 3, 8<sup>2/3</sup> = ∛64 = 4, 16<sup>−3/4</sup> = <sup>1</sup>/<sub>8</sub>. Asos musbat bo‘lishi talab qilinadi, aks holda ziddiyatlar paydo bo‘ladi.', '<b>Рациональный показатель:</b> при a &gt; 0, целом m и натуральном n ≥ 2 <b>a<sup>m/n</sup> = <sup>n</sup>√(a<sup>m</sup>)</b>. В частности, a<sup>1/n</sup> = <sup>n</sup>√a. Например, 9<sup>1/2</sup> = √9 = 3, 8<sup>2/3</sup> = ∛64 = 4, 16<sup>−3/4</sup> = <sup>1</sup>/<sub>8</sub>. Основание должно быть положительным, иначе возникают противоречия.', '<b>Rational exponent:</b> for a &gt; 0, integer m and natural n ≥ 2, <b>a<sup>m/n</sup> = <sup>n</sup>√(a<sup>m</sup>)</b>. In particular, a<sup>1/n</sup> = <sup>n</sup>√a. For example, 9<sup>1/2</sup> = √9 = 3, 8<sup>2/3</sup> = ∛64 = 4, 16<sup>−3/4</sup> = <sup>1</sup>/<sub>8</sub>. The base must be positive, otherwise contradictions appear.')
    ] },
    { kind: 'history', h: L('Tarixdan: Oremdan Nyutongacha', 'Из истории: от Орема до Ньютона', 'From history: from Oresme to Newton'), p: [
      L('XIV asrda fransuz olimi <b>Nikolay Orem</b> birinchilardan bo‘lib kasr ko‘rsatkichli daraja g‘oyasini ilgari surgan: u «ikki karra yarim» kabi nisbatlar haqida yozib, ularni hozirgi 2<sup>3/2</sup> ga mos keladigan ma’noda tushungan. 1544-yilda nemis <b>Mixael Shtifel</b> 2 ning darajalari jadvalini manfiy ko‘rsatkichlar tomon davom ettirdi va ko‘rsatkichlar qo‘shilganda darajalar ko‘paytirilishini ta’kidladi.', 'В XIV веке французский учёный <b>Николай Орем</b> одним из первых высказал идею дробного показателя: он писал об отношениях вроде «полуторной степени» и понимал их в смысле, соответствующем нашему 2<sup>3/2</sup>. В 1544 году немец <b>Михаэль Штифель</b> продолжил таблицу степеней двойки в сторону отрицательных показателей и отметил, что при сложении показателей степени перемножаются.', 'In the 14th century the French scholar <b>Nicole Oresme</b> was among the first to suggest fractional exponents: he wrote about ratios such as “one and a half times” a power and understood them in a sense matching our 2<sup>3/2</sup>. In 1544 the German <b>Michael Stifel</b> extended the table of powers of 2 to negative exponents and noted that adding exponents corresponds to multiplying powers.'),
      L('XVII asrda ingliz <b>Jon Uollis</b> manfiy va kasr ko‘rsatkichlardan foydalandi, 1676-yilda esa <b>Isaak Nyuton</b> o‘z xatida a<sup>−1</sup>, a<sup>1/2</sup>, a<sup>3/2</sup> kabi yozuvlarni tizimli ishlatib, ularni bugungi ma’noda tushuntirdi. Bu belgilar Nyutonning binom formulasini istalgan ratsional ko‘rsatkich uchun yozishga imkon berdi. Shu tariqa uzun ildiz yozuvlari o‘rniga ixcham daraja yozuvi qaror topdi.', 'В XVII веке англичанин <b>Джон Валлис</b> пользовался отрицательными и дробными показателями, а в 1676 году <b>Исаак Ньютон</b> в своём письме систематически применил записи a<sup>−1</sup>, a<sup>1/2</sup>, a<sup>3/2</sup> и объяснил их в современном смысле. Эти обозначения позволили записать формулу бинома Ньютона для любого рационального показателя. Так компактная запись степени вытеснила громоздкие корни.', 'In the 17th century the Englishman <b>John Wallis</b> used negative and fractional exponents, and in 1676 <b>Isaac Newton</b>, in a letter, systematically used the notations a<sup>−1</sup>, a<sup>1/2</sup>, a<sup>3/2</sup> and explained them in today’s sense. These notations let him state his binomial theorem for any rational exponent. In this way the compact power notation replaced clumsy root signs.')
    ] },
    { kind: 'rule', h: L('Nega aynan shunday ta’rif?', 'Почему определение именно такое?', 'Why this definition?'), p: [
      L('<b>a<sup>0</sup> = 1.</b> a<sup>m</sup> : a<sup>n</sup> = a<sup>m − n</sup> qoidasi m = n da ham ishlashini xohlaymiz: a<sup>n</sup> : a<sup>n</sup> = 1, bir tomondan, va a<sup>0</sup>, ikkinchi tomondan. Demak, a<sup>0</sup> = 1 deb olish yagona to‘g‘ri tanlov.', '<b>a<sup>0</sup> = 1.</b> Хотим, чтобы правило a<sup>m</sup> : a<sup>n</sup> = a<sup>m − n</sup> работало и при m = n: a<sup>n</sup> : a<sup>n</sup> = 1 с одной стороны и a<sup>0</sup> — с другой. Значит, a<sup>0</sup> = 1 — единственный правильный выбор.', '<b>a<sup>0</sup> = 1.</b> We want a<sup>m</sup> ÷ a<sup>n</sup> = a<sup>m − n</sup> to work when m = n too: a<sup>n</sup> ÷ a<sup>n</sup> = 1 on one hand and a<sup>0</sup> on the other. So a<sup>0</sup> = 1 is the only sensible choice.'),
      L('<b>a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub>.</b> a<sup>n</sup> · a<sup>−n</sup> = a<sup>0</sup> = 1 bo‘lishi kerak, demak a<sup>−n</sup> — a<sup>n</sup> ga teskari son. Jadvalda ham ko‘rinadi: 2<sup>3</sup> = 8, 2<sup>2</sup> = 4, 2<sup>1</sup> = 2, 2<sup>0</sup> = 1, 2<sup>−1</sup> = <sup>1</sup>/<sub>2</sub>, 2<sup>−2</sup> = <sup>1</sup>/<sub>4</sub> — har qadamda 2 ga bo‘linadi.', '<b>a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub>.</b> Должно быть a<sup>n</sup> · a<sup>−n</sup> = a<sup>0</sup> = 1, значит a<sup>−n</sup> — число, обратное a<sup>n</sup>. Это видно и по таблице: 2<sup>3</sup> = 8, 2<sup>2</sup> = 4, 2<sup>1</sup> = 2, 2<sup>0</sup> = 1, 2<sup>−1</sup> = <sup>1</sup>/<sub>2</sub>, 2<sup>−2</sup> = <sup>1</sup>/<sub>4</sub> — каждый шаг делим на 2.', '<b>a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub>.</b> We need a<sup>n</sup> · a<sup>−n</sup> = a<sup>0</sup> = 1, so a<sup>−n</sup> is the reciprocal of a<sup>n</sup>. The pattern shows it too: 2<sup>3</sup> = 8, 2<sup>2</sup> = 4, 2<sup>1</sup> = 2, 2<sup>0</sup> = 1, 2<sup>−1</sup> = <sup>1</sup>/<sub>2</sub>, 2<sup>−2</sup> = <sup>1</sup>/<sub>4</sub> — each step divides by 2.'),
      L('<b>a<sup>1/n</sup> = <sup>n</sup>√a.</b> (a<sup>m</sup>)<sup>k</sup> = a<sup>mk</sup> qoidasi saqlansa, (a<sup>1/n</sup>)<sup>n</sup> = a<sup>1</sup> = a bo‘ladi. Demak, a<sup>1/n</sup> — n-darajasi a ga teng musbat son, ya’ni <sup>n</sup>√a. Xuddi shunday a<sup>m/n</sup> = (a<sup>1/n</sup>)<sup>m</sup> = (<sup>n</sup>√a)<sup>m</sup> = <sup>n</sup>√(a<sup>m</sup>).', '<b>a<sup>1/n</sup> = <sup>n</sup>√a.</b> Если сохранить правило (a<sup>m</sup>)<sup>k</sup> = a<sup>mk</sup>, то (a<sup>1/n</sup>)<sup>n</sup> = a<sup>1</sup> = a. Значит, a<sup>1/n</sup> — положительное число, n-я степень которого равна a, то есть <sup>n</sup>√a. Аналогично a<sup>m/n</sup> = (a<sup>1/n</sup>)<sup>m</sup> = (<sup>n</sup>√a)<sup>m</sup> = <sup>n</sup>√(a<sup>m</sup>).', '<b>a<sup>1/n</sup> = <sup>n</sup>√a.</b> If (a<sup>m</sup>)<sup>k</sup> = a<sup>mk</sup> is to hold, then (a<sup>1/n</sup>)<sup>n</sup> = a<sup>1</sup> = a. So a<sup>1/n</sup> is the positive number whose n-th power is a, namely <sup>n</sup>√a. Likewise a<sup>m/n</sup> = (a<sup>1/n</sup>)<sup>m</sup> = (<sup>n</sup>√a)<sup>m</sup> = <sup>n</sup>√(a<sup>m</sup>).')
    ] },
    { kind: 'table', h: L('Daraja xossalari (a, b &gt; 0; p, q — ratsional)', 'Свойства степеней (a, b &gt; 0; p, q — рациональные)', 'Power laws (a, b &gt; 0; p, q rational)'), table: { head: [L('Xossa', 'Свойство', 'Law'), L('Misol', 'Пример', 'Example')], rows: [
      [L('a<sup>p</sup> · a<sup>q</sup> = a<sup>p + q</sup>', 'a<sup>p</sup> · a<sup>q</sup> = a<sup>p + q</sup>', 'a<sup>p</sup> · a<sup>q</sup> = a<sup>p + q</sup>'), L('5<sup>1/3</sup> · 5<sup>2/3</sup> = 5<sup>1</sup> = 5', '5<sup>1/3</sup> · 5<sup>2/3</sup> = 5<sup>1</sup> = 5', '5<sup>1/3</sup> · 5<sup>2/3</sup> = 5<sup>1</sup> = 5')],
      [L('a<sup>p</sup> : a<sup>q</sup> = a<sup>p − q</sup>', 'a<sup>p</sup> : a<sup>q</sup> = a<sup>p − q</sup>', 'a<sup>p</sup> ÷ a<sup>q</sup> = a<sup>p − q</sup>'), L('7<sup>5/2</sup> : 7<sup>1/2</sup> = 7<sup>2</sup> = 49', '7<sup>5/2</sup> : 7<sup>1/2</sup> = 7<sup>2</sup> = 49', '7<sup>5/2</sup> ÷ 7<sup>1/2</sup> = 7<sup>2</sup> = 49')],
      [L('(a<sup>p</sup>)<sup>q</sup> = a<sup>pq</sup>', '(a<sup>p</sup>)<sup>q</sup> = a<sup>pq</sup>', '(a<sup>p</sup>)<sup>q</sup> = a<sup>pq</sup>'), L('(4<sup>3/4</sup>)<sup>2</sup> = 4<sup>3/2</sup> = 8', '(4<sup>3/4</sup>)<sup>2</sup> = 4<sup>3/2</sup> = 8', '(4<sup>3/4</sup>)<sup>2</sup> = 4<sup>3/2</sup> = 8')],
      [L('(ab)<sup>p</sup> = a<sup>p</sup>b<sup>p</sup>', '(ab)<sup>p</sup> = a<sup>p</sup>b<sup>p</sup>', '(ab)<sup>p</sup> = a<sup>p</sup>b<sup>p</sup>'), L('(4 · 9)<sup>1/2</sup> = 2 · 3 = 6', '(4 · 9)<sup>1/2</sup> = 2 · 3 = 6', '(4 · 9)<sup>1/2</sup> = 2 · 3 = 6')],
      [L('(<sup>a</sup>/<sub>b</sub>)<sup>p</sup> = <sup>a<sup>p</sup></sup>/<sub>b<sup>p</sup></sub>', '(<sup>a</sup>/<sub>b</sub>)<sup>p</sup> = <sup>a<sup>p</sup></sup>/<sub>b<sup>p</sup></sub>', '(<sup>a</sup>/<sub>b</sub>)<sup>p</sup> = <sup>a<sup>p</sup></sup>/<sub>b<sup>p</sup></sub>'), L('(<sup>8</sup>/<sub>27</sub>)<sup>1/3</sup> = <sup>2</sup>/<sub>3</sub>', '(<sup>8</sup>/<sub>27</sub>)<sup>1/3</sup> = <sup>2</sup>/<sub>3</sub>', '(<sup>8</sup>/<sub>27</sub>)<sup>1/3</sup> = <sup>2</sup>/<sub>3</sub>')]
    ] }, after: [
      L('Barcha xossalar butun ko‘rsatkichlar uchun to‘g‘ri bo‘lgan qoidalarning davomi va ildiz xossalari orqali isbotlanadi.', 'Все свойства — продолжение правил для целых показателей и доказываются через свойства корней.', 'All the laws extend the whole-number rules and are proved using the properties of roots.')
    ] },
    { kind: 'steps', h: L('Kasr ko‘rsatkichli darajani hisoblash', 'Как вычислить степень с дробным показателем', 'Evaluating a fractional power'), list: [
      L('<b>1.</b> Ko‘rsatkich manfiy bo‘lsa, asosni teskari songa almashtiring: a<sup>−p</sup> = (<sup>1</sup>/<sub>a</sub>)<sup>p</sup>.', '<b>1.</b> Если показатель отрицательный, замените основание обратным: a<sup>−p</sup> = (<sup>1</sup>/<sub>a</sub>)<sup>p</sup>.', '<b>1.</b> If the exponent is negative, replace the base by its reciprocal: a<sup>−p</sup> = (<sup>1</sup>/<sub>a</sub>)<sup>p</sup>.'),
      L('<b>2.</b> Avval ildizni chiqaring (maxraj — ildiz ko‘rsatkichi), so‘ng darajaga ko‘taring (surat). Bu tartibda sonlar kichik qoladi: 27<sup>4/3</sup> = (∛27)<sup>4</sup> = 3<sup>4</sup> = 81.', '<b>2.</b> Сначала извлеките корень (знаменатель — показатель корня), потом возведите в степень (числитель). Так числа остаются маленькими: 27<sup>4/3</sup> = (∛27)<sup>4</sup> = 3<sup>4</sup> = 81.', '<b>2.</b> Take the root first (the denominator is the index), then raise to the power (the numerator). This keeps numbers small: 27<sup>4/3</sup> = (∛27)<sup>4</sup> = 3<sup>4</sup> = 81.'),
      L('<b>3.</b> Bir xil asosli darajalar ko‘paytmasida ko‘rsatkichlarni qo‘shing (umumiy maxrajga keltirib).', '<b>3.</b> В произведении степеней с одинаковым основанием складывайте показатели (приведя их к общему знаменателю).', '<b>3.</b> When multiplying powers with the same base, add the exponents (using a common denominator).'),
      L('<b>4.</b> Asoslarni bir xil qilishga harakat qiling: 4 = 2<sup>2</sup>, 8 = 2<sup>3</sup>, 27 = 3<sup>3</sup>.', '<b>4.</b> Старайтесь привести основания к одному: 4 = 2<sup>2</sup>, 8 = 2<sup>3</sup>, 27 = 3<sup>3</sup>.', '<b>4.</b> Try to make the bases equal: 4 = 2<sup>2</sup>, 8 = 2<sup>3</sup>, 27 = 3<sup>3</sup>.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Hisoblang: 32<sup>3/5</sup> va 125<sup>−2/3</sup>.', 'Вычислите: 32<sup>3/5</sup> и 125<sup>−2/3</sup>.', 'Compute 32<sup>3/5</sup> and 125<sup>−2/3</sup>.'),
        s: L('32<sup>3/5</sup> = (<sup>5</sup>√32)<sup>3</sup> = 2<sup>3</sup> = 8. 125<sup>−2/3</sup> = <sup>1</sup>/<sub>(∛125)<sup>2</sup></sub> = <sup>1</sup>/<sub>25</sub> = 0,04.', '32<sup>3/5</sup> = (<sup>5</sup>√32)<sup>3</sup> = 2<sup>3</sup> = 8. 125<sup>−2/3</sup> = <sup>1</sup>/<sub>(∛125)<sup>2</sup></sub> = <sup>1</sup>/<sub>25</sub> = 0,04.', '32<sup>3/5</sup> = (<sup>5</sup>√32)<sup>3</sup> = 2<sup>3</sup> = 8. 125<sup>−2/3</sup> = <sup>1</sup>/<sub>(∛125)<sup>2</sup></sub> = <sup>1</sup>/<sub>25</sub> = 0.04.') },
      { q: L('Hisoblang: 2<sup>1/3</sup> · 4<sup>1/3</sup> va 9<sup>0,5</sup> + 16<sup>0,25</sup> − 1<sup>−3</sup>.', 'Вычислите: 2<sup>1/3</sup> · 4<sup>1/3</sup> и 9<sup>0,5</sup> + 16<sup>0,25</sup> − 1<sup>−3</sup>.', 'Compute 2<sup>1/3</sup> · 4<sup>1/3</sup> and 9<sup>0.5</sup> + 16<sup>0.25</sup> − 1<sup>−3</sup>.'),
        s: L('2<sup>1/3</sup> · 4<sup>1/3</sup> = (2 · 4)<sup>1/3</sup> = 8<sup>1/3</sup> = 2. Ikkinchisi: 0,5 = <sup>1</sup>/<sub>2</sub>, 0,25 = <sup>1</sup>/<sub>4</sub>; 3 + 2 − 1 = 4.', '2<sup>1/3</sup> · 4<sup>1/3</sup> = (2 · 4)<sup>1/3</sup> = 8<sup>1/3</sup> = 2. Второе: 0,5 = <sup>1</sup>/<sub>2</sub>, 0,25 = <sup>1</sup>/<sub>4</sub>; 3 + 2 − 1 = 4.', '2<sup>1/3</sup> · 4<sup>1/3</sup> = (2 · 4)<sup>1/3</sup> = 8<sup>1/3</sup> = 2. Second: 0.5 = <sup>1</sup>/<sub>2</sub>, 0.25 = <sup>1</sup>/<sub>4</sub>; 3 + 2 − 1 = 4.') },
      { q: L('Soddalashtiring (a &gt; 0): <sup>a<sup>1/2</sup> · a<sup>1/3</sup></sup>/<sub>a<sup>1/6</sup></sub>.', 'Упростите (a &gt; 0): <sup>a<sup>1/2</sup> · a<sup>1/3</sup></sup>/<sub>a<sup>1/6</sup></sub>.', 'Simplify (a &gt; 0): <sup>a<sup>1/2</sup> · a<sup>1/3</sup></sup>/<sub>a<sup>1/6</sup></sub>.'),
        s: L('Ko‘rsatkich: <sup>1</sup>/<sub>2</sub> + <sup>1</sup>/<sub>3</sub> − <sup>1</sup>/<sub>6</sub> = <sup>3 + 2 − 1</sup>/<sub>6</sub> = <sup>4</sup>/<sub>6</sub> = <sup>2</sup>/<sub>3</sub>. Javob: a<sup>2/3</sup> = ∛(a<sup>2</sup>).', 'Показатель: <sup>1</sup>/<sub>2</sub> + <sup>1</sup>/<sub>3</sub> − <sup>1</sup>/<sub>6</sub> = <sup>3 + 2 − 1</sup>/<sub>6</sub> = <sup>4</sup>/<sub>6</sub> = <sup>2</sup>/<sub>3</sub>. Ответ: a<sup>2/3</sup> = ∛(a<sup>2</sup>).', 'Exponent: <sup>1</sup>/<sub>2</sub> + <sup>1</sup>/<sub>3</sub> − <sup>1</sup>/<sub>6</sub> = <sup>3 + 2 − 1</sup>/<sub>6</sub> = <sup>4</sup>/<sub>6</sub> = <sup>2</sup>/<sub>3</sub>. Answer: a<sup>2/3</sup> = ∛(a<sup>2</sup>).') },
      { q: L('Ildizni daraja ko‘rinishida yozing va soddalashtiring: √x · ∛x (x &gt; 0).', 'Запишите через степени и упростите: √x · ∛x (x &gt; 0).', 'Write with exponents and simplify: √x · ∛x (x &gt; 0).'),
        s: L('x<sup>1/2</sup> · x<sup>1/3</sup> = x<sup>5/6</sup> = <sup>6</sup>√(x<sup>5</sup>). Daraja yozuvi har xil ko‘rsatkichli ildizlarni ko‘paytirishni juda osonlashtiradi.', 'x<sup>1/2</sup> · x<sup>1/3</sup> = x<sup>5/6</sup> = <sup>6</sup>√(x<sup>5</sup>). Запись через степени очень упрощает умножение корней разных степеней.', 'x<sup>1/2</sup> · x<sup>1/3</sup> = x<sup>5/6</sup> = <sup>6</sup>√(x<sup>5</sup>). Exponent notation makes multiplying roots of different indices very easy.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Manfiy ko‘rsatkich = manfiy son?</b> Yo‘q! 2<sup>−3</sup> = <sup>1</sup>/<sub>8</sub>, −8 emas va −6 ham emas.', '<b>Отрицательный показатель = отрицательное число?</b> Нет! 2<sup>−3</sup> = <sup>1</sup>/<sub>8</sub>, а не −8 и не −6.', '<b>Negative exponent = negative number?</b> No! 2<sup>−3</sup> = <sup>1</sup>/<sub>8</sub>, not −8 and not −6.'),
      L('<b>Asosni ko‘rsatkichga ko‘paytirish:</b> 8<sup>1/3</sup> ≠ <sup>8</sup>/<sub>3</sub>. 8<sup>1/3</sup> = ∛8 = 2.', '<b>Умножение основания на показатель:</b> 8<sup>1/3</sup> ≠ <sup>8</sup>/<sub>3</sub>. 8<sup>1/3</sup> = ∛8 = 2.', '<b>Multiplying base by exponent:</b> 8<sup>1/3</sup> ≠ <sup>8</sup>/<sub>3</sub>. 8<sup>1/3</sup> = ∛8 = 2.'),
      L('<b>Surat va maxrajni chalkashtirish:</b> 8<sup>2/3</sup> = (∛8)<sup>2</sup> = 4, ammo (√8)<sup>3</sup> emas.', '<b>Путаница числителя и знаменателя:</b> 8<sup>2/3</sup> = (∛8)<sup>2</sup> = 4, а не (√8)<sup>3</sup>.', '<b>Mixing up top and bottom:</b> 8<sup>2/3</sup> = (∛8)<sup>2</sup> = 4, not (√8)<sup>3</sup>.'),
      L('<b>Har xil asosli darajalarda ko‘rsatkichlarni qo‘shish:</b> 2<sup>1/2</sup> · 3<sup>1/2</sup> = 6<sup>1/2</sup>, lekin 2<sup>1/2</sup> · 3<sup>1/3</sup> ni bunday birlashtirib bo‘lmaydi.', '<b>Сложение показателей при разных основаниях:</b> 2<sup>1/2</sup> · 3<sup>1/2</sup> = 6<sup>1/2</sup>, но 2<sup>1/2</sup> · 3<sup>1/3</sup> так не объединить.', '<b>Adding exponents with different bases:</b> 2<sup>1/2</sup> · 3<sup>1/2</sup> = 6<sup>1/2</sup>, but 2<sup>1/2</sup> · 3<sup>1/3</sup> cannot be combined that way.'),
      L('<b>Manfiy asos:</b> (−8)<sup>1/3</sup> yozuvi ta’rif bo‘yicha ishlatilmaydi (asos musbat bo‘lishi shart), garchi ∛(−8) = −2 mavjud bo‘lsa ham. Sababi: (−8)<sup>1/3</sup> = (−8)<sup>2/6</sup> desak, <sup>6</sup>√64 = 2 chiqib, ziddiyat yuzaga keladi.', '<b>Отрицательное основание:</b> запись (−8)<sup>1/3</sup> по определению не используется (основание должно быть положительным), хотя ∛(−8) = −2 существует. Причина: если (−8)<sup>1/3</sup> = (−8)<sup>2/6</sup>, то получим <sup>6</sup>√64 = 2 — противоречие.', '<b>Negative base:</b> (−8)<sup>1/3</sup> is not used by definition (the base must be positive), even though ∛(−8) = −2 exists. Reason: writing (−8)<sup>1/3</sup> = (−8)<sup>2/6</sup> would give <sup>6</sup>√64 = 2 — a contradiction.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Kalkulyator va dasturlash.</b> Ko‘p kalkulyatorlarda alohida ∛ tugmasi yo‘q, lekin x<sup>y</sup> tugmasi bor: ∛50 ni 50<sup>(1/3)</sup> deb hisoblaymiz ≈ 3,684. Dasturlash tillarida ham Math.pow(50, 1/3) shunday ishlaydi.', '<b>Калькулятор и программирование.</b> На многих калькуляторах нет кнопки ∛, но есть x<sup>y</sup>: ∛50 считаем как 50<sup>(1/3)</sup> ≈ 3,684. В языках программирования Math.pow(50, 1/3) работает так же.', '<b>Calculators and programming.</b> Many calculators have no ∛ key but do have x<sup>y</sup>: we compute ∛50 as 50<sup>(1/3)</sup> ≈ 3.684. In programming languages Math.pow(50, 1/3) works the same way.'),
      L('<b>Astronomiya.</b> Keplerning uchinchi qonuni: sayyoraning aylanish davri orbita radiusining <sup>3</sup>/<sub>2</sub> darajasiga proporsional, T ∼ R<sup>3/2</sup>. Yupiter Quyoshdan Yerga nisbatan taxminan 5,2 marta uzoq, shuning uchun uning yili 5,2<sup>3/2</sup> ≈ 11,9 Yer yiliga teng.', '<b>Астрономия.</b> Третий закон Кеплера: период обращения планеты пропорционален радиусу орбиты в степени <sup>3</sup>/<sub>2</sub>, T ∼ R<sup>3/2</sup>. Юпитер примерно в 5,2 раза дальше от Солнца, чем Земля, поэтому его год равен 5,2<sup>3/2</sup> ≈ 11,9 земного года.', '<b>Astronomy.</b> Kepler’s third law: a planet’s orbital period is proportional to its orbital radius to the power <sup>3</sup>/<sub>2</sub>, T ∼ R<sup>3/2</sup>. Jupiter is about 5.2 times farther from the Sun than Earth, so its year is 5.2<sup>3/2</sup> ≈ 11.9 Earth years.'),
      L('<b>Biologiya.</b> Hayvonning energiya sarfi massasining taxminan <sup>3</sup>/<sub>4</sub> darajasiga proporsional (Kleyber qonuni): fil sichqondan 10 000 marta og‘ir, ammo energiyani atigi 10 000<sup>3/4</sup> = 1000 marta ko‘p sarflaydi.', '<b>Биология.</b> Расход энергии животного пропорционален массе примерно в степени <sup>3</sup>/<sub>4</sub> (закон Клейбера): слон в 10 000 раз тяжелее мыши, но тратит энергии лишь в 10 000<sup>3/4</sup> = 1000 раз больше.', '<b>Biology.</b> An animal’s energy use is roughly proportional to its mass to the power <sup>3</sup>/<sub>4</sub> (Kleiber’s law): an elephant is 10,000 times heavier than a mouse but uses only 10,000<sup>3/4</sup> = 1000 times more energy.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Kompyuter xotirasi o‘lchovlari ikkining darajalari: 1 KB = 2<sup>10</sup> = 1024 bayt. Manfiy darajalar esa juda kichik sonlarni yozishga qulay: 10<sup>−9</sup> m — nanometr.', 'Единицы компьютерной памяти — степени двойки: 1 КБ = 2<sup>10</sup> = 1024 байта. А отрицательные степени удобны для маленьких величин: 10<sup>−9</sup> м — нанометр.', 'Computer memory units are powers of two: 1 KB = 2<sup>10</sup> = 1024 bytes. Negative powers are handy for tiny quantities: 10<sup>−9</sup> m is a nanometre.'),
      L('Musiqadagi yarim ton chastotalari nisbati 2<sup>1/12</sup> ≈ 1,0595: «la» notasi 440 Hz bo‘lsa, bir yarim ton yuqoridagi nota ≈ 466,2 Hz.', 'Отношение частот полутона в музыке 2<sup>1/12</sup> ≈ 1,0595: если «ля» звучит на 440 Гц, нота на полутон выше — ≈ 466,2 Гц.', 'A musical semitone has frequency ratio 2<sup>1/12</sup> ≈ 1.0595: if A is 440 Hz, the note a semitone higher is ≈ 466.2 Hz.'),
      L('Ko‘rsatkich irratsional ham bo‘lishi mumkin, masalan 2<sup>√2</sup> ≈ 2,665. Bu yuqori sinflarda ratsional ko‘rsatkichlar orqali yaqinlashish yo‘li bilan ta’riflanadi.', 'Показатель бывает и иррациональным, например 2<sup>√2</sup> ≈ 2,665. В старших классах это определяют через приближения рациональными показателями.', 'Exponents can even be irrational, such as 2<sup>√2</sup> ≈ 2.665. In higher grades this is defined by approximating with rational exponents.')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('81<sup>3/4</sup> = ?', '81<sup>3/4</sup> = ?', '81<sup>3/4</sup> = ?'), s: L('(<sup>4</sup>√81)<sup>3</sup> = 3<sup>3</sup> = 27.', '(<sup>4</sup>√81)<sup>3</sup> = 3<sup>3</sup> = 27.', '(<sup>4</sup>√81)<sup>3</sup> = 3<sup>3</sup> = 27.') },
      { q: L('(<sup>1</sup>/<sub>4</sub>)<sup>−1/2</sup> = ?', '(<sup>1</sup>/<sub>4</sub>)<sup>−1/2</sup> = ?', '(<sup>1</sup>/<sub>4</sub>)<sup>−1/2</sup> = ?'), s: L('4<sup>1/2</sup> = 2.', '4<sup>1/2</sup> = 2.', '4<sup>1/2</sup> = 2.') },
      { q: L('(b<sup>3/4</sup>)<sup>4</sup> · b<sup>−2</sup> = ? (b &gt; 0)', '(b<sup>3/4</sup>)<sup>4</sup> · b<sup>−2</sup> = ? (b &gt; 0)', '(b<sup>3/4</sup>)<sup>4</sup> · b<sup>−2</sup> = ? (b &gt; 0)'), s: L('b<sup>3</sup> · b<sup>−2</sup> = b.', 'b<sup>3</sup> · b<sup>−2</sup> = b.', 'b<sup>3</sup> · b<sup>−2</sup> = b.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('a<sup>0</sup> = 1, a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub> (a ≠ 0).', 'a<sup>0</sup> = 1, a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub> (a ≠ 0).', 'a<sup>0</sup> = 1, a<sup>−n</sup> = <sup>1</sup>/<sub>a<sup>n</sup></sub> (a ≠ 0).'),
      L('a<sup>m/n</sup> = <sup>n</sup>√(a<sup>m</sup>) = (<sup>n</sup>√a)<sup>m</sup>, a &gt; 0.', 'a<sup>m/n</sup> = <sup>n</sup>√(a<sup>m</sup>) = (<sup>n</sup>√a)<sup>m</sup>, a &gt; 0.', 'a<sup>m/n</sup> = <sup>n</sup>√(a<sup>m</sup>) = (<sup>n</sup>√a)<sup>m</sup>, a &gt; 0.'),
      L('Ta’riflar darajaning eski xossalari saqlanishi uchun tanlangan.', 'Определения выбраны так, чтобы сохранились старые свойства степеней.', 'The definitions are chosen so that the old power laws remain true.'),
      L('Ko‘paytirishda ko‘rsatkichlar qo‘shiladi, bo‘lishda ayiriladi, darajani darajaga ko‘tarishda ko‘paytiriladi.', 'При умножении показатели складываются, при делении вычитаются, при возведении степени в степень перемножаются.', 'Exponents add when multiplying, subtract when dividing and multiply for a power of a power.'),
      L('Manfiy ko‘rsatkich sonni manfiy qilmaydi — u teskari sonni beradi.', 'Отрицательный показатель не делает число отрицательным — он даёт обратное число.', 'A negative exponent does not make a number negative — it gives the reciprocal.'),
      L('Hisoblashda avval ildiz, keyin daraja: sonlar kichik bo‘lib qoladi.', 'При вычислении сначала корень, потом степень: числа остаются маленькими.', 'When computing, take the root first and then the power: numbers stay small.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t7. Sonli tengsizliklar va ularning xossalari ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Tenglikdan tengsizlikka', 'От равенства к неравенству', 'From equality to inequality'), p: [
      L('Hayotda ko‘pincha aniq tenglik emas, balki «ko‘p yoki kam» degan savol muhim. Avtobusga ko‘pi bilan 50 yo‘lovchi sig‘adi; liftga 400 kg dan ortiq yuk ortib bo‘lmaydi; imtihondan o‘tish uchun kamida 56 ball kerak. Bularning barchasi <b>tengsizliklar</b> bilan yoziladi: n ≤ 50, m ≤ 400, b ≥ 56.', 'В жизни часто важно не точное равенство, а вопрос «больше или меньше». В автобус помещается не более 50 пассажиров; в лифт нельзя грузить больше 400 кг; чтобы сдать экзамен, нужно не меньше 56 баллов. Всё это записывается <b>неравенствами</b>: n ≤ 50, m ≤ 400, b ≥ 56.', 'In real life the question is often not exact equality but “more or less”. A bus holds at most 50 passengers; a lift cannot carry more than 400 kg; passing an exam needs at least 56 points. All of these are written as <b>inequalities</b>: n ≤ 50, m ≤ 400, b ≥ 56.'),
      L('Sonlarni taqqoslashni siz boshlang‘ich sinflardan bilasiz. Endi esa tengsizliklarni algebraik ob’ekt sifatida o‘rganamiz: ular ustida qanday amallar bajarish mumkin, qachon belgi saqlanadi va qachon teskarisiga o‘zgaradi? Bu xossalar keyingi mavzularda tengsizliklarni yechish uchun asosiy qurol bo‘ladi.', 'Сравнивать числа вы умеете с начальной школы. Теперь изучим неравенства как алгебраический объект: какие действия с ними можно выполнять, когда знак сохраняется и когда меняется на противоположный? Эти свойства станут главным инструментом для решения неравенств в следующих темах.', 'You have compared numbers since primary school. Now we study inequalities as algebraic objects: which operations can we perform on them, when does the sign stay, and when does it flip? These properties will be the main tool for solving inequalities in the next topics.')
    ] },
    { kind: 'def', h: L('Ta’rif: «katta» nimani anglatadi?', 'Определение: что значит «больше»?', 'Definition: what does “greater” mean?'), p: [
      L('<b>a soni b sonidan katta</b> (a &gt; b), agar a − b ayirma musbat bo‘lsa. <b>a soni b dan kichik</b> (a &lt; b), agar a − b manfiy bo‘lsa. Agar a − b = 0 bo‘lsa, a = b. Bu ta’rif har qanday ikki sonni taqqoslashning universal usulini beradi: ayirmani tuzib, uning ishorasini aniqlash kifoya.', '<b>Число a больше числа b</b> (a &gt; b), если разность a − b положительна. <b>a меньше b</b> (a &lt; b), если a − b отрицательна. Если a − b = 0, то a = b. Это определение даёт универсальный способ сравнения: составить разность и определить её знак.', '<b>a is greater than b</b> (a &gt; b) if the difference a − b is positive. <b>a is less than b</b> (a &lt; b) if a − b is negative. If a − b = 0, then a = b. This definition gives a universal way to compare any two numbers: form the difference and find its sign.'),
      L('&gt; va &lt; belgili tengsizliklar <b>qat’iy</b>, ≥ («katta yoki teng») va ≤ («kichik yoki teng») belgililari <b>noqat’iy</b> tengsizliklar deyiladi. a ≥ b yozuvi «a &gt; b yoki a = b» degani, shuning uchun 5 ≥ 5 va 7 ≥ 5 — ikkalasi ham to‘g‘ri. Ikki tengsizlik <b>bir xil ma’noli</b> deyiladi, agar ularning belgilari bir xil bo‘lsa (masalan, a &gt; b va c &gt; d), aks holda — <b>qarama-qarshi ma’noli</b>.', 'Неравенства со знаками &gt; и &lt; называются <b>строгими</b>, со знаками ≥ («больше или равно») и ≤ («меньше или равно») — <b>нестрогими</b>. Запись a ≥ b означает «a &gt; b или a = b», поэтому верны и 5 ≥ 5, и 7 ≥ 5. Два неравенства называются <b>одного смысла</b>, если их знаки одинаковы (например, a &gt; b и c &gt; d), иначе — <b>противоположного смысла</b>.', 'Inequalities with &gt; and &lt; are <b>strict</b>; those with ≥ (“greater than or equal to”) and ≤ (“less than or equal to”) are <b>non-strict</b>. a ≥ b means “a &gt; b or a = b”, so both 5 ≥ 5 and 7 ≥ 5 are true. Two inequalities have the <b>same direction</b> if their signs match (for example a &gt; b and c &gt; d); otherwise they have <b>opposite directions</b>.')
    ] },
    { kind: 'history', h: L('Tarixdan: &lt; va &gt; belgilari qanday paydo bo‘lgan', 'Из истории: откуда знаки &lt; и &gt;', 'From history: where &lt; and &gt; came from'), p: [
      L('Uzoq vaqt «katta» va «kichik» so‘z bilan yozilgan. Tenglik belgisi «=» ni 1557-yilda uelslik <b>Robert Rekord</b> kiritgan: «ikki parallel kesmadan ko‘ra tengroq narsa yo‘q». &lt; va &gt; belgilarini esa ingliz matematigi va astronomi <b>Tomas Xarriot</b> o‘ylab topgan; ular uning vafotidan keyin, 1631-yilda nashr etilgan «Analitik san’at amaliyoti» kitobida paydo bo‘lgan. Belgining keng tomoni katta songa, o‘tkir uchi kichik songa qaraydi.', 'Долгое время «больше» и «меньше» писали словами. Знак равенства «=» ввёл в 1557 году валлиец <b>Роберт Рекорд</b>: «нет ничего более равного, чем два параллельных отрезка». Знаки &lt; и &gt; придумал английский математик и астроном <b>Томас Хэрриот</b>; они появились в его книге «Практика аналитического искусства», изданной посмертно в 1631 году. Широкая сторона знака обращена к большему числу, острие — к меньшему.', 'For a long time “greater” and “less” were written out in words. The equals sign “=” was introduced in 1557 by the Welshman <b>Robert Recorde</b>: “nothing is more equal than a pair of parallel lines”. The signs &lt; and &gt; were invented by the English mathematician and astronomer <b>Thomas Harriot</b>; they appeared in his book “The Practice of the Analytic Art”, published after his death in 1631. The open side faces the larger number, the point faces the smaller.'),
      L('≤ va ≥ belgilarini 1734-yilda fransuz olimi <b>Pyer Buger</b> taklif qilgan. Sharq olimlari esa tengsizliklarni so‘z bilan bo‘lsa-da faol qo‘llagan: <b>Beruniy</b> va <b>Ulug‘bek</b> astronomik kattaliklarni «dan katta, lekin dan kichik» ko‘rinishidagi chegaralar bilan baholagan. Arximed esa π sonini 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub> qo‘sh tengsizlik bilan aniqlagan.', 'Знаки ≤ и ≥ предложил в 1734 году французский учёный <b>Пьер Бугер</b>. Учёные Востока активно пользовались неравенствами, хотя и словесно: <b>Беруни</b> и <b>Улугбек</b> оценивали астрономические величины границами вида «больше, чем…, но меньше, чем…». А Архимед заключил π в двойное неравенство 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub>.', 'The signs ≤ and ≥ were proposed in 1734 by the French scientist <b>Pierre Bouguer</b>. Scholars of the East used inequalities actively, if in words: <b>al-Biruni</b> and <b>Ulugh Beg</b> estimated astronomical quantities with bounds of the form “more than …, but less than …”. Archimedes trapped π in the double inequality 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub>.')
    ] },
    { kind: 'rule', h: L('Sonli tengsizliklarning xossalari', 'Свойства числовых неравенств', 'Properties of numerical inequalities'), list: [
      L('<b>1. Antisimmetriya:</b> a &gt; b bo‘lsa, b &lt; a.', '<b>1. Антисимметричность:</b> если a &gt; b, то b &lt; a.', '<b>1. Reversal:</b> if a &gt; b, then b &lt; a.'),
      L('<b>2. Tranzitivlik:</b> a &gt; b va b &gt; c bo‘lsa, a &gt; c. <i>Isbot:</i> a − c = (a − b) + (b − c) — ikki musbat sonning yig‘indisi, demak musbat.', '<b>2. Транзитивность:</b> если a &gt; b и b &gt; c, то a &gt; c. <i>Доказательство:</i> a − c = (a − b) + (b − c) — сумма двух положительных чисел, значит положительна.', '<b>2. Transitivity:</b> if a &gt; b and b &gt; c, then a &gt; c. <i>Proof:</i> a − c = (a − b) + (b − c) is a sum of two positives, hence positive.'),
      L('<b>3.</b> a &gt; b bo‘lsa, istalgan c uchun a + c &gt; b + c. <i>Isbot:</i> (a + c) − (b + c) = a − b &gt; 0.', '<b>3.</b> Если a &gt; b, то a + c &gt; b + c для любого c. <i>Доказательство:</i> (a + c) − (b + c) = a − b &gt; 0.', '<b>3.</b> If a &gt; b, then a + c &gt; b + c for any c. <i>Proof:</i> (a + c) − (b + c) = a − b &gt; 0.'),
      L('<b>4.</b> a &gt; b va c &gt; 0 bo‘lsa, ac &gt; bc; a &gt; b va c &lt; 0 bo‘lsa, ac &lt; bc. <i>Isbot:</i> ac − bc = (a − b)c; a − b &gt; 0, shuning uchun ko‘paytmaning ishorasi c ning ishorasiga teng.', '<b>4.</b> Если a &gt; b и c &gt; 0, то ac &gt; bc; если a &gt; b и c &lt; 0, то ac &lt; bc. <i>Доказательство:</i> ac − bc = (a − b)c; a − b &gt; 0, поэтому знак произведения совпадает со знаком c.', '<b>4.</b> If a &gt; b and c &gt; 0, then ac &gt; bc; if a &gt; b and c &lt; 0, then ac &lt; bc. <i>Proof:</i> ac − bc = (a − b)c; since a − b &gt; 0, the product has the same sign as c.'),
      L('<b>5. Qo‘shish:</b> a &gt; b va c &gt; d bo‘lsa, a + c &gt; b + d (bir xil ma’noli tengsizliklarni hadma-had qo‘shish mumkin).', '<b>5. Сложение:</b> если a &gt; b и c &gt; d, то a + c &gt; b + d (неравенства одного смысла можно почленно складывать).', '<b>5. Adding:</b> if a &gt; b and c &gt; d, then a + c &gt; b + d (inequalities of the same direction can be added term by term).'),
      L('<b>6. Ko‘paytirish:</b> a &gt; b &gt; 0 va c &gt; d &gt; 0 bo‘lsa, ac &gt; bd. Natija: a &gt; b &gt; 0 bo‘lsa, a<sup>n</sup> &gt; b<sup>n</sup> va <sup>1</sup>/<sub>a</sub> &lt; <sup>1</sup>/<sub>b</sub>.', '<b>6. Умножение:</b> если a &gt; b &gt; 0 и c &gt; d &gt; 0, то ac &gt; bd. Следствие: при a &gt; b &gt; 0 a<sup>n</sup> &gt; b<sup>n</sup> и <sup>1</sup>/<sub>a</sub> &lt; <sup>1</sup>/<sub>b</sub>.', '<b>6. Multiplying:</b> if a &gt; b &gt; 0 and c &gt; d &gt; 0, then ac &gt; bd. Consequence: for a &gt; b &gt; 0, a<sup>n</sup> &gt; b<sup>n</sup> and <sup>1</sup>/<sub>a</sub> &lt; <sup>1</sup>/<sub>b</sub>.')
    ] },
    { kind: 'steps', h: L('Ayirma usuli bilan taqqoslash', 'Сравнение методом разности', 'Comparing by the difference method'), p: [
      L('Ikki ifodani taqqoslash yoki tengsizlikni isbotlash uchun eng ishonchli yo‘l — ta’rifdan foydalanish:', 'Самый надёжный способ сравнить два выражения или доказать неравенство — воспользоваться определением:', 'The most reliable way to compare two expressions or prove an inequality is to use the definition:')
    ], list: [
      L('<b>1.</b> Ayirmani tuzing: A − B.', '<b>1.</b> Составьте разность A − B.', '<b>1.</b> Form the difference A − B.'),
      L('<b>2.</b> Uni soddalashtiring: umumiy maxrajga keltiring, qavslarni oching yoki ko‘paytuvchilarga ajrating, to‘la kvadrat ajrating.', '<b>2.</b> Упростите её: приведите к общему знаменателю, раскройте скобки или разложите на множители, выделите полный квадрат.', '<b>2.</b> Simplify it: use a common denominator, expand or factorise, complete the square.'),
      L('<b>3.</b> Ishorasini aniqlang. Kvadrat har doim ≥ 0, musbat sonlarning ko‘paytmasi va yig‘indisi musbat.', '<b>3.</b> Определите знак. Квадрат всегда ≥ 0, произведение и сумма положительных чисел положительны.', '<b>3.</b> Determine its sign. A square is always ≥ 0; sums and products of positive numbers are positive.'),
      L('<b>4.</b> Xulosa yozing: A − B &gt; 0 bo‘lsa, A &gt; B; A − B ≥ 0 bo‘lsa, A ≥ B.', '<b>4.</b> Сделайте вывод: если A − B &gt; 0, то A &gt; B; если A − B ≥ 0, то A ≥ B.', '<b>4.</b> Conclude: if A − B &gt; 0, then A &gt; B; if A − B ≥ 0, then A ≥ B.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Taqqoslang: <sup>5</sup>/<sub>8</sub> va <sup>7</sup>/<sub>11</sub>.', 'Сравните <sup>5</sup>/<sub>8</sub> и <sup>7</sup>/<sub>11</sub>.', 'Compare <sup>5</sup>/<sub>8</sub> and <sup>7</sup>/<sub>11</sub>.'),
        s: L('<sup>5</sup>/<sub>8</sub> − <sup>7</sup>/<sub>11</sub> = <sup>55 − 56</sup>/<sub>88</sub> = −<sup>1</sup>/<sub>88</sub> &lt; 0. Demak, <sup>5</sup>/<sub>8</sub> &lt; <sup>7</sup>/<sub>11</sub>.', '<sup>5</sup>/<sub>8</sub> − <sup>7</sup>/<sub>11</sub> = <sup>55 − 56</sup>/<sub>88</sub> = −<sup>1</sup>/<sub>88</sub> &lt; 0. Значит, <sup>5</sup>/<sub>8</sub> &lt; <sup>7</sup>/<sub>11</sub>.', '<sup>5</sup>/<sub>8</sub> − <sup>7</sup>/<sub>11</sub> = <sup>55 − 56</sup>/<sub>88</sub> = −<sup>1</sup>/<sub>88</sub> &lt; 0. Hence <sup>5</sup>/<sub>8</sub> &lt; <sup>7</sup>/<sub>11</sub>.') },
      { q: L('Isbotlang: istalgan a, b uchun a<sup>2</sup> + b<sup>2</sup> ≥ 2ab.', 'Докажите: для любых a, b a<sup>2</sup> + b<sup>2</sup> ≥ 2ab.', 'Prove that a<sup>2</sup> + b<sup>2</sup> ≥ 2ab for all a, b.'),
        s: L('a<sup>2</sup> + b<sup>2</sup> − 2ab = (a − b)<sup>2</sup> ≥ 0. Tenglik faqat a = b da. Natija: musbat a, b uchun <sup>a + b</sup>/<sub>2</sub> ≥ √(ab) — o‘rta arifmetik o‘rta geometrikdan kichik emas.', 'a<sup>2</sup> + b<sup>2</sup> − 2ab = (a − b)<sup>2</sup> ≥ 0. Равенство только при a = b. Следствие: для положительных a, b <sup>a + b</sup>/<sub>2</sub> ≥ √(ab) — среднее арифметическое не меньше среднего геометрического.', 'a<sup>2</sup> + b<sup>2</sup> − 2ab = (a − b)<sup>2</sup> ≥ 0, with equality only when a = b. Consequence: for positive a, b, <sup>a + b</sup>/<sub>2</sub> ≥ √(ab) — the arithmetic mean is at least the geometric mean.') },
      { q: L('2 &lt; a &lt; 3 va 4 &lt; b &lt; 5 ma’lum. a + b, a − b va ab ni baholang.', 'Известно 2 &lt; a &lt; 3 и 4 &lt; b &lt; 5. Оцените a + b, a − b и ab.', 'Given 2 &lt; a &lt; 3 and 4 &lt; b &lt; 5, estimate a + b, a − b and ab.'),
        s: L('Qo‘shamiz: 6 &lt; a + b &lt; 8. Ayirma uchun −b ni baholaymiz: −5 &lt; −b &lt; −4 (−1 ga ko‘paytirganda belgilar almashdi); qo‘shsak, −3 &lt; a − b &lt; −1. Barcha sonlar musbat, ko‘paytiramiz: 8 &lt; ab &lt; 15.', 'Складываем: 6 &lt; a + b &lt; 8. Для разности оценим −b: −5 &lt; −b &lt; −4 (при умножении на −1 знаки сменились); складывая, −3 &lt; a − b &lt; −1. Все числа положительны, перемножаем: 8 &lt; ab &lt; 15.', 'Add: 6 &lt; a + b &lt; 8. For the difference, estimate −b: −5 &lt; −b &lt; −4 (multiplying by −1 flipped the signs); adding gives −3 &lt; a − b &lt; −1. All numbers are positive, so multiply: 8 &lt; ab &lt; 15.') },
      { q: L('Taqqoslang: √3 + √5 va 4.', 'Сравните √3 + √5 и 4.', 'Compare √3 + √5 and 4.'),
        s: L('Ikkala son musbat, kvadratga ko‘taramiz (6-xossa natijasi): (√3 + √5)<sup>2</sup> = 8 + 2√15, 4<sup>2</sup> = 16. 2√15 = √60 &lt; √64 = 8, demak 8 + 2√15 &lt; 16 va √3 + √5 &lt; 4.', 'Оба числа положительны, возводим в квадрат (следствие свойства 6): (√3 + √5)<sup>2</sup> = 8 + 2√15, 4<sup>2</sup> = 16. 2√15 = √60 &lt; √64 = 8, значит 8 + 2√15 &lt; 16 и √3 + √5 &lt; 4.', 'Both numbers are positive, so square them (a consequence of property 6): (√3 + √5)<sup>2</sup> = 8 + 2√15 and 4<sup>2</sup> = 16. Since 2√15 = √60 &lt; √64 = 8, we get 8 + 2√15 &lt; 16, so √3 + √5 &lt; 4.') }
    ] },
    { kind: 'table', h: L('Amallar va belgi: qachon almashadi?', 'Действия и знак: когда он меняется?', 'Operations and the sign: when does it flip?'), table: { head: [L('a &gt; b bilan amal', 'Действие с a &gt; b', 'Operation on a &gt; b'), L('Natija', 'Результат', 'Result'), L('Belgi', 'Знак', 'Sign')], rows: [
      [L('ikki tomonga c qo‘shish', 'прибавить c к обеим частям', 'add c to both sides'), L('a + c &gt; b + c', 'a + c &gt; b + c', 'a + c &gt; b + c'), L('saqlanadi', 'сохраняется', 'kept')],
      [L('c &gt; 0 ga ko‘paytirish', 'умножить на c &gt; 0', 'multiply by c &gt; 0'), L('ac &gt; bc', 'ac &gt; bc', 'ac &gt; bc'), L('saqlanadi', 'сохраняется', 'kept')],
      [L('c &lt; 0 ga ko‘paytirish', 'умножить на c &lt; 0', 'multiply by c &lt; 0'), L('ac &lt; bc', 'ac &lt; bc', 'ac &lt; bc'), L('almashadi', 'меняется', 'flipped')],
      [L('teskari songa o‘tish (a, b &gt; 0)', 'перейти к обратным (a, b &gt; 0)', 'take reciprocals (a, b &gt; 0)'), L('<sup>1</sup>/<sub>a</sub> &lt; <sup>1</sup>/<sub>b</sub>', '<sup>1</sup>/<sub>a</sub> &lt; <sup>1</sup>/<sub>b</sub>', '<sup>1</sup>/<sub>a</sub> &lt; <sup>1</sup>/<sub>b</sub>'), L('almashadi', 'меняется', 'flipped')],
      [L('kvadratga ko‘tarish (a, b ≥ 0)', 'возвести в квадрат (a, b ≥ 0)', 'square (a, b ≥ 0)'), L('a<sup>2</sup> &gt; b<sup>2</sup>', 'a<sup>2</sup> &gt; b<sup>2</sup>', 'a<sup>2</sup> &gt; b<sup>2</sup>'), L('saqlanadi', 'сохраняется', 'kept')]
    ] }, after: [
      L('Manfiy sonlarni kvadratga ko‘tarishda ehtiyot bo‘ling: −3 &gt; −5, lekin 9 &lt; 25.', 'Осторожно с квадратами отрицательных чисел: −3 &gt; −5, но 9 &lt; 25.', 'Be careful when squaring negatives: −3 &gt; −5, but 9 &lt; 25.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Manfiy songa ko‘paytirib, belgini almashtirmaslik.</b> 3 &gt; 1 ⇒ −3 &gt; −1 — xato; to‘g‘risi −3 &lt; −1.', '<b>Не сменить знак при умножении на отрицательное.</b> 3 &gt; 1 ⇒ −3 &gt; −1 — ошибка; верно −3 &lt; −1.', '<b>Not flipping when multiplying by a negative.</b> 3 &gt; 1 ⇒ −3 &gt; −1 is wrong; correct: −3 &lt; −1.'),
      L('<b>Tengsizliklarni ayirish.</b> 10 &gt; 2 va 9 &gt; 1 dan 10 − 9 &gt; 2 − 1, ya’ni 1 &gt; 1 kelib chiqmaydi. Bir xil ma’noli tengsizliklarni faqat qo‘shish mumkin, ayirish uchun ikkinchisini −1 ga ko‘paytirib, belgisini almashtiring.', '<b>Вычитание неравенств.</b> Из 10 &gt; 2 и 9 &gt; 1 не следует 10 − 9 &gt; 2 − 1, то есть 1 &gt; 1. Неравенства одного смысла можно только складывать; для вычитания умножьте второе на −1 и смените его знак.', '<b>Subtracting inequalities.</b> 10 &gt; 2 and 9 &gt; 1 do not give 10 − 9 &gt; 2 − 1, i.e. 1 &gt; 1. Same-direction inequalities may only be added; to subtract, multiply the second by −1 and flip its sign.'),
      L('<b>Manfiy sonlar bilan ko‘paytirish.</b> 2 &gt; −3 va 1 &gt; −4, lekin 2 · 1 = 2 &lt; 12 = (−3)(−4). 6-xossa faqat musbat sonlar uchun.', '<b>Перемножение с отрицательными.</b> 2 &gt; −3 и 1 &gt; −4, но 2 · 1 = 2 &lt; 12 = (−3)(−4). Свойство 6 — только для положительных.', '<b>Multiplying with negatives.</b> 2 &gt; −3 and 1 &gt; −4, but 2 · 1 = 2 &lt; 12 = (−3)(−4). Property 6 is only for positive numbers.'),
      L('<b>≥ ni noto‘g‘ri tushunish.</b> «4 ≥ 4» to‘g‘ri tengsizlik; «4 &gt; 4» esa noto‘g‘ri.', '<b>Непонимание ≥.</b> «4 ≥ 4» — верное неравенство, а «4 &gt; 4» — неверное.', '<b>Misreading ≥.</b> “4 ≥ 4” is true, while “4 &gt; 4” is false.')
    ] },
    { kind: 'life', h: L('Hayotda tengsizliklar', 'Неравенства в жизни', 'Inequalities in life'), p: [
      L('<b>Baholash va xatolik.</b> O‘lchovlar hech qachon mutlaq aniq bo‘lmaydi. Xona uzunligi 4,25 m bilan 4,26 m orasida, eni 3,10 m bilan 3,12 m orasida bo‘lsa, 4-xossa va 6-xossa bo‘yicha yuz 13,175 m<sup>2</sup> bilan 13,291 m<sup>2</sup> oralig‘ida. Muhandislar xuddi shunday hisoblaydi.', '<b>Оценки и погрешности.</b> Измерения никогда не бывают абсолютно точными. Если длина комнаты между 4,25 и 4,26 м, а ширина между 3,10 и 3,12 м, то по свойствам неравенств площадь между 13,175 и 13,291 м<sup>2</sup>. Инженеры считают именно так.', '<b>Estimates and errors.</b> Measurements are never perfectly exact. If a room is between 4.25 and 4.26 m long and between 3.10 and 3.12 m wide, the inequality properties put its area between 13.175 and 13.291 m<sup>2</sup>. Engineers calculate exactly like this.'),
      L('<b>Xavfsizlik.</b> Yo‘l belgilari «60 dan oshmasin» (v ≤ 60), dorilar dozasi «sutkasiga 4 tabletkadan ko‘p emas», ko‘prik ustidan «10 tonnadan og‘ir bo‘lmagan» mashinalar o‘tadi. <b>Byudjet:</b> oylik xarajatlar daromaddan oshmasligi kerak — bu ham tengsizlik.', '<b>Безопасность.</b> Знаки «не более 60» (v ≤ 60), дозировка лекарства «не более 4 таблеток в сутки», по мосту проезжают машины «не тяжелее 10 тонн». <b>Бюджет:</b> расходы за месяц не должны превышать доходы — это тоже неравенство.', '<b>Safety.</b> Road signs say “no more than 60” (v ≤ 60), medicine labels say “no more than 4 tablets a day”, a bridge allows lorries “not heavier than 10 tonnes”. <b>Budgeting:</b> monthly spending must not exceed income — another inequality.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Xarriot faqat matematik emas edi: u 1609-yilda, Galileydan bir necha oy oldin, Oyni teleskopda kuzatib, uning xaritasini chizgan.', 'Хэрриот был не только математиком: в 1609 году, на несколько месяцев раньше Галилея, он наблюдал Луну в телескоп и зарисовал её карту.', 'Harriot was not only a mathematician: in 1609, a few months before Galileo, he observed the Moon through a telescope and drew a map of it.'),
      L('Perimetri bir xil bo‘lgan to‘g‘ri to‘rtburchaklar ichida eng katta yuzaga kvadrat ega — bu a<sup>2</sup> + b<sup>2</sup> ≥ 2ab tengsizlikning natijasi.', 'Среди прямоугольников с одинаковым периметром наибольшую площадь имеет квадрат — это следствие неравенства a<sup>2</sup> + b<sup>2</sup> ≥ 2ab.', 'Among rectangles with the same perimeter, the square has the largest area — a consequence of a<sup>2</sup> + b<sup>2</sup> ≥ 2ab.'),
      L('Arximedning 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub> bahosi π ni 0,002 dan yaxshiroq aniqlikda beradi — 2200 yil oldin!', 'Оценка Архимеда 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub> даёт π с точностью лучше 0,002 — 2200 лет назад!', 'Archimedes’ bound 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub> pins down π to better than 0.002 — 2200 years ago!')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('a &gt; b. Taqqoslang: 5 − 2a va 5 − 2b.', 'a &gt; b. Сравните 5 − 2a и 5 − 2b.', 'a &gt; b. Compare 5 − 2a and 5 − 2b.'), s: L('−2a &lt; −2b, demak 5 − 2a &lt; 5 − 2b.', '−2a &lt; −2b, значит 5 − 2a &lt; 5 − 2b.', '−2a &lt; −2b, so 5 − 2a &lt; 5 − 2b.') },
      { q: L('1 &lt; x &lt; 3 bo‘lsa, 2x + 1 qaysi oraliqda?', 'Если 1 &lt; x &lt; 3, где находится 2x + 1?', 'If 1 &lt; x &lt; 3, where does 2x + 1 lie?'), s: L('3 &lt; 2x + 1 &lt; 7.', '3 &lt; 2x + 1 &lt; 7.', '3 &lt; 2x + 1 &lt; 7.') },
      { q: L('Isbotlang: x<sup>2</sup> + 4 ≥ 4x.', 'Докажите: x<sup>2</sup> + 4 ≥ 4x.', 'Prove x<sup>2</sup> + 4 ≥ 4x.'), s: L('x<sup>2</sup> − 4x + 4 = (x − 2)<sup>2</sup> ≥ 0.', 'x<sup>2</sup> − 4x + 4 = (x − 2)<sup>2</sup> ≥ 0.', 'x<sup>2</sup> − 4x + 4 = (x − 2)<sup>2</sup> ≥ 0.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('a &gt; b ⇔ a − b &gt; 0: taqqoslash uchun ayirmaning ishorasini topamiz.', 'a &gt; b ⇔ a − b &gt; 0: для сравнения находим знак разности.', 'a &gt; b ⇔ a − b &gt; 0: to compare, find the sign of the difference.'),
      L('Ikki tomonga bir xil son qo‘shish yoki ayirish belgini saqlaydi.', 'Прибавление или вычитание одного числа сохраняет знак.', 'Adding or subtracting the same number keeps the sign.'),
      L('Musbat songa ko‘paytirish belgini saqlaydi, manfiy songa ko‘paytirish — almashtiradi.', 'Умножение на положительное сохраняет знак, на отрицательное — меняет.', 'Multiplying by a positive keeps the sign; by a negative flips it.'),
      L('Bir xil ma’noli tengsizliklarni qo‘shish mumkin, ayirish mumkin emas.', 'Неравенства одного смысла можно складывать, но не вычитать.', 'Same-direction inequalities can be added, not subtracted.'),
      L('Musbat hadli tengsizliklarni ko‘paytirish va darajaga ko‘tarish mumkin.', 'Неравенства с положительными членами можно перемножать и возводить в степень.', 'Inequalities with positive terms can be multiplied and raised to powers.'),
      L('&lt; va &gt; belgilarini Xarriot, ≤ va ≥ ni Buger kiritgan.', 'Знаки &lt; и &gt; ввёл Хэрриот, ≤ и ≥ — Бугер.', 'Harriot introduced &lt; and &gt;, Bouguer introduced ≤ and ≥.')
    ] }
  ] });

  // ---------- t8. Bir noma'lumli tengsizliklar ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('Bitta javob emas, butun to‘plam', 'Не один ответ, а целое множество', 'Not one answer but a whole set'), p: [
      L('Telefon tarifi: oylik to‘lov 30 000 so‘m va har bir gigabayt uchun 5 000 so‘m. Oyiga 80 000 so‘mdan oshirmaslik uchun ko‘pi bilan necha gigabayt ishlatish mumkin? Gigabaytlar sonini x deb belgilasak, 30 000 + 5 000x ≤ 80 000 tengsizlikni olamiz. Uning yechimi x ≤ 10 — bu bitta son emas, balki cheksiz ko‘p sonlar to‘plami.', 'Тариф телефона: абонентская плата 30 000 сумов и 5 000 сумов за каждый гигабайт. Сколько гигабайт можно использовать, чтобы не потратить больше 80 000 сумов в месяц? Обозначив число гигабайт через x, получим неравенство 30 000 + 5 000x ≤ 80 000. Его решение x ≤ 10 — не одно число, а бесконечное множество чисел.', 'A phone plan costs 30,000 sum a month plus 5,000 sum per gigabyte. How many gigabytes can you use without spending more than 80,000 sum a month? Writing x for the number of gigabytes, we get 30,000 + 5,000x ≤ 80,000. Its solution x ≤ 10 is not a single number but an infinite set of numbers.'),
      L('Bu tenglama va tengsizlikning asosiy farqi: tenglamaning odatda bir yoki bir nechta ildizi bo‘ladi, tengsizlikning yechimi esa ko‘pincha butun <b>son oralig‘i</b>. Bu mavzuda chiziqli tengsizliklarni yechishni, javobni oraliq va son o‘qida tasvirlashni o‘rganamiz.', 'В этом главное отличие уравнения от неравенства: у уравнения обычно один или несколько корней, а решение неравенства чаще всего — целый <b>числовой промежуток</b>. В этой теме научимся решать линейные неравенства и изображать ответ промежутком и на числовой прямой.', 'This is the key difference between equations and inequalities: an equation usually has one or a few roots, while the solution of an inequality is usually a whole <b>interval</b> of numbers. In this topic we learn to solve linear inequalities and show the answer as an interval and on the number line.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), p: [
      L('O‘zgaruvchi qatnashgan tengsizlikning <b>yechimi</b> — uni to‘g‘ri sonli tengsizlikka aylantiradigan o‘zgaruvchi qiymati. <b>Tengsizlikni yechish</b> — uning barcha yechimlarini topish yoki yechimlari yo‘qligini ko‘rsatish. Masalan, x = 4 soni 2x − 1 &gt; 5 ning yechimi (7 &gt; 5), x = 2 esa yechim emas (3 &gt; 5 — noto‘g‘ri).', '<b>Решение</b> неравенства с переменной — значение переменной, обращающее его в верное числовое неравенство. <b>Решить неравенство</b> — найти все его решения или доказать, что их нет. Например, x = 4 — решение 2x − 1 &gt; 5 (7 &gt; 5), а x = 2 — нет (3 &gt; 5 неверно).', 'A <b>solution</b> of an inequality in a variable is a value that turns it into a true numerical inequality. To <b>solve</b> an inequality means to find all its solutions or show there are none. For example, x = 4 solves 2x − 1 &gt; 5 (7 &gt; 5), while x = 2 does not (3 &gt; 5 is false).'),
      L('ax + b &gt; 0 (yoki &lt;, ≥, ≤) ko‘rinishidagi tengsizlik, bunda a ≠ 0, <b>birinchi darajali</b> (chiziqli) tengsizlik deyiladi. Yechimlari bir xil bo‘lgan ikki tengsizlik <b>teng kuchli</b> deyiladi. Tengsizlikni yechish — uni ketma-ket teng kuchli, borgan sari soddaroq tengsizliklar bilan almashtirish.', 'Неравенство вида ax + b &gt; 0 (или &lt;, ≥, ≤), где a ≠ 0, называется <b>линейным</b> (первой степени). Два неравенства с одинаковыми множествами решений называются <b>равносильными</b>. Решить неравенство — последовательно заменять его равносильными, всё более простыми.', 'An inequality of the form ax + b &gt; 0 (or &lt;, ≥, ≤) with a ≠ 0 is called <b>linear</b> (first-degree). Two inequalities with the same solution sets are <b>equivalent</b>. Solving an inequality means replacing it step by step with simpler equivalent ones.')
    ] },
    { kind: 'history', h: L('Tarixdan: tengsizliklar fanga aylanadi', 'Из истории: неравенства становятся наукой', 'From history: inequalities become a science'), p: [
      L('<b>Al-Xorazmiy</b> tenglamalarni yechishda ikki asosiy amal — «al-jabr» (manfiy hadni boshqa tomonga o‘tkazib, uni musbat qilish) va «al-muqobala» (ikki tomondagi o‘xshash hadlarni ixchamlash)dan foydalangan. Ajablanarlisi shundaki, bugun tengsizliklarni yechishda ham aynan shu ikki amal ishlatiladi — faqat manfiy songa bo‘lishda belgini almashtirishni unutmaslik kerak.', '<b>Аль-Хорезми</b> при решении уравнений применял два главных действия — «аль-джабр» (перенос отрицательного члена в другую часть, где он становится положительным) и «аль-мукабала» (приведение подобных членов в обеих частях). Удивительно, но при решении неравенств сегодня используют те же два действия — нужно лишь не забывать менять знак при делении на отрицательное число.', '<b>Al-Khwarizmi</b> solved equations with two main operations — “al-jabr” (moving a negative term to the other side, where it becomes positive) and “al-muqabala” (collecting like terms on both sides). Remarkably, today we use exactly the same two operations to solve inequalities — we just must remember to flip the sign when dividing by a negative number.'),
      L('XIX asrda fransuz <b>Jozef Furye</b> chiziqli tengsizliklar sistemalarini o‘rgana boshladi. 1939-yilda sovet matematigi <b>Leonid Kantorovich</b> zavod ishini rejalashtirish uchun chiziqli tengsizliklarga asoslangan usul yaratdi — <b>chiziqli dasturlash</b>. Bu ish uchun u 1975-yilda iqtisod bo‘yicha Nobel mukofotini oldi.', 'В XIX веке француз <b>Жозеф Фурье</b> начал изучать системы линейных неравенств. В 1939 году советский математик <b>Леонид Канторович</b> для планирования работы фабрики создал метод на основе линейных неравенств — <b>линейное программирование</b>. За эту работу в 1975 году он получил Нобелевскую премию по экономике.', 'In the 19th century the Frenchman <b>Joseph Fourier</b> began to study systems of linear inequalities. In 1939 the Soviet mathematician <b>Leonid Kantorovich</b> created a method based on linear inequalities to plan a factory’s work — <b>linear programming</b>. In 1975 he received the Nobel Prize in Economics for this work.')
    ] },
    { kind: 'rule', h: L('Teng kuchli almashtirishlar', 'Равносильные преобразования', 'Equivalent transformations'), list: [
      L('<b>1. Hadni ko‘chirish.</b> Istalgan hadni tengsizlikning bir tomonidan ikkinchisiga qarama-qarshi ishora bilan o‘tkazish mumkin: 3x − 7 &gt; 2 ⇔ 3x &gt; 2 + 7. Bu ikki tomonga bir xil son qo‘shishning o‘zi.', '<b>1. Перенос членов.</b> Любой член можно перенести из одной части неравенства в другую с противоположным знаком: 3x − 7 &gt; 2 ⇔ 3x &gt; 2 + 7. Это то же, что прибавить к обеим частям одно число.', '<b>1. Moving terms.</b> Any term can be moved to the other side with the opposite sign: 3x − 7 &gt; 2 ⇔ 3x &gt; 2 + 7. This is just adding the same number to both sides.'),
      L('<b>2. Musbat songa ko‘paytirish yoki bo‘lish.</b> Ikki tomonni bir xil musbat songa ko‘paytirish yoki bo‘lish mumkin, belgi saqlanadi: 3x &gt; 9 ⇔ x &gt; 3.', '<b>2. Умножение или деление на положительное число.</b> Обе части можно умножить или разделить на одно положительное число, знак сохраняется: 3x &gt; 9 ⇔ x &gt; 3.', '<b>2. Multiplying or dividing by a positive.</b> Both sides may be multiplied or divided by the same positive number; the sign stays: 3x &gt; 9 ⇔ x &gt; 3.'),
      L('<b>3. Manfiy songa ko‘paytirish yoki bo‘lish.</b> Ikki tomonni manfiy songa ko‘paytirsak yoki bo‘lsak, tengsizlik belgisini <b>qarama-qarshisiga</b> almashtirish shart: −2x &gt; 6 ⇔ x &lt; −3.', '<b>3. Умножение или деление на отрицательное число.</b> Умножая или деля обе части на отрицательное число, знак неравенства нужно <b>поменять на противоположный</b>: −2x &gt; 6 ⇔ x &lt; −3.', '<b>3. Multiplying or dividing by a negative.</b> When multiplying or dividing both sides by a negative number, the inequality sign <b>must be reversed</b>: −2x &gt; 6 ⇔ x &lt; −3.')
    ], after: [
      L('Bu qoidalar oldingi mavzudagi sonli tengsizliklar xossalaridan bevosita kelib chiqadi: x ning har bir qiymati uchun biz sonli tengsizlik bilan ishlayapmiz. Yakunda ax &gt; b ko‘rinishi hosil bo‘ladi: a &gt; 0 da x &gt; <sup>b</sup>/<sub>a</sub>, a &lt; 0 da x &lt; <sup>b</sup>/<sub>a</sub>. Agar a = 0 bo‘lib qolsa (0 · x &gt; b), javob b ga bog‘liq: b &lt; 0 da x — istalgan son, b ≥ 0 da yechim yo‘q.', 'Эти правила прямо следуют из свойств числовых неравенств: для каждого значения x мы работаем с числовым неравенством. В итоге получается ax &gt; b: при a &gt; 0 x &gt; <sup>b</sup>/<sub>a</sub>, при a &lt; 0 x &lt; <sup>b</sup>/<sub>a</sub>. Если же a = 0 (0 · x &gt; b), ответ зависит от b: при b &lt; 0 x — любое число, при b ≥ 0 решений нет.', 'These rules follow directly from the properties of numerical inequalities: for each value of x we are dealing with a numerical inequality. In the end we get ax &gt; b: if a &gt; 0, x &gt; <sup>b</sup>/<sub>a</sub>; if a &lt; 0, x &lt; <sup>b</sup>/<sub>a</sub>. If a = 0 (0 · x &gt; b), the answer depends on b: for b &lt; 0 every x works, for b ≥ 0 there is no solution.')
    ] },
    { kind: 'steps', h: L('Yechish algoritmi', 'Алгоритм решения', 'Solving algorithm'), list: [
      L('<b>1.</b> Kasrlar bo‘lsa, ikki tomonni maxrajlarning EKUK iga (musbat son!) ko‘paytiring.', '<b>1.</b> Если есть дроби, умножьте обе части на НОК знаменателей (положительное число!).', '<b>1.</b> If there are fractions, multiply both sides by the LCM of the denominators (a positive number!).'),
      L('<b>2.</b> Qavslarni oching.', '<b>2.</b> Раскройте скобки.', '<b>2.</b> Expand the brackets.'),
      L('<b>3.</b> Noma’lumli hadlarni bir tomonga, sonlarni ikkinchi tomonga o‘tkazing.', '<b>3.</b> Перенесите члены с неизвестным в одну часть, числа — в другую.', '<b>3.</b> Move the unknown terms to one side and the numbers to the other.'),
      L('<b>4.</b> O‘xshash hadlarni ixchamlang: ax &gt; b ko‘rinishiga keltiring.', '<b>4.</b> Приведите подобные: получите ax &gt; b.', '<b>4.</b> Collect like terms to get ax &gt; b.'),
      L('<b>5.</b> a ga bo‘ling; a &lt; 0 bo‘lsa — belgini almashtiring!', '<b>5.</b> Разделите на a; если a &lt; 0 — смените знак!', '<b>5.</b> Divide by a; if a &lt; 0, flip the sign!'),
      L('<b>6.</b> Javobni son o‘qida tasvirlang va oraliq ko‘rinishida yozing. Qat’iy tengsizlikda nuqta «bo‘sh» (chegara kirmaydi), noqat’iyda «bo‘yalgan» (kiradi).', '<b>6.</b> Изобразите ответ на числовой прямой и запишите промежутком. При строгом неравенстве точка «пустая» (граница не входит), при нестрогом — «закрашенная» (входит).', '<b>6.</b> Show the answer on the number line and write it as an interval. For a strict inequality the endpoint is “open” (not included); for a non-strict one it is “filled” (included).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Yeching: 5x − 3 &gt; 2x + 9.', 'Решите: 5x − 3 &gt; 2x + 9.', 'Solve 5x − 3 &gt; 2x + 9.'),
        s: L('5x − 2x &gt; 9 + 3 ⇒ 3x &gt; 12 ⇒ x &gt; 4. Javob: (4; +∞). Tekshiruv: x = 5 da 22 &gt; 19 — to‘g‘ri.', '5x − 2x &gt; 9 + 3 ⇒ 3x &gt; 12 ⇒ x &gt; 4. Ответ: (4; +∞). Проверка: при x = 5 22 &gt; 19 — верно.', '5x − 2x &gt; 9 + 3 ⇒ 3x &gt; 12 ⇒ x &gt; 4. Answer: (4; +∞). Check: at x = 5, 22 &gt; 19 — true.') },
      { q: L('Yeching: 7 − 3(x + 1) ≥ x.', 'Решите: 7 − 3(x + 1) ≥ x.', 'Solve 7 − 3(x + 1) ≥ x.'),
        s: L('7 − 3x − 3 ≥ x ⇒ −4x ≥ −4 ⇒ x ≤ 1 (−4 ga bo‘ldik, belgi almashdi). Javob: (−∞; 1].', '7 − 3x − 3 ≥ x ⇒ −4x ≥ −4 ⇒ x ≤ 1 (делили на −4, знак сменился). Ответ: (−∞; 1].', '7 − 3x − 3 ≥ x ⇒ −4x ≥ −4 ⇒ x ≤ 1 (we divided by −4, so the sign flipped). Answer: (−∞; 1].') },
      { q: L('Yeching: <sup>x − 1</sup>/<sub>2</sub> − <sup>x</sup>/<sub>3</sub> &lt; 1.', 'Решите: <sup>x − 1</sup>/<sub>2</sub> − <sup>x</sup>/<sub>3</sub> &lt; 1.', 'Solve <sup>x − 1</sup>/<sub>2</sub> − <sup>x</sup>/<sub>3</sub> &lt; 1.'),
        s: L('6 ga ko‘paytiramiz: 3(x − 1) − 2x &lt; 6 ⇒ 3x − 3 − 2x &lt; 6 ⇒ x &lt; 9. Javob: (−∞; 9).', 'Умножаем на 6: 3(x − 1) − 2x &lt; 6 ⇒ 3x − 3 − 2x &lt; 6 ⇒ x &lt; 9. Ответ: (−∞; 9).', 'Multiply by 6: 3(x − 1) − 2x &lt; 6 ⇒ 3x − 3 − 2x &lt; 6 ⇒ x &lt; 9. Answer: (−∞; 9).') },
      { q: L('Telefon masalasi: 30 000 + 5 000x ≤ 80 000 ning eng katta butun yechimini toping.', 'Задача о тарифе: найдите наибольшее целое решение 30 000 + 5 000x ≤ 80 000.', 'Phone-plan problem: find the largest whole solution of 30,000 + 5,000x ≤ 80,000.'),
        s: L('5 000x ≤ 50 000 ⇒ x ≤ 10. Eng katta butun yechim 10: ko‘pi bilan 10 GB ishlatish mumkin.', '5 000x ≤ 50 000 ⇒ x ≤ 10. Наибольшее целое решение 10: можно использовать не более 10 ГБ.', '5,000x ≤ 50,000 ⇒ x ≤ 10. The largest whole solution is 10: you can use at most 10 GB.') }
    ] },
    { kind: 'example', h: L('Maxsus holatlar', 'Особые случаи', 'Special cases'), p: [
      L('Ba’zan soddalashtirishdan keyin x butunlay yo‘qolib ketadi. Bunda sonli tengsizlik qoladi va javob ikki xil bo‘lishi mumkin.', 'Иногда после упрощения x полностью исчезает. Остаётся числовое неравенство, и ответ бывает двух видов.', 'Sometimes x disappears completely after simplifying. A numerical inequality is left, and the answer can be one of two kinds.')
    ], ex: [
      { q: L('Yeching: 2(x + 3) &gt; 2x + 1.', 'Решите: 2(x + 3) &gt; 2x + 1.', 'Solve 2(x + 3) &gt; 2x + 1.'),
        s: L('2x + 6 &gt; 2x + 1 ⇒ 0 · x &gt; −5 ⇒ 0 &gt; −5 — har doim to‘g‘ri. Javob: x — istalgan son, (−∞; +∞).', '2x + 6 &gt; 2x + 1 ⇒ 0 · x &gt; −5 ⇒ 0 &gt; −5 — всегда верно. Ответ: x — любое число, (−∞; +∞).', '2x + 6 &gt; 2x + 1 ⇒ 0 · x &gt; −5 ⇒ 0 &gt; −5 — always true. Answer: every x, (−∞; +∞).') },
      { q: L('Yeching: 3x − 4 ≥ 3(x + 1).', 'Решите: 3x − 4 ≥ 3(x + 1).', 'Solve 3x − 4 ≥ 3(x + 1).'),
        s: L('3x − 4 ≥ 3x + 3 ⇒ 0 · x ≥ 7 ⇒ 0 ≥ 7 — noto‘g‘ri. Javob: yechim yo‘q.', '3x − 4 ≥ 3x + 3 ⇒ 0 · x ≥ 7 ⇒ 0 ≥ 7 — неверно. Ответ: решений нет.', '3x − 4 ≥ 3x + 3 ⇒ 0 · x ≥ 7 ⇒ 0 ≥ 7 — false. Answer: no solution.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Belgini almashtirmaslik.</b> −3x &lt; 12 ⇒ x &lt; −4 — xato! To‘g‘risi x &gt; −4. Tekshiring: x = 0 da 0 &lt; 12 to‘g‘ri, 0 esa x &gt; −4 ga kiradi.', '<b>Не сменить знак.</b> −3x &lt; 12 ⇒ x &lt; −4 — ошибка! Верно x &gt; −4. Проверка: x = 0 даёт 0 &lt; 12 — верно, и 0 входит в x &gt; −4.', '<b>Not flipping the sign.</b> −3x &lt; 12 ⇒ x &lt; −4 is wrong! Correct: x &gt; −4. Check: x = 0 gives 0 &lt; 12, true, and 0 is in x &gt; −4.'),
      L('<b>Hadni ko‘chirganda belgini almashtirish.</b> Ko‘chirishda hadning ishorasi o‘zgaradi, tengsizlik belgisi emas: x − 5 &gt; 2 ⇒ x &gt; 7.', '<b>Смена знака неравенства при переносе.</b> При переносе меняется знак члена, а не неравенства: x − 5 &gt; 2 ⇒ x &gt; 7.', '<b>Flipping when moving a term.</b> Moving a term changes the term’s sign, not the inequality’s: x − 5 &gt; 2 ⇒ x &gt; 7.'),
      L('<b>Qavslarni chalkashtirish.</b> x ≤ 1 ⇒ (−∞; 1], (−∞; 1) emas. Cheksizlik oldida doim oddiy qavs.', '<b>Путаница скобок.</b> x ≤ 1 ⇒ (−∞; 1], а не (−∞; 1). У бесконечности всегда круглая скобка.', '<b>Mixing up brackets.</b> x ≤ 1 gives (−∞; 1], not (−∞; 1). Infinity always takes a round bracket.'),
      L('<b>Javobni tenglama kabi yozish.</b> «x = 4» emas, «x &gt; 4» — yechim bitta son emas, oraliq.', '<b>Запись ответа как у уравнения.</b> Не «x = 4», а «x &gt; 4» — решение не одно число, а промежуток.', '<b>Writing the answer like an equation.</b> Not “x = 4” but “x &gt; 4” — the solution is an interval, not one number.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Xarid.</b> 150 000 so‘mingiz bor. Ruchka 4 000 so‘m, daftar 7 000 so‘m. 10 ta daftar olsangiz, ko‘pi bilan nechta ruchka olasiz? 70 000 + 4 000x ≤ 150 000 ⇒ x ≤ 20. <b>Taksi:</b> chaqiruv 8 000 so‘m, har km 3 000 so‘m; 50 000 so‘mga x ≤ 14 km yurish mumkin.', '<b>Покупки.</b> У вас 150 000 сумов. Ручка стоит 4 000, тетрадь — 7 000. Купив 10 тетрадей, сколько ручек вы сможете купить максимум? 70 000 + 4 000x ≤ 150 000 ⇒ x ≤ 20. <b>Такси:</b> посадка 8 000 сумов, километр 3 000; на 50 000 сумов можно проехать x ≤ 14 км.', '<b>Shopping.</b> You have 150,000 sum. A pen costs 4,000 and a notebook 7,000. After buying 10 notebooks, how many pens can you buy at most? 70,000 + 4,000x ≤ 150,000 ⇒ x ≤ 20. <b>Taxi:</b> 8,000 sum to start plus 3,000 per km; for 50,000 sum you can ride x ≤ 14 km.'),
      L('<b>Ta’lim.</b> Choraklik baho uchun o‘rtacha ball kamida 4,5 bo‘lishi kerak. 5, 4, 4 baholaringiz bor. To‘rtinchi baho x qanday bo‘lishi kerak? <sup>13 + x</sup>/<sub>4</sub> ≥ 4,5 ⇒ x ≥ 5. Demak, faqat «5» olish kerak. <b>Sport:</b> yuguruvchi rekordni yangilash uchun 100 m ni t &lt; 11,2 soniyada yugurishi kerak.', '<b>Учёба.</b> Для четвертной оценки средний балл должен быть не ниже 4,5. У вас оценки 5, 4, 4. Какой должна быть четвёртая x? <sup>13 + x</sup>/<sub>4</sub> ≥ 4,5 ⇒ x ≥ 5. Значит, нужна только «5». <b>Спорт:</b> чтобы побить рекорд, бегун должен пробежать 100 м за t &lt; 11,2 с.', '<b>School.</b> For a top term grade the average must be at least 4.5. Your marks are 5, 4, 4. What must the fourth mark x be? <sup>13 + x</sup>/<sub>4</sub> ≥ 4.5 ⇒ x ≥ 5. So only a 5 will do. <b>Sport:</b> to break a record, a runner must cover 100 m in t &lt; 11.2 s.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Aviakompaniyalar, logistika va fabrikalar har kuni minglab chiziqli tengsizliklardan iborat masalalarni kompyuterda yechadi: qaysi samolyot qayerga uchishi, qaysi yuk qaysi omborga borishi va hokazo.', 'Авиакомпании, логистика и заводы ежедневно решают на компьютерах задачи из тысяч линейных неравенств: какой самолёт куда летит, какой груз в какой склад и т. д.', 'Airlines, logistics firms and factories solve problems with thousands of linear inequalities on computers every day: which plane flies where, which cargo goes to which warehouse, and so on.'),
      L('«∞» belgisini 1655-yilda ingliz matematigi Jon Uollis kiritgan.', 'Знак «∞» ввёл в 1655 году английский математик Джон Валлис.', 'The sign “∞” was introduced in 1655 by the English mathematician John Wallis.'),
      L('Kantorovich chiziqli dasturlashni fanera zavodining ishini optimallashtirish iltimosidan keyin kashf qilgan — oddiy amaliy savol yangi fan sohasini yaratgan.', 'Канторович открыл линейное программирование после просьбы оптимизировать работу фанерного треста — простой практический вопрос породил новую область науки.', 'Kantorovich discovered linear programming after being asked to optimise a plywood trust — a simple practical question gave birth to a new field of science.')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('4x + 1 ≤ 13', '4x + 1 ≤ 13', '4x + 1 ≤ 13'), s: L('x ≤ 3; (−∞; 3].', 'x ≤ 3; (−∞; 3].', 'x ≤ 3; (−∞; 3].') },
      { q: L('2 − 5x &gt; 17', '2 − 5x &gt; 17', '2 − 5x &gt; 17'), s: L('−5x &gt; 15 ⇒ x &lt; −3; (−∞; −3).', '−5x &gt; 15 ⇒ x &lt; −3; (−∞; −3).', '−5x &gt; 15 ⇒ x &lt; −3; (−∞; −3).') },
      { q: L('3(x − 2) &lt; 5x + 4 ning eng kichik butun yechimi?', 'Наименьшее целое решение 3(x − 2) &lt; 5x + 4?', 'Smallest whole solution of 3(x − 2) &lt; 5x + 4?'), s: L('3x − 6 &lt; 5x + 4 ⇒ −2x &lt; 10 ⇒ x &gt; −5; eng kichik butun: −4.', '3x − 6 &lt; 5x + 4 ⇒ −2x &lt; 10 ⇒ x &gt; −5; наименьшее целое: −4.', '3x − 6 &lt; 5x + 4 ⇒ −2x &lt; 10 ⇒ x &gt; −5; smallest whole number: −4.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Tengsizlikning yechimi odatda son oralig‘i bo‘ladi.', 'Решение неравенства обычно — числовой промежуток.', 'The solution of an inequality is usually an interval.'),
      L('Hadlarni ishorasini almashtirib ko‘chirish mumkin — tengsizlik belgisi o‘zgarmaydi.', 'Члены переносят со сменой их знака — знак неравенства при этом не меняется.', 'Terms move across with their sign changed — the inequality sign stays.'),
      L('Musbat songa bo‘lish belgini saqlaydi, manfiy songa bo‘lish uni almashtiradi.', 'Деление на положительное сохраняет знак, на отрицательное — меняет.', 'Dividing by a positive keeps the sign; by a negative flips it.'),
      L('0 · x &gt; b holatida javob: «istalgan x» yoki «yechim yo‘q».', 'В случае 0 · x &gt; b ответ: «любое x» или «решений нет».', 'In the case 0 · x &gt; b the answer is “every x” or “no solution”.'),
      L('Qat’iy tengsizlikda chegara kirmaydi — ( ), noqat’iyda kiradi — [ ].', 'При строгом неравенстве граница не входит — ( ), при нестрогом входит — [ ].', 'For strict inequalities the endpoint is excluded — ( ); for non-strict it is included — [ ].'),
      L('Javobni tekshirish uchun oraliqdan bitta sonni qo‘yib ko‘ring.', 'Для проверки подставьте одно число из промежутка.', 'To check, substitute one number from the interval.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t9. Tengsizliklar sistemasi. Sonli oraliqlar ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Bir vaqtda bir nechta shart', 'Несколько условий одновременно', 'Several conditions at once'), p: [
      L('Akvariumdagi baliqlar uchun suv harorati 22 °C dan past va 28 °C dan yuqori bo‘lmasligi kerak. Bu bitta emas, ikkita shart: t ≥ 22 va t ≤ 28. Ular <b>bir vaqtda</b> bajarilishi kerak, shuning uchun bunday shartlar <b>tengsizliklar sistemasi</b> ko‘rinishida yoziladi. Javob esa bitta oraliq: 22 dan 28 gacha bo‘lgan barcha haroratlar.', 'Для рыбок в аквариуме температура воды должна быть не ниже 22 °C и не выше 28 °C. Это не одно, а два условия: t ≥ 22 и t ≤ 28. Они должны выполняться <b>одновременно</b>, поэтому такие условия записывают <b>системой неравенств</b>. А ответ — один промежуток: все температуры от 22 до 28.', 'Fish in an aquarium need water no colder than 22 °C and no warmer than 28 °C. That is not one condition but two: t ≥ 22 and t ≤ 28. They must hold <b>at the same time</b>, so such conditions are written as a <b>system of inequalities</b>. The answer is a single interval: every temperature from 22 to 28.'),
      L('Bu mavzuda biz son oraliqlarining turlari va ularning belgilanishi bilan tanishamiz, oraliqlarning kesishmasi va birlashmasini topishni, tengsizliklar sistemalari va qo‘sh tengsizliklarni yechishni o‘rganamiz. Son o‘qidagi chizma bu yerda asosiy yordamchi bo‘ladi.', 'В этой теме мы познакомимся с видами числовых промежутков и их обозначениями, научимся находить пересечение и объединение промежутков, решать системы неравенств и двойные неравенства. Главным помощником будет рисунок на числовой прямой.', 'In this topic we meet the kinds of intervals and their notation, learn to find intersections and unions of intervals, and solve systems of inequalities and double inequalities. A sketch on the number line will be our main helper.')
    ] },
    { kind: 'def', h: L('Son oraliqlari', 'Числовые промежутки', 'Intervals of numbers'), p: [
      L('a &lt; b bo‘lsin. a &lt; x &lt; b shartni qanoatlantiruvchi barcha x sonlar to‘plami <b>interval</b> deyiladi va (a; b) bilan belgilanadi. a ≤ x ≤ b — <b>kesma</b>, [a; b]. a ≤ x &lt; b va a &lt; x ≤ b — <b>yarim intervallar</b>, [a; b) va (a; b]. Bundan tashqari, <b>nurlar</b> bor: x &gt; a — (a; +∞), x ≥ a — [a; +∞), x &lt; b — (−∞; b), x ≤ b — (−∞; b]. Barcha sonlar to‘plami — (−∞; +∞).', 'Пусть a &lt; b. Множество всех x, для которых a &lt; x &lt; b, называется <b>интервалом</b> и обозначается (a; b). a ≤ x ≤ b — <b>отрезок</b> [a; b]. a ≤ x &lt; b и a &lt; x ≤ b — <b>полуинтервалы</b> [a; b) и (a; b]. Кроме того, есть <b>лучи</b>: x &gt; a — (a; +∞), x ≥ a — [a; +∞), x &lt; b — (−∞; b), x ≤ b — (−∞; b]. Множество всех чисел — (−∞; +∞).', 'Let a &lt; b. The set of all x with a &lt; x &lt; b is called an <b>open interval</b>, written (a; b). a ≤ x ≤ b is a <b>closed interval</b> [a; b]. a ≤ x &lt; b and a &lt; x ≤ b are <b>half-open intervals</b> [a; b) and (a; b]. There are also <b>rays</b>: x &gt; a — (a; +∞), x ≥ a — [a; +∞), x &lt; b — (−∞; b), x ≤ b — (−∞; b]. The set of all numbers is (−∞; +∞).'),
      L('Ikki to‘plamning <b>kesishmasi</b> (∩) — ikkalasiga ham tegishli elementlar; <b>birlashmasi</b> (∪) — kamida bittasiga tegishli elementlar. <b>Tengsizliklar sistemasi</b> — barchasi bir vaqtda bajarilishi kerak bo‘lgan tengsizliklar; ular figurali qavs { bilan birlashtiriladi. Sistemaning yechimi — har bir tengsizlik yechimlarining <b>kesishmasi</b>.', '<b>Пересечение</b> двух множеств (∩) — элементы, принадлежащие обоим; <b>объединение</b> (∪) — принадлежащие хотя бы одному. <b>Система неравенств</b> — неравенства, которые должны выполняться одновременно; их объединяют фигурной скобкой {. Решение системы — <b>пересечение</b> решений всех неравенств.', 'The <b>intersection</b> (∩) of two sets consists of elements in both; the <b>union</b> (∪) of elements in at least one. A <b>system of inequalities</b> is a set of inequalities that must all hold at once; they are joined with a curly brace {. The solution of the system is the <b>intersection</b> of the solutions of each inequality.')
    ] },
    { kind: 'history', h: L('Tarixdan: son o‘qi va to‘plamlar', 'Из истории: числовая прямая и множества', 'From history: the number line and sets'), p: [
      L('Sonlarni to‘g‘ri chiziqdagi nuqtalar sifatida tasvirlash g‘oyasi <b>Rene Dekart</b> koordinatalar usulidan kelib chiqqan. Manfiy sonlarni ham o‘z ichiga olgan son o‘qini birinchilardan bo‘lib ingliz <b>Jon Uollis</b> 1685-yilda tasvirlab bergan: u manfiy sonni nol nuqtasidan orqaga yurish deb tushuntirgan.', 'Идея изображать числа точками прямой выросла из метода координат <b>Рене Декарта</b>. Числовую прямую с отрицательными числами одним из первых описал англичанин <b>Джон Валлис</b> в 1685 году: отрицательное число он объяснял как движение назад от нулевой точки.', 'The idea of showing numbers as points on a line grew out of <b>René Descartes’</b> coordinate method. One of the first to describe a number line including negative numbers was the Englishman <b>John Wallis</b> in 1685: he explained a negative number as moving backwards from the zero point.'),
      L('To‘plamlar nazariyasini XIX asr oxirida nemis matematigi <b>Georg Kantor</b> yaratdi. ∩ va ∪ belgilarini 1888-yilda italiyalik <b>Juzeppe Peano</b> kiritgan. Ular tez orada butun matematikaning umumiy tiliga aylandi. Oraliqlarni kvadrat va oddiy qavslar bilan belgilash odati XX asrda keng tarqaldi. Xorazmiy va Beruniy davrida esa bunday shartlar «dan kam emas va dan oshmaydi» degan so‘zlar bilan ifodalangan.', 'Теорию множеств в конце XIX века создал немецкий математик <b>Георг Кантор</b>. Знаки ∩ и ∪ ввёл в 1888 году итальянец <b>Джузеппе Пеано</b>. Вскоре они стали общим языком всей математики. Обычай обозначать промежутки квадратными и круглыми скобками распространился в XX веке. А во времена Хорезми и Беруни такие условия выражали словами «не меньше… и не больше…».', 'Set theory was created at the end of the 19th century by the German mathematician <b>Georg Cantor</b>. The signs ∩ and ∪ were introduced in 1888 by the Italian <b>Giuseppe Peano</b>, and they soon became the common language of all mathematics. Writing intervals with square and round brackets spread in the 20th century. In the days of al-Khwarizmi and al-Biruni such conditions were expressed in words: “not less than … and not more than …”.')
    ] },
    { kind: 'table', h: L('Oraliqlar jadvali', 'Таблица промежутков', 'Table of intervals'), table: { head: [L('Tengsizlik', 'Неравенство', 'Inequality'), L('Belgilanish', 'Обозначение', 'Notation'), L('Nomi', 'Название', 'Name')], rows: [
      [L('a &lt; x &lt; b', 'a &lt; x &lt; b', 'a &lt; x &lt; b'), L('(a; b)', '(a; b)', '(a; b)'), L('interval', 'интервал', 'open interval')],
      [L('a ≤ x ≤ b', 'a ≤ x ≤ b', 'a ≤ x ≤ b'), L('[a; b]', '[a; b]', '[a; b]'), L('kesma', 'отрезок', 'closed interval')],
      [L('a ≤ x &lt; b', 'a ≤ x &lt; b', 'a ≤ x &lt; b'), L('[a; b)', '[a; b)', '[a; b)'), L('yarim interval', 'полуинтервал', 'half-open interval')],
      [L('a &lt; x ≤ b', 'a &lt; x ≤ b', 'a &lt; x ≤ b'), L('(a; b]', '(a; b]', '(a; b]'), L('yarim interval', 'полуинтервал', 'half-open interval')],
      [L('x &gt; a', 'x &gt; a', 'x &gt; a'), L('(a; +∞)', '(a; +∞)', '(a; +∞)'), L('ochiq nur', 'открытый луч', 'open ray')],
      [L('x ≤ b', 'x ≤ b', 'x ≤ b'), L('(−∞; b]', '(−∞; b]', '(−∞; b]'), L('nur', 'луч', 'closed ray')]
    ] }, after: [
      L('Eslab qoling: kvadrat qavs «chegara kiradi», oddiy qavs «kirmaydi». Chizmada kiradigan chegara bo‘yalgan nuqta, kirmaydigani bo‘sh doiracha bilan ko‘rsatiladi.', 'Запомните: квадратная скобка — «граница входит», круглая — «не входит». На рисунке входящая граница — закрашенная точка, невходящая — пустой кружок.', 'Remember: a square bracket means “endpoint included”, a round one “not included”. On a sketch an included endpoint is a filled dot and an excluded one an open circle.')
    ] },
    { kind: 'rule', h: L('Sistemani yechish qoidasi', 'Правило решения системы', 'How to solve a system'), p: [
      L('Tengsizliklar sistemasini yechish uchun: <b>har bir tengsizlikni alohida yechamiz</b>, so‘ng yechimlarni son o‘qida belgilab, ularning <b>umumiy qismini</b> (kesishmasini) topamiz. Kesishma bo‘sh bo‘lsa, sistema yechimga ega emas.', 'Чтобы решить систему неравенств, <b>решаем каждое неравенство отдельно</b>, затем отмечаем решения на числовой прямой и находим их <b>общую часть</b> (пересечение). Если пересечение пусто, система решений не имеет.', 'To solve a system of inequalities: <b>solve each inequality separately</b>, then mark the solutions on a number line and find their <b>common part</b> (intersection). If the intersection is empty, the system has no solution.'),
      L('Ikki nur kesishmasi uchun foydali qoida: { x &gt; a; x &gt; b } ⇒ x &gt; eng kattasi; { x &lt; a; x &lt; b } ⇒ x &lt; eng kichigi. { x &gt; a; x &lt; b } bo‘lsa: a &lt; b da javob (a; b), a ≥ b da yechim yo‘q.', 'Полезное правило для двух лучей: { x &gt; a; x &gt; b } ⇒ x больше наибольшего; { x &lt; a; x &lt; b } ⇒ x меньше наименьшего. Для { x &gt; a; x &lt; b }: при a &lt; b ответ (a; b), при a ≥ b решений нет.', 'A handy rule for two rays: { x &gt; a; x &gt; b } ⇒ x is greater than the larger; { x &lt; a; x &lt; b } ⇒ x is less than the smaller. For { x &gt; a; x &lt; b }: if a &lt; b the answer is (a; b); if a ≥ b there is no solution.'),
      L('<b>Qo‘sh tengsizlik</b> m &lt; f(x) &lt; n — bu { f(x) &gt; m; f(x) &lt; n } sistemaning qisqa yozuvi. Agar f(x) chiziqli bo‘lsa, uchta qismning hammasiga bir vaqtda bir xil amallarni qo‘llash mumkin.', '<b>Двойное неравенство</b> m &lt; f(x) &lt; n — краткая запись системы { f(x) &gt; m; f(x) &lt; n }. Если f(x) линейная, одни и те же действия можно выполнять сразу со всеми тремя частями.', 'A <b>double inequality</b> m &lt; f(x) &lt; n is shorthand for the system { f(x) &gt; m; f(x) &lt; n }. If f(x) is linear, the same operations can be applied to all three parts at once.')
    ] },
    { kind: 'steps', h: L('Bosqichma-bosqich', 'Пошагово', 'Step by step'), list: [
      L('<b>1.</b> Sistemaning birinchi tengsizligini yeching va javobni yozing.', '<b>1.</b> Решите первое неравенство системы и запишите ответ.', '<b>1.</b> Solve the first inequality and write down its answer.'),
      L('<b>2.</b> Ikkinchisini (va qolganlarini) yeching.', '<b>2.</b> Решите второе (и остальные).', '<b>2.</b> Solve the second (and any others).'),
      L('<b>3.</b> Bitta son o‘qida barcha yechimlarni shtrixlang; har biriga alohida «qavat» ishlatish qulay.', '<b>3.</b> На одной числовой прямой заштрихуйте все решения; удобно рисовать каждое на своём «этаже».', '<b>3.</b> Shade all the solutions on one number line; it helps to draw each on its own “level”.'),
      L('<b>4.</b> Barcha shtrixlar ustma-ust tushgan joy — javob. Chegaralar kirish-kirmasligini har bir tengsizlik bo‘yicha tekshiring.', '<b>4.</b> Где все штриховки совпали — там ответ. Проверьте, входят ли границы, по каждому неравенству.', '<b>4.</b> Where all the shadings overlap is the answer. Check whether each endpoint is included, inequality by inequality.'),
      L('<b>5.</b> Javobni oraliq ko‘rinishida yozing; kerak bo‘lsa, butun yechimlarni sanang.', '<b>5.</b> Запишите ответ промежутком; при необходимости перечислите целые решения.', '<b>5.</b> Write the answer as an interval; list the whole-number solutions if asked.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Yeching: { 3x − 2 &gt; 4; 5 − x ≥ −2 }.', 'Решите: { 3x − 2 &gt; 4; 5 − x ≥ −2 }.', 'Solve { 3x − 2 &gt; 4; 5 − x ≥ −2 }.'),
        s: L('Birinchisi: 3x &gt; 6 ⇒ x &gt; 2. Ikkinchisi: −x ≥ −7 ⇒ x ≤ 7. Kesishma: 2 &lt; x ≤ 7. Javob: (2; 7]. Butun yechimlar: 3, 4, 5, 6, 7 — jami 5 ta.', 'Первое: 3x &gt; 6 ⇒ x &gt; 2. Второе: −x ≥ −7 ⇒ x ≤ 7. Пересечение: 2 &lt; x ≤ 7. Ответ: (2; 7]. Целые решения: 3, 4, 5, 6, 7 — всего 5.', 'First: 3x &gt; 6 ⇒ x &gt; 2. Second: −x ≥ −7 ⇒ x ≤ 7. Intersection: 2 &lt; x ≤ 7. Answer: (2; 7]. Whole solutions: 3, 4, 5, 6, 7 — five in all.') },
      { q: L('Yeching: { 2x + 1 &lt; 5; x − 4 &gt; 0 }.', 'Решите: { 2x + 1 &lt; 5; x − 4 &gt; 0 }.', 'Solve { 2x + 1 &lt; 5; x − 4 &gt; 0 }.'),
        s: L('x &lt; 2 va x &gt; 4. Bu nurlar kesishmaydi: 2 dan kichik va 4 dan katta son yo‘q. Javob: yechim yo‘q.', 'x &lt; 2 и x &gt; 4. Лучи не пересекаются: нет числа, меньшего 2 и большего 4. Ответ: решений нет.', 'x &lt; 2 and x &gt; 4. These rays do not overlap: no number is both less than 2 and greater than 4. Answer: no solution.') },
      { q: L('Qo‘sh tengsizlikni yeching: −1 ≤ 2x + 3 &lt; 9.', 'Решите двойное неравенство: −1 ≤ 2x + 3 &lt; 9.', 'Solve the double inequality −1 ≤ 2x + 3 &lt; 9.'),
        s: L('Uchala qismdan 3 ni ayiramiz: −4 ≤ 2x &lt; 6. 2 ga bo‘lamiz: −2 ≤ x &lt; 3. Javob: [−2; 3).', 'Вычитаем 3 из всех трёх частей: −4 ≤ 2x &lt; 6. Делим на 2: −2 ≤ x &lt; 3. Ответ: [−2; 3).', 'Subtract 3 from all three parts: −4 ≤ 2x &lt; 6. Divide by 2: −2 ≤ x &lt; 3. Answer: [−2; 3).') },
      { q: L('Yeching: 1 &lt; 4 − 3x ≤ 10.', 'Решите: 1 &lt; 4 − 3x ≤ 10.', 'Solve 1 &lt; 4 − 3x ≤ 10.'),
        s: L('−3 &lt; −3x ≤ 6. −3 ga bo‘lamiz — ikkala belgi ham almashadi: 1 &gt; x ≥ −2, ya’ni −2 ≤ x &lt; 1. Javob: [−2; 1).', '−3 &lt; −3x ≤ 6. Делим на −3 — оба знака меняются: 1 &gt; x ≥ −2, то есть −2 ≤ x &lt; 1. Ответ: [−2; 1).', '−3 &lt; −3x ≤ 6. Divide by −3 — both signs flip: 1 &gt; x ≥ −2, i.e. −2 ≤ x &lt; 1. Answer: [−2; 1).') }
    ] },
    { kind: 'example', h: L('Kesishma va birlashma', 'Пересечение и объединение', 'Intersection and union'), p: [
      L('Kesishma «va» so‘ziga, birlashma «yoki» so‘ziga mos keladi. Sistemada «va», keyingi mavzudagi modulli tengsizliklarda esa ko‘pincha «yoki» uchraydi.', 'Пересечение соответствует слову «и», объединение — слову «или». В системе — «и», а в неравенствах с модулем из следующей темы часто встречается «или».', 'Intersection matches the word “and”, union the word “or”. A system uses “and”; the absolute-value inequalities of the next topic often use “or”.')
    ], ex: [
      { q: L('[−3; 5) ∩ (1; 8] va [−3; 5) ∪ (1; 8] ni toping.', 'Найдите [−3; 5) ∩ (1; 8] и [−3; 5) ∪ (1; 8].', 'Find [−3; 5) ∩ (1; 8] and [−3; 5) ∪ (1; 8].'),
        s: L('Kesishma — umumiy qism: (1; 5). Birlashma — hammasi: [−3; 8].', 'Пересечение — общая часть: (1; 5). Объединение — всё вместе: [−3; 8].', 'Intersection — the common part: (1; 5). Union — everything together: [−3; 8].') },
      { q: L('Akvarium masalasi: harorat 22 ≤ t ≤ 28. Termometr 0,5 °C xatolik bilan ko‘rsatsa, uning ko‘rsatkichi qaysi oraliqda bo‘lishi kerak, toki haqiqiy harorat albatta mos bo‘lsin?', 'Задача об аквариуме: 22 ≤ t ≤ 28. Термометр ошибается на 0,5 °C. В каком промежутке должны быть его показания, чтобы истинная температура заведомо подходила?', 'Aquarium problem: 22 ≤ t ≤ 28. The thermometer may be off by 0.5 °C. In which interval must its reading lie for the true temperature to be surely fine?'),
        s: L('Haqiqiy t ko‘rsatkich T dan ±0,5 farq qiladi, shuning uchun T − 0,5 ≥ 22 va T + 0,5 ≤ 28 bo‘lishi kerak: 22,5 ≤ T ≤ 27,5.', 'Истинная t отличается от показания T на ±0,5, поэтому нужно T − 0,5 ≥ 22 и T + 0,5 ≤ 28: 22,5 ≤ T ≤ 27,5.', 'The true t differs from the reading T by up to 0.5, so we need T − 0.5 ≥ 22 and T + 0.5 ≤ 28: 22.5 ≤ T ≤ 27.5.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Kesishma o‘rniga birlashma olish.</b> { x &gt; 1; x &lt; 6 } ⇒ (1; 6), «barcha sonlar» emas.', '<b>Объединение вместо пересечения.</b> { x &gt; 1; x &lt; 6 } ⇒ (1; 6), а не «все числа».', '<b>Taking the union instead of the intersection.</b> { x &gt; 1; x &lt; 6 } gives (1; 6), not “all numbers”.'),
      L('<b>Teskari oraliq yozish.</b> (5; 1) yozuvi ma’nosiz — chap chegara har doim kichik son.', '<b>Запись «перевёрнутого» промежутка.</b> (5; 1) не имеет смысла — левая граница всегда меньше.', '<b>Writing a reversed interval.</b> (5; 1) is meaningless — the left end is always the smaller number.'),
      L('<b>Qo‘sh tengsizlikda faqat bir belgini almashtirish.</b> Manfiy songa bo‘lganda <b>ikkala</b> belgi ham almashadi.', '<b>Смена только одного знака в двойном неравенстве.</b> При делении на отрицательное меняются <b>оба</b> знака.', '<b>Flipping only one sign in a double inequality.</b> Dividing by a negative flips <b>both</b> signs.'),
      L('<b>Chegarani noto‘g‘ri belgilash.</b> Agar bir tengsizlikda chegara kirsa, ikkinchisida kirmasa, natijada u kirmaydi: { x ≥ 3; x &gt; 3 } ⇒ (3; +∞).', '<b>Неверная граница.</b> Если в одном неравенстве граница входит, а в другом нет, в ответе она не входит: { x ≥ 3; x &gt; 3 } ⇒ (3; +∞).', '<b>Wrong endpoint.</b> If one inequality includes an endpoint and the other excludes it, the answer excludes it: { x ≥ 3; x &gt; 3 } ⇒ (3; +∞).')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Tibbiyot.</b> Sog‘lom odamning tana harorati 36,1 ≤ t ≤ 37,2 °C, qondagi qand miqdori och qoringa 3,9 dan 5,5 mmol/l gacha — bularning barchasi oraliqlar. Shifokor tahlil natijasini aynan shu oraliqqa tushish-tushmasligi bo‘yicha baholaydi.', '<b>Медицина.</b> Температура здорового человека 36,1 ≤ t ≤ 37,2 °C, сахар в крови натощак — от 3,9 до 5,5 ммоль/л: всё это промежутки. Врач оценивает анализ по тому, попадает ли результат в такой промежуток.', '<b>Medicine.</b> A healthy body temperature is 36.1 ≤ t ≤ 37.2 °C; fasting blood sugar is 3.9 to 5.5 mmol/l — all intervals. A doctor judges a test by whether the result falls inside such an interval.'),
      L('<b>Ishlab chiqarish.</b> Zavodda tayyorlangan detal uzunligi 50 ± 0,1 mm bo‘lishi kerak, ya’ni 49,9 ≤ l ≤ 50,1. <b>Sayohat:</b> samolyotga qo‘l yuki 55 × 40 × 20 sm dan oshmasligi va 8 kg dan og‘ir bo‘lmasligi kerak — bir nechta tengsizlikdan iborat sistema.', '<b>Производство.</b> Длина детали на заводе должна быть 50 ± 0,1 мм, то есть 49,9 ≤ l ≤ 50,1. <b>Путешествия:</b> ручная кладь в самолёте — не более 55 × 40 × 20 см и не тяжелее 8 кг: система из нескольких неравенств.', '<b>Manufacturing.</b> A machined part must be 50 ± 0.1 mm long, i.e. 49.9 ≤ l ≤ 50.1. <b>Travel:</b> airline hand luggage must not exceed 55 × 40 × 20 cm and 8 kg — a system of several inequalities.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Har qanday (a; b) interval, hatto juda qisqa bo‘lsa ham, cheksiz ko‘p sonni o‘z ichiga oladi — (0; 0,001) da ham.', 'Любой интервал (a; b), даже очень короткий, содержит бесконечно много чисел — даже (0; 0,001).', 'Every interval (a; b), however short, contains infinitely many numbers — even (0; 0.001).'),
      L('Kantor isbotlaganki, (0; 1) intervaldagi sonlar butun sonlardan «ko‘proq»: ularni 1, 2, 3, … deb raqamlab chiqib bo‘lmaydi.', 'Кантор доказал, что чисел в интервале (0; 1) «больше», чем натуральных: их нельзя перенумеровать 1, 2, 3, …', 'Cantor proved that there are “more” numbers in (0; 1) than natural numbers: they cannot be numbered 1, 2, 3, …'),
      L('GPS navigatori joylashuvingizni bir nechta sun’iy yo‘ldoshdan olingan masofa baholarini kesishtirib aniqlaydi — bu ham kesishma g‘oyasi.', 'GPS-навигатор находит ваше положение, пересекая оценки расстояний от нескольких спутников, — это тоже идея пересечения.', 'A GPS receiver locates you by intersecting distance estimates from several satellites — another use of intersection.')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('{ x ≥ −1; x &lt; 4 } — javob va butun yechimlar soni?', '{ x ≥ −1; x &lt; 4 } — ответ и число целых решений?', '{ x ≥ −1; x &lt; 4 } — answer and number of whole solutions?'), s: L('[−1; 4); butun yechimlar −1, 0, 1, 2, 3 — 5 ta.', '[−1; 4); целые −1, 0, 1, 2, 3 — 5 штук.', '[−1; 4); whole solutions −1, 0, 1, 2, 3 — five.') },
      { q: L('{ 4x − 1 &gt; 7; 3x ≤ 15 }', '{ 4x − 1 &gt; 7; 3x ≤ 15 }', '{ 4x − 1 &gt; 7; 3x ≤ 15 }'), s: L('x &gt; 2 va x ≤ 5 ⇒ (2; 5].', 'x &gt; 2 и x ≤ 5 ⇒ (2; 5].', 'x &gt; 2 and x ≤ 5 ⇒ (2; 5].') },
      { q: L('−3 &lt; 1 − 2x &lt; 5', '−3 &lt; 1 − 2x &lt; 5', '−3 &lt; 1 − 2x &lt; 5'), s: L('−4 &lt; −2x &lt; 4 ⇒ −2 &lt; x &lt; 2; (−2; 2).', '−4 &lt; −2x &lt; 4 ⇒ −2 &lt; x &lt; 2; (−2; 2).', '−4 &lt; −2x &lt; 4 ⇒ −2 &lt; x &lt; 2; (−2; 2).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Son oraliqlari: interval (a; b), kesma [a; b], yarim intervallar, nurlar.', 'Числовые промежутки: интервал (a; b), отрезок [a; b], полуинтервалы, лучи.', 'Intervals: open (a; b), closed [a; b], half-open, and rays.'),
      L('Kvadrat qavs — chegara kiradi, oddiy qavs — kirmaydi; ∞ yonida har doim oddiy qavs.', 'Квадратная скобка — граница входит, круглая — нет; у ∞ всегда круглая.', 'Square bracket — endpoint included, round — excluded; ∞ always gets a round bracket.'),
      L('Sistema yechimi — har bir tengsizlik yechimlarining kesishmasi («va»).', 'Решение системы — пересечение решений всех неравенств («и»).', 'A system’s solution is the intersection of the individual solutions (“and”).'),
      L('Kesishma bo‘sh bo‘lsa, sistema yechimga ega emas.', 'Если пересечение пусто, система не имеет решений.', 'If the intersection is empty, the system has no solution.'),
      L('Qo‘sh tengsizlikda amallar uchala qismga bajariladi; manfiy songa bo‘lishda ikkala belgi almashadi.', 'В двойном неравенстве действия выполняют со всеми тремя частями; при делении на отрицательное меняются оба знака.', 'In a double inequality, apply each step to all three parts; dividing by a negative flips both signs.'),
      L('Son o‘qidagi chizma — eng ishonchli yordamchi.', 'Рисунок на числовой прямой — самый надёжный помощник.', 'A number-line sketch is your most reliable helper.')
    ] }
  ] });

  // ---------- t10. Modul qatnashgan tenglama va tengsizliklar ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Masofa haqida tenglamalar', 'Уравнения о расстояниях', 'Equations about distance'), p: [
      L('Toshkent metrosining bir bekatida turibsiz. Sizdan 3 bekat uzoqlikdagi bekat qaysi? Ikkita javob bor: 3 bekat oldinda va 3 bekat orqada. Yo‘nalishni emas, faqat <b>masofani</b> bildiruvchi matematik vosita — <b>modul</b> (absolyut qiymat). |x| yozuvi x sonining nolgacha bo‘lgan masofasini bildiradi.', 'Вы стоите на станции ташкентского метро. Какая станция находится в 3 перегонах от вас? Ответов два: на 3 станции вперёд и на 3 назад. Математический инструмент, который выражает не направление, а только <b>расстояние</b>, — это <b>модуль</b> (абсолютная величина). Запись |x| означает расстояние от числа x до нуля.', 'You are at a station of the Tashkent metro. Which station is 3 stops away? There are two answers: 3 stops ahead and 3 stops back. The mathematical tool that expresses only <b>distance</b>, not direction, is the <b>absolute value</b> (modulus). |x| means the distance from x to zero.'),
      L('Modul qatnashgan tenglama va tengsizliklar ko‘pincha ikki yoki undan ko‘p yechimga ega bo‘ladi va ularni yechish uchun ehtiyotkorlik kerak. Bu mavzuda modulning ta’rifi va geometrik ma’nosini, |x| = a, |x| &lt; a, |x| &gt; a ko‘rinishidagi masalalarni yechishni, hamda o‘lchash xatoliklari bilan bog‘liq amaliy masalalarni o‘rganamiz.', 'Уравнения и неравенства с модулем часто имеют два и больше решений и требуют аккуратности. В этой теме изучим определение и геометрический смысл модуля, решение задач вида |x| = a, |x| &lt; a, |x| &gt; a и практические задачи о погрешностях измерений.', 'Equations and inequalities with absolute values often have two or more solutions and need care. In this topic we study the definition and geometric meaning of the absolute value, how to solve problems of the form |x| = a, |x| &lt; a, |x| &gt; a, and practical problems about measurement errors.')
    ] },
    { kind: 'def', h: L('Modulning ta’rifi', 'Определение модуля', 'Definition of absolute value'), p: [
      L('Sonning <b>moduli</b>: <b>|a| = a</b>, agar a ≥ 0 bo‘lsa; <b>|a| = −a</b>, agar a &lt; 0 bo‘lsa. Masalan, |7| = 7, |0| = 0, |−4,5| = 4,5. E’tibor bering: a manfiy bo‘lganda −a musbat son, shuning uchun modul hech qachon manfiy emas: |a| ≥ 0.', '<b>Модуль</b> числа: <b>|a| = a</b>, если a ≥ 0; <b>|a| = −a</b>, если a &lt; 0. Например, |7| = 7, |0| = 0, |−4,5| = 4,5. Обратите внимание: при отрицательном a число −a положительно, поэтому модуль никогда не бывает отрицательным: |a| ≥ 0.', 'The <b>absolute value</b> of a number: <b>|a| = a</b> if a ≥ 0; <b>|a| = −a</b> if a &lt; 0. For example, |7| = 7, |0| = 0, |−4.5| = 4.5. Note that when a is negative, −a is positive, so an absolute value is never negative: |a| ≥ 0.'),
      L('<b>Geometrik ma’no:</b> |a| — son o‘qida a nuqtadan 0 gacha bo‘lgan masofa; <b>|a − b|</b> — a va b nuqtalar orasidagi masofa. Masalan, |x − 3| — x dan 3 gacha masofa, |x + 2| = |x − (−2)| — x dan −2 gacha masofa. Bu talqin ko‘p masalalarni chizma yordamida og‘zaki yechishga imkon beradi.', '<b>Геометрический смысл:</b> |a| — расстояние на числовой прямой от точки a до 0; <b>|a − b|</b> — расстояние между точками a и b. Например, |x − 3| — расстояние от x до 3, |x + 2| = |x − (−2)| — расстояние от x до −2. Такой взгляд позволяет решать многие задачи устно, по рисунку.', '<b>Geometric meaning:</b> |a| is the distance on the number line from a to 0; <b>|a − b|</b> is the distance between a and b. For example, |x − 3| is the distance from x to 3, and |x + 2| = |x − (−2)| is the distance from x to −2. This view lets you solve many problems mentally from a sketch.')
    ] },
    { kind: 'history', h: L('Tarixdan: modul belgisi', 'Из истории: знак модуля', 'From history: the absolute-value sign'), p: [
      L('Sonning ishorasini e’tiborga olmay, faqat «kattaligi»ni o‘lchash g‘oyasi juda qadimiy. O‘rta Osiyo astronomlari, xususan <b>Beruniy</b> va <b>Ulug‘bek</b> maktabi, jadvallarida kuzatuv natijasining hisoblangan qiymatdan qanchaga farq qilishini — ya’ni farqning «kattaligini» — doimo baholagan. Ulug‘bekning «Ziji Ko‘ragoniy» jadvalida sayyoralar holati bir necha yoy daqiqasigacha aniq berilgan.', 'Идея измерять только «величину» числа, не обращая внимания на знак, очень древняя. Среднеазиатские астрономы, в частности <b>Беруни</b> и школа <b>Улугбека</b>, в своих таблицах постоянно оценивали, насколько наблюдение отличается от расчёта, то есть «величину» разности. В «Зидже Гурагани» Улугбека положения планет даны с точностью до нескольких угловых минут.', 'The idea of measuring only the “size” of a number, ignoring its sign, is very old. Central Asian astronomers, notably <b>al-Biruni</b> and <b>Ulugh Beg’s</b> school, constantly estimated in their tables how far an observation differed from a calculation — the “size” of the difference. Ulugh Beg’s “Zij-i Gurgani” gives planetary positions to within a few minutes of arc.'),
      L('«Modul» atamasini (lotincha «modulus» — «o‘lchov») 1806-yilda fransuz <b>Jan-Robert Argan</b>, so‘ngra <b>Ogyusten Koshi</b> ishlatgan. Ikki vertikal chiziqdan iborat |x| belgisini 1841-yilda nemis matematigi <b>Karl Veyershtrass</b> kiritgan va u tezda butun dunyoda qabul qilingan. Inglizcha «absolute value» nomi XIX asr oxirida keng tarqaldi.', 'Термин «модуль» (лат. «modulus» — «мера») использовали в 1806 году француз <b>Жан-Робер Арган</b>, а затем <b>Огюстен Коши</b>. Знак |x| из двух вертикальных черт ввёл в 1841 году немецкий математик <b>Карл Вейерштрасс</b>, и он быстро был принят во всём мире. Английское название «absolute value» распространилось в конце XIX века.', 'The term “modulus” (Latin for “measure”) was used in 1806 by the Frenchman <b>Jean-Robert Argand</b> and then by <b>Augustin-Louis Cauchy</b>. The two-vertical-bar sign |x| was introduced in 1841 by the German mathematician <b>Karl Weierstrass</b> and was quickly adopted worldwide. The English name “absolute value” spread at the end of the 19th century.')
    ] },
    { kind: 'rule', h: L('Asosiy qoidalar', 'Основные правила', 'Main rules'), p: [
      L('a — berilgan son bo‘lsin. Modulning masofa ma’nosidan quyidagilar kelib chiqadi:', 'Пусть a — данное число. Из смысла модуля как расстояния следует:', 'Let a be a given number. From the distance meaning of the absolute value we get:')
    ], list: [
      L('<b>|x| = a:</b> a &gt; 0 da x = a yoki x = −a (ikki yechim); a = 0 da x = 0; a &lt; 0 da yechim yo‘q (masofa manfiy bo‘lmaydi).', '<b>|x| = a:</b> при a &gt; 0 x = a или x = −a (два решения); при a = 0 x = 0; при a &lt; 0 решений нет (расстояние не бывает отрицательным).', '<b>|x| = a:</b> if a &gt; 0, x = a or x = −a (two solutions); if a = 0, x = 0; if a &lt; 0, no solution (distance cannot be negative).'),
      L('<b>|x| &lt; a</b> (a &gt; 0) ⇔ −a &lt; x &lt; a: noldan masofasi a dan kichik nuqtalar — (−a; a) interval.', '<b>|x| &lt; a</b> (a &gt; 0) ⇔ −a &lt; x &lt; a: точки на расстоянии меньше a от нуля — интервал (−a; a).', '<b>|x| &lt; a</b> (a &gt; 0) ⇔ −a &lt; x &lt; a: points closer than a to zero — the interval (−a; a).'),
      L('<b>|x| &gt; a</b> (a &gt; 0) ⇔ x &lt; −a yoki x &gt; a: noldan uzoqroq nuqtalar — (−∞; −a) ∪ (a; +∞).', '<b>|x| &gt; a</b> (a &gt; 0) ⇔ x &lt; −a или x &gt; a: точки дальше a от нуля — (−∞; −a) ∪ (a; +∞).', '<b>|x| &gt; a</b> (a &gt; 0) ⇔ x &lt; −a or x &gt; a: points farther than a from zero — (−∞; −a) ∪ (a; +∞).'),
      L('<b>Umumlashma:</b> |x − c| = a ⇔ x = c ± a; |x − c| &lt; a ⇔ c − a &lt; x &lt; c + a; |x − c| &gt; a ⇔ x &lt; c − a yoki x &gt; c + a.', '<b>Обобщение:</b> |x − c| = a ⇔ x = c ± a; |x − c| &lt; a ⇔ c − a &lt; x &lt; c + a; |x − c| &gt; a ⇔ x &lt; c − a или x &gt; c + a.', '<b>In general:</b> |x − c| = a ⇔ x = c ± a; |x − c| &lt; a ⇔ c − a &lt; x &lt; c + a; |x − c| &gt; a ⇔ x &lt; c − a or x &gt; c + a.')
    ], after: [
      L('<b>Asoslash.</b> |x| &lt; a ni ta’rif bo‘yicha ikki holatga ajratamiz. x ≥ 0 da |x| = x, shart x &lt; a; x &lt; 0 da |x| = −x, shart −x &lt; a, ya’ni x &gt; −a. Ikkala holatni birlashtirsak, −a &lt; x &lt; a. Modulning yana muhim xossalari: |ab| = |a| · |b|, |−a| = |a|, √(a<sup>2</sup>) = |a|.', '<b>Обоснование.</b> Разберём |x| &lt; a по определению на два случая. При x ≥ 0 |x| = x, условие x &lt; a; при x &lt; 0 |x| = −x, условие −x &lt; a, то есть x &gt; −a. Объединив случаи, получаем −a &lt; x &lt; a. Другие важные свойства: |ab| = |a| · |b|, |−a| = |a|, √(a<sup>2</sup>) = |a|.', '<b>Justification.</b> Split |x| &lt; a into two cases by the definition. For x ≥ 0, |x| = x and the condition is x &lt; a; for x &lt; 0, |x| = −x and the condition is −x &lt; a, i.e. x &gt; −a. Putting the cases together gives −a &lt; x &lt; a. Other key properties: |ab| = |a| · |b|, |−a| = |a|, √(a<sup>2</sup>) = |a|.')
    ] },
    { kind: 'steps', h: L('|f(x)| = a tenglamani yechish', 'Решение уравнения |f(x)| = a', 'Solving |f(x)| = a'), list: [
      L('<b>1.</b> O‘ng tomonni tekshiring: a &lt; 0 bo‘lsa — darhol «yechim yo‘q».', '<b>1.</b> Проверьте правую часть: если a &lt; 0 — сразу «решений нет».', '<b>1.</b> Check the right side: if a &lt; 0, there is no solution.'),
      L('<b>2.</b> a ≥ 0 bo‘lsa, ikki tenglamaga ajrating: f(x) = a yoki f(x) = −a.', '<b>2.</b> Если a ≥ 0, разбейте на два уравнения: f(x) = a или f(x) = −a.', '<b>2.</b> If a ≥ 0, split into two equations: f(x) = a or f(x) = −a.'),
      L('<b>3.</b> Har birini yeching va barcha ildizlarni javobga yozing.', '<b>3.</b> Решите каждое и запишите все корни в ответ.', '<b>3.</b> Solve each and list all the roots in the answer.'),
      L('<b>4.</b> Tengsizlikda: «&lt;» bo‘lsa — qo‘sh tengsizlik (−a &lt; f(x) &lt; a), «&gt;» bo‘lsa — ikki tengsizlikning birlashmasi (f(x) &lt; −a yoki f(x) &gt; a).', '<b>4.</b> Для неравенства: при «&lt;» — двойное неравенство (−a &lt; f(x) &lt; a), при «&gt;» — объединение двух неравенств (f(x) &lt; −a или f(x) &gt; a).', '<b>4.</b> For an inequality: “&lt;” gives a double inequality (−a &lt; f(x) &lt; a); “&gt;” gives a union of two (f(x) &lt; −a or f(x) &gt; a).'),
      L('<b>5.</b> Javobni tekshiring — topilgan sonni dastlabki tenglamaga qo‘ying.', '<b>5.</b> Проверьте ответ — подставьте найденные числа в исходное уравнение.', '<b>5.</b> Check your answer by substituting into the original equation.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Yeching: |x − 3| = 5.', 'Решите: |x − 3| = 5.', 'Solve |x − 3| = 5.'),
        s: L('x − 3 = 5 ⇒ x = 8; x − 3 = −5 ⇒ x = −2. Geometrik: 3 dan 5 birlik masofadagi nuqtalar 8 va −2. Javob: −2; 8.', 'x − 3 = 5 ⇒ x = 8; x − 3 = −5 ⇒ x = −2. Геометрически: точки на расстоянии 5 от 3 — это 8 и −2. Ответ: −2; 8.', 'x − 3 = 5 ⇒ x = 8; x − 3 = −5 ⇒ x = −2. Geometrically: the points at distance 5 from 3 are 8 and −2. Answer: −2; 8.') },
      { q: L('Yeching: |2x + 1| = 7 va |x + 4| = −1.', 'Решите: |2x + 1| = 7 и |x + 4| = −1.', 'Solve |2x + 1| = 7 and |x + 4| = −1.'),
        s: L('2x + 1 = 7 ⇒ x = 3; 2x + 1 = −7 ⇒ x = −4. Javob: −4; 3. Ikkinchisi: modul manfiy bo‘lolmaydi — yechim yo‘q.', '2x + 1 = 7 ⇒ x = 3; 2x + 1 = −7 ⇒ x = −4. Ответ: −4; 3. Второе: модуль не может быть отрицательным — решений нет.', '2x + 1 = 7 ⇒ x = 3; 2x + 1 = −7 ⇒ x = −4. Answer: −4; 3. The second: an absolute value cannot be negative — no solution.') },
      { q: L('Yeching: |x − 1| &lt; 4.', 'Решите: |x − 1| &lt; 4.', 'Solve |x − 1| &lt; 4.'),
        s: L('−4 &lt; x − 1 &lt; 4 ⇒ −3 &lt; x &lt; 5. Javob: (−3; 5). Geometrik: 1 dan 4 birlikdan kam masofadagi nuqtalar.', '−4 &lt; x − 1 &lt; 4 ⇒ −3 &lt; x &lt; 5. Ответ: (−3; 5). Геометрически: точки, удалённые от 1 меньше чем на 4.', '−4 &lt; x − 1 &lt; 4 ⇒ −3 &lt; x &lt; 5. Answer: (−3; 5). Geometrically: points less than 4 units from 1.') },
      { q: L('Yeching: |3x − 6| ≥ 9.', 'Решите: |3x − 6| ≥ 9.', 'Solve |3x − 6| ≥ 9.'),
        s: L('3x − 6 ≤ −9 ⇒ x ≤ −1 yoki 3x − 6 ≥ 9 ⇒ x ≥ 5. Javob: (−∞; −1] ∪ [5; +∞).', '3x − 6 ≤ −9 ⇒ x ≤ −1 или 3x − 6 ≥ 9 ⇒ x ≥ 5. Ответ: (−∞; −1] ∪ [5; +∞).', '3x − 6 ≤ −9 ⇒ x ≤ −1 or 3x − 6 ≥ 9 ⇒ x ≥ 5. Answer: (−∞; −1] ∪ [5; +∞).') }
    ] },
    { kind: 'table', h: L('Qisqa ma’lumotnoma (a &gt; 0)', 'Краткая памятка (a &gt; 0)', 'Quick reference (a &gt; 0)'), table: { head: [L('Ko‘rinish', 'Вид', 'Form'), L('Teng kuchli', 'Равносильно', 'Equivalent to'), L('Javob', 'Ответ', 'Answer')], rows: [
      [L('|x| = a', '|x| = a', '|x| = a'), L('x = a yoki x = −a', 'x = a или x = −a', 'x = a or x = −a'), L('±a', '±a', '±a')],
      [L('|x| &lt; a', '|x| &lt; a', '|x| &lt; a'), L('−a &lt; x &lt; a', '−a &lt; x &lt; a', '−a &lt; x &lt; a'), L('(−a; a)', '(−a; a)', '(−a; a)')],
      [L('|x| ≤ a', '|x| ≤ a', '|x| ≤ a'), L('−a ≤ x ≤ a', '−a ≤ x ≤ a', '−a ≤ x ≤ a'), L('[−a; a]', '[−a; a]', '[−a; a]')],
      [L('|x| &gt; a', '|x| &gt; a', '|x| &gt; a'), L('x &lt; −a yoki x &gt; a', 'x &lt; −a или x &gt; a', 'x &lt; −a or x &gt; a'), L('(−∞; −a) ∪ (a; +∞)', '(−∞; −a) ∪ (a; +∞)', '(−∞; −a) ∪ (a; +∞)')],
      [L('|x| = −a', '|x| = −a', '|x| = −a'), L('mumkin emas', 'невозможно', 'impossible'), L('yechim yo‘q', 'нет решений', 'no solution')],
      [L('|x| &gt; −a', '|x| &gt; −a', '|x| &gt; −a'), L('doim to‘g‘ri', 'всегда верно', 'always true'), L('(−∞; +∞)', '(−∞; +∞)', '(−∞; +∞)')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Bitta ildizni yo‘qotish.</b> |x| = 6 ning javobi faqat 6 emas, balki ±6.', '<b>Потеря корня.</b> Ответ |x| = 6 — не только 6, а ±6.', '<b>Losing a root.</b> The answer to |x| = 6 is not just 6 but ±6.'),
      L('<b>Modulni «minusni o‘chirish» deb tushunish.</b> |x − 5| ≠ x + 5! x = 1 da |1 − 5| = 4, 1 + 5 = 6. −a ham doim manfiy emas: a = −3 da −a = 3.', '<b>Модуль как «стирание минуса».</b> |x − 5| ≠ x + 5! При x = 1: |1 − 5| = 4, а 1 + 5 = 6. И −a не всегда отрицательно: при a = −3 −a = 3.', '<b>Treating the modulus as “deleting minus signs”.</b> |x − 5| ≠ x + 5! At x = 1: |1 − 5| = 4 but 1 + 5 = 6. And −a is not always negative: if a = −3, −a = 3.'),
      L('<b>«&gt;» uchun qo‘sh tengsizlik yozish.</b> |x| &gt; 3 ⇒ −3 &gt; x &gt; 3 — ma’nosiz yozuv. To‘g‘risi: x &lt; −3 <b>yoki</b> x &gt; 3.', '<b>Двойное неравенство для «&gt;».</b> |x| &gt; 3 ⇒ −3 &gt; x &gt; 3 — бессмысленная запись. Верно: x &lt; −3 <b>или</b> x &gt; 3.', '<b>Writing a double inequality for “&gt;”.</b> |x| &gt; 3 ⇒ −3 &gt; x &gt; 3 is meaningless. Correct: x &lt; −3 <b>or</b> x &gt; 3.'),
      L('<b>Manfiy o‘ng tomonni e’tiborsiz qoldirish.</b> |x + 1| = −2 ni x + 1 = ±2 deb yechish xato — yechim yo‘q.', '<b>Игнорирование отрицательной правой части.</b> Решать |x + 1| = −2 как x + 1 = ±2 — ошибка: решений нет.', '<b>Ignoring a negative right side.</b> Solving |x + 1| = −2 as x + 1 = ±2 is wrong — there is no solution.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>O‘lchash xatoligi.</b> Agar haqiqiy qiymat x, o‘lchangani a bo‘lsa, |x − a| — <b>absolyut xatolik</b>. «Taroziga ishonch ±5 g» degani |x − a| ≤ 5. Masalan, 250 g ko‘rsatgan bo‘lsa, haqiqiy massa 245 ≤ x ≤ 255 oralig‘ida. Bu mavzu keyingi «Taqribiy hisoblashlar» mavzusiga ko‘prik bo‘ladi.', '<b>Погрешность измерения.</b> Если истинное значение x, а измеренное a, то |x − a| — <b>абсолютная погрешность</b>. «Точность весов ±5 г» означает |x − a| ≤ 5. Если весы показали 250 г, истинная масса в пределах 245 ≤ x ≤ 255. Это мостик к теме «Приближённые вычисления».', '<b>Measurement error.</b> If the true value is x and the measured value a, then |x − a| is the <b>absolute error</b>. “Scale accuracy ±5 g” means |x − a| ≤ 5. If the scale reads 250 g, the true mass satisfies 245 ≤ x ≤ 255. This is a bridge to the topic “Approximate calculations”.'),
      L('<b>Sport va texnika.</b> Sport zalidagi basketbol to‘pi bosimi me’yordan 0,1 atm dan ko‘p farq qilmasligi kerak; zavodda detal o‘lchami |l − 50| ≤ 0,1 mm talabiga javob berishi kerak. <b>Shahar:</b> yo‘lda ikki shahar orasidagi masofa — koordinatalar ayirmasining moduli, chunki masofa hech qachon manfiy emas.', '<b>Спорт и техника.</b> Давление баскетбольного мяча не должно отличаться от нормы больше чем на 0,1 атм; деталь на заводе должна удовлетворять |l − 50| ≤ 0,1 мм. <b>Город:</b> расстояние между двумя пунктами на дороге — модуль разности координат, ведь расстояние не бывает отрицательным.', '<b>Sport and engineering.</b> A basketball’s pressure must not differ from the standard by more than 0.1 atm; a factory part must satisfy |l − 50| ≤ 0.1 mm. <b>Maps:</b> the distance between two points on a road is the absolute value of the difference of their coordinates, since distance is never negative.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('y = |x| funksiyaning grafigi «V» harfiga o‘xshaydi: u koordinatalar boshida «sinadi» — matematiklar bunday nuqtalarni alohida o‘rganadi.', 'График y = |x| похож на букву «V»: в начале координат он «ломается» — такие точки математики изучают особо.', 'The graph of y = |x| looks like the letter “V”: it has a sharp corner at the origin — mathematicians study such points specially.'),
      L('Uchburchak tengsizligi: |a + b| ≤ |a| + |b|. Uning ma’nosi — to‘g‘ri yo‘l har doim eng qisqa yo‘l.', 'Неравенство треугольника: |a + b| ≤ |a| + |b|. Его смысл — прямой путь всегда самый короткий.', 'The triangle inequality: |a + b| ≤ |a| + |b|. It means the straight path is always the shortest.'),
      L('Dasturlash tillarida modul abs() funksiyasi bilan hisoblanadi — «absolute» so‘zining qisqartmasi.', 'В языках программирования модуль вычисляют функцией abs() — сокращение от «absolute».', 'In programming languages the absolute value is computed by abs() — short for “absolute”.')
    ] },
    { kind: 'practice', h: L('Mashq qiling', 'Потренируйтесь', 'Practice'), ex: [
      { q: L('|x + 2| = 3', '|x + 2| = 3', '|x + 2| = 3'), s: L('x = 1 yoki x = −5.', 'x = 1 или x = −5.', 'x = 1 or x = −5.') },
      { q: L('|x| ≤ 2,5 ning butun yechimlari?', 'Целые решения |x| ≤ 2,5?', 'Whole solutions of |x| ≤ 2.5?'), s: L('−2, −1, 0, 1, 2.', '−2, −1, 0, 1, 2.', '−2, −1, 0, 1, 2.') },
      { q: L('|5 − x| &gt; 1', '|5 − x| &gt; 1', '|5 − x| &gt; 1'), s: L('|x − 5| &gt; 1 ⇒ x &lt; 4 yoki x &gt; 6; (−∞; 4) ∪ (6; +∞).', '|x − 5| &gt; 1 ⇒ x &lt; 4 или x &gt; 6; (−∞; 4) ∪ (6; +∞).', '|x − 5| &gt; 1 ⇒ x &lt; 4 or x &gt; 6; (−∞; 4) ∪ (6; +∞).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('|a| = a (a ≥ 0), |a| = −a (a &lt; 0); har doim |a| ≥ 0.', '|a| = a (a ≥ 0), |a| = −a (a &lt; 0); всегда |a| ≥ 0.', '|a| = a (a ≥ 0), |a| = −a (a &lt; 0); always |a| ≥ 0.'),
      L('|a − b| — son o‘qida a va b orasidagi masofa.', '|a − b| — расстояние между a и b на числовой прямой.', '|a − b| is the distance between a and b on the number line.'),
      L('|x| = a (a &gt; 0) ikki yechimga ega: ±a; a &lt; 0 da yechim yo‘q.', '|x| = a (a &gt; 0) имеет два решения: ±a; при a &lt; 0 решений нет.', '|x| = a (a &gt; 0) has two solutions ±a; for a &lt; 0 there are none.'),
      L('|x| &lt; a ⇔ −a &lt; x &lt; a — bitta oraliq («va»).', '|x| &lt; a ⇔ −a &lt; x &lt; a — один промежуток («и»).', '|x| &lt; a ⇔ −a &lt; x &lt; a — one interval (“and”).'),
      L('|x| &gt; a ⇔ x &lt; −a yoki x &gt; a — ikki nur birlashmasi («yoki»).', '|x| &gt; a ⇔ x &lt; −a или x &gt; a — объединение двух лучей («или»).', '|x| &gt; a ⇔ x &lt; −a or x &gt; a — a union of two rays (“or”).'),
      L('|x| belgisini 1841-yilda Veyershtrass kiritgan; modul o‘lchash xatoligini ifodalaydi.', 'Знак |x| ввёл Вейерштрасс в 1841 году; модуль выражает погрешность измерения.', 'Weierstrass introduced |x| in 1841; the absolute value expresses measurement error.')
    ] }
  ] });
})(this);
