// Nuvemath — 8-sinf, I qism nazariyasi (ikkinchi yarmi: t11–t19). Vaqtinchalik fayl, keyin g8-1.js ga qo‘shiladi. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t11. Taqribiy hisoblash. Absolyut va nisbiy xatolik ----------
  T.add(P, 't11', { sections: [
    { kind: 'intro', h: L('Nega taqribiy hisoblaymiz?', 'Зачем нужны приближённые вычисления?', 'Why do we approximate?'), p: [
      L('Do‘kondagi tarozi olmalarning og‘irligini 1,2 kg deb ko‘rsatdi. Lekin olmalar aynan 1,2 kg emas, balki, masalan, 1,213 kg yoki 1,196 kg bo‘lishi mumkin. Har qanday o‘lchov asbobi faqat ma’lum aniqlikda ishlaydi: maktab chizg‘ichi millimetrgacha, uy termometri o‘ndan bir gradusgacha, sport sekundomeri esa yuzdan bir sekundgacha aniq. Shuning uchun amalda biz deyarli har doim <b>taqribiy</b>, ya’ni aniq qiymatga yaqin bo‘lgan sonlar bilan ishlaymiz.',
        'Весы в магазине показали, что яблоки весят 1,2 кг. Но на самом деле они могут весить, например, 1,213 кг или 1,196 кг. Любой измерительный прибор работает лишь с определённой точностью: школьная линейка — до миллиметра, комнатный термометр — до десятой доли градуса, спортивный секундомер — до сотой доли секунды. Поэтому на практике мы почти всегда имеем дело с <b>приближёнными</b> числами, то есть числами, близкими к точному значению.',
        'The scales in a shop say the apples weigh 1.2 kg. In reality they might weigh 1.213 kg or 1.196 kg. Every measuring instrument works only to a certain accuracy: a school ruler to the nearest millimetre, a room thermometer to a tenth of a degree, a sports stopwatch to a hundredth of a second. So in practice we almost always work with <b>approximate</b> numbers — numbers that are close to the exact value but not equal to it.'),
      L('Taqribiy sonlar faqat o‘lchashda paydo bo‘lmaydi. √2, π yoki <sup>1</sup>/<sub>3</sub> kabi sonlarni o‘nli kasr ko‘rinishida oxirigacha yozib bo‘lmaydi, shuning uchun ularni yaxlitlab olamiz: √2 ≈ 1,41, π ≈ 3,14, <sup>1</sup>/<sub>3</sub> ≈ 0,33. Kalkulyator ham faqat ekranga sig‘adigan raqamlarni ko‘rsatadi. Tabiiy savol tug‘iladi: bunday yaxlitlashda biz qancha xato qilamiz va bu xato muhimmi? Bu mavzuda xatoni o‘lchashning ikki usulini — <b>absolyut</b> va <b>nisbiy</b> xatolikni o‘rganamiz.',
        'Приближённые числа возникают не только при измерениях. Числа √2, π или <sup>1</sup>/<sub>3</sub> нельзя записать конечной десятичной дробью, поэтому мы их округляем: √2 ≈ 1,41, π ≈ 3,14, <sup>1</sup>/<sub>3</sub> ≈ 0,33. Калькулятор тоже показывает лишь те цифры, что помещаются на экране. Возникает естественный вопрос: насколько мы ошибаемся при таком округлении и важна ли эта ошибка? В этой теме мы изучим два способа измерить ошибку — <b>абсолютную</b> и <b>относительную</b> погрешность.',
        'Approximate numbers do not only come from measuring. Numbers like √2, π or <sup>1</sup>/<sub>3</sub> cannot be written as terminating decimals, so we round them: √2 ≈ 1.41, π ≈ 3.14, <sup>1</sup>/<sub>3</sub> ≈ 0.33. A calculator, too, shows only the digits that fit on its screen. A natural question arises: how much do we lose by rounding, and does the loss matter? In this topic we learn two ways to measure an error — the <b>absolute</b> error and the <b>relative</b> error.'),
      L('Bir misol: 1 mm xato kitob uzunligini o‘lchashda arzimas, ammo soat mexanizmidagi kichkina tishli g‘ildirak uchun juda katta. Xuddi shuningdek, 1 km xato Toshkentdan Samarqandgacha bo‘lgan masofada deyarli sezilmaydi, lekin 400 metrli stadion yo‘lagida mutlaqo qabul qilinmaydi. Demak, xatoning o‘zini emas, balki uning o‘lchanayotgan kattalikka nisbatini ham bilish kerak.',
        'Пример: ошибка в 1 мм ничтожна при измерении длины книги, но огромна для крошечной шестерёнки в часовом механизме. Точно так же ошибка в 1 км почти незаметна на расстоянии от Ташкента до Самарканда, но совершенно недопустима на 400-метровой дорожке стадиона. Значит, важна не только сама ошибка, но и её отношение к измеряемой величине.',
        'An example: an error of 1 mm is negligible when measuring a book, yet huge for a tiny gear wheel inside a watch. Likewise, an error of 1 km goes almost unnoticed on the road from Tashkent to Samarkand, but is completely unacceptable on a 400-metre running track. So what matters is not only the error itself but also how big it is compared with the quantity being measured.')
    ] },
    { kind: 'def', h: L('Absolyut va nisbiy xatolik ta’rifi', 'Определения абсолютной и относительной погрешности', 'Defining absolute and relative error'), p: [
      L('Aytaylik, x — biror kattalikning aniq qiymati, a esa uning taqribiy qiymati. Bu holda x ≈ a deb yozamiz («x taqriban a ga teng» deb o‘qiladi) va quyidagi tushunchalarni kiritamiz.',
        'Пусть x — точное значение некоторой величины, а a — её приближённое значение. Тогда пишут x ≈ a (читается «x приближённо равно a») и вводят следующие понятия.',
        'Let x be the exact value of some quantity and a its approximate value. We write x ≈ a (read “x is approximately equal to a”) and introduce the following ideas.')
    ], list: [
      L('<b>Absolyut xatolik</b> — aniq va taqribiy qiymatlar ayirmasining moduli: Δ = |x − a|. U xato necha birlik ekanini ko‘rsatadi va o‘lchanayotgan kattalik birligida (cm, kg, s) ifodalanadi.',
        '<b>Абсолютная погрешность</b> — модуль разности точного и приближённого значений: Δ = |x − a|. Она показывает, на сколько единиц мы ошиблись, и выражается в единицах измеряемой величины (см, кг, с).',
        'The <b>absolute error</b> is the modulus of the difference between the exact and approximate values: Δ = |x − a|. It tells us by how many units we are off, and it is measured in the units of the quantity (cm, kg, s).'),
      L('<b>Nisbiy xatolik</b> — absolyut xatolikning aniq qiymat moduliga nisbati: δ = |x − a| : |x|. Odatda foizlarda yoziladi: δ = |x − a| : |x| · 100%. Bu birliksiz son, shuning uchun turli kattaliklarni taqqoslashga yaraydi.',
        '<b>Относительная погрешность</b> — отношение абсолютной погрешности к модулю точного значения: δ = |x − a| : |x|. Обычно её записывают в процентах: δ = |x − a| : |x| · 100%. Это безразмерное число, поэтому оно позволяет сравнивать разные величины.',
        'The <b>relative error</b> is the absolute error divided by the modulus of the exact value: δ = |x − a| : |x|. It is usually written as a percentage: δ = |x − a| : |x| · 100%. It has no units, so it lets us compare quite different quantities.'),
      L('Agar a &gt; x bo‘lsa, a son x ning <b>ortig‘i bilan</b> olingan taqribiy qiymati, a &lt; x bo‘lsa — <b>kami bilan</b> olingan taqribiy qiymati deyiladi.',
        'Если a &gt; x, то a называют приближённым значением <b>с избытком</b>, если a &lt; x — <b>с недостатком</b>.',
        'If a &gt; x, then a is an approximation <b>from above</b> (an over-estimate); if a &lt; x, it is an approximation <b>from below</b> (an under-estimate).')
    ], after: [
      L('Ko‘pincha aniq qiymat x bizga noma’lum bo‘ladi — aks holda taqribiy sonni ishlatishga hojat ham bo‘lmasdi. Shunda absolyut xatolikning o‘zini emas, uning <b>chegarasini</b> ko‘rsatamiz: agar |x − a| ≤ h bo‘lsa, «x son a ga h aniqlikda teng» deyiladi va x = a ± h deb yoziladi. Masalan, chizg‘ich bilan o‘lchangan uzunlik l = 12,4 ± 0,1 cm bo‘lsa, haqiqiy uzunlik 12,3 cm dan 12,5 cm gacha bo‘lgan oraliqda yotadi. Bunday holda nisbiy xatolik taxminan h : |a| deb baholanadi.',
        'Часто точное значение x нам неизвестно — иначе не было бы нужды в приближении. Тогда указывают не саму абсолютную погрешность, а её <b>границу</b>: если |x − a| ≤ h, говорят, что «x равно a с точностью до h», и пишут x = a ± h. Например, если длина, измеренная линейкой, равна l = 12,4 ± 0,1 см, то истинная длина лежит в промежутке от 12,3 см до 12,5 см. В этом случае относительную погрешность оценивают как h : |a|.',
        'Often the exact value x is unknown — otherwise we would not need an approximation at all. Then we give not the absolute error itself but a <b>bound</b> for it: if |x − a| ≤ h, we say “x equals a to within h” and write x = a ± h. For example, if a length measured with a ruler is l = 12.4 ± 0.1 cm, the true length lies between 12.3 cm and 12.5 cm. In this case the relative error is estimated as h : |a|.'),
      L('Modul belgisi nima uchun kerak? Chunki bizni xatolikning yo‘nalishi (ortiq yoki kam) emas, uning kattaligi qiziqtiradi. 49 o‘rniga 50 yoki 51 o‘rniga 50 yozsak, ikkala holda ham absolyut xatolik 1 ga teng bo‘ladi.',
        'Зачем нужен модуль? Потому что нас интересует не направление ошибки (избыток или недостаток), а её величина. Напишем ли мы 50 вместо 49 или 50 вместо 51 — в обоих случаях абсолютная погрешность равна 1.',
        'Why the modulus? Because we care about the size of the error, not its direction (too big or too small). Whether we write 50 instead of 49 or 50 instead of 51, the absolute error is 1 in both cases.')
    ] },
    { kind: 'history', h: L('Tarixdan: Arximed, Beruniy va al-Koshiy', 'Из истории: Архимед, Бируни и аль-Каши', 'From history: Archimedes, al-Biruni and al-Kashi'), p: [
      L('Taqribiy hisoblash g‘oyasi juda qadimiy. Miloddan avvalgi III asrda yunon olimi Arximed aylanaga ichki va tashqi chizilgan 96 burchakli muntazam ko‘pburchaklarning perimetrlarini hisoblab, π sonining chegaralarini topdi: 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub>. U π ni aniq topib bo‘lmasligini tushundi, ammo xatolikni qat’iy chegaraladi. Bu aynan bugungi «a ± h» yozuvining g‘oyasidir.',
        'Идея приближённых вычислений очень древняя. В III веке до н. э. греческий учёный Архимед вычислил периметры вписанного и описанного правильных 96-угольников и нашёл границы числа π: 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub>. Он понимал, что точно π найти нельзя, но строго ограничил погрешность. Это и есть идея современной записи «a ± h».',
        'The idea of approximation is very old. In the 3rd century BC the Greek scholar Archimedes computed the perimeters of regular 96-sided polygons drawn inside and outside a circle and found bounds for π: 3<sup>10</sup>/<sub>71</sub> &lt; π &lt; 3<sup>1</sup>/<sub>7</sub>. He knew π could not be found exactly, but he strictly bounded the error — exactly the idea behind today’s “a ± h”.'),
      L('XI asrda buyuk xorazmlik olim Abu Rayhon Beruniy Yer radiusini o‘lchashning yangi usulini taklif qildi. U balandligi oldindan o‘lchangan tog‘ cho‘qqisiga chiqib, ufq chizig‘ining pastga og‘ish burchagini o‘lchadi va trigonometriya yordamida radiusni hisobladi. Beruniy topgan natija taxminan 6340 km, hozirgi o‘rtacha qiymat esa taxminan 6371 km. Absolyut xatolik 30 km atrofida, nisbiy xatolik esa yarim foizdan ham kam! Ming yil oldin oddiy asboblar bilan erishilgan bu aniqlik hozir ham hayratlanarli.',
        'В XI веке великий хорезмский учёный Абу Райхан Бируни предложил новый способ измерения радиуса Земли. Он поднялся на гору заранее измеренной высоты, измерил угол понижения линии горизонта и с помощью тригонометрии вычислил радиус. Результат Бируни — около 6340 км, а современное среднее значение — около 6371 км. Абсолютная погрешность около 30 км, а относительная — меньше половины процента! Такая точность, достигнутая тысячу лет назад простыми инструментами, поражает и сегодня.',
        'In the 11th century the great Khwarazmian scholar Abu Rayhan al-Biruni proposed a new way to measure the Earth’s radius. He climbed a mountain whose height he had measured beforehand, measured how far the horizon dipped below the level, and used trigonometry to compute the radius. His result was about 6340 km, while the modern mean value is about 6371 km. The absolute error is around 30 km and the relative error is under half a percent! Such accuracy, reached a thousand years ago with simple instruments, is still astonishing.'),
      L('XV asrda Samarqanddagi Ulug‘bek rasadxonasida ishlagan G‘iyosiddin al-Koshiy 1424-yilda π sonini 16 ta o‘nli xona aniqligida hisobladi. Bu rekord Yevropada qariyb 180 yil davomida takrorlanmadi. Al-Koshiy o‘nli kasrlardan keng foydalanishni ham targ‘ib qilgan — taqribiy hisoblashlar aynan o‘nli kasrlarda eng qulay bajariladi.',
        'В XV веке Гияс ад-Дин аль-Каши, работавший в обсерватории Улугбека в Самарканде, в 1424 году вычислил число π с точностью до 16 десятичных знаков. В Европе этот рекорд не могли повторить почти 180 лет. Аль-Каши также пропагандировал десятичные дроби — именно в них удобнее всего выполнять приближённые вычисления.',
        'In the 15th century Ghiyath al-Din al-Kashi, who worked at Ulugh Beg’s observatory in Samarkand, computed π to 16 decimal places in 1424. Nobody in Europe matched this record for almost 180 years. Al-Kashi also promoted decimal fractions — the most convenient tool for approximate calculation.')
    ] },
    { kind: 'rule', h: L('Yaxlitlash qoidasi va xatolik chegarasi', 'Правило округления и граница погрешности', 'Rounding and the error bound'), p: [
      L('Sonni biror xonagacha yaxlitlash uchun shu xonadan keyingi birinchi raqamga qaraymiz. Agar u 0, 1, 2, 3 yoki 4 bo‘lsa, keyingi barcha raqamlarni tashlab yuboramiz (kami bilan yaxlitlash). Agar u 5, 6, 7, 8 yoki 9 bo‘lsa, yaxlitlanayotgan xonadagi raqamni 1 ga oshiramiz (ortig‘i bilan yaxlitlash). Masalan, 3,14159 ≈ 3,14 (yuzdan birgacha), 2,718 ≈ 2,72 (yuzdan birgacha), 6371 ≈ 6400 (yuzlargacha).',
        'Чтобы округлить число до некоторого разряда, смотрим на первую цифру после этого разряда. Если это 0, 1, 2, 3 или 4, отбрасываем все следующие цифры (округление с недостатком). Если 5, 6, 7, 8 или 9 — увеличиваем цифру округляемого разряда на 1 (округление с избытком). Например, 3,14159 ≈ 3,14 (до сотых), 2,718 ≈ 2,72 (до сотых), 6371 ≈ 6400 (до сотен).',
        'To round a number to a given place, look at the first digit after that place. If it is 0, 1, 2, 3 or 4, drop all the following digits (rounding down). If it is 5, 6, 7, 8 or 9, increase the digit in the rounding place by 1 (rounding up). For example, 3.14159 ≈ 3.14 (to hundredths), 2.718 ≈ 2.72 (to hundredths), 6371 ≈ 6400 (to hundreds).'),
      L('<b>Muhim xossa:</b> sonni biror xonagacha to‘g‘ri yaxlitlasak, absolyut xatolik shu xona birligining yarmidan oshmaydi. O‘ndan birgacha yaxlitlashda Δ ≤ 0,05, yuzdan birgacha — Δ ≤ 0,005, butunlargacha — Δ ≤ 0,5. Sababi: yaxlitlangan son aniq sonning ikki «qo‘shni» qiymatidan eng yaqiniga teng, ular orasidagi masofa esa bir birlik.',
        '<b>Важное свойство:</b> при правильном округлении до некоторого разряда абсолютная погрешность не превышает половины единицы этого разряда. При округлении до десятых Δ ≤ 0,05, до сотых — Δ ≤ 0,005, до целых — Δ ≤ 0,5. Причина: округлённое число — ближайшее из двух «соседних» значений, а расстояние между ними равно одной единице разряда.',
        '<b>Key property:</b> when a number is rounded correctly to some place, the absolute error is at most half a unit of that place. Rounding to tenths gives Δ ≤ 0.05, to hundredths Δ ≤ 0.005, to whole numbers Δ ≤ 0.5. The reason: the rounded number is the nearer of the two “neighbouring” values, and these neighbours are one unit apart.'),
      L('Nisbiy xatolik formulasi: δ = Δ : |x| · 100%. Nisbiy xatolik qancha kichik bo‘lsa, o‘lchov yoki hisob shuncha <b>sifatli</b> hisoblanadi. Taqqoslang: 1000 km ni 1 km xato bilan o‘lchash (δ = 0,1%) 10 m ni 1 m xato bilan o‘lchashdan (δ = 10%) yuz marta aniqroq, garchi birinchi holda absolyut xatolik ming marta katta bo‘lsa ham.',
        'Формула относительной погрешности: δ = Δ : |x| · 100%. Чем меньше относительная погрешность, тем <b>качественнее</b> измерение или вычисление. Сравните: измерить 1000 км с ошибкой 1 км (δ = 0,1%) в сто раз точнее, чем 10 м с ошибкой 1 м (δ = 10%), хотя в первом случае абсолютная погрешность в тысячу раз больше.',
        'The relative error formula is δ = Δ : |x| · 100%. The smaller the relative error, the <b>better</b> the measurement or calculation. Compare: measuring 1000 km with an error of 1 km (δ = 0.1%) is a hundred times more accurate than measuring 10 m with an error of 1 m (δ = 10%), even though the absolute error in the first case is a thousand times larger.')
    ] },
    { kind: 'steps', h: L('Xatolikni topish algoritmi', 'Алгоритм нахождения погрешности', 'How to find the error, step by step'), list: [
      L('<b>1-qadam.</b> Aniq qiymat x ni va taqribiy qiymat a ni aniqlang. Qaysi biri aniq ekanini adashtirmang.',
        '<b>Шаг 1.</b> Определите точное значение x и приближённое значение a. Не перепутайте, какое из них точное.',
        '<b>Step 1.</b> Identify the exact value x and the approximate value a. Do not mix up which one is exact.'),
      L('<b>2-qadam.</b> Ayirmani hisoblang: x − a. Agar x oddiy kasr bo‘lsa, ayirmani ham oddiy kasrda hisoblash qulayroq.',
        '<b>Шаг 2.</b> Вычислите разность x − a. Если x — обыкновенная дробь, разность удобнее считать тоже в обыкновенных дробях.',
        '<b>Step 2.</b> Compute the difference x − a. If x is a common fraction, it is easier to work with common fractions here too.'),
      L('<b>3-qadam.</b> Modulini oling — bu absolyut xatolik Δ = |x − a|. U har doim manfiy emas.',
        '<b>Шаг 3.</b> Возьмите модуль — это абсолютная погрешность Δ = |x − a|. Она всегда неотрицательна.',
        '<b>Step 3.</b> Take the modulus — this is the absolute error Δ = |x − a|. It is never negative.'),
      L('<b>4-qadam.</b> Δ ni |x| ga bo‘ling va 100% ga ko‘paytiring — bu nisbiy xatolik δ.',
        '<b>Шаг 4.</b> Разделите Δ на |x| и умножьте на 100% — это относительная погрешность δ.',
        '<b>Step 4.</b> Divide Δ by |x| and multiply by 100% — this is the relative error δ.'),
      L('<b>5-qadam.</b> Natijani mantiqan tekshiring: δ odatda kichik son (bir necha foiz yoki undan kam). Agar 50% chiqsa, ehtimol, x va a almashib ketgan yoki xona noto‘g‘ri.',
        '<b>Шаг 5.</b> Проверьте результат на здравый смысл: δ обычно мала (несколько процентов или меньше). Если получилось 50%, вероятно, перепутаны x и a или ошибка в разряде.',
        '<b>Step 5.</b> Check that the answer makes sense: δ is usually small (a few percent or less). If you get 50%, you have probably swapped x and a or slipped a decimal place.')
    ], after: [
      L('Agar x noma’lum bo‘lib, faqat x = a ± h berilgan bo‘lsa, 2–3-qadamlar o‘rniga Δ ≤ h deb olamiz, 4-qadamda esa |x| o‘rniga |a| ga bo‘lamiz. Bu baholash deyiladi va u amalda deyarli bir xil natija beradi, chunki a son x ga juda yaqin.',
        'Если x неизвестно и дано лишь x = a ± h, то вместо шагов 2–3 считаем Δ ≤ h, а на шаге 4 делим не на |x|, а на |a|. Это называется оценкой, и на практике она даёт почти тот же результат, ведь a очень близко к x.',
        'If x is unknown and only x = a ± h is given, replace steps 2–3 by Δ ≤ h and in step 4 divide by |a| instead of |x|. This is called an estimate, and in practice it gives almost the same result, because a is very close to x.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('x = 50, a = 49. Absolyut va nisbiy xatolikni toping.', 'x = 50, a = 49. Найдите абсолютную и относительную погрешности.', 'x = 50, a = 49. Find the absolute and relative errors.'),
        s: L('Δ = |50 − 49| = 1. δ = 1 : 50 · 100% = 2%. Taqribiy qiymat kami bilan olingan, chunki 49 &lt; 50.', 'Δ = |50 − 49| = 1. δ = 1 : 50 · 100% = 2%. Приближение взято с недостатком, так как 49 &lt; 50.', 'Δ = |50 − 49| = 1. δ = 1 : 50 · 100% = 2%. This is an approximation from below, since 49 &lt; 50.') },
      { q: L('2,718 sonini o‘ndan birgacha yaxlitlang va xatoliklarni toping.', 'Округлите 2,718 до десятых и найдите погрешности.', 'Round 2.718 to tenths and find the errors.'),
        s: L('O‘ndan birlardan keyingi raqam 1 &lt; 5, demak, a = 2,7. Δ = |2,718 − 2,7| = 0,018 (bu 0,05 dan kichik, qoida bajarildi). δ = 0,018 : 2,718 · 100% ≈ 0,66%.', 'Цифра после десятых равна 1 &lt; 5, значит, a = 2,7. Δ = |2,718 − 2,7| = 0,018 (меньше 0,05, правило выполнено). δ = 0,018 : 2,718 · 100% ≈ 0,66%.', 'The digit after the tenths is 1 &lt; 5, so a = 2.7. Δ = |2.718 − 2.7| = 0.018 (less than 0.05, as the rule promises). δ = 0.018 : 2.718 · 100% ≈ 0.66%.') },
      { q: L('<sup>1</sup>/<sub>3</sub> ≈ 0,33 deb olindi. Xatoliklarni aniq hisoblang.', 'Приняли <sup>1</sup>/<sub>3</sub> ≈ 0,33. Найдите погрешности точно.', 'We take <sup>1</sup>/<sub>3</sub> ≈ 0.33. Find the errors exactly.'),
        s: L('Oddiy kasrlarda ishlaymiz: 0,33 = <sup>33</sup>/<sub>100</sub>. Δ = |<sup>1</sup>/<sub>3</sub> − <sup>33</sup>/<sub>100</sub>| = |<sup>100 − 99</sup>/<sub>300</sub>| = <sup>1</sup>/<sub>300</sub> ≈ 0,0033. δ = <sup>1</sup>/<sub>300</sub> : <sup>1</sup>/<sub>3</sub> = <sup>3</sup>/<sub>300</sub> = 0,01 = 1%.', 'Работаем с обыкновенными дробями: 0,33 = <sup>33</sup>/<sub>100</sub>. Δ = |<sup>1</sup>/<sub>3</sub> − <sup>33</sup>/<sub>100</sub>| = |<sup>100 − 99</sup>/<sub>300</sub>| = <sup>1</sup>/<sub>300</sub> ≈ 0,0033. δ = <sup>1</sup>/<sub>300</sub> : <sup>1</sup>/<sub>3</sub> = <sup>3</sup>/<sub>300</sub> = 0,01 = 1%.', 'Work with common fractions: 0.33 = <sup>33</sup>/<sub>100</sub>. Δ = |<sup>1</sup>/<sub>3</sub> − <sup>33</sup>/<sub>100</sub>| = |<sup>100 − 99</sup>/<sub>300</sub>| = <sup>1</sup>/<sub>300</sub> ≈ 0.0033. δ = <sup>1</sup>/<sub>300</sub> : <sup>1</sup>/<sub>3</sub> = <sup>3</sup>/<sub>300</sub> = 0.01 = 1%.') },
      { q: L('Kitob uzunligi 25 ± 0,1 cm, yo‘l uzunligi 12 ± 0,1 km. Qaysi o‘lchov sifatliroq?', 'Длина книги 25 ± 0,1 см, длина дороги 12 ± 0,1 км. Какое измерение качественнее?', 'A book is 25 ± 0.1 cm long, a road is 12 ± 0.1 km long. Which measurement is better?'),
        s: L('Absolyut xatoliklarni taqqoslab bo‘lmaydi (cm va km). Nisbiy xatoliklar: kitob uchun 0,1 : 25 = 0,004 = 0,4%; yo‘l uchun 0,1 : 12 ≈ 0,0083 ≈ 0,83%. Kitob o‘lchovi ikki baravar aniqroq.', 'Абсолютные погрешности сравнивать нельзя (см и км). Относительные: для книги 0,1 : 25 = 0,004 = 0,4%; для дороги 0,1 : 12 ≈ 0,0083 ≈ 0,83%. Измерение книги примерно вдвое точнее.', 'The absolute errors cannot be compared (cm versus km). Relative errors: book 0.1 : 25 = 0.004 = 0.4%; road 0.1 : 12 ≈ 0.0083 ≈ 0.83%. The book measurement is about twice as accurate.') }
    ] },
    { kind: 'table', h: L('π ning taqribiy qiymatlari', 'Приближённые значения π', 'Approximations of π'), p: [
      L('π = 3,14159265… sonining turli yaqinlashishlari va ularning xatoliklari. Raqamlar ko‘paygan sari nisbiy xatolik keskin kamayadi.', 'Различные приближения числа π = 3,14159265… и их погрешности. С каждой новой цифрой относительная погрешность резко уменьшается.', 'Various approximations of π = 3.14159265… and their errors. With each extra digit the relative error drops sharply.')
    ], table: { head: [L('Taqribiy qiymat', 'Приближение', 'Approximation'), L('Absolyut xatolik', 'Абсолютная погрешность', 'Absolute error'), L('Nisbiy xatolik', 'Относительная погрешность', 'Relative error')], rows: [
      ['3', L('≈ 0,1416', '≈ 0,1416', '≈ 0.1416'), L('≈ 4,5%', '≈ 4,5%', '≈ 4.5%')],
      [L('3,1', '3,1', '3.1'), L('≈ 0,0416', '≈ 0,0416', '≈ 0.0416'), L('≈ 1,3%', '≈ 1,3%', '≈ 1.3%')],
      [L('3,14', '3,14', '3.14'), L('≈ 0,0016', '≈ 0,0016', '≈ 0.0016'), L('≈ 0,05%', '≈ 0,05%', '≈ 0.05%')],
      [L('<sup>22</sup>/<sub>7</sub> (Arximed)', '<sup>22</sup>/<sub>7</sub> (Архимед)', '<sup>22</sup>/<sub>7</sub> (Archimedes)'), L('≈ 0,0013', '≈ 0,0013', '≈ 0.0013'), L('≈ 0,04%', '≈ 0,04%', '≈ 0.04%')],
      [L('3,1416', '3,1416', '3.1416'), L('≈ 0,0000073', '≈ 0,0000073', '≈ 0.0000073'), L('≈ 0,0002%', '≈ 0,0002%', '≈ 0.0002%')],
      [L('<sup>355</sup>/<sub>113</sub> (Zu Chongzhi)', '<sup>355</sup>/<sub>113</sub> (Цзу Чунчжи)', '<sup>355</sup>/<sub>113</sub> (Zu Chongzhi)'), L('≈ 0,00000027', '≈ 0,00000027', '≈ 0.00000027'), L('≈ 0,00001%', '≈ 0,00001%', '≈ 0.00001%')]
    ] }, after: [
      L('Qiziq: <sup>22</sup>/<sub>7</sub> kasri 3,14 dan biroz aniqroq, ammo ortig‘i bilan olingan. V asrda yashagan xitoy olimi Zu Chongzhi topgan <sup>355</sup>/<sub>113</sub> kasri esa olti o‘nli xonagacha to‘g‘ri — maxraji kichik kasrlar ichida eng yaxshi yaqinlashishlardan biri.', 'Интересно: дробь <sup>22</sup>/<sub>7</sub> чуть точнее, чем 3,14, но взята с избытком. А дробь <sup>355</sup>/<sub>113</sub>, найденная китайским учёным Цзу Чунчжи в V веке, верна до шести знаков — одно из лучших приближений с небольшим знаменателем.', 'Interesting: <sup>22</sup>/<sub>7</sub> is a little more accurate than 3.14, but it is an over-estimate. The fraction <sup>355</sup>/<sub>113</sub>, found by the Chinese scholar Zu Chongzhi in the 5th century, is correct to six decimal places — one of the best approximations with a small denominator.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Modulni unutish.</b> x = 49, a = 50 bo‘lsa, Δ = |49 − 50| = 1, −1 emas. Xatolik hech qachon manfiy bo‘lmaydi.', '<b>Забыть модуль.</b> При x = 49, a = 50 имеем Δ = |49 − 50| = 1, а не −1. Погрешность не бывает отрицательной.', '<b>Forgetting the modulus.</b> With x = 49, a = 50 we get Δ = |49 − 50| = 1, not −1. An error is never negative.'),
      L('<b>Absolyut xatoliklarni turli kattaliklar uchun taqqoslash.</b> 1 kg va 1 g xatolarning qaysi biri «yomonroq» ekanini faqat nisbiy xatolik ayta oladi.', '<b>Сравнивать абсолютные погрешности разных величин.</b> Какая ошибка «хуже» — 1 кг или 1 г — может сказать только относительная погрешность.', '<b>Comparing absolute errors of different quantities.</b> Only the relative error can tell whether an error of 1 kg or of 1 g is “worse”.'),
      L('<b>Ikki marta yaxlitlash.</b> 2,45 ni butungacha yaxlitlashda avval 2,5 ga, keyin 3 ga yaxlitlash noto‘g‘ri. To‘g‘ri javob 2, chunki o‘ndan birlar raqami 4 &lt; 5. Har doim asl sondan bir marta yaxlitlang.', '<b>Двойное округление.</b> Округляя 2,45 до целых, нельзя сначала получить 2,5, а потом 3. Правильно 2, так как цифра десятых 4 &lt; 5. Всегда округляйте исходное число один раз.', '<b>Double rounding.</b> When rounding 2.45 to a whole number, do not go 2.45 → 2.5 → 3. The correct answer is 2, because the tenths digit is 4 &lt; 5. Always round the original number once.'),
      L('<b>Foizga o‘tkazishni unutish.</b> 0,02 va 2% bir xil son, ammo «nisbiy xatolik 0,02%» deb yozish xato — bu yuz marta kichik.', '<b>Забыть перевести в проценты.</b> 0,02 и 2% — одно и то же число, но написать «относительная погрешность 0,02%» — ошибка: это в сто раз меньше.', '<b>Forgetting to convert to percent.</b> 0.02 and 2% are the same number, but writing “relative error 0.02%” is wrong — that is a hundred times smaller.'),
      L('<b>Ortiqcha raqamlar.</b> Agar tomonlar 0,1 cm aniqlikda o‘lchangan bo‘lsa, yuzani 12,37684 cm<sup>2</sup> deb yozish ma’nosiz: oxirgi raqamlar ishonchsiz. Natijani berilgan ma’lumotlar aniqligiga mos yaxlitlang.', '<b>Лишние цифры.</b> Если стороны измерены с точностью 0,1 см, писать площадь 12,37684 см<sup>2</sup> бессмысленно: последние цифры недостоверны. Округляйте результат в соответствии с точностью данных.', '<b>Too many digits.</b> If the sides were measured to 0.1 cm, writing the area as 12.37684 cm<sup>2</sup> is meaningless: the last digits are unreliable. Round the result to match the accuracy of the data.')
    ] },
    { kind: 'life', h: L('Hayotda xatolik', 'Погрешность в жизни', 'Errors in real life'), p: [
      L('<b>Tibbiyot.</b> Dori dozasida nisbiy xatolik juda kichik bo‘lishi shart. Bola uchun 5 ml sirop o‘rniga 6 ml berish — 20% xato, bu esa xavfli bo‘lishi mumkin. Shuning uchun dorixonada maxsus o‘lchov shpritslari ishlatiladi.', '<b>Медицина.</b> В дозировке лекарств относительная погрешность должна быть очень маленькой. Дать ребёнку 6 мл сиропа вместо 5 мл — ошибка в 20%, а это может быть опасно. Поэтому используют специальные мерные шприцы.', '<b>Medicine.</b> In medicine doses the relative error must be very small. Giving a child 6 ml of syrup instead of 5 ml is a 20% error, which can be dangerous. That is why special measuring syringes are used.'),
      L('<b>Qurilish.</b> Uy poydevorini quyishda 1 cm xato 10 m uzunlikda atigi 0,1% ni tashkil etadi va odatda qabul qilinadi. Ammo deraza romi uchun 1 cm xato — katta muammo: rom o‘rniga tushmaydi.', '<b>Строительство.</b> При заливке фундамента ошибка 1 см на длине 10 м составляет всего 0,1% и обычно допустима. А для оконной рамы ошибка в 1 см — большая проблема: рама не встанет на место.', '<b>Building.</b> When pouring a foundation, an error of 1 cm over 10 m is only 0.1% and is usually fine. For a window frame, though, a 1 cm error is a big problem: the frame will not fit.'),
      L('<b>Navigatsiya.</b> Telefondagi GPS joylashuvni odatda 3–5 metr aniqlikda aniqlaydi. Shahar ko‘chasida bu yetarli, ammo dron qo‘ndirish yoki dalani avtomatik haydash uchun santimetrli aniqlik kerak bo‘ladi. <b>Sport</b>da esa natijalar yuzdan, hatto mingdan bir sekundgacha qayd etiladi, chunki g‘olib va ikkinchi o‘rin orasidagi farq ba’zan 0,01 s bo‘ladi.', '<b>Навигация.</b> GPS в телефоне обычно определяет место с точностью 3–5 метров. Для городской улицы этого хватает, но для посадки дрона или автоматической вспашки поля нужна сантиметровая точность. В <b>спорте</b> результаты фиксируют до сотых и даже тысячных долей секунды, ведь победителя от второго места порой отделяют 0,01 с.', '<b>Navigation.</b> A phone’s GPS usually finds your position to within 3–5 metres. That is enough on a city street, but landing a drone or steering a tractor automatically needs centimetre accuracy. In <b>sport</b>, results are recorded to hundredths or even thousandths of a second, because the winner and the runner-up may be only 0.01 s apart.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Kosmik kemalarni boshqarishda NASA muhandislari π ning atigi 15 ta o‘nli xonasidan foydalanadi. Bu Quyosh tizimi miqyosidagi hisoblarda santimetr ulushlaridagi xato beradi xolos.', 'Для навигации космических аппаратов инженеры NASA используют лишь 15 знаков числа π. В масштабах Солнечной системы это даёт ошибку в доли сантиметра.', 'To navigate spacecraft, NASA engineers use only 15 decimal places of π. Across the Solar System this produces an error of only a fraction of a centimetre.'),
      L('Eng aniq zamonaviy optik soatlar shunchalik aniqki, ular koinot yoshiga teng vaqt davomida ham bir sekunddan kam adashadi. Ularning nisbiy xatoligi 10<sup>−18</sup> atrofida.', 'Самые точные современные оптические часы настолько точны, что за время, равное возрасту Вселенной, ошиблись бы меньше чем на секунду. Их относительная погрешность — около 10<sup>−18</sup>.', 'The most accurate modern optical clocks are so precise that over a time equal to the age of the Universe they would drift by less than a second. Their relative error is about 10<sup>−18</sup>.'),
      L('Metr dastlab Yer meridiani choragining o‘n milliondan biri deb ta’riflangan edi. Keyinchalik o‘lchashlar unda kichik xato borligini ko‘rsatdi, shuning uchun bugun metr yorug‘lik tezligi orqali ta’riflanadi.', 'Метр сначала определили как одну десятимиллионную четверти земного меридиана. Позже измерения показали, что в этом есть небольшая погрешность, поэтому сегодня метр определяют через скорость света.', 'The metre was first defined as one ten-millionth of a quarter of the Earth’s meridian. Later measurements showed a small error in this, so today the metre is defined through the speed of light.'),
      L('Ovoz berish natijalarida «±3%» degan yozuv — bu so‘rovnomaning xatolik chegarasi. Agar ikki nomzod farqi 2% bo‘lsa, so‘rovnoma g‘olibni ishonchli aniqlay olmaydi.', 'Пометка «±3%» в результатах опросов — это граница погрешности опроса. Если два кандидата различаются на 2%, опрос не может надёжно назвать победителя.', 'The note “±3%” next to opinion poll results is the poll’s error bound. If two candidates differ by 2%, the poll cannot reliably name the winner.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), p: [
      L('Avval o‘zingiz yeching, so‘ng yechimni tekshiring.', 'Сначала решите сами, затем сверьтесь с решением.', 'Solve each one yourself first, then check the solution.')
    ], ex: [
      { q: L('x = 200, a = 198. Δ va δ ni toping.', 'x = 200, a = 198. Найдите Δ и δ.', 'x = 200, a = 198. Find Δ and δ.'), s: L('Δ = 2, δ = 2 : 200 · 100% = 1%.', 'Δ = 2, δ = 2 : 200 · 100% = 1%.', 'Δ = 2, δ = 2 : 200 · 100% = 1%.') },
      { q: L('7,846 ni yuzdan birgacha yaxlitlang va absolyut xatolikni toping.', 'Округлите 7,846 до сотых и найдите абсолютную погрешность.', 'Round 7.846 to hundredths and find the absolute error.'), s: L('Mingdan birlar raqami 6 ≥ 5, demak, a = 7,85. Δ = |7,846 − 7,85| = 0,004 ≤ 0,005.', 'Цифра тысячных 6 ≥ 5, значит, a = 7,85. Δ = |7,846 − 7,85| = 0,004 ≤ 0,005.', 'The thousandths digit is 6 ≥ 5, so a = 7.85. Δ = |7.846 − 7.85| = 0.004 ≤ 0.005.') },
      { q: L('Qaysi tortish aniqroq: 10 ± 0,5 kg yoki 1000 ± 5 kg?', 'Какое взвешивание точнее: 10 ± 0,5 кг или 1000 ± 5 кг?', 'Which weighing is more accurate: 10 ± 0.5 kg or 1000 ± 5 kg?'), s: L('Nisbiy xatoliklar: 0,5 : 10 = 5% va 5 : 1000 = 0,5%. Ikkinchisi o‘n marta aniqroq, garchi absolyut xatoligi katta bo‘lsa ham.', 'Относительные погрешности: 0,5 : 10 = 5% и 5 : 1000 = 0,5%. Второе в десять раз точнее, хотя абсолютная погрешность больше.', 'Relative errors: 0.5 : 10 = 5% and 5 : 1000 = 0.5%. The second is ten times more accurate, even though its absolute error is larger.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Amalda o‘lchov va yaxlitlash tufayli deyarli hamma sonlar taqribiy: x ≈ a.', 'На практике из-за измерений и округлений почти все числа приближённые: x ≈ a.', 'In practice, because of measuring and rounding, almost all numbers are approximate: x ≈ a.'),
      L('Absolyut xatolik Δ = |x − a| — xato necha birlik ekanini ko‘rsatadi.', 'Абсолютная погрешность Δ = |x − a| показывает, на сколько единиц мы ошиблись.', 'The absolute error Δ = |x − a| tells how many units we are off.'),
      L('Nisbiy xatolik δ = |x − a| : |x| · 100% — o‘lchov sifatini ko‘rsatadi va turli kattaliklarni taqqoslashga imkon beradi.', 'Относительная погрешность δ = |x − a| : |x| · 100% показывает качество измерения и позволяет сравнивать разные величины.', 'The relative error δ = |x − a| : |x| · 100% shows the quality of a measurement and lets us compare different quantities.'),
      L('x = a ± h yozuvi aniq qiymat a − h dan a + h gacha oraliqda yotishini bildiradi.', 'Запись x = a ± h означает, что точное значение лежит между a − h и a + h.', 'Writing x = a ± h means the exact value lies between a − h and a + h.'),
      L('To‘g‘ri yaxlitlashda absolyut xatolik yaxlitlanayotgan xona birligining yarmidan oshmaydi.', 'При правильном округлении абсолютная погрешность не больше половины единицы разряда.', 'Correct rounding gives an absolute error of at most half a unit of the rounding place.'),
      L('Beruniy Yer radiusini yarim foizdan kam nisbiy xatolik bilan o‘lchagan, al-Koshiy esa π ni 16 xona aniqlikda hisoblagan.', 'Бируни измерил радиус Земли с относительной погрешностью меньше полупроцента, а аль-Каши вычислил π с 16 знаками.', 'Al-Biruni measured the Earth’s radius with a relative error under half a percent, and al-Kashi computed π to 16 places.')
    ] }
  ] });

  // ---------- t12. Kvadrat tenglama. Chala kvadrat tenglamalar ----------
  T.add(P, 't12', { sections: [
    { kind: 'intro', h: L('Kvadrat bilan bog‘liq masala', 'Задача, связанная с квадратом', 'A problem about a square'), p: [
      L('Bog‘bon kvadrat shaklidagi gulzor yaratmoqchi. Uning yuzi 49 m<sup>2</sup> bo‘lishi kerak. Gulzorning tomoni necha metr? Tomonni x deb belgilasak, x<sup>2</sup> = 49 tenglama hosil bo‘ladi va javob x = 7 m. Endi masalani biroz murakkablashtiramiz: gulzor atrofida kengligi 1 m bo‘lgan yo‘lak qilinadi va gulzor bilan yo‘lakning umumiy yuzi 64 m<sup>2</sup> ga teng. Bu safar (x + 2)<sup>2</sup> = 64 tenglamaga kelamiz.',
        'Садовник хочет разбить квадратную клумбу площадью 49 м<sup>2</sup>. Какова сторона клумбы? Обозначив сторону через x, получим уравнение x<sup>2</sup> = 49 и ответ x = 7 м. Немного усложним задачу: вокруг клумбы делают дорожку шириной 1 м, и общая площадь клумбы с дорожкой равна 64 м<sup>2</sup>. Теперь получаем уравнение (x + 2)<sup>2</sup> = 64.',
        'A gardener wants a square flower bed with an area of 49 m<sup>2</sup>. How long is its side? Calling the side x, we get the equation x<sup>2</sup> = 49 and the answer x = 7 m. Now make it harder: a path 1 m wide is laid around the bed, and the bed together with the path covers 64 m<sup>2</sup>. This time we get the equation (x + 2)<sup>2</sup> = 64.'),
      L('Ikkala tenglamada ham noma’lum <b>kvadratda</b> qatnashmoqda. Bunday tenglamalar 7-sinfda o‘rganilgan chiziqli tenglamalardan farq qiladi: ularda noma’lumni oddiygina bir tomonga o‘tkazib, bo‘lib yuborish yetarli emas. Bundan tashqari, kvadrat tenglamaning ildizlari ikkita, bitta bo‘lishi yoki umuman bo‘lmasligi mumkin. Masalan, x<sup>2</sup> = 49 tenglamaning ildizlari 7 va −7, chunki (−7)<sup>2</sup> = 49 ham to‘g‘ri.',
        'В обоих уравнениях неизвестное стоит <b>в квадрате</b>. Такие уравнения отличаются от линейных, изученных в 7 классе: здесь недостаточно просто перенести неизвестное в одну сторону и разделить. Кроме того, у квадратного уравнения может быть два корня, один корень или ни одного. Например, у уравнения x<sup>2</sup> = 49 корни 7 и −7, ведь (−7)<sup>2</sup> = 49 тоже верно.',
        'In both equations the unknown appears <b>squared</b>. Such equations differ from the linear ones of Year 7: it is not enough just to move the unknown to one side and divide. Moreover, a quadratic equation may have two roots, one root or none at all. For example, x<sup>2</sup> = 49 has the roots 7 and −7, because (−7)<sup>2</sup> = 49 is also true.'),
      L('Kvadrat tenglamalar algebra fanining markazida turadi: ular fizikada (jismning tushishi), geometriyada (yuzalar), iqtisodda (foyda) va dasturlashda (kompyuter o‘yinlaridagi to‘qnashuvlar) uchraydi. Bu mavzuda kvadrat tenglamaning umumiy ko‘rinishini va eng sodda — <b>chala</b> kvadrat tenglamalarni yechishni o‘rganamiz.',
        'Квадратные уравнения стоят в центре алгебры: они встречаются в физике (падение тел), геометрии (площади), экономике (прибыль) и программировании (столкновения в компьютерных играх). В этой теме мы изучим общий вид квадратного уравнения и научимся решать самые простые — <b>неполные</b> квадратные уравнения.',
        'Quadratic equations sit at the heart of algebra: they appear in physics (falling bodies), geometry (areas), economics (profit) and programming (collisions in computer games). In this topic we study the general form of a quadratic equation and learn to solve the simplest ones — <b>incomplete</b> quadratic equations.')
    ] },
    { kind: 'def', h: L('Kvadrat tenglama ta’rifi', 'Определение квадратного уравнения', 'Definition of a quadratic equation'), p: [
      L('<b>Kvadrat tenglama</b> deb ax<sup>2</sup> + bx + c = 0 ko‘rinishidagi tenglamaga aytiladi, bu yerda x — noma’lum, a, b, c — berilgan sonlar va <b>a ≠ 0</b>. Sonlar quyidagicha ataladi:',
        '<b>Квадратным уравнением</b> называется уравнение вида ax<sup>2</sup> + bx + c = 0, где x — неизвестное, a, b, c — данные числа и <b>a ≠ 0</b>. Числа называются так:',
        'A <b>quadratic equation</b> is an equation of the form ax<sup>2</sup> + bx + c = 0, where x is the unknown, a, b, c are given numbers and <b>a ≠ 0</b>. The numbers are called:')
    ], list: [
      L('a — <b>birinchi</b> (bosh) koeffitsiyent, x<sup>2</sup> oldidagi son;', 'a — <b>первый</b> (старший) коэффициент, число перед x<sup>2</sup>;', 'a — the <b>leading</b> coefficient, the number in front of x<sup>2</sup>;'),
      L('b — <b>ikkinchi</b> koeffitsiyent, x oldidagi son;', 'b — <b>второй</b> коэффициент, число перед x;', 'b — the <b>second</b> coefficient, the number in front of x;'),
      L('c — <b>ozod had</b>, x qatnashmagan son.', 'c — <b>свободный член</b>, число без x.', 'c — the <b>constant term</b>, the number without x.')
    ], after: [
      L('Nega a ≠ 0? Agar a = 0 bo‘lsa, x<sup>2</sup> hadi yo‘qoladi va tenglama bx + c = 0 chiziqli tenglamaga aylanadi. Masalan, 3x<sup>2</sup> − 5x + 2 = 0 da a = 3, b = −5, c = 2. Ishoralarga e’tibor bering: b koeffitsiyent minus ishorasi bilan birga olinadi. x<sup>2</sup> − 9 = 0 da a = 1, b = 0, c = −9.',
        'Почему a ≠ 0? Если a = 0, член x<sup>2</sup> пропадает и уравнение превращается в линейное bx + c = 0. Например, в 3x<sup>2</sup> − 5x + 2 = 0 имеем a = 3, b = −5, c = 2. Обратите внимание на знаки: коэффициент b берётся вместе со знаком минус. В x<sup>2</sup> − 9 = 0: a = 1, b = 0, c = −9.',
        'Why a ≠ 0? If a = 0, the x<sup>2</sup> term vanishes and the equation becomes the linear equation bx + c = 0. For example, in 3x<sup>2</sup> − 5x + 2 = 0 we have a = 3, b = −5, c = 2. Watch the signs: b is taken together with its minus sign. In x<sup>2</sup> − 9 = 0: a = 1, b = 0, c = −9.'),
      L('Tenglamaning <b>ildizi</b> — uni to‘g‘ri tenglikka aylantiruvchi x qiymati. Tenglamani <b>yechish</b> — barcha ildizlarini topish yoki ildiz yo‘qligini isbotlash. Agar a = 1 bo‘lsa, tenglama <b>keltirilgan</b> deyiladi: x<sup>2</sup> + px + q = 0. Agar b yoki c (yoki ikkalasi) nolga teng bo‘lsa, tenglama <b>chala</b> kvadrat tenglama deyiladi; barcha koeffitsiyentlar noldan farqli bo‘lsa — <b>to‘la</b> kvadrat tenglama.',
        '<b>Корень</b> уравнения — значение x, обращающее его в верное равенство. <b>Решить</b> уравнение — найти все его корни или доказать, что их нет. Если a = 1, уравнение называют <b>приведённым</b>: x<sup>2</sup> + px + q = 0. Если b или c (или оба) равны нулю, уравнение называют <b>неполным</b> квадратным; если все коэффициенты отличны от нуля — <b>полным</b>.',
        'A <b>root</b> of the equation is a value of x that turns it into a true equality. To <b>solve</b> an equation means to find all its roots or prove that there are none. If a = 1 the equation is called <b>monic</b> (reduced): x<sup>2</sup> + px + q = 0. If b or c (or both) is zero, the equation is an <b>incomplete</b> quadratic; if all coefficients are non-zero, it is a <b>complete</b> quadratic.')
    ] },
    { kind: 'history', h: L('Tarixdan: Bobil loy taxtachalari', 'Из истории: вавилонские глиняные таблички', 'From history: Babylonian clay tablets'), p: [
      L('Kvadrat tenglamalarni odamlar 4000 yil oldin yecha olishgan. Miloddan avvalgi XVIII asrga oid Bobil loy taxtachalarida (ulardan biri bugun Britaniya muzeyida BM 13901 raqami ostida saqlanadi) quyidagicha masala bor: «Kvadrat yuzini uning tomoniga qo‘shdim, <sup>3</sup>/<sub>4</sub> chiqdi». Hozirgi tilda bu x<sup>2</sup> + x = <sup>3</sup>/<sub>4</sub> tenglamasi. Bobil mirzosi javobni — <sup>1</sup>/<sub>2</sub> ni — so‘zlar bilan yozilgan qadam-baqadam «retsept» orqali topgan.',
        'Квадратные уравнения люди умели решать 4000 лет назад. На вавилонских глиняных табличках XVIII века до н. э. (одна из них хранится в Британском музее под номером BM 13901) есть такая задача: «Я сложил площадь квадрата и его сторону — получилось <sup>3</sup>/<sub>4</sub>». На современном языке это уравнение x<sup>2</sup> + x = <sup>3</sup>/<sub>4</sub>. Вавилонский писец находил ответ — <sup>1</sup>/<sub>2</sub> — по пошаговому «рецепту», записанному словами.',
        'People could solve quadratic equations 4000 years ago. Babylonian clay tablets from the 18th century BC (one of them is kept in the British Museum as BM 13901) contain a problem like this: “I added the area of a square to its side and got <sup>3</sup>/<sub>4</sub>.” In modern language this is the equation x<sup>2</sup> + x = <sup>3</sup>/<sub>4</sub>. The Babylonian scribe found the answer, <sup>1</sup>/<sub>2</sub>, with a step-by-step “recipe” written in words.'),
      L('Bobilliklar harflar va formulalardan foydalanmagan, manfiy sonlarni ham bilishmagan. Shuning uchun ular faqat musbat ildizni topganlar — ular uchun bu yer maydonining tomoni yoki g‘ishtlar soni edi. Qadimgi yunonlar esa kvadrat tenglamalarni geometrik usulda — kvadrat va to‘g‘ri to‘rtburchaklarni qirqib, qayta yig‘ish yo‘li bilan yechishgan.',
        'Вавилоняне не пользовались буквами и формулами и не знали отрицательных чисел. Поэтому они находили только положительный корень — для них это была сторона участка или число кирпичей. Древние греки решали квадратные уравнения геометрически — разрезая и перекладывая квадраты и прямоугольники.',
        'The Babylonians did not use letters or formulas and did not know negative numbers. So they found only the positive root — for them it was the side of a field or a number of bricks. The ancient Greeks solved quadratic equations geometrically, by cutting and rearranging squares and rectangles.'),
      L('IX asrda Bag‘doddagi «Bayt ul-hikma»da ishlagan Muhammad ibn Muso al-Xorazmiy kvadrat tenglamalarni birinchi bo‘lib tizimli turlarga ajratdi. U, jumladan, «kvadratlar ildizlarga teng» (ax<sup>2</sup> = bx) va «kvadratlar songa teng» (ax<sup>2</sup> = c) kabi chala turlarni alohida ko‘rib chiqdi. Biz bugun o‘rganadigan chala tenglamalar aynan shu turlarga mos keladi.',
        'В IX веке Мухаммад ибн Муса аль-Хорезми, работавший в багдадском «Доме мудрости», впервые систематически разделил квадратные уравнения на виды. В частности, он отдельно рассмотрел неполные виды «квадраты равны корням» (ax<sup>2</sup> = bx) и «квадраты равны числу» (ax<sup>2</sup> = c). Неполные уравнения, которые мы изучаем сегодня, соответствуют именно этим видам.',
        'In the 9th century Muhammad ibn Musa al-Khwarizmi, who worked at the House of Wisdom in Baghdad, was the first to sort quadratic equations systematically into types. Among them he treated separately the incomplete types “squares equal roots” (ax<sup>2</sup> = bx) and “squares equal a number” (ax<sup>2</sup> = c). The incomplete equations we study today correspond exactly to these types.')
    ] },
    { kind: 'rule', h: L('Chala kvadrat tenglamalarning uch turi', 'Три вида неполных квадратных уравнений', 'The three kinds of incomplete quadratics'), p: [
      L('<b>1-tur: ax<sup>2</sup> = 0 (b = 0, c = 0).</b> a ≠ 0 bo‘lgani uchun ikkala tomonni a ga bo‘lamiz: x<sup>2</sup> = 0. Kvadrati nolga teng yagona son — nol. Demak, tenglama bitta ildizga ega: x = 0.',
        '<b>Вид 1: ax<sup>2</sup> = 0 (b = 0, c = 0).</b> Так как a ≠ 0, делим обе части на a: x<sup>2</sup> = 0. Единственное число с нулевым квадратом — ноль. Значит, уравнение имеет один корень: x = 0.',
        '<b>Type 1: ax<sup>2</sup> = 0 (b = 0, c = 0).</b> Since a ≠ 0, divide both sides by a: x<sup>2</sup> = 0. The only number whose square is zero is zero itself. So the equation has exactly one root: x = 0.'),
      L('<b>2-tur: ax<sup>2</sup> + bx = 0 (c = 0, b ≠ 0).</b> Umumiy ko‘paytuvchi x ni qavsdan chiqaramiz: x(ax + b) = 0. Ko‘paytma nolga teng bo‘lishi uchun ko‘paytuvchilardan kamida biri nolga teng bo‘lishi kerak. Demak, x = 0 yoki ax + b = 0, ya’ni x = −<sup>b</sup>/<sub>a</sub>. Bu tur doimo <b>ikki</b> ildizga ega va ulardan biri har doim 0.',
        '<b>Вид 2: ax<sup>2</sup> + bx = 0 (c = 0, b ≠ 0).</b> Выносим общий множитель x за скобки: x(ax + b) = 0. Произведение равно нулю, если хотя бы один из множителей равен нулю. Значит, x = 0 или ax + b = 0, то есть x = −<sup>b</sup>/<sub>a</sub>. Такое уравнение всегда имеет <b>два</b> корня, и один из них всегда 0.',
        '<b>Type 2: ax<sup>2</sup> + bx = 0 (c = 0, b ≠ 0).</b> Take out the common factor x: x(ax + b) = 0. A product is zero when at least one factor is zero. So x = 0 or ax + b = 0, i.e. x = −<sup>b</sup>/<sub>a</sub>. This type always has <b>two</b> roots, and one of them is always 0.'),
      L('<b>3-tur: ax<sup>2</sup> + c = 0 (b = 0, c ≠ 0).</b> c ni o‘ng tomonga o‘tkazib, a ga bo‘lamiz: x<sup>2</sup> = −<sup>c</sup>/<sub>a</sub>. Agar −<sup>c</sup>/<sub>a</sub> &gt; 0 bo‘lsa, ikki ildiz bor: x = ±√(−<sup>c</sup>/<sub>a</sub>). Agar −<sup>c</sup>/<sub>a</sub> &lt; 0 bo‘lsa, ildiz yo‘q, chunki hech bir haqiqiy sonning kvadrati manfiy emas. (−<sup>c</sup>/<sub>a</sub> = 0 holati bo‘lmaydi, chunki c ≠ 0.)',
        '<b>Вид 3: ax<sup>2</sup> + c = 0 (b = 0, c ≠ 0).</b> Переносим c вправо и делим на a: x<sup>2</sup> = −<sup>c</sup>/<sub>a</sub>. Если −<sup>c</sup>/<sub>a</sub> &gt; 0, корней два: x = ±√(−<sup>c</sup>/<sub>a</sub>). Если −<sup>c</sup>/<sub>a</sub> &lt; 0, корней нет, так как квадрат действительного числа не бывает отрицательным. (Случай −<sup>c</sup>/<sub>a</sub> = 0 невозможен, ведь c ≠ 0.)',
        '<b>Type 3: ax<sup>2</sup> + c = 0 (b = 0, c ≠ 0).</b> Move c to the right and divide by a: x<sup>2</sup> = −<sup>c</sup>/<sub>a</sub>. If −<sup>c</sup>/<sub>a</sub> &gt; 0 there are two roots: x = ±√(−<sup>c</sup>/<sub>a</sub>). If −<sup>c</sup>/<sub>a</sub> &lt; 0 there are no roots, because the square of a real number is never negative. (The case −<sup>c</sup>/<sub>a</sub> = 0 cannot happen, since c ≠ 0.)')
    ] },
    { kind: 'steps', h: L('Chala tenglamani yechish tartibi', 'Порядок решения неполного уравнения', 'How to solve an incomplete quadratic'), list: [
      L('<b>1.</b> Tenglamani ax<sup>2</sup> + bx + c = 0 ko‘rinishiga keltiring: barcha hadlarni chap tomonga o‘tkazing, qavslarni oching, o‘xshash hadlarni ixchamlang.', '<b>1.</b> Приведите уравнение к виду ax<sup>2</sup> + bx + c = 0: перенесите все члены влево, раскройте скобки, приведите подобные.', '<b>1.</b> Bring the equation to the form ax<sup>2</sup> + bx + c = 0: move everything to the left, expand brackets, collect like terms.'),
      L('<b>2.</b> Koeffitsiyentlarni yozib oling va qaysi biri nolga tengligini aniqlang — shunga qarab tur tanlanadi.', '<b>2.</b> Выпишите коэффициенты и определите, какой из них равен нулю, — от этого зависит вид.', '<b>2.</b> Write down the coefficients and see which of them is zero — this tells you the type.'),
      L('<b>3.</b> c = 0 bo‘lsa — x ni qavsdan chiqaring va har bir ko‘paytuvchini nolga tenglang.', '<b>3.</b> Если c = 0 — вынесите x за скобки и приравняйте каждый множитель к нулю.', '<b>3.</b> If c = 0 — factor out x and set each factor equal to zero.'),
      L('<b>4.</b> b = 0 bo‘lsa — x<sup>2</sup> ni yolg‘iz qoldiring va o‘ng tomonning ishorasini tekshiring: musbat bo‘lsa ± ildiz chiqaring, manfiy bo‘lsa «ildiz yo‘q» deb yozing.', '<b>4.</b> Если b = 0 — уедините x<sup>2</sup> и проверьте знак правой части: если она положительна, извлеките корень со знаком ±, если отрицательна — запишите «корней нет».', '<b>4.</b> If b = 0 — isolate x<sup>2</sup> and check the sign of the right-hand side: if positive, take the square root with ±; if negative, write “no roots”.'),
      L('<b>5.</b> Topilgan ildizlarni dastlabki tenglamaga qo‘yib tekshiring va javobni yozing.', '<b>5.</b> Проверьте корни подстановкой в исходное уравнение и запишите ответ.', '<b>5.</b> Check the roots by substituting them into the original equation and write the answer.')
    ], after: [
      L('Eslatma: ax<sup>2</sup> + bx = 0 tenglamani hech qachon x ga bo‘lmang! Bo‘lish faqat bo‘luvchi nolga teng emasligi aniq bo‘lsagina mumkin, x esa aynan 0 bo‘lishi mumkin. Bo‘lsangiz, x = 0 ildizi yo‘qoladi.', 'Помните: уравнение ax<sup>2</sup> + bx = 0 нельзя делить на x! Делить можно, только если делитель заведомо не равен нулю, а x как раз может равняться 0. Разделив, вы потеряете корень x = 0.', 'Remember: never divide ax<sup>2</sup> + bx = 0 by x! You may divide only by something known to be non-zero, and x may well be 0. If you divide, you lose the root x = 0.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('2x<sup>2</sup> − 6x = 0 tenglamani yeching.', 'Решите уравнение 2x<sup>2</sup> − 6x = 0.', 'Solve 2x<sup>2</sup> − 6x = 0.'), s: L('c = 0. Qavsdan chiqaramiz: 2x(x − 3) = 0. Demak, x = 0 yoki x − 3 = 0, ya’ni x = 3. Tekshirish: 2 · 9 − 18 = 0 ✓. Javob: 0; 3.', 'c = 0. Выносим за скобки: 2x(x − 3) = 0. Значит, x = 0 или x − 3 = 0, то есть x = 3. Проверка: 2 · 9 − 18 = 0 ✓. Ответ: 0; 3.', 'Here c = 0. Factor: 2x(x − 3) = 0. So x = 0 or x − 3 = 0, i.e. x = 3. Check: 2 · 9 − 18 = 0 ✓. Answer: 0; 3.') },
      { q: L('3x<sup>2</sup> − 48 = 0 tenglamani yeching.', 'Решите уравнение 3x<sup>2</sup> − 48 = 0.', 'Solve 3x<sup>2</sup> − 48 = 0.'), s: L('b = 0. 3x<sup>2</sup> = 48, x<sup>2</sup> = 16, x = ±4. Tekshirish: 3 · 16 − 48 = 0 ✓. Javob: −4; 4.', 'b = 0. 3x<sup>2</sup> = 48, x<sup>2</sup> = 16, x = ±4. Проверка: 3 · 16 − 48 = 0 ✓. Ответ: −4; 4.', 'Here b = 0. 3x<sup>2</sup> = 48, x<sup>2</sup> = 16, x = ±4. Check: 3 · 16 − 48 = 0 ✓. Answer: −4; 4.') },
      { q: L('5x<sup>2</sup> + 20 = 0 tenglamani yeching.', 'Решите уравнение 5x<sup>2</sup> + 20 = 0.', 'Solve 5x<sup>2</sup> + 20 = 0.'), s: L('5x<sup>2</sup> = −20, x<sup>2</sup> = −4. Hech bir sonning kvadrati manfiy emas, shuning uchun tenglama ildizga ega emas. Javob: ildiz yo‘q.', '5x<sup>2</sup> = −20, x<sup>2</sup> = −4. Квадрат числа не бывает отрицательным, поэтому уравнение корней не имеет. Ответ: корней нет.', '5x<sup>2</sup> = −20, x<sup>2</sup> = −4. No square is negative, so the equation has no roots. Answer: no roots.') },
      { q: L('(x + 2)<sup>2</sup> = 64 tenglamani yeching (kirishdagi gulzor masalasi).', 'Решите уравнение (x + 2)<sup>2</sup> = 64 (задача о клумбе из введения).', 'Solve (x + 2)<sup>2</sup> = 64 (the flower-bed problem from the introduction).'), s: L('Qavsni ochmasdan yechish qulay: x + 2 = 8 yoki x + 2 = −8. Bundan x = 6 yoki x = −10. Tomon uzunligi musbat, shuning uchun gulzor tomoni 6 m. Tekshirish: (6 + 2)<sup>2</sup> = 64 ✓.', 'Удобно решать без раскрытия скобок: x + 2 = 8 или x + 2 = −8. Отсюда x = 6 или x = −10. Длина стороны положительна, поэтому сторона клумбы 6 м. Проверка: (6 + 2)<sup>2</sup> = 64 ✓.', 'It is easiest not to expand: x + 2 = 8 or x + 2 = −8. So x = 6 or x = −10. A side length is positive, so the bed has side 6 m. Check: (6 + 2)<sup>2</sup> = 64 ✓.') },
      { q: L('(x − 1)(x + 1) = 2x<sup>2</sup> − 10 tenglamani yeching.', 'Решите уравнение (x − 1)(x + 1) = 2x<sup>2</sup> − 10.', 'Solve (x − 1)(x + 1) = 2x<sup>2</sup> − 10.'), s: L('Chap tomon: x<sup>2</sup> − 1. Tenglama: x<sup>2</sup> − 1 = 2x<sup>2</sup> − 10, ya’ni −x<sup>2</sup> + 9 = 0, x<sup>2</sup> = 9, x = ±3. Bu — 3-turdagi chala tenglama, faqat avval uni standart ko‘rinishga keltirish kerak edi. Javob: −3; 3.', 'Левая часть: x<sup>2</sup> − 1. Уравнение: x<sup>2</sup> − 1 = 2x<sup>2</sup> − 10, то есть −x<sup>2</sup> + 9 = 0, x<sup>2</sup> = 9, x = ±3. Это неполное уравнение 3-го вида — просто сначала его нужно было привести к стандартному виду. Ответ: −3; 3.', 'The left side is x<sup>2</sup> − 1. So x<sup>2</sup> − 1 = 2x<sup>2</sup> − 10, i.e. −x<sup>2</sup> + 9 = 0, x<sup>2</sup> = 9, x = ±3. This is a type-3 incomplete equation; it just had to be brought to standard form first. Answer: −3; 3.') }
    ] },
    { kind: 'table', h: L('Chala tenglamalar jadvali', 'Таблица неполных уравнений', 'Table of incomplete quadratics'), table: { head: [L('Ko‘rinish', 'Вид', 'Form'), L('Shart', 'Условие', 'Condition'), L('Yechim', 'Решение', 'Solution'), L('Ildizlar soni', 'Число корней', 'Number of roots')], rows: [
      [L('ax<sup>2</sup> = 0', 'ax<sup>2</sup> = 0', 'ax<sup>2</sup> = 0'), L('b = c = 0', 'b = c = 0', 'b = c = 0'), L('x = 0', 'x = 0', 'x = 0'), L('bitta', 'один', 'one')],
      [L('ax<sup>2</sup> + bx = 0', 'ax<sup>2</sup> + bx = 0', 'ax<sup>2</sup> + bx = 0'), L('c = 0, b ≠ 0', 'c = 0, b ≠ 0', 'c = 0, b ≠ 0'), L('x = 0; x = −b/a', 'x = 0; x = −b/a', 'x = 0; x = −b/a'), L('ikkita', 'два', 'two')],
      [L('ax<sup>2</sup> + c = 0', 'ax<sup>2</sup> + c = 0', 'ax<sup>2</sup> + c = 0'), L('−c/a &gt; 0', '−c/a &gt; 0', '−c/a &gt; 0'), L('x = ±√(−c/a)', 'x = ±√(−c/a)', 'x = ±√(−c/a)'), L('ikkita', 'два', 'two')],
      [L('ax<sup>2</sup> + c = 0', 'ax<sup>2</sup> + c = 0', 'ax<sup>2</sup> + c = 0'), L('−c/a &lt; 0', '−c/a &lt; 0', '−c/a &lt; 0'), L('—', '—', '—'), L('ildiz yo‘q', 'нет корней', 'none')]
    ] }, after: [
      L('Jadvaldan ko‘rinib turibdiki, ax<sup>2</sup> + c = 0 da a va c ning ishoralari hal qiluvchi: agar ular har xil ishorali bo‘lsa, ikki ildiz bor; bir xil ishorali bo‘lsa, ildiz yo‘q. Masalan, 4x<sup>2</sup> − 1 = 0 ning ildizlari ±<sup>1</sup>/<sub>2</sub>, 4x<sup>2</sup> + 1 = 0 esa ildizga ega emas.', 'Из таблицы видно, что в ax<sup>2</sup> + c = 0 решают знаки a и c: если они разные, корней два; если одинаковые — корней нет. Например, у 4x<sup>2</sup> − 1 = 0 корни ±<sup>1</sup>/<sub>2</sub>, а 4x<sup>2</sup> + 1 = 0 корней не имеет.', 'The table shows that in ax<sup>2</sup> + c = 0 the signs of a and c decide everything: if they differ, there are two roots; if they are the same, there are none. For example, 4x<sup>2</sup> − 1 = 0 has roots ±<sup>1</sup>/<sub>2</sub>, while 4x<sup>2</sup> + 1 = 0 has no roots.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>x ga bo‘lib, ildizni yo‘qotish.</b> x<sup>2</sup> = 5x dan «x = 5» deb yozish xato. To‘g‘ri: x<sup>2</sup> − 5x = 0, x(x − 5) = 0, x = 0 yoki x = 5.', '<b>Деление на x и потеря корня.</b> Из x<sup>2</sup> = 5x писать «x = 5» неверно. Правильно: x<sup>2</sup> − 5x = 0, x(x − 5) = 0, x = 0 или x = 5.', '<b>Dividing by x and losing a root.</b> Writing “x = 5” from x<sup>2</sup> = 5x is wrong. Correct: x<sup>2</sup> − 5x = 0, x(x − 5) = 0, x = 0 or x = 5.'),
      L('<b>Manfiy ildizni unutish.</b> x<sup>2</sup> = 9 ning ildizlari 3 va −3. Faqat 3 deb yozish — yarim javob.', '<b>Забыть отрицательный корень.</b> У x<sup>2</sup> = 9 корни 3 и −3. Написать только 3 — значит дать половину ответа.', '<b>Forgetting the negative root.</b> x<sup>2</sup> = 9 has roots 3 and −3. Writing only 3 is half an answer.'),
      L('<b>Manfiy sondan ildiz chiqarish.</b> x<sup>2</sup> = −4 dan «x = ±2» deb yozish xato: (±2)<sup>2</sup> = 4, −4 emas. Ildiz yo‘q.', '<b>Извлечь корень из отрицательного числа.</b> Из x<sup>2</sup> = −4 писать «x = ±2» нельзя: (±2)<sup>2</sup> = 4, а не −4. Корней нет.', '<b>Taking the root of a negative number.</b> From x<sup>2</sup> = −4 you cannot write “x = ±2”: (±2)<sup>2</sup> = 4, not −4. There are no roots.'),
      L('<b>Koeffitsiyent ishorasini yo‘qotish.</b> x<sup>2</sup> − 7x = 0 da b = −7, 7 emas. Ishorani har doim had bilan birga oling.', '<b>Потерять знак коэффициента.</b> В x<sup>2</sup> − 7x = 0 коэффициент b = −7, а не 7. Всегда берите знак вместе с членом.', '<b>Losing the sign of a coefficient.</b> In x<sup>2</sup> − 7x = 0, b = −7, not 7. Always take the sign together with the term.'),
      L('<b>Standart ko‘rinishga keltirmaslik.</b> 3x<sup>2</sup> = 2x<sup>2</sup> + 25 da a = 3 deb olish xato; avval x<sup>2</sup> = 25 ga keltiring.', '<b>Не привести к стандартному виду.</b> В 3x<sup>2</sup> = 2x<sup>2</sup> + 25 нельзя считать a = 3; сначала приведите к x<sup>2</sup> = 25.', '<b>Not reaching standard form.</b> In 3x<sup>2</sup> = 2x<sup>2</sup> + 25 it is wrong to take a = 3; first simplify to x<sup>2</sup> = 25.')
    ] },
    { kind: 'life', h: L('Hayotda chala kvadrat tenglamalar', 'Неполные квадратные уравнения в жизни', 'Incomplete quadratics in real life'), p: [
      L('<b>Erkin tushish.</b> Havo qarshiligi hisobga olinmasa, jism t sekundda taxminan h = 5t<sup>2</sup> metr tushadi. Agar tosh 45 m balandlikdagi ko‘prikdan tashlansa, 5t<sup>2</sup> = 45, t<sup>2</sup> = 9, t = 3 s. Manfiy ildiz t = −3 vaqt uchun ma’noga ega emas.', '<b>Свободное падение.</b> Без учёта сопротивления воздуха тело за t секунд пролетает примерно h = 5t<sup>2</sup> метров. Если камень бросили с моста высотой 45 м, то 5t<sup>2</sup> = 45, t<sup>2</sup> = 9, t = 3 с. Отрицательный корень t = −3 для времени смысла не имеет.', '<b>Free fall.</b> Ignoring air resistance, a body falls about h = 5t<sup>2</sup> metres in t seconds. If a stone is dropped from a bridge 45 m high, then 5t<sup>2</sup> = 45, t<sup>2</sup> = 9, t = 3 s. The negative root t = −3 makes no sense for time.'),
      L('<b>Yuza va o‘lcham.</b> Kvadrat xona polining yuzi 20,25 m<sup>2</sup> bo‘lsa, uning tomoni √20,25 = 4,5 m. Doira shaklidagi hovuz yuzi 314 m<sup>2</sup> bo‘lsa, πr<sup>2</sup> = 314 dan r<sup>2</sup> ≈ 100, r ≈ 10 m. Duradgor, quruvchi va dizaynerlar bunday hisoblarni har kuni bajaradi.', '<b>Площадь и размер.</b> Если площадь пола квадратной комнаты 20,25 м<sup>2</sup>, её сторона √20,25 = 4,5 м. Если площадь круглого бассейна 314 м<sup>2</sup>, то из πr<sup>2</sup> = 314 получаем r<sup>2</sup> ≈ 100, r ≈ 10 м. Плотники, строители и дизайнеры выполняют такие расчёты каждый день.', '<b>Area and size.</b> If a square room has a floor area of 20.25 m<sup>2</sup>, its side is √20.25 = 4.5 m. If a round pool has an area of 314 m<sup>2</sup>, then πr<sup>2</sup> = 314 gives r<sup>2</sup> ≈ 100, r ≈ 10 m. Carpenters, builders and designers do such sums every day.'),
      L('<b>To‘p parvozi.</b> Yerdan otilgan to‘pning balandligi h = 20t − 5t<sup>2</sup> formulasi bilan berilsa, to‘p qachon yerga tushishini bilish uchun 20t − 5t<sup>2</sup> = 0 ni yechamiz: 5t(4 − t) = 0, t = 0 (otilgan payt) yoki t = 4 s (qo‘ngan payt). Bu 2-turdagi chala tenglama!', '<b>Полёт мяча.</b> Если высота мяча, подброшенного с земли, задаётся формулой h = 20t − 5t<sup>2</sup>, то чтобы узнать, когда он упадёт, решаем 20t − 5t<sup>2</sup> = 0: 5t(4 − t) = 0, t = 0 (момент броска) или t = 4 с (момент падения). Это неполное уравнение 2-го вида!', '<b>A ball in flight.</b> If the height of a ball kicked from the ground is h = 20t − 5t<sup>2</sup>, then to find when it lands we solve 20t − 5t<sup>2</sup> = 0: 5t(4 − t) = 0, t = 0 (the kick) or t = 4 s (the landing). That is a type-2 incomplete quadratic!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('«Kvadrat tenglama» nomi x<sup>2</sup> hadidan kelib chiqqan: x<sup>2</sup> — tomoni x bo‘lgan kvadratning yuzi. Lotin tilida quadratus — «kvadrat» degani.', 'Название «квадратное уравнение» происходит от члена x<sup>2</sup>: x<sup>2</sup> — площадь квадрата со стороной x. По-латыни quadratus — «квадрат».', 'The name “quadratic” comes from the x<sup>2</sup> term: x<sup>2</sup> is the area of a square with side x. In Latin, quadratus means “square”.'),
      L('Bobil mirzolari 60 lik sanoq tizimida hisoblagan. Bizning soatdagi 60 daqiqa va aylanadagi 360 gradus — o‘sha davrdan qolgan meros.', 'Вавилонские писцы считали в шестидесятеричной системе. 60 минут в часе и 360 градусов в окружности — наследие той эпохи.', 'Babylonian scribes counted in base 60. The 60 minutes in an hour and 360 degrees in a circle are a legacy of that era.'),
      L('al-Xorazmiy kitobi nomidagi «al-jabr» so‘zidan «algebra» atamasi kelib chiqqan, uning ismi esa «algoritm» so‘ziga aylangan.', 'От слова «аль-джабр» в названии книги аль-Хорезми произошёл термин «алгебра», а его имя превратилось в слово «алгоритм».', 'The word “algebra” comes from “al-jabr” in the title of al-Khwarizmi’s book, and his name became the word “algorithm”.'),
      L('Har qanday chala kvadrat tenglamani ham, keyingi mavzudagi umumiy formula bilan ham yechish mumkin — lekin chala tenglamalar uchun maxsus usul ancha tezroq.', 'Любое неполное квадратное уравнение можно решить и общей формулой из следующей темы — но специальный способ для неполных уравнений гораздо быстрее.', 'Any incomplete quadratic can also be solved with the general formula from the next topic — but the special method for incomplete equations is much faster.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), ex: [
      { q: L('x<sup>2</sup> − 16 = 0', 'x<sup>2</sup> − 16 = 0', 'x<sup>2</sup> − 16 = 0'), s: L('x<sup>2</sup> = 16, x = ±4.', 'x<sup>2</sup> = 16, x = ±4.', 'x<sup>2</sup> = 16, x = ±4.') },
      { q: L('7x<sup>2</sup> + 14x = 0', '7x<sup>2</sup> + 14x = 0', '7x<sup>2</sup> + 14x = 0'), s: L('7x(x + 2) = 0, x = 0 yoki x = −2.', '7x(x + 2) = 0, x = 0 или x = −2.', '7x(x + 2) = 0, x = 0 or x = −2.') },
      { q: L('x<sup>2</sup> + 9 = 0', 'x<sup>2</sup> + 9 = 0', 'x<sup>2</sup> + 9 = 0'), s: L('x<sup>2</sup> = −9 &lt; 0 — ildiz yo‘q.', 'x<sup>2</sup> = −9 &lt; 0 — корней нет.', 'x<sup>2</sup> = −9 &lt; 0 — no roots.') },
      { q: L('Qanday k da kx<sup>2</sup> − 8 = 0 tenglama ±2 ildizlarga ega?', 'При каком k уравнение kx<sup>2</sup> − 8 = 0 имеет корни ±2?', 'For which k does kx<sup>2</sup> − 8 = 0 have roots ±2?'), s: L('x = 2 ni qo‘yamiz: 4k − 8 = 0, k = 2.', 'Подставим x = 2: 4k − 8 = 0, k = 2.', 'Substitute x = 2: 4k − 8 = 0, so k = 2.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Kvadrat tenglama: ax<sup>2</sup> + bx + c = 0, bunda a ≠ 0; a — bosh koeffitsiyent, b — ikkinchi koeffitsiyent, c — ozod had.', 'Квадратное уравнение: ax<sup>2</sup> + bx + c = 0, где a ≠ 0; a — старший коэффициент, b — второй, c — свободный член.', 'A quadratic equation is ax<sup>2</sup> + bx + c = 0 with a ≠ 0; a is the leading coefficient, b the second, c the constant term.'),
      L('b yoki c nolga teng bo‘lsa, tenglama chala deyiladi.', 'Если b или c равно нулю, уравнение называется неполным.', 'If b or c is zero, the equation is called incomplete.'),
      L('ax<sup>2</sup> = 0 ⇒ x = 0 (bitta ildiz).', 'ax<sup>2</sup> = 0 ⇒ x = 0 (один корень).', 'ax<sup>2</sup> = 0 ⇒ x = 0 (one root).'),
      L('ax<sup>2</sup> + bx = 0 ⇒ x(ax + b) = 0 ⇒ x = 0 yoki x = −b/a. Hech qachon x ga bo‘lmang!', 'ax<sup>2</sup> + bx = 0 ⇒ x(ax + b) = 0 ⇒ x = 0 или x = −b/a. Никогда не делите на x!', 'ax<sup>2</sup> + bx = 0 ⇒ x(ax + b) = 0 ⇒ x = 0 or x = −b/a. Never divide by x!'),
      L('ax<sup>2</sup> + c = 0 ⇒ x<sup>2</sup> = −c/a: musbat bo‘lsa x = ±√(−c/a), manfiy bo‘lsa ildiz yo‘q.', 'ax<sup>2</sup> + c = 0 ⇒ x<sup>2</sup> = −c/a: если положительно — x = ±√(−c/a), если отрицательно — корней нет.', 'ax<sup>2</sup> + c = 0 ⇒ x<sup>2</sup> = −c/a: if positive, x = ±√(−c/a); if negative, no roots.'),
      L('Kvadrat tenglamalarni Bobilda 4000 yil oldin yechishgan; al-Xorazmiy ularni birinchi bo‘lib tizimli turlarga ajratgan.', 'Квадратные уравнения решали в Вавилоне 4000 лет назад; аль-Хорезми первым систематически разделил их на виды.', 'Quadratics were solved in Babylon 4000 years ago; al-Khwarizmi was the first to sort them systematically into types.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t13. Kvadrat tenglama ildizlari formulasi. Diskriminant ----------
  T.add(P, 't13', { sections: [
    { kind: 'intro', h: L('Har qanday kvadrat tenglama uchun bitta kalit', 'Один ключ для любого квадратного уравнения', 'One key for every quadratic'), p: [
      L('Oldingi mavzuda chala kvadrat tenglamalarni yechdik: qavsdan chiqarish yoki kvadrat ildiz olish yetarli edi. Ammo x<sup>2</sup> − 5x + 6 = 0 yoki 2x<sup>2</sup> + 3x − 2 = 0 kabi to‘la tenglamalarda bu usullar ishlamaydi: x ni qavsdan chiqarib bo‘lmaydi, x<sup>2</sup> ni ham yolg‘iz qoldirib bo‘lmaydi.',
        'В прошлой теме мы решали неполные квадратные уравнения: хватало вынесения за скобки или извлечения корня. Но для полных уравнений вроде x<sup>2</sup> − 5x + 6 = 0 или 2x<sup>2</sup> + 3x − 2 = 0 эти приёмы не работают: x не вынести за скобки, x<sup>2</sup> не уединить.',
        'In the previous topic we solved incomplete quadratics: factoring out x or taking a square root was enough. But for complete equations such as x<sup>2</sup> − 5x + 6 = 0 or 2x<sup>2</sup> + 3x − 2 = 0 these tricks fail: x cannot be factored out and x<sup>2</sup> cannot be isolated.'),
      L('Bu mavzuda <b>har qanday</b> kvadrat tenglamani yechadigan universal formulani keltirib chiqaramiz. U ildizlarni a, b, c koeffitsiyentlar orqali to‘g‘ridan-to‘g‘ri ifodalaydi. Bundan tashqari, ildizlarni hisoblamasdan turib ham ularning nechta ekanini aytib beradigan maxsus son — <b>diskriminant</b> bilan tanishamiz.',
        'В этой теме мы выведем универсальную формулу, которая решает <b>любое</b> квадратное уравнение. Она выражает корни прямо через коэффициенты a, b, c. Кроме того, мы познакомимся с особым числом — <b>дискриминантом</b>, которое ещё до вычисления корней говорит, сколько их.',
        'In this topic we derive a universal formula that solves <b>any</b> quadratic equation. It expresses the roots directly in terms of the coefficients a, b, c. We also meet a special number — the <b>discriminant</b> — which tells us how many roots there are before we even compute them.'),
      L('Formulaning g‘oyasi oddiy va chiroyli: tenglamaning chap tomonini <b>to‘la kvadrat</b> ko‘rinishiga keltiramiz, shunda u chala tenglamaning 3-turiga — (x + m)<sup>2</sup> = n ga aylanadi, buni esa biz yecha olamiz. Bu usulni «to‘la kvadrat ajratish» deyiladi va uni ming yildan ko‘proq vaqt oldin al-Xorazmiy geometrik tarzda tasvirlagan.',
        'Идея формулы проста и красива: левую часть уравнения приводим к виду <b>полного квадрата</b>, и тогда оно превращается в уравнение вида (x + m)<sup>2</sup> = n, которое мы решать умеем. Этот приём называется «выделение полного квадрата», и более тысячи лет назад его геометрически описал аль-Хорезми.',
        'The idea behind the formula is simple and beautiful: turn the left-hand side into a <b>perfect square</b>, so that the equation becomes (x + m)<sup>2</sup> = n, which we already know how to solve. This method is called “completing the square”, and al-Khwarizmi described it geometrically more than a thousand years ago.')
    ] },
    { kind: 'def', h: L('Diskriminant', 'Дискриминант', 'The discriminant'), p: [
      L('ax<sup>2</sup> + bx + c = 0 kvadrat tenglamaning <b>diskriminanti</b> deb D = b<sup>2</sup> − 4ac soniga aytiladi. «Diskriminant» so‘zi lotincha discriminare — «ajratmoq, farqlamoq» so‘zidan olingan: bu son ildizi bor tenglamalarni ildizi yo‘qlaridan ajratib beradi.',
        '<b>Дискриминантом</b> квадратного уравнения ax<sup>2</sup> + bx + c = 0 называется число D = b<sup>2</sup> − 4ac. Слово «дискриминант» происходит от латинского discriminare — «различать, разделять»: это число отделяет уравнения, имеющие корни, от уравнений без корней.',
        'The <b>discriminant</b> of the quadratic equation ax<sup>2</sup> + bx + c = 0 is the number D = b<sup>2</sup> − 4ac. The word comes from the Latin discriminare, “to distinguish, to separate”: this number separates equations that have roots from those that do not.'),
      L('Masalan, x<sup>2</sup> − 5x + 6 = 0 uchun a = 1, b = −5, c = 6, demak, D = (−5)<sup>2</sup> − 4 · 1 · 6 = 25 − 24 = 1. 2x<sup>2</sup> + 3x + 4 = 0 uchun D = 9 − 32 = −23. x<sup>2</sup> − 6x + 9 = 0 uchun D = 36 − 36 = 0. Diskriminantni hisoblashda b manfiy bo‘lsa ham b<sup>2</sup> doimo musbat ekanini unutmang, ya’ni (−5)<sup>2</sup> = 25.',
        'Например, для x<sup>2</sup> − 5x + 6 = 0 имеем a = 1, b = −5, c = 6, значит, D = (−5)<sup>2</sup> − 4 · 1 · 6 = 25 − 24 = 1. Для 2x<sup>2</sup> + 3x + 4 = 0: D = 9 − 32 = −23. Для x<sup>2</sup> − 6x + 9 = 0: D = 36 − 36 = 0. Помните, что даже при отрицательном b величина b<sup>2</sup> неотрицательна: (−5)<sup>2</sup> = 25.',
        'For example, for x<sup>2</sup> − 5x + 6 = 0 we have a = 1, b = −5, c = 6, so D = (−5)<sup>2</sup> − 4 · 1 · 6 = 25 − 24 = 1. For 2x<sup>2</sup> + 3x + 4 = 0, D = 9 − 32 = −23. For x<sup>2</sup> − 6x + 9 = 0, D = 36 − 36 = 0. Remember that even when b is negative, b<sup>2</sup> is not: (−5)<sup>2</sup> = 25.')
    ], list: [
      L('D &gt; 0 — tenglama <b>ikkita</b> turli haqiqiy ildizga ega;', 'D &gt; 0 — уравнение имеет <b>два</b> различных действительных корня;', 'D &gt; 0 — the equation has <b>two</b> different real roots;'),
      L('D = 0 — <b>bitta</b> ildiz (ba’zan «ikkita teng ildiz» deyiladi);', 'D = 0 — <b>один</b> корень (иногда говорят «два равных корня»);', 'D = 0 — <b>one</b> root (sometimes called “two equal roots”);'),
      L('D &lt; 0 — haqiqiy ildizlar <b>yo‘q</b>.', 'D &lt; 0 — действительных корней <b>нет</b>.', 'D &lt; 0 — there are <b>no</b> real roots.')
    ] },
    { kind: 'history', h: L('Tarixdan: al-Xorazmiy va Brahmagupta', 'Из истории: аль-Хорезми и Брахмагупта', 'From history: al-Khwarizmi and Brahmagupta'), p: [
      L('VII asrda hind matematigi Brahmagupta 628-yilda yozgan «Brahmasphutasiddhanta» asarida kvadrat tenglamaning ildizini topish qoidasini so‘zlar bilan bayon qildi. Bu qoida hozirgi formulaga juda yaqin edi. Brahmagupta manfiy sonlar va nol bilan amallar qoidalarini ham birinchilardan bo‘lib aniq yozgan, shuning uchun u manfiy ildizlarni ham qabul qila olgan.',
        'В VII веке индийский математик Брахмагупта в труде «Брахмаспхута-сиддханта» (628 год) словами описал правило нахождения корня квадратного уравнения. Это правило было очень близко к современной формуле. Брахмагупта одним из первых чётко сформулировал правила действий с отрицательными числами и нулём, поэтому мог признавать и отрицательные корни.',
        'In the 7th century the Indian mathematician Brahmagupta, in his work “Brahmasphutasiddhanta” (628), described in words a rule for finding the root of a quadratic equation. The rule was very close to the modern formula. Brahmagupta was also among the first to state clearly the rules for working with negative numbers and zero, so he could accept negative roots as well.'),
      L('IX asrda Muhammad al-Xorazmiy «Al-kitob al-muxtasar fi hisob al-jabr va-l-muqobala» kitobida x<sup>2</sup> + 10x = 39 misolini geometrik yo‘l bilan yechgan. U tomoni x bo‘lgan kvadratga ikki tomonidan kengligi 5 bo‘lgan to‘g‘ri to‘rtburchaklarni qo‘shdi, so‘ng burchakdagi bo‘sh joyni 5 · 5 = 25 yuzali kichik kvadrat bilan to‘ldirdi. Natijada katta kvadrat hosil bo‘ldi: (x + 5)<sup>2</sup> = 39 + 25 = 64. Demak, x + 5 = 8 va x = 3. «To‘la kvadrat ajratish» degan nom aynan shu rasmdan kelib chiqqan — kvadratni tom ma’noda «to‘ldiramiz».',
        'В IX веке Мухаммад аль-Хорезми в «Краткой книге об исчислении аль-джабра и аль-мукабалы» решил пример x<sup>2</sup> + 10x = 39 геометрически. К квадрату со стороной x он приложил с двух сторон прямоугольники шириной 5, а затем заполнил пустой угол маленьким квадратом площадью 5 · 5 = 25. Получился большой квадрат: (x + 5)<sup>2</sup> = 39 + 25 = 64. Значит, x + 5 = 8 и x = 3. Название «выделение полного квадрата» пошло именно от этого рисунка — квадрат в буквальном смысле «дополняют».',
        'In the 9th century Muhammad al-Khwarizmi, in “The Compendious Book on Calculation by Completion and Balancing”, solved x<sup>2</sup> + 10x = 39 geometrically. To a square of side x he attached rectangles of width 5 on two sides, then filled the empty corner with a small square of area 5 · 5 = 25. The result was a big square: (x + 5)<sup>2</sup> = 39 + 25 = 64. So x + 5 = 8 and x = 3. The name “completing the square” comes from exactly this picture — the square is literally completed.'),
      L('Formula bugungi harfiy ko‘rinishiga XVI–XVII asrlarda, Viyet va Dekart ramziy algebrani yaratganidan keyin ega bo‘ldi.',
        'Современный буквенный вид формула получила в XVI–XVII веках, после того как Виет и Декарт создали символическую алгебру.',
        'The formula took its modern letter form in the 16th–17th centuries, after Viète and Descartes created symbolic algebra.')
    ] },
    { kind: 'rule', h: L('Formulani keltirib chiqarish', 'Вывод формулы корней', 'Deriving the quadratic formula'), p: [
      L('ax<sup>2</sup> + bx + c = 0 (a ≠ 0) tenglamani olamiz. Ikkala tomonni 4a ga ko‘paytiramiz: 4a<sup>2</sup>x<sup>2</sup> + 4abx + 4ac = 0. Ikkala tomonga b<sup>2</sup> qo‘shib, 4ac ni o‘ngga o‘tkazamiz: 4a<sup>2</sup>x<sup>2</sup> + 4abx + b<sup>2</sup> = b<sup>2</sup> − 4ac.',
        'Возьмём уравнение ax<sup>2</sup> + bx + c = 0 (a ≠ 0). Умножим обе части на 4a: 4a<sup>2</sup>x<sup>2</sup> + 4abx + 4ac = 0. Прибавим к обеим частям b<sup>2</sup> и перенесём 4ac вправо: 4a<sup>2</sup>x<sup>2</sup> + 4abx + b<sup>2</sup> = b<sup>2</sup> − 4ac.',
        'Take the equation ax<sup>2</sup> + bx + c = 0 (a ≠ 0). Multiply both sides by 4a: 4a<sup>2</sup>x<sup>2</sup> + 4abx + 4ac = 0. Add b<sup>2</sup> to both sides and move 4ac to the right: 4a<sup>2</sup>x<sup>2</sup> + 4abx + b<sup>2</sup> = b<sup>2</sup> − 4ac.'),
      L('Chap tomon to‘la kvadrat: (2ax)<sup>2</sup> + 2 · 2ax · b + b<sup>2</sup> = (2ax + b)<sup>2</sup>. O‘ng tomon esa diskriminant. Shunday qilib, <b>(2ax + b)<sup>2</sup> = D</b>. Endi uch hol bor. Agar D &lt; 0 bo‘lsa, chap tomon (kvadrat) manfiy bo‘la olmaydi — ildiz yo‘q. Agar D = 0 bo‘lsa, 2ax + b = 0, ya’ni x = −<sup>b</sup>/<sub>2a</sub>. Agar D &gt; 0 bo‘lsa, 2ax + b = √D yoki 2ax + b = −√D.',
        'Левая часть — полный квадрат: (2ax)<sup>2</sup> + 2 · 2ax · b + b<sup>2</sup> = (2ax + b)<sup>2</sup>. Справа — дискриминант. Итак, <b>(2ax + b)<sup>2</sup> = D</b>. Возможны три случая. Если D &lt; 0, левая часть (квадрат) не может быть отрицательной — корней нет. Если D = 0, то 2ax + b = 0, то есть x = −<sup>b</sup>/<sub>2a</sub>. Если D &gt; 0, то 2ax + b = √D или 2ax + b = −√D.',
        'The left side is a perfect square: (2ax)<sup>2</sup> + 2 · 2ax · b + b<sup>2</sup> = (2ax + b)<sup>2</sup>. The right side is the discriminant. So <b>(2ax + b)<sup>2</sup> = D</b>. There are three cases. If D &lt; 0, the left side (a square) cannot be negative — no roots. If D = 0, then 2ax + b = 0, i.e. x = −<sup>b</sup>/<sub>2a</sub>. If D &gt; 0, then 2ax + b = √D or 2ax + b = −√D.'),
      L('Oxirgi holda x ni topamiz va <b>kvadrat tenglama ildizlari formulasi</b>ni olamiz:<br><b>x<sub>1,2</sub> = (−b ± √D) : 2a, bunda D = b<sup>2</sup> − 4ac.</b><br>D = 0 bo‘lganda ham shu formula ishlaydi: ± √0 = 0, ikkala ildiz −<sup>b</sup>/<sub>2a</sub> ga teng bo‘ladi.',
        'В последнем случае находим x и получаем <b>формулу корней квадратного уравнения</b>:<br><b>x<sub>1,2</sub> = (−b ± √D) : 2a, где D = b<sup>2</sup> − 4ac.</b><br>При D = 0 эта формула тоже работает: ± √0 = 0, и оба корня равны −<sup>b</sup>/<sub>2a</sub>.',
        'In the last case we solve for x and obtain the <b>quadratic formula</b>:<br><b>x<sub>1,2</sub> = (−b ± √D) : 2a, where D = b<sup>2</sup> − 4ac.</b><br>The same formula also works when D = 0: ± √0 = 0, and both roots equal −<sup>b</sup>/<sub>2a</sub>.'),
      L('<b>Juft ikkinchi koeffitsiyent.</b> Agar b = 2k bo‘lsa, hisob qisqaradi: D<sub>1</sub> = k<sup>2</sup> − ac (bu D : 4 ga teng) va x<sub>1,2</sub> = (−k ± √D<sub>1</sub>) : a. Masalan, 4x<sup>2</sup> − 12x + 5 = 0 da k = −6, D<sub>1</sub> = 36 − 20 = 16, x = (6 ± 4) : 4, ya’ni 2,5 va 0,5.',
        '<b>Чётный второй коэффициент.</b> Если b = 2k, вычисления короче: D<sub>1</sub> = k<sup>2</sup> − ac (это D : 4) и x<sub>1,2</sub> = (−k ± √D<sub>1</sub>) : a. Например, в 4x<sup>2</sup> − 12x + 5 = 0 имеем k = −6, D<sub>1</sub> = 36 − 20 = 16, x = (6 ± 4) : 4, то есть 2,5 и 0,5.',
        '<b>Even second coefficient.</b> If b = 2k the work is shorter: D<sub>1</sub> = k<sup>2</sup> − ac (this is D : 4) and x<sub>1,2</sub> = (−k ± √D<sub>1</sub>) : a. For example, in 4x<sup>2</sup> − 12x + 5 = 0 we have k = −6, D<sub>1</sub> = 36 − 20 = 16, x = (6 ± 4) : 4, i.e. 2.5 and 0.5.')
    ] },
    { kind: 'steps', h: L('Yechish algoritmi', 'Алгоритм решения', 'The algorithm'), list: [
      L('<b>1.</b> Tenglamani ax<sup>2</sup> + bx + c = 0 ko‘rinishiga keltiring. Agar barcha koeffitsiyentlar umumiy bo‘luvchiga ega bo‘lsa, unga bo‘ling; a manfiy bo‘lsa, ikkala tomonni −1 ga ko‘paytirish qulay.', '<b>1.</b> Приведите уравнение к виду ax<sup>2</sup> + bx + c = 0. Если у всех коэффициентов есть общий делитель — сократите; если a отрицательно, удобно умножить обе части на −1.', '<b>1.</b> Bring the equation to the form ax<sup>2</sup> + bx + c = 0. If all coefficients share a common factor, divide it out; if a is negative, it helps to multiply both sides by −1.'),
      L('<b>2.</b> a, b, c ni ishoralari bilan yozib oling.', '<b>2.</b> Выпишите a, b, c вместе со знаками.', '<b>2.</b> Write down a, b, c with their signs.'),
      L('<b>3.</b> D = b<sup>2</sup> − 4ac ni hisoblang.', '<b>3.</b> Вычислите D = b<sup>2</sup> − 4ac.', '<b>3.</b> Compute D = b<sup>2</sup> − 4ac.'),
      L('<b>4.</b> D &lt; 0 bo‘lsa — «ildiz yo‘q» deb javob bering. D ≥ 0 bo‘lsa — √D ni toping.', '<b>4.</b> Если D &lt; 0 — ответ «корней нет». Если D ≥ 0 — найдите √D.', '<b>4.</b> If D &lt; 0, answer “no roots”. If D ≥ 0, find √D.'),
      L('<b>5.</b> x<sub>1,2</sub> = (−b ± √D) : 2a formulasiga qo‘ying va ikki ildizni alohida hisoblang.', '<b>5.</b> Подставьте в формулу x<sub>1,2</sub> = (−b ± √D) : 2a и вычислите оба корня отдельно.', '<b>5.</b> Substitute into x<sub>1,2</sub> = (−b ± √D) : 2a and compute the two roots separately.'),
      L('<b>6.</b> Kamida bitta ildizni tenglamaga qo‘yib tekshiring.', '<b>6.</b> Проверьте хотя бы один корень подстановкой.', '<b>6.</b> Check at least one root by substitution.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('x<sup>2</sup> − 5x + 6 = 0', 'x<sup>2</sup> − 5x + 6 = 0', 'x<sup>2</sup> − 5x + 6 = 0'), s: L('a = 1, b = −5, c = 6. D = 25 − 24 = 1, √D = 1. x = (5 ± 1) : 2, ya’ni x<sub>1</sub> = 3, x<sub>2</sub> = 2. Tekshirish: 9 − 15 + 6 = 0 ✓.', 'a = 1, b = −5, c = 6. D = 25 − 24 = 1, √D = 1. x = (5 ± 1) : 2, то есть x<sub>1</sub> = 3, x<sub>2</sub> = 2. Проверка: 9 − 15 + 6 = 0 ✓.', 'a = 1, b = −5, c = 6. D = 25 − 24 = 1, √D = 1. x = (5 ± 1) : 2, so x<sub>1</sub> = 3, x<sub>2</sub> = 2. Check: 9 − 15 + 6 = 0 ✓.') },
      { q: L('2x<sup>2</sup> + 3x − 2 = 0', '2x<sup>2</sup> + 3x − 2 = 0', '2x<sup>2</sup> + 3x − 2 = 0'), s: L('D = 9 − 4 · 2 · (−2) = 9 + 16 = 25, √D = 5. x = (−3 ± 5) : 4, ya’ni x<sub>1</sub> = 0,5, x<sub>2</sub> = −2. Tekshirish: 2 · 4 − 6 − 2 = 0 ✓.', 'D = 9 − 4 · 2 · (−2) = 9 + 16 = 25, √D = 5. x = (−3 ± 5) : 4, то есть x<sub>1</sub> = 0,5, x<sub>2</sub> = −2. Проверка: 2 · 4 − 6 − 2 = 0 ✓.', 'D = 9 − 4 · 2 · (−2) = 9 + 16 = 25, √D = 5. x = (−3 ± 5) : 4, so x<sub>1</sub> = 0.5, x<sub>2</sub> = −2. Check: 2 · 4 − 6 − 2 = 0 ✓.') },
      { q: L('x<sup>2</sup> − 6x + 9 = 0', 'x<sup>2</sup> − 6x + 9 = 0', 'x<sup>2</sup> − 6x + 9 = 0'), s: L('D = 36 − 36 = 0, demak, bitta ildiz: x = 6 : 2 = 3. Darhaqiqat, chap tomon (x − 3)<sup>2</sup> ga teng.', 'D = 36 − 36 = 0, значит, корень один: x = 6 : 2 = 3. Действительно, левая часть равна (x − 3)<sup>2</sup>.', 'D = 36 − 36 = 0, so there is one root: x = 6 : 2 = 3. Indeed, the left side equals (x − 3)<sup>2</sup>.') },
      { q: L('x<sup>2</sup> + x + 1 = 0', 'x<sup>2</sup> + x + 1 = 0', 'x<sup>2</sup> + x + 1 = 0'), s: L('D = 1 − 4 = −3 &lt; 0. Haqiqiy ildizlar yo‘q. (Sababi: x<sup>2</sup> + x + 1 = (x + 0,5)<sup>2</sup> + 0,75 har doim musbat.)', 'D = 1 − 4 = −3 &lt; 0. Действительных корней нет. (Причина: x<sup>2</sup> + x + 1 = (x + 0,5)<sup>2</sup> + 0,75 всегда положительно.)', 'D = 1 − 4 = −3 &lt; 0. There are no real roots. (Reason: x<sup>2</sup> + x + 1 = (x + 0.5)<sup>2</sup> + 0.75 is always positive.)') },
      { q: L('−3x<sup>2</sup> + 2x + 8 = 0', '−3x<sup>2</sup> + 2x + 8 = 0', '−3x<sup>2</sup> + 2x + 8 = 0'), s: L('−1 ga ko‘paytiramiz: 3x<sup>2</sup> − 2x − 8 = 0. b = −2 juft, k = −1: D<sub>1</sub> = 1 + 24 = 25. x = (1 ± 5) : 3, ya’ni x<sub>1</sub> = 2, x<sub>2</sub> = −<sup>4</sup>/<sub>3</sub>.', 'Умножим на −1: 3x<sup>2</sup> − 2x − 8 = 0. b = −2 чётное, k = −1: D<sub>1</sub> = 1 + 24 = 25. x = (1 ± 5) : 3, то есть x<sub>1</sub> = 2, x<sub>2</sub> = −<sup>4</sup>/<sub>3</sub>.', 'Multiply by −1: 3x<sup>2</sup> − 2x − 8 = 0. b = −2 is even, k = −1: D<sub>1</sub> = 1 + 24 = 25. x = (1 ± 5) : 3, so x<sub>1</sub> = 2, x<sub>2</sub> = −<sup>4</sup>/<sub>3</sub>.') }
    ] },
    { kind: 'table', h: L('Diskriminant va ildizlar', 'Дискриминант и корни', 'Discriminant and roots'), table: { head: [L('Tenglama', 'Уравнение', 'Equation'), L('D', 'D', 'D'), L('Ildizlar soni', 'Число корней', 'Number of roots'), L('Ildizlar', 'Корни', 'Roots')], rows: [
      [L('x<sup>2</sup> − 7x + 10 = 0', 'x<sup>2</sup> − 7x + 10 = 0', 'x<sup>2</sup> − 7x + 10 = 0'), '9', L('ikkita', 'два', 'two'), L('2; 5', '2; 5', '2; 5')],
      [L('x<sup>2</sup> + 4x − 21 = 0', 'x<sup>2</sup> + 4x − 21 = 0', 'x<sup>2</sup> + 4x − 21 = 0'), '100', L('ikkita', 'два', 'two'), L('−7; 3', '−7; 3', '−7; 3')],
      [L('4x<sup>2</sup> + 4x + 1 = 0', '4x<sup>2</sup> + 4x + 1 = 0', '4x<sup>2</sup> + 4x + 1 = 0'), '0', L('bitta', 'один', 'one'), L('−0,5', '−0,5', '−0.5')],
      [L('x<sup>2</sup> − 2x + 5 = 0', 'x<sup>2</sup> − 2x + 5 = 0', 'x<sup>2</sup> − 2x + 5 = 0'), L('−16', '−16', '−16'), L('yo‘q', 'нет', 'none'), L('—', '—', '—')],
      [L('x<sup>2</sup> − 2x − 1 = 0', 'x<sup>2</sup> − 2x − 1 = 0', 'x<sup>2</sup> − 2x − 1 = 0'), '8', L('ikkita', 'два', 'two'), L('1 ± √2', '1 ± √2', '1 ± √2')]
    ] }, after: [
      L('Oxirgi qatorga e’tibor bering: diskriminant to‘la kvadrat bo‘lmasa, ildizlar irratsional chiqadi va ularni ildiz belgisi bilan qoldiramiz: x = (2 ± √8) : 2 = 1 ± √2. Kerak bo‘lsa, taqribiy qiymat: 2,41 va −0,41.', 'Обратите внимание на последнюю строку: если дискриминант не является полным квадратом, корни иррациональны, и мы оставляем их со знаком корня: x = (2 ± √8) : 2 = 1 ± √2. При необходимости приближённо: 2,41 и −0,41.', 'Note the last row: if the discriminant is not a perfect square, the roots are irrational and we leave them in surd form: x = (2 ± √8) : 2 = 1 ± √2. If needed, approximately 2.41 and −0.41.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>b<sup>2</sup> ni noto‘g‘ri hisoblash.</b> b = −5 bo‘lsa, b<sup>2</sup> = 25, −25 emas. Kalkulyatorda −5<sup>2</sup> yozish −25 beradi — qavs qo‘ying: (−5)<sup>2</sup>.', '<b>Неверно вычислить b<sup>2</sup>.</b> При b = −5 имеем b<sup>2</sup> = 25, а не −25. На калькуляторе −5<sup>2</sup> даёт −25 — ставьте скобки: (−5)<sup>2</sup>.', '<b>Getting b<sup>2</sup> wrong.</b> If b = −5, then b<sup>2</sup> = 25, not −25. Typing −5<sup>2</sup> on a calculator gives −25 — use brackets: (−5)<sup>2</sup>.'),
      L('<b>−4ac dagi ishora.</b> c manfiy bo‘lsa, −4ac musbat bo‘ladi: 2x<sup>2</sup> + 3x − 2 = 0 da D = 9 + 16, 9 − 16 emas.', '<b>Знак в −4ac.</b> Если c отрицательно, то −4ac положительно: в 2x<sup>2</sup> + 3x − 2 = 0 будет D = 9 + 16, а не 9 − 16.', '<b>The sign in −4ac.</b> If c is negative, −4ac is positive: in 2x<sup>2</sup> + 3x − 2 = 0, D = 9 + 16, not 9 − 16.'),
      L('<b>Maxrajni 2a o‘rniga 2 deb olish.</b> Formulada butun surat 2a ga bo‘linadi. a ≠ 1 bo‘lganda bu eng ko‘p uchraydigan xato.', '<b>Делить на 2 вместо 2a.</b> В формуле весь числитель делится на 2a. При a ≠ 1 это самая частая ошибка.', '<b>Dividing by 2 instead of 2a.</b> In the formula the whole numerator is divided by 2a. When a ≠ 1 this is the most common slip.'),
      L('<b>−b ni yo‘qotish.</b> b = −5 bo‘lsa, −b = 5. Ishorani almashtirishni unutish ildizlarni teskari ishorali qilib qo‘yadi.', '<b>Потерять −b.</b> При b = −5 имеем −b = 5. Если забыть сменить знак, корни получатся с противоположными знаками.', '<b>Losing −b.</b> If b = −5 then −b = 5. Forgetting to change the sign flips the signs of the roots.'),
      L('<b>Tenglamani standart ko‘rinishga keltirmasdan formula qo‘llash.</b> x<sup>2</sup> = 3x + 4 da c = 4 emas: avval x<sup>2</sup> − 3x − 4 = 0 deb yozing, shunda b = −3, c = −4.', '<b>Применять формулу, не приведя уравнение к стандартному виду.</b> В x<sup>2</sup> = 3x + 4 не c = 4: сначала запишите x<sup>2</sup> − 3x − 4 = 0, тогда b = −3, c = −4.', '<b>Using the formula before reaching standard form.</b> In x<sup>2</sup> = 3x + 4, c is not 4: first write x<sup>2</sup> − 3x − 4 = 0, so b = −3, c = −4.')
    ] },
    { kind: 'life', h: L('Formula hayotda', 'Формула в жизни', 'The formula in real life'), p: [
      L('<b>Fizika.</b> Yuqoriga 15 m/s tezlik bilan otilgan to‘pning balandligi h = 15t − 5t<sup>2</sup> (metr). To‘p qachon 10 m balandlikda bo‘ladi? 5t<sup>2</sup> − 15t + 10 = 0, ya’ni t<sup>2</sup> − 3t + 2 = 0, D = 1, t = 1 s (ko‘tarilayotganda) va t = 2 s (tushayotganda). Ikki ildiz — ikki payt!', '<b>Физика.</b> Высота мяча, брошенного вверх со скоростью 15 м/с, равна h = 15t − 5t<sup>2</sup> (м). Когда мяч будет на высоте 10 м? 5t<sup>2</sup> − 15t + 10 = 0, то есть t<sup>2</sup> − 3t + 2 = 0, D = 1, t = 1 с (на подъёме) и t = 2 с (на спуске). Два корня — два момента времени!', '<b>Physics.</b> A ball thrown upwards at 15 m/s has height h = 15t − 5t<sup>2</sup> (metres). When is it 10 m high? 5t<sup>2</sup> − 15t + 10 = 0, i.e. t<sup>2</sup> − 3t + 2 = 0, D = 1, t = 1 s (going up) and t = 2 s (coming down). Two roots — two moments!'),
      L('Agar so‘ralsa: «to‘p 20 m ga yetadimi?», 5t<sup>2</sup> − 15t + 20 = 0, t<sup>2</sup> − 3t + 4 = 0, D = 9 − 16 = −7 &lt; 0. Ildiz yo‘q — demak, to‘p bu balandlikka yetmaydi. Diskriminant savolga ildizlarni hisoblamasdan javob berdi!', 'А если спросить: «долетит ли мяч до 20 м?», то 5t<sup>2</sup> − 15t + 20 = 0, t<sup>2</sup> − 3t + 4 = 0, D = 9 − 16 = −7 &lt; 0. Корней нет — значит, мяч до этой высоты не долетит. Дискриминант ответил на вопрос без вычисления корней!', 'And if we ask “will the ball reach 20 m?”, then 5t<sup>2</sup> − 15t + 20 = 0, t<sup>2</sup> − 3t + 4 = 0, D = 9 − 16 = −7 &lt; 0. No roots — so the ball never gets that high. The discriminant answered without computing any roots!'),
      L('<b>Kompyuter grafikasi.</b> O‘yinlarda nur sharga tegadimi yoki yo‘qmi, aynan kvadrat tenglama diskriminanti orqali tekshiriladi: D &gt; 0 — nur sharni kesib o‘tadi, D = 0 — sirtiga urinadi, D &lt; 0 — yonidan o‘tib ketadi. Har bir kadrda bunday hisob millionlab marta bajariladi.', '<b>Компьютерная графика.</b> В играх, попадает ли луч в шар, проверяют именно по дискриминанту квадратного уравнения: D &gt; 0 — луч пересекает шар, D = 0 — касается поверхности, D &lt; 0 — проходит мимо. В каждом кадре такой расчёт выполняется миллионы раз.', '<b>Computer graphics.</b> In games, whether a ray hits a sphere is decided by the discriminant of a quadratic: D &gt; 0 — the ray passes through, D = 0 — it just touches the surface, D &lt; 0 — it misses. This calculation runs millions of times in every frame.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Kvadrat tenglama formulasi dunyodagi eng mashhur formulalardan biri. AQSH va Angliyada o‘quvchilar uni «Pop goes the weasel» qo‘shig‘i ohangida yodlashadi.', 'Формула корней — одна из самых знаменитых формул в мире. В США и Англии школьники запоминают её под мелодию детской песенки «Pop goes the weasel».', 'The quadratic formula is one of the most famous formulas in the world. In the USA and Britain pupils memorise it to the tune of the nursery song “Pop goes the weasel”.'),
      L('Uchinchi va to‘rtinchi darajali tenglamalar uchun ham formulalar bor (XVI asr, Italiya). Ammo beshinchi va undan yuqori darajali umumiy tenglamalar uchun bunday formula mavjud emasligini 1824-yilda Abel isbotlagan.', 'Формулы есть и для уравнений третьей и четвёртой степени (XVI век, Италия). Но для общих уравнений пятой и более высоких степеней такой формулы не существует — это доказал Абель в 1824 году.', 'There are formulas for equations of degree three and four as well (16th century, Italy). But for general equations of degree five and higher no such formula exists — Abel proved this in 1824.'),
      L('D &lt; 0 bo‘lganda haqiqiy ildizlar yo‘q, ammo matematiklar keyinchalik «kompleks sonlar» ni o‘ylab topishdi — ularda bunday tenglamalar ham ildizga ega bo‘ladi.', 'При D &lt; 0 действительных корней нет, но позже математики придумали «комплексные числа» — в них и такие уравнения имеют корни.', 'When D &lt; 0 there are no real roots, but mathematicians later invented “complex numbers”, in which such equations do have roots.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), ex: [
      { q: L('x<sup>2</sup> + 2x − 15 = 0', 'x<sup>2</sup> + 2x − 15 = 0', 'x<sup>2</sup> + 2x − 15 = 0'), s: L('D<sub>1</sub> = 1 + 15 = 16, x = −1 ± 4, ya’ni 3 va −5.', 'D<sub>1</sub> = 1 + 15 = 16, x = −1 ± 4, то есть 3 и −5.', 'D<sub>1</sub> = 1 + 15 = 16, x = −1 ± 4, i.e. 3 and −5.') },
      { q: L('3x<sup>2</sup> − 7x + 2 = 0', '3x<sup>2</sup> − 7x + 2 = 0', '3x<sup>2</sup> − 7x + 2 = 0'), s: L('D = 49 − 24 = 25, x = (7 ± 5) : 6, ya’ni 2 va <sup>1</sup>/<sub>3</sub>.', 'D = 49 − 24 = 25, x = (7 ± 5) : 6, то есть 2 и <sup>1</sup>/<sub>3</sub>.', 'D = 49 − 24 = 25, x = (7 ± 5) : 6, i.e. 2 and <sup>1</sup>/<sub>3</sub>.') },
      { q: L('Qanday c da x<sup>2</sup> − 8x + c = 0 bitta ildizga ega?', 'При каком c уравнение x<sup>2</sup> − 8x + c = 0 имеет один корень?', 'For which c does x<sup>2</sup> − 8x + c = 0 have exactly one root?'), s: L('D = 64 − 4c = 0, c = 16. Ildiz x = 4.', 'D = 64 − 4c = 0, c = 16. Корень x = 4.', 'D = 64 − 4c = 0, c = 16. The root is x = 4.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Diskriminant: D = b<sup>2</sup> − 4ac.', 'Дискриминант: D = b<sup>2</sup> − 4ac.', 'Discriminant: D = b<sup>2</sup> − 4ac.'),
      L('D &gt; 0 — ikki ildiz, D = 0 — bitta ildiz, D &lt; 0 — haqiqiy ildiz yo‘q.', 'D &gt; 0 — два корня, D = 0 — один, D &lt; 0 — действительных корней нет.', 'D &gt; 0 — two roots, D = 0 — one root, D &lt; 0 — no real roots.'),
      L('Ildizlar formulasi: x<sub>1,2</sub> = (−b ± √D) : 2a.', 'Формула корней: x<sub>1,2</sub> = (−b ± √D) : 2a.', 'The quadratic formula: x<sub>1,2</sub> = (−b ± √D) : 2a.'),
      L('Formula to‘la kvadrat ajratish orqali keltirib chiqariladi: (2ax + b)<sup>2</sup> = D.', 'Формула выводится выделением полного квадрата: (2ax + b)<sup>2</sup> = D.', 'The formula comes from completing the square: (2ax + b)<sup>2</sup> = D.'),
      L('b = 2k juft bo‘lsa: D<sub>1</sub> = k<sup>2</sup> − ac, x = (−k ± √D<sub>1</sub>) : a.', 'Если b = 2k чётное: D<sub>1</sub> = k<sup>2</sup> − ac, x = (−k ± √D<sub>1</sub>) : a.', 'If b = 2k is even: D<sub>1</sub> = k<sup>2</sup> − ac, x = (−k ± √D<sub>1</sub>) : a.'),
      L('Bu usul tarixi Brahmagupta va al-Xorazmiyga borib taqaladi.', 'История этого метода восходит к Брахмагупте и аль-Хорезми.', 'The method goes back to Brahmagupta and al-Khwarizmi.')
    ] }
  ] });

  // ---------- t14. Viyet teoremasi. Kvadrat uchhadni ko‘paytuvchilarga ajratish ----------
  T.add(P, 't14', { sections: [
    { kind: 'intro', h: L('Ildizlarni og‘zaki topish mumkinmi?', 'Можно ли найти корни устно?', 'Can roots be found in your head?'), p: [
      L('x<sup>2</sup> − 7x + 12 = 0 tenglamaga qarang. Diskriminant formulasi bilan yechish mumkin, lekin tajribali o‘quvchi bir zumda «3 va 4» deb javob beradi. Qanday qilib? U ko‘paytmasi 12 ga, yig‘indisi 7 ga teng bo‘lgan ikki sonni izlagan. Bu tasodif emas: keltirilgan kvadrat tenglama ildizlari bilan koeffitsiyentlari o‘rtasida ajoyib bog‘lanish bor.',
        'Посмотрите на уравнение x<sup>2</sup> − 7x + 12 = 0. Можно решить его через дискриминант, но опытный ученик мгновенно ответит «3 и 4». Как? Он искал два числа с произведением 12 и суммой 7. Это не случайность: между корнями приведённого квадратного уравнения и его коэффициентами есть замечательная связь.',
        'Look at x<sup>2</sup> − 7x + 12 = 0. You could solve it with the discriminant, but an experienced pupil instantly says “3 and 4”. How? They looked for two numbers whose product is 12 and whose sum is 7. This is no accident: there is a remarkable link between the roots of a monic quadratic and its coefficients.'),
      L('Bu bog‘lanish fransuz matematigi Fransua Viyet nomi bilan ataladi. Viyet teoremasi faqat og‘zaki hisob uchun emas: u yordamida ildizlarni tekshirish, ildizlarni topmasdan ularning ishoralarini aniqlash, bir ildiz ma’lum bo‘lsa ikkinchisini topish va, eng muhimi, kvadrat uchhadni <b>ko‘paytuvchilarga ajratish</b> mumkin.',
        'Эта связь носит имя французского математика Франсуа Виета. Теорема Виета нужна не только для устного счёта: с её помощью можно проверять корни, определять их знаки, не находя самих корней, находить второй корень по известному первому и, главное, <b>раскладывать</b> квадратный трёхчлен <b>на множители</b>.',
        'This link is named after the French mathematician François Viète. Vieta’s theorem is not just for mental arithmetic: with it we can check roots, find their signs without computing them, find the second root when one is known and, most importantly, <b>factorise</b> a quadratic trinomial.'),
      L('Bu mavzuda teoremani isbotlaymiz, unga teskari teoremani o‘rganamiz va ax<sup>2</sup> + bx + c ko‘phadni a(x − x<sub>1</sub>)(x − x<sub>2</sub>) ko‘rinishida yozishni o‘rganamiz.',
        'В этой теме мы докажем теорему, изучим обратную к ней и научимся записывать многочлен ax<sup>2</sup> + bx + c в виде a(x − x<sub>1</sub>)(x − x<sub>2</sub>).',
        'In this topic we prove the theorem, study its converse and learn to write the polynomial ax<sup>2</sup> + bx + c as a(x − x<sub>1</sub>)(x − x<sub>2</sub>).')
    ] },
    { kind: 'def', h: L('Viyet teoremasi', 'Теорема Виета', 'Vieta’s theorem'), p: [
      L('<b>Teorema.</b> Agar x<sup>2</sup> + px + q = 0 keltirilgan kvadrat tenglama x<sub>1</sub> va x<sub>2</sub> ildizlarga ega bo‘lsa, u holda<br><b>x<sub>1</sub> + x<sub>2</sub> = −p, x<sub>1</sub> · x<sub>2</sub> = q.</b><br>So‘z bilan: ildizlar yig‘indisi qarama-qarshi ishora bilan olingan ikkinchi koeffitsiyentga, ko‘paytmasi esa ozod hadga teng.',
        '<b>Теорема.</b> Если приведённое квадратное уравнение x<sup>2</sup> + px + q = 0 имеет корни x<sub>1</sub> и x<sub>2</sub>, то<br><b>x<sub>1</sub> + x<sub>2</sub> = −p, x<sub>1</sub> · x<sub>2</sub> = q.</b><br>Словами: сумма корней равна второму коэффициенту с противоположным знаком, а произведение — свободному члену.',
        '<b>Theorem.</b> If the monic quadratic equation x<sup>2</sup> + px + q = 0 has roots x<sub>1</sub> and x<sub>2</sub>, then<br><b>x<sub>1</sub> + x<sub>2</sub> = −p, x<sub>1</sub> · x<sub>2</sub> = q.</b><br>In words: the sum of the roots is the second coefficient with the opposite sign, and their product is the constant term.'),
      L('<b>Umumiy holat.</b> ax<sup>2</sup> + bx + c = 0 tenglamani a ga bo‘lsak, x<sup>2</sup> + <sup>b</sup>/<sub>a</sub>x + <sup>c</sup>/<sub>a</sub> = 0 keltirilgan tenglama hosil bo‘ladi. Shuning uchun x<sub>1</sub> + x<sub>2</sub> = −<sup>b</sup>/<sub>a</sub>, x<sub>1</sub> · x<sub>2</sub> = <sup>c</sup>/<sub>a</sub>.',
        '<b>Общий случай.</b> Разделив ax<sup>2</sup> + bx + c = 0 на a, получим приведённое уравнение x<sup>2</sup> + <sup>b</sup>/<sub>a</sub>x + <sup>c</sup>/<sub>a</sub> = 0. Поэтому x<sub>1</sub> + x<sub>2</sub> = −<sup>b</sup>/<sub>a</sub>, x<sub>1</sub> · x<sub>2</sub> = <sup>c</sup>/<sub>a</sub>.',
        '<b>General case.</b> Dividing ax<sup>2</sup> + bx + c = 0 by a gives the monic equation x<sup>2</sup> + <sup>b</sup>/<sub>a</sub>x + <sup>c</sup>/<sub>a</sub> = 0. Hence x<sub>1</sub> + x<sub>2</sub> = −<sup>b</sup>/<sub>a</sub> and x<sub>1</sub> · x<sub>2</sub> = <sup>c</sup>/<sub>a</sub>.'),
      L('<b>Teskari teorema.</b> Agar m va n sonlar uchun m + n = −p va m · n = q bo‘lsa, u holda m va n — x<sup>2</sup> + px + q = 0 tenglamaning ildizlari. Aynan shu teorema ildizlarni «tanlab» topishga huquq beradi: mos juftni topdikmi — bu albatta ildizlar.',
        '<b>Обратная теорема.</b> Если числа m и n таковы, что m + n = −p и m · n = q, то m и n — корни уравнения x<sup>2</sup> + px + q = 0. Именно эта теорема даёт право находить корни «подбором»: нашли подходящую пару — это обязательно корни.',
        '<b>Converse.</b> If numbers m and n satisfy m + n = −p and m · n = q, then m and n are the roots of x<sup>2</sup> + px + q = 0. It is this converse that justifies finding roots “by guessing”: once a suitable pair is found, it must be the roots.')
    ] },
    { kind: 'history', h: L('Tarixdan: Viyet va Dekart', 'Из истории: Виет и Декарт', 'From history: Viète and Descartes'), p: [
      L('Fransua Viyet (1540–1603) kasbi bo‘yicha huquqshunos va qirol maslahatchisi bo‘lgan, matematika bilan esa bo‘sh vaqtida shug‘ullangan. Shunga qaramay, u algebrada inqilob qildi. 1591-yilda chop etilgan «Analitik san’atga kirish» asarida u birinchi bo‘lib nafaqat noma’lumlarni, balki <b>ma’lum</b> kattaliklarni (koeffitsiyentlarni) ham harflar bilan belgiladi: noma’lumlarni unli, ma’lumlarni undosh harflar bilan. Shu tufayli butun bir tenglamalar sinfi uchun umumiy qoidalar yozish mumkin bo‘ldi — ildizlar va koeffitsiyentlar orasidagi bog‘lanish ham shunday qoidalardan biri.',
        'Франсуа Виет (1540–1603) был по профессии юристом и советником короля, а математикой занимался в свободное время. Тем не менее он совершил переворот в алгебре. В труде «Введение в аналитическое искусство» (1591) он впервые обозначил буквами не только неизвестные, но и <b>известные</b> величины (коэффициенты): неизвестные — гласными, известные — согласными буквами. Благодаря этому стало возможно записывать общие правила для целых классов уравнений — связь корней и коэффициентов одно из таких правил.',
        'François Viète (1540–1603) was a lawyer and royal adviser by profession and did mathematics in his spare time. Even so, he revolutionised algebra. In his “Introduction to the Analytic Art” (1591) he was the first to use letters not only for unknowns but also for <b>known</b> quantities (coefficients): vowels for unknowns, consonants for knowns. This made it possible to write general rules for whole families of equations — and the link between roots and coefficients is one such rule.'),
      L('Viyet urush paytida dushman maxfiy xatlarini ham ochib bergan. Raqiblar uni «shaytonning yordamchisi» deb ayblashgan — shifrni insonning o‘zi ocha olmaydi deb o‘ylashgan!',
        'Во время войны Виет расшифровывал секретные письма противника. Враги обвиняли его в связи с дьяволом — они считали, что человек сам такой шифр разгадать не может!',
        'During a war Viète deciphered the enemy’s secret letters. His opponents accused him of being in league with the devil — they thought no human could break such a cipher alone!'),
      L('Biz bugun foydalanadigan belgilashni — noma’lumlar uchun x, y, z, ma’lumlar uchun a, b, c, darajalar uchun x<sup>2</sup> — 1637-yilda Rene Dekart «Geometriya» asarida kiritdi. Shu tufayli Viyet teoremasini bugun bir qatorda yoza olamiz.',
        'Обозначения, которыми мы пользуемся сегодня — x, y, z для неизвестных, a, b, c для известных и x<sup>2</sup> для степеней, — ввёл Рене Декарт в «Геометрии» (1637). Благодаря этому теорему Виета сегодня можно записать в одну строку.',
        'The notation we use today — x, y, z for unknowns, a, b, c for knowns and x<sup>2</sup> for powers — was introduced by René Descartes in his “Geometry” (1637). Thanks to it we can now write Vieta’s theorem on one line.')
    ] },
    { kind: 'rule', h: L('Isbot va ko‘paytuvchilarga ajratish', 'Доказательство и разложение на множители', 'Proof and factorisation'), p: [
      L('<b>Viyet teoremasining isboti.</b> x<sup>2</sup> + px + q = 0 tenglama uchun D = p<sup>2</sup> − 4q ≥ 0 va ildizlar x<sub>1</sub> = (−p + √D) : 2, x<sub>2</sub> = (−p − √D) : 2. Qo‘shamiz: √D lar qisqaradi, x<sub>1</sub> + x<sub>2</sub> = −2p : 2 = −p. Ko‘paytiramiz va kvadratlar ayirmasi formulasidan foydalanamiz: x<sub>1</sub> · x<sub>2</sub> = ((−p)<sup>2</sup> − (√D)<sup>2</sup>) : 4 = (p<sup>2</sup> − p<sup>2</sup> + 4q) : 4 = q. Isbot tugadi.',
        '<b>Доказательство теоремы Виета.</b> Для x<sup>2</sup> + px + q = 0 имеем D = p<sup>2</sup> − 4q ≥ 0 и корни x<sub>1</sub> = (−p + √D) : 2, x<sub>2</sub> = (−p − √D) : 2. Складываем: √D сокращаются, x<sub>1</sub> + x<sub>2</sub> = −2p : 2 = −p. Перемножаем, используя формулу разности квадратов: x<sub>1</sub> · x<sub>2</sub> = ((−p)<sup>2</sup> − (√D)<sup>2</sup>) : 4 = (p<sup>2</sup> − p<sup>2</sup> + 4q) : 4 = q. Что и требовалось доказать.',
        '<b>Proof of Vieta’s theorem.</b> For x<sup>2</sup> + px + q = 0 we have D = p<sup>2</sup> − 4q ≥ 0 and roots x<sub>1</sub> = (−p + √D) : 2, x<sub>2</sub> = (−p − √D) : 2. Adding them, the √D terms cancel: x<sub>1</sub> + x<sub>2</sub> = −2p : 2 = −p. Multiplying and using the difference of squares: x<sub>1</sub> · x<sub>2</sub> = ((−p)<sup>2</sup> − (√D)<sup>2</sup>) : 4 = (p<sup>2</sup> − p<sup>2</sup> + 4q) : 4 = q. This completes the proof.'),
      L('<b>Kvadrat uchhadni ko‘paytuvchilarga ajratish.</b> Agar ax<sup>2</sup> + bx + c uchhad x<sub>1</sub>, x<sub>2</sub> ildizlarga ega bo‘lsa, u holda<br><b>ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)(x − x<sub>2</sub>).</b><br>Isbot: Viyet bo‘yicha b = −a(x<sub>1</sub> + x<sub>2</sub>), c = a · x<sub>1</sub>x<sub>2</sub>. U holda ax<sup>2</sup> + bx + c = a(x<sup>2</sup> − (x<sub>1</sub> + x<sub>2</sub>)x + x<sub>1</sub>x<sub>2</sub>) = a(x − x<sub>1</sub>)(x − x<sub>2</sub>) — qavslarni ochib tekshirish oson.',
        '<b>Разложение квадратного трёхчлена на множители.</b> Если трёхчлен ax<sup>2</sup> + bx + c имеет корни x<sub>1</sub>, x<sub>2</sub>, то<br><b>ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)(x − x<sub>2</sub>).</b><br>Доказательство: по Виету b = −a(x<sub>1</sub> + x<sub>2</sub>), c = a · x<sub>1</sub>x<sub>2</sub>. Тогда ax<sup>2</sup> + bx + c = a(x<sup>2</sup> − (x<sub>1</sub> + x<sub>2</sub>)x + x<sub>1</sub>x<sub>2</sub>) = a(x − x<sub>1</sub>)(x − x<sub>2</sub>) — это легко проверить, раскрыв скобки.',
        '<b>Factorising a quadratic trinomial.</b> If the trinomial ax<sup>2</sup> + bx + c has roots x<sub>1</sub>, x<sub>2</sub>, then<br><b>ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)(x − x<sub>2</sub>).</b><br>Proof: by Vieta, b = −a(x<sub>1</sub> + x<sub>2</sub>) and c = a · x<sub>1</sub>x<sub>2</sub>. Then ax<sup>2</sup> + bx + c = a(x<sup>2</sup> − (x<sub>1</sub> + x<sub>2</sub>)x + x<sub>1</sub>x<sub>2</sub>) = a(x − x<sub>1</sub>)(x − x<sub>2</sub>) — easy to check by expanding.'),
      L('Agar D = 0 bo‘lsa, ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)<sup>2</sup>. Agar D &lt; 0 bo‘lsa, uchhadni chiziqli ko‘paytuvchilarga ajratib bo‘lmaydi.',
        'Если D = 0, то ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)<sup>2</sup>. Если D &lt; 0, трёхчлен на линейные множители не раскладывается.',
        'If D = 0, then ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)<sup>2</sup>. If D &lt; 0, the trinomial cannot be split into linear factors.')
    ] },
    { kind: 'steps', h: L('Ildizlarni tanlash va ajratish tartibi', 'Порядок подбора корней и разложения', 'How to guess roots and factorise'), list: [
      L('<b>1.</b> Tenglama keltirilgan (a = 1) ekanini tekshiring; aks holda a ga bo‘ling yoki umumiy formulalardan foydalaning.', '<b>1.</b> Убедитесь, что уравнение приведённое (a = 1); иначе разделите на a или используйте общие формулы.', '<b>1.</b> Make sure the equation is monic (a = 1); otherwise divide by a or use the general formulas.'),
      L('<b>2.</b> q ning butun bo‘luvchilari juftlarini yozing: masalan, q = 12 uchun 1 · 12, 2 · 6, 3 · 4 va ularning manfiy variantlari.', '<b>2.</b> Выпишите пары целых делителей q: например, для q = 12 — 1 · 12, 2 · 6, 3 · 4 и их отрицательные варианты.', '<b>2.</b> List the pairs of whole-number factors of q: for q = 12, these are 1 · 12, 2 · 6, 3 · 4 and their negative versions.'),
      L('<b>3.</b> Ishoralarni aniqlang: q &gt; 0 bo‘lsa, ildizlar bir xil ishorali (yig‘indi −p ishorasi bilan); q &lt; 0 bo‘lsa — har xil ishorali.', '<b>3.</b> Определите знаки: если q &gt; 0, корни одного знака (знака суммы −p); если q &lt; 0 — разных знаков.', '<b>3.</b> Decide the signs: if q &gt; 0 the roots have the same sign (the sign of the sum −p); if q &lt; 0 they have opposite signs.'),
      L('<b>4.</b> Yig‘indisi −p ga teng juftni tanlang. Topilmasa — diskriminant formulasiga o‘ting (ildizlar butun bo‘lmasligi mumkin).', '<b>4.</b> Выберите пару с суммой −p. Если не находится — переходите к формуле с дискриминантом (корни могут быть нецелыми).', '<b>4.</b> Pick the pair whose sum is −p. If none works, switch to the discriminant formula (the roots may not be whole numbers).'),
      L('<b>5.</b> Ko‘paytuvchilarga ajrating: a(x − x<sub>1</sub>)(x − x<sub>2</sub>) va qavslarni ochib tekshiring.', '<b>5.</b> Разложите: a(x − x<sub>1</sub>)(x − x<sub>2</sub>) — и проверьте, раскрыв скобки.', '<b>5.</b> Factorise as a(x − x<sub>1</sub>)(x − x<sub>2</sub>) and check by expanding.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('x<sup>2</sup> + x − 20 = 0 tenglamani og‘zaki yeching.', 'Решите устно x<sup>2</sup> + x − 20 = 0.', 'Solve x<sup>2</sup> + x − 20 = 0 mentally.'), s: L('x<sub>1</sub>x<sub>2</sub> = −20 &lt; 0 — ishoralar har xil; x<sub>1</sub> + x<sub>2</sub> = −1. Juft: 4 va −5 (4 · (−5) = −20, 4 + (−5) = −1). Javob: 4; −5.', 'x<sub>1</sub>x<sub>2</sub> = −20 &lt; 0 — знаки разные; x<sub>1</sub> + x<sub>2</sub> = −1. Пара: 4 и −5 (4 · (−5) = −20, 4 + (−5) = −1). Ответ: 4; −5.', 'x<sub>1</sub>x<sub>2</sub> = −20 &lt; 0, so the signs differ; x<sub>1</sub> + x<sub>2</sub> = −1. The pair is 4 and −5 (4 · (−5) = −20, 4 + (−5) = −1). Answer: 4; −5.') },
      { q: L('x<sup>2</sup> + px − 12 = 0 tenglamaning bir ildizi 3. Ikkinchi ildizni va p ni toping.', 'Один корень уравнения x<sup>2</sup> + px − 12 = 0 равен 3. Найдите второй корень и p.', 'One root of x<sup>2</sup> + px − 12 = 0 is 3. Find the other root and p.'), s: L('Ko‘paytmadan: 3 · x<sub>2</sub> = −12, x<sub>2</sub> = −4. Yig‘indidan: 3 + (−4) = −1 = −p, demak, p = 1.', 'Из произведения: 3 · x<sub>2</sub> = −12, x<sub>2</sub> = −4. Из суммы: 3 + (−4) = −1 = −p, значит, p = 1.', 'From the product: 3 · x<sub>2</sub> = −12, x<sub>2</sub> = −4. From the sum: 3 + (−4) = −1 = −p, so p = 1.') },
      { q: L('2x<sup>2</sup> − x − 3 ni ko‘paytuvchilarga ajrating.', 'Разложите на множители 2x<sup>2</sup> − x − 3.', 'Factorise 2x<sup>2</sup> − x − 3.'), s: L('D = 1 + 24 = 25, x = (1 ± 5) : 4, ya’ni 1,5 va −1. Demak, 2x<sup>2</sup> − x − 3 = 2(x − 1,5)(x + 1) = (2x − 3)(x + 1). Tekshirish: 2x<sup>2</sup> + 2x − 3x − 3 ✓.', 'D = 1 + 24 = 25, x = (1 ± 5) : 4, то есть 1,5 и −1. Значит, 2x<sup>2</sup> − x − 3 = 2(x − 1,5)(x + 1) = (2x − 3)(x + 1). Проверка: 2x<sup>2</sup> + 2x − 3x − 3 ✓.', 'D = 1 + 24 = 25, x = (1 ± 5) : 4, i.e. 1.5 and −1. So 2x<sup>2</sup> − x − 3 = 2(x − 1.5)(x + 1) = (2x − 3)(x + 1). Check: 2x<sup>2</sup> + 2x − 3x − 3 ✓.') },
      { q: L('Kasrni qisqartiring: (x<sup>2</sup> − 9) : (x<sup>2</sup> − 5x + 6).', 'Сократите дробь (x<sup>2</sup> − 9) : (x<sup>2</sup> − 5x + 6).', 'Simplify the fraction (x<sup>2</sup> − 9) : (x<sup>2</sup> − 5x + 6).'), s: L('Surat: (x − 3)(x + 3). Maxraj: ildizlari 2 va 3 (yig‘indi 5, ko‘paytma 6), demak, (x − 2)(x − 3). Qisqartiramiz: (x + 3) : (x − 2), bunda x ≠ 2, x ≠ 3.', 'Числитель: (x − 3)(x + 3). Знаменатель: корни 2 и 3 (сумма 5, произведение 6), значит, (x − 2)(x − 3). Сокращаем: (x + 3) : (x − 2), где x ≠ 2, x ≠ 3.', 'Numerator: (x − 3)(x + 3). Denominator: its roots are 2 and 3 (sum 5, product 6), so (x − 2)(x − 3). Cancelling: (x + 3) : (x − 2), with x ≠ 2, x ≠ 3.') },
      { q: L('Ildizlari 5 va −2 bo‘lgan keltirilgan kvadrat tenglama tuzing.', 'Составьте приведённое квадратное уравнение с корнями 5 и −2.', 'Write a monic quadratic equation with roots 5 and −2.'), s: L('Yig‘indi 3, ko‘paytma −10. Teskari teorema bo‘yicha p = −3, q = −10: x<sup>2</sup> − 3x − 10 = 0.', 'Сумма 3, произведение −10. По обратной теореме p = −3, q = −10: x<sup>2</sup> − 3x − 10 = 0.', 'Sum 3, product −10. By the converse, p = −3, q = −10: x<sup>2</sup> − 3x − 10 = 0.') }
    ] },
    { kind: 'table', h: L('Ildizlar ishorasi (D ≥ 0 da)', 'Знаки корней (при D ≥ 0)', 'Signs of the roots (when D ≥ 0)'), table: { head: [L('q (ko‘paytma)', 'q (произведение)', 'q (product)'), L('−p (yig‘indi)', '−p (сумма)', '−p (sum)'), L('Ildizlar', 'Корни', 'Roots'), L('Misol', 'Пример', 'Example')], rows: [
      [L('q &gt; 0', 'q &gt; 0', 'q &gt; 0'), L('−p &gt; 0', '−p &gt; 0', '−p &gt; 0'), L('ikkalasi musbat', 'оба положительны', 'both positive'), L('x<sup>2</sup> − 7x + 12: 3; 4', 'x<sup>2</sup> − 7x + 12: 3; 4', 'x<sup>2</sup> − 7x + 12: 3; 4')],
      [L('q &gt; 0', 'q &gt; 0', 'q &gt; 0'), L('−p &lt; 0', '−p &lt; 0', '−p &lt; 0'), L('ikkalasi manfiy', 'оба отрицательны', 'both negative'), L('x<sup>2</sup> + 5x + 6: −2; −3', 'x<sup>2</sup> + 5x + 6: −2; −3', 'x<sup>2</sup> + 5x + 6: −2; −3')],
      [L('q &lt; 0', 'q &lt; 0', 'q &lt; 0'), L('istalgan', 'любая', 'any'), L('har xil ishorali', 'разных знаков', 'opposite signs'), L('x<sup>2</sup> − x − 6: 3; −2', 'x<sup>2</sup> − x − 6: 3; −2', 'x<sup>2</sup> − x − 6: 3; −2')],
      [L('q = 0', 'q = 0', 'q = 0'), L('istalgan', 'любая', 'any'), L('biri nol', 'один равен нулю', 'one is zero'), L('x<sup>2</sup> − 4x: 0; 4', 'x<sup>2</sup> − 4x: 0; 4', 'x<sup>2</sup> − 4x: 0; 4')]
    ] }, after: [
      L('E’tibor bering: q &lt; 0 bo‘lsa, D = p<sup>2</sup> − 4q albatta musbat, demak, ildizlar har doim mavjud. q &gt; 0 bo‘lganda esa avval D ≥ 0 ekanini tekshirish kerak: masalan, x<sup>2</sup> + x + 1 = 0 da ildiz umuman yo‘q.', 'Заметьте: если q &lt; 0, то D = p<sup>2</sup> − 4q обязательно положителен, значит, корни всегда есть. При q &gt; 0 сначала надо проверить D ≥ 0: например, у x<sup>2</sup> + x + 1 = 0 корней нет вовсе.', 'Note: if q &lt; 0, then D = p<sup>2</sup> − 4q is certainly positive, so roots always exist. When q &gt; 0, first check that D ≥ 0: for example, x<sup>2</sup> + x + 1 = 0 has no roots at all.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Yig‘indi ishorasi.</b> x<sup>2</sup> − 7x + 12 = 0 da yig‘indi 7, −7 emas: x<sub>1</sub> + x<sub>2</sub> = −p, p = −7.', '<b>Знак суммы.</b> В x<sup>2</sup> − 7x + 12 = 0 сумма равна 7, а не −7: x<sub>1</sub> + x<sub>2</sub> = −p, p = −7.', '<b>The sign of the sum.</b> In x<sup>2</sup> − 7x + 12 = 0 the sum is 7, not −7: x<sub>1</sub> + x<sub>2</sub> = −p with p = −7.'),
      L('<b>Keltirilmagan tenglamaga to‘g‘ridan-to‘g‘ri qo‘llash.</b> 2x<sup>2</sup> − 6x + 4 = 0 da yig‘indi 6 emas, balki <sup>6</sup>/<sub>2</sub> = 3, ko‘paytma <sup>4</sup>/<sub>2</sub> = 2.', '<b>Применять к неприведённому уравнению напрямую.</b> В 2x<sup>2</sup> − 6x + 4 = 0 сумма не 6, а <sup>6</sup>/<sub>2</sub> = 3, произведение <sup>4</sup>/<sub>2</sub> = 2.', '<b>Applying it to a non-monic equation directly.</b> In 2x<sup>2</sup> − 6x + 4 = 0 the sum is not 6 but <sup>6</sup>/<sub>2</sub> = 3, and the product is <sup>4</sup>/<sub>2</sub> = 2.'),
      L('<b>D &lt; 0 da Viyetdan foydalanish.</b> x<sup>2</sup> + 2x + 5 = 0 uchun «ildizlar yig‘indisi −2» deyish ma’nosiz — haqiqiy ildizlar yo‘q. Avval D ni tekshiring.', '<b>Применять Виета при D &lt; 0.</b> Для x<sup>2</sup> + 2x + 5 = 0 говорить «сумма корней −2» бессмысленно — действительных корней нет. Сначала проверьте D.', '<b>Using Vieta when D &lt; 0.</b> For x<sup>2</sup> + 2x + 5 = 0, saying “the sum of the roots is −2” is meaningless — there are no real roots. Check D first.'),
      L('<b>Ajratishda a ni unutish.</b> 2x<sup>2</sup> − x − 3 ≠ (x − 1,5)(x + 1); oldida 2 bo‘lishi kerak.', '<b>Забыть a при разложении.</b> 2x<sup>2</sup> − x − 3 ≠ (x − 1,5)(x + 1); впереди должен стоять множитель 2.', '<b>Forgetting a when factorising.</b> 2x<sup>2</sup> − x − 3 ≠ (x − 1.5)(x + 1); the factor 2 must stay in front.'),
      L('<b>Qavs ichidagi ishora.</b> Ildiz −5 bo‘lsa, ko‘paytuvchi (x + 5), (x − 5) emas: x − x<sub>1</sub> = x − (−5).', '<b>Знак в скобке.</b> Если корень −5, множитель (x + 5), а не (x − 5): x − x<sub>1</sub> = x − (−5).', '<b>The sign in the bracket.</b> If a root is −5, the factor is (x + 5), not (x − 5): x − x<sub>1</sub> = x − (−5).')
    ] },
    { kind: 'life', h: L('Viyet teoremasi amalda', 'Теорема Виета на практике', 'Vieta in practice'), p: [
      L('<b>Tez hisob va tekshirish.</b> Imtihonda diskriminant orqali 3 va 4 ildizlarini topdingizmi? Ularni tenglamaga qo‘yish o‘rniga yig‘indi va ko‘paytmani tekshiring: bu bir necha soniya oladi va xatoni darrov ko‘rsatadi.', '<b>Быстрый счёт и проверка.</b> Нашли на экзамене корни 3 и 4 через дискриминант? Вместо подстановки проверьте сумму и произведение — это займёт секунды и сразу покажет ошибку.', '<b>Fast work and checking.</b> Found the roots 3 and 4 with the discriminant in an exam? Instead of substituting, check the sum and product — it takes seconds and reveals any slip immediately.'),
      L('<b>Geometriya.</b> To‘g‘ri to‘rtburchakning perimetri 34 cm, yuzi 60 cm<sup>2</sup>. Tomonlar yig‘indisi 17, ko‘paytmasi 60 — demak, ular x<sup>2</sup> − 17x + 60 = 0 tenglamaning ildizlari: 5 va 12 cm. Viyet teoremasi tenglamani «tayyor holda» beradi.', '<b>Геометрия.</b> Периметр прямоугольника 34 см, площадь 60 см<sup>2</sup>. Сумма сторон 17, произведение 60 — значит, они корни уравнения x<sup>2</sup> − 17x + 60 = 0: 5 и 12 см. Теорема Виета даёт уравнение «в готовом виде».', '<b>Geometry.</b> A rectangle has perimeter 34 cm and area 60 cm<sup>2</sup>. The sides add to 17 and multiply to 60, so they are the roots of x<sup>2</sup> − 17x + 60 = 0: 5 and 12 cm. Vieta hands us the equation ready-made.'),
      L('<b>Muhandislik va dasturlash.</b> Kompyuterlar kvadrat tenglamani yechganda ikki ildiz juda farq qilsa, kichik ildizni formula bilan hisoblash yaxlitlash xatosini oshiradi. Shuning uchun dasturchilar avval katta ildizni formula bilan, kichigini esa Viyet bo‘yicha x<sub>2</sub> = <sup>c</sup>/<sub>(a · x<sub>1</sub>)</sub> deb hisoblashadi.', '<b>Инженерия и программирование.</b> Когда компьютер решает квадратное уравнение с очень разными корнями, вычисление меньшего корня по формуле увеличивает ошибку округления. Поэтому программисты считают больший корень по формуле, а меньший — по Виету: x<sub>2</sub> = <sup>c</sup>/<sub>(a · x<sub>1</sub>)</sub>.', '<b>Engineering and programming.</b> When a computer solves a quadratic whose roots differ greatly, computing the smaller root with the formula magnifies rounding error. So programmers compute the larger root with the formula and the smaller one via Vieta: x<sub>2</sub> = <sup>c</sup>/<sub>(a · x<sub>1</sub>)</sub>.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Viyet formulalari istalgan darajali tenglamalar uchun ham bor. Masalan, kub tenglama x<sup>3</sup> + ax<sup>2</sup> + bx + c = 0 ildizlari yig‘indisi −a, ko‘paytmasi esa −c.', 'Формулы Виета существуют для уравнений любой степени. Например, сумма корней кубического уравнения x<sup>3</sup> + ax<sup>2</sup> + bx + c = 0 равна −a, а произведение равно −c.', 'Vieta’s formulas exist for equations of any degree. For instance, the roots of the cubic x<sup>3</sup> + ax<sup>2</sup> + bx + c = 0 add up to −a and multiply to −c.'),
      L('Viyet π soni uchun birinchi cheksiz ko‘paytma formulasini ham topgan (1593). Unda faqat 2 soni va kvadrat ildizlar qatnashadi.', 'Виет нашёл и первую формулу бесконечного произведения для числа π (1593). В ней участвуют только число 2 и квадратные корни.', 'Viète also found the first infinite-product formula for π (1593). It uses only the number 2 and square roots.'),
      L('Rossiya maktablarida o‘quvchilar bu teoremani uni madh etuvchi mashhur maktab she’ri orqali yodlashadi — demak, matematikaning ham o‘z folklori bor.', 'В России школьники запоминают теорему по известному школьному стихотворению «По праву достойна в стихах быть воспета…» — у математики тоже есть свой фольклор.', 'In Russia pupils remember the theorem through a well-known school poem praising it — proof that mathematics has its own folklore too.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), ex: [
      { q: L('x<sup>2</sup> − 9x + 20 = 0 ni og‘zaki yeching.', 'Решите устно x<sup>2</sup> − 9x + 20 = 0.', 'Solve x<sup>2</sup> − 9x + 20 = 0 mentally.'), s: L('Yig‘indi 9, ko‘paytma 20: 4 va 5.', 'Сумма 9, произведение 20: 4 и 5.', 'Sum 9, product 20: 4 and 5.') },
      { q: L('x<sup>2</sup> + 3x − 10 ni ko‘paytuvchilarga ajrating.', 'Разложите на множители x<sup>2</sup> + 3x − 10.', 'Factorise x<sup>2</sup> + 3x − 10.'), s: L('Ildizlar 2 va −5: (x − 2)(x + 5).', 'Корни 2 и −5: (x − 2)(x + 5).', 'The roots are 2 and −5: (x − 2)(x + 5).') },
      { q: L('3x<sup>2</sup> − 5x − 2 = 0 tenglama ildizlari yig‘indisi va ko‘paytmasini toping (yechmasdan).', 'Найдите сумму и произведение корней 3x<sup>2</sup> − 5x − 2 = 0, не решая уравнения.', 'Find the sum and product of the roots of 3x<sup>2</sup> − 5x − 2 = 0 without solving it.'), s: L('D = 25 + 24 &gt; 0. Yig‘indi <sup>5</sup>/<sub>3</sub>, ko‘paytma −<sup>2</sup>/<sub>3</sub>.', 'D = 25 + 24 &gt; 0. Сумма <sup>5</sup>/<sub>3</sub>, произведение −<sup>2</sup>/<sub>3</sub>.', 'D = 25 + 24 &gt; 0. Sum <sup>5</sup>/<sub>3</sub>, product −<sup>2</sup>/<sub>3</sub>.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('x<sup>2</sup> + px + q = 0 uchun: x<sub>1</sub> + x<sub>2</sub> = −p, x<sub>1</sub>x<sub>2</sub> = q.', 'Для x<sup>2</sup> + px + q = 0: x<sub>1</sub> + x<sub>2</sub> = −p, x<sub>1</sub>x<sub>2</sub> = q.', 'For x<sup>2</sup> + px + q = 0: x<sub>1</sub> + x<sub>2</sub> = −p, x<sub>1</sub>x<sub>2</sub> = q.'),
      L('ax<sup>2</sup> + bx + c = 0 uchun: yig‘indi −b/a, ko‘paytma c/a.', 'Для ax<sup>2</sup> + bx + c = 0: сумма −b/a, произведение c/a.', 'For ax<sup>2</sup> + bx + c = 0: sum −b/a, product c/a.'),
      L('Teskari teorema ildizlarni tanlab topishga imkon beradi.', 'Обратная теорема позволяет находить корни подбором.', 'The converse lets us find roots by guessing.'),
      L('ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)(x − x<sub>2</sub>); D &lt; 0 bo‘lsa, ajratib bo‘lmaydi.', 'ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)(x − x<sub>2</sub>); при D &lt; 0 разложение невозможно.', 'ax<sup>2</sup> + bx + c = a(x − x<sub>1</sub>)(x − x<sub>2</sub>); if D &lt; 0 there is no such factorisation.'),
      L('q &lt; 0 — ildizlar har xil ishorali; q &gt; 0 — bir xil ishorali.', 'q &lt; 0 — корни разных знаков; q &gt; 0 — одного знака.', 'q &lt; 0 — roots of opposite signs; q &gt; 0 — the same sign.'),
      L('Viyet koeffitsiyentlarni harflar bilan belgilashni boshlagan, Dekart esa bugungi belgilashni yaratgan.', 'Виет начал обозначать коэффициенты буквами, а Декарт создал современные обозначения.', 'Viète began writing coefficients as letters, and Descartes created today’s notation.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t15. Bikvadrat tenglamalar ----------
  T.add(P, 't15', { sections: [
    { kind: 'intro', h: L('To‘rtinchi darajali tenglamadan qo‘rqmang', 'Не бойтесь уравнения четвёртой степени', 'Don’t fear a fourth-degree equation'), p: [
      L('x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0 tenglamaga qarang. Unda noma’lum to‘rtinchi darajada qatnashmoqda, va birinchi qarashda bu biz yecha olmaydigan tenglamaga o‘xshaydi. Lekin diqqat bilan qarasak, x<sup>4</sup> = (x<sup>2</sup>)<sup>2</sup> ekanini ko‘ramiz. Agar x<sup>2</sup> ni bitta yangi harf bilan, masalan, t bilan belgilasak, tenglama t<sup>2</sup> − 5t + 4 = 0 ko‘rinishini oladi — bu esa oddiy kvadrat tenglama!',
        'Посмотрите на уравнение x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0. Неизвестное в нём стоит в четвёртой степени, и на первый взгляд кажется, что решать такое мы не умеем. Но если присмотреться, видно, что x<sup>4</sup> = (x<sup>2</sup>)<sup>2</sup>. Обозначив x<sup>2</sup> одной новой буквой, например t, получим t<sup>2</sup> − 5t + 4 = 0 — обычное квадратное уравнение!',
        'Look at x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0. The unknown appears to the fourth power, and at first sight it seems we cannot solve it. But look closely: x<sup>4</sup> = (x<sup>2</sup>)<sup>2</sup>. If we call x<sup>2</sup> by a single new letter, say t, the equation becomes t<sup>2</sup> − 5t + 4 = 0 — an ordinary quadratic!'),
      L('Bu usul <b>yangi o‘zgaruvchi kiritish</b> yoki <b>almashtirish</b> deyiladi. U matematikaning eng kuchli g‘oyalaridan biri: murakkab ko‘rinishdagi masalani tanish masalaga aylantiramiz, uni yechamiz va so‘ng orqaga qaytamiz. Bu mavzuda almashtirishni bikvadrat tenglamalarda, keyin esa boshqa «kvadrat tenglamaga keltiriladigan» tenglamalarda qo‘llashni o‘rganamiz.',
        'Этот приём называется <b>введением новой переменной</b> или <b>заменой</b>. Это одна из самых сильных идей математики: сложную на вид задачу превращаем в знакомую, решаем её и затем возвращаемся назад. В этой теме мы научимся применять замену в биквадратных уравнениях, а затем и в других уравнениях, «сводящихся к квадратным».',
        'This method is called <b>introducing a new variable</b>, or <b>substitution</b>. It is one of the most powerful ideas in mathematics: we turn a complicated-looking problem into a familiar one, solve it and then come back. In this topic we learn to use substitution for biquadratic equations and then for other equations that “reduce to quadratics”.'),
      L('Diqqat qiling: bir t qiymatiga ikkita x qiymat mos kelishi mumkin, shuning uchun bikvadrat tenglamaning ildizlari to‘rttagacha bo‘lishi mumkin.',
        'Обратите внимание: одному значению t могут соответствовать два значения x, поэтому у биквадратного уравнения может быть до четырёх корней.',
        'Notice that one value of t may correspond to two values of x, so a biquadratic equation can have up to four roots.')
    ] },
    { kind: 'def', h: L('Bikvadrat tenglama ta’rifi', 'Определение биквадратного уравнения', 'Definition of a biquadratic equation'), p: [
      L('<b>Bikvadrat tenglama</b> deb ax<sup>4</sup> + bx<sup>2</sup> + c = 0 ko‘rinishidagi tenglamaga aytiladi, bunda a ≠ 0. «Bi» old qo‘shimchasi lotincha «ikki» degani: bu tenglama go‘yo «ikki marta kvadrat» — x<sup>2</sup> ning kvadrati qatnashadi. Unda x<sup>3</sup> va x hadlari yo‘q, faqat x ning juft darajalari bor.',
        '<b>Биквадратным</b> называется уравнение вида ax<sup>4</sup> + bx<sup>2</sup> + c = 0, где a ≠ 0. Приставка «би» по-латыни означает «два»: это уравнение как бы «дважды квадратное» — в нём есть квадрат от x<sup>2</sup>. Членов x<sup>3</sup> и x в нём нет, только чётные степени x.',
        'A <b>biquadratic</b> equation is an equation of the form ax<sup>4</sup> + bx<sup>2</sup> + c = 0 with a ≠ 0. The prefix “bi” means “two” in Latin: the equation is “twice quadratic” — it contains the square of x<sup>2</sup>. There are no x<sup>3</sup> or x terms, only even powers of x.'),
      L('Uni yechish uchun <b>t = x<sup>2</sup></b> almashtirishini kiritamiz. Unda x<sup>4</sup> = t<sup>2</sup> va tenglama at<sup>2</sup> + bt + c = 0 ga aylanadi. Bu yordamchi (rezolventa) kvadrat tenglama deyiladi. Muhim cheklov: x<sup>2</sup> hech qachon manfiy bo‘lmaydi, shuning uchun <b>t ≥ 0</b> bo‘lishi shart. Manfiy t qiymatlari tashlab yuboriladi.',
        'Для решения вводим замену <b>t = x<sup>2</sup></b>. Тогда x<sup>4</sup> = t<sup>2</sup>, и уравнение превращается в at<sup>2</sup> + bt + c = 0. Его называют вспомогательным квадратным уравнением. Важное ограничение: x<sup>2</sup> никогда не бывает отрицательным, поэтому обязательно <b>t ≥ 0</b>. Отрицательные значения t отбрасываются.',
        'To solve it we substitute <b>t = x<sup>2</sup></b>. Then x<sup>4</sup> = t<sup>2</sup> and the equation becomes at<sup>2</sup> + bt + c = 0, called the auxiliary quadratic. An important restriction: x<sup>2</sup> is never negative, so we must have <b>t ≥ 0</b>. Negative values of t are rejected.'),
      L('Umumroq qilib aytganda, agar tenglamada bir xil ifoda (masalan, x<sup>2</sup> + x yoki <sup>1</sup>/<sub>x</sub>) bir necha marta takrorlansa va tenglama shu ifodaga nisbatan kvadrat bo‘lsa, uni ham yangi o‘zgaruvchi bilan almashtirib, kvadrat tenglamaga keltirish mumkin.',
        'В более общем виде: если в уравнении несколько раз повторяется одно и то же выражение (например, x<sup>2</sup> + x или <sup>1</sup>/<sub>x</sub>) и уравнение квадратное относительно этого выражения, его тоже можно заменить новой переменной и свести к квадратному.',
        'More generally: if the same expression (for example x<sup>2</sup> + x or <sup>1</sup>/<sub>x</sub>) is repeated in an equation and the equation is quadratic in that expression, it too can be replaced by a new variable and reduced to a quadratic.')
    ] },
    { kind: 'history', h: L('Tarixdan: almashtirish g‘oyasi', 'Из истории: идея замены', 'From history: the idea of substitution'), p: [
      L('Yangi o‘zgaruvchi kiritish g‘oyasi juda qadimiy. Bobil mirzolari ham ba’zi murakkab masalalarni yordamchi kattalik kiritib, sodda ko‘rinishga keltirgan. IX asrda al-Xorazmiy esa barcha tenglamalarni bir nechta standart turga «keltirish» kerakligini o‘rgatgan: «al-jabr» (to‘ldirish) va «al-muqobala» (qarama-qarshi qo‘yish) amallari aynan murakkab tenglamani tanish turga olib kelish uchun ishlatilgan.',
        'Идея введения новой переменной очень древняя. Ещё вавилонские писцы сводили некоторые сложные задачи к простым, вводя вспомогательную величину. В IX веке аль-Хорезми учил «приводить» все уравнения к нескольким стандартным видам: действия «аль-джабр» (восполнение) и «аль-мукабала» (противопоставление) служили именно для того, чтобы привести сложное уравнение к знакомому виду.',
        'Introducing a new variable is a very old idea. Babylonian scribes already reduced some hard problems to simpler ones by bringing in an auxiliary quantity. In the 9th century al-Khwarizmi taught that every equation should be “reduced” to one of a few standard types: the operations “al-jabr” (restoring) and “al-muqabala” (balancing) were used precisely to bring a complicated equation to a familiar form.'),
      L('XVI asrda italiyalik matematiklar to‘rtinchi darajali tenglamalarning umumiy yechimini topishdi: 1540-yillarda Lodoviko Ferrari umumiy to‘rtinchi darajali tenglamani almashtirishlar zanjiri orqali kub va kvadrat tenglamalarga keltirdi, natija 1545-yilda Jerolamo Kardanoning «Buyuk san’at» kitobida chop etildi. Bikvadrat tenglama — bu umumiy holning eng sodda xususiy holi bo‘lib, unda bitta almashtirishning o‘zi yetarli.',
        'В XVI веке итальянские математики нашли общее решение уравнений четвёртой степени: в 1540-х годах Лодовико Феррари цепочкой замен свёл общее уравнение четвёртой степени к кубическому и квадратным, а результат был опубликован в 1545 году в книге Джероламо Кардано «Великое искусство». Биквадратное уравнение — простейший частный случай, где хватает одной замены.',
        'In the 16th century Italian mathematicians found the general solution of fourth-degree equations: in the 1540s Lodovico Ferrari used a chain of substitutions to reduce the general quartic to a cubic and quadratics, and the result was published in 1545 in Gerolamo Cardano’s book “The Great Art”. The biquadratic equation is the simplest special case, where one substitution is enough.')
    ] },
    { kind: 'rule', h: L('Ildizlar qanday topiladi', 'Как находятся корни', 'How the roots are found'), p: [
      L('at<sup>2</sup> + bt + c = 0 yordamchi tenglamani yechgandan so‘ng, uning har bir ildizi t<sub>0</sub> uchun x<sup>2</sup> = t<sub>0</sub> tenglamani yechamiz:',
        'Решив вспомогательное уравнение at<sup>2</sup> + bt + c = 0, для каждого его корня t<sub>0</sub> решаем уравнение x<sup>2</sup> = t<sub>0</sub>:',
        'After solving the auxiliary equation at<sup>2</sup> + bt + c = 0, for each of its roots t<sub>0</sub> we solve x<sup>2</sup> = t<sub>0</sub>:')
    ], list: [
      L('agar t<sub>0</sub> &gt; 0 bo‘lsa — ikki ildiz: x = ±√t<sub>0</sub>;', 'если t<sub>0</sub> &gt; 0 — два корня: x = ±√t<sub>0</sub>;', 'if t<sub>0</sub> &gt; 0 — two roots: x = ±√t<sub>0</sub>;'),
      L('agar t<sub>0</sub> = 0 bo‘lsa — bitta ildiz: x = 0;', 'если t<sub>0</sub> = 0 — один корень: x = 0;', 'if t<sub>0</sub> = 0 — one root: x = 0;'),
      L('agar t<sub>0</sub> &lt; 0 bo‘lsa — ildiz yo‘q (bu t<sub>0</sub> chet ildiz sifatida tashlanadi).', 'если t<sub>0</sub> &lt; 0 — корней нет (такое t<sub>0</sub> отбрасывается как посторонний корень).', 'if t<sub>0</sub> &lt; 0 — no roots (this t<sub>0</sub> is discarded as an extraneous root).')
    ], after: [
      L('Shunday qilib, bikvadrat tenglama 0, 1, 2, 3 yoki 4 ta ildizga ega bo‘lishi mumkin. Masalan, x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0 da t = 1 va t = 4, ikkalasi musbat, shuning uchun to‘rt ildiz bor: ±1, ±2. x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0 da t = 1 va t = −4; ikkinchisi yaroqsiz, shuning uchun faqat ±1.',
        'Итак, биквадратное уравнение может иметь 0, 1, 2, 3 или 4 корня. Например, в x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0 получаем t = 1 и t = 4, оба положительны, поэтому корней четыре: ±1, ±2. В x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0 получаем t = 1 и t = −4; второе не годится, поэтому корни только ±1.',
        'So a biquadratic equation can have 0, 1, 2, 3 or 4 roots. In x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0 we get t = 1 and t = 4, both positive, so there are four roots: ±1, ±2. In x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0 we get t = 1 and t = −4; the second is not allowed, so the roots are just ±1.'),
      L('Bikvadrat tenglamaning ildizlari doimo simmetrik: agar x — ildiz bo‘lsa, −x ham ildiz, chunki (−x)<sup>4</sup> = x<sup>4</sup> va (−x)<sup>2</sup> = x<sup>2</sup>. Shuning uchun nol bo‘lmagan ildizlar doimo juft-juft keladi.',
        'Корни биквадратного уравнения всегда симметричны: если x — корень, то и −x — корень, ведь (−x)<sup>4</sup> = x<sup>4</sup> и (−x)<sup>2</sup> = x<sup>2</sup>. Поэтому ненулевые корни всегда идут парами.',
        'The roots of a biquadratic are always symmetric: if x is a root, so is −x, because (−x)<sup>4</sup> = x<sup>4</sup> and (−x)<sup>2</sup> = x<sup>2</sup>. That is why the non-zero roots always come in pairs.')
    ] },
    { kind: 'steps', h: L('Yechish algoritmi', 'Алгоритм решения', 'The algorithm'), list: [
      L('<b>1.</b> Tenglama ax<sup>4</sup> + bx<sup>2</sup> + c = 0 ko‘rinishida ekanini tekshiring (yoki unga keltiring).', '<b>1.</b> Убедитесь, что уравнение имеет вид ax<sup>4</sup> + bx<sup>2</sup> + c = 0 (или приведите его к такому виду).', '<b>1.</b> Make sure the equation has the form ax<sup>4</sup> + bx<sup>2</sup> + c = 0 (or bring it to that form).'),
      L('<b>2.</b> t = x<sup>2</sup> almashtirishini yozing va t ≥ 0 shartini qayd eting.', '<b>2.</b> Запишите замену t = x<sup>2</sup> и отметьте условие t ≥ 0.', '<b>2.</b> Write the substitution t = x<sup>2</sup> and note the condition t ≥ 0.'),
      L('<b>3.</b> at<sup>2</sup> + bt + c = 0 ni diskriminant yoki Viyet teoremasi bilan yeching.', '<b>3.</b> Решите at<sup>2</sup> + bt + c = 0 через дискриминант или по теореме Виета.', '<b>3.</b> Solve at<sup>2</sup> + bt + c = 0 with the discriminant or Vieta’s theorem.'),
      L('<b>4.</b> Manfiy t larni tashlab yuboring.', '<b>4.</b> Отбросьте отрицательные значения t.', '<b>4.</b> Discard any negative values of t.'),
      L('<b>5.</b> Har bir yaroqli t uchun «orqaga qayting»: x<sup>2</sup> = t, x = ±√t.', '<b>5.</b> Для каждого подходящего t выполните «обратную замену»: x<sup>2</sup> = t, x = ±√t.', '<b>5.</b> For each valid t, “substitute back”: x<sup>2</sup> = t, x = ±√t.'),
      L('<b>6.</b> Barcha x larni yig‘ib, javobni yozing.', '<b>6.</b> Соберите все x и запишите ответ.', '<b>6.</b> Collect all the values of x and write the answer.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('x<sup>4</sup> − 13x<sup>2</sup> + 36 = 0', 'x<sup>4</sup> − 13x<sup>2</sup> + 36 = 0', 'x<sup>4</sup> − 13x<sup>2</sup> + 36 = 0'), s: L('t = x<sup>2</sup> ≥ 0: t<sup>2</sup> − 13t + 36 = 0. Viyet bo‘yicha t = 4 va t = 9 (yig‘indi 13, ko‘paytma 36). x<sup>2</sup> = 4 ⇒ x = ±2; x<sup>2</sup> = 9 ⇒ x = ±3. Javob: −3; −2; 2; 3.', 't = x<sup>2</sup> ≥ 0: t<sup>2</sup> − 13t + 36 = 0. По Виету t = 4 и t = 9 (сумма 13, произведение 36). x<sup>2</sup> = 4 ⇒ x = ±2; x<sup>2</sup> = 9 ⇒ x = ±3. Ответ: −3; −2; 2; 3.', 't = x<sup>2</sup> ≥ 0: t<sup>2</sup> − 13t + 36 = 0. By Vieta, t = 4 and t = 9 (sum 13, product 36). x<sup>2</sup> = 4 ⇒ x = ±2; x<sup>2</sup> = 9 ⇒ x = ±3. Answer: −3; −2; 2; 3.') },
      { q: L('x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0', 'x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0', 'x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0'), s: L('t<sup>2</sup> + 3t − 4 = 0, t = 1 yoki t = −4. t = −4 &lt; 0 yaroqsiz. x<sup>2</sup> = 1 ⇒ x = ±1. Javob: ±1.', 't<sup>2</sup> + 3t − 4 = 0, t = 1 или t = −4. t = −4 &lt; 0 не годится. x<sup>2</sup> = 1 ⇒ x = ±1. Ответ: ±1.', 't<sup>2</sup> + 3t − 4 = 0, t = 1 or t = −4. t = −4 &lt; 0 is not allowed. x<sup>2</sup> = 1 ⇒ x = ±1. Answer: ±1.') },
      { q: L('x<sup>4</sup> + 5x<sup>2</sup> + 6 = 0', 'x<sup>4</sup> + 5x<sup>2</sup> + 6 = 0', 'x<sup>4</sup> + 5x<sup>2</sup> + 6 = 0'), s: L('t<sup>2</sup> + 5t + 6 = 0, t = −2 yoki t = −3. Ikkalasi manfiy — ildiz yo‘q. Buni darhol ham ko‘rish mumkin: x<sup>4</sup> + 5x<sup>2</sup> + 6 ≥ 6 &gt; 0.', 't<sup>2</sup> + 5t + 6 = 0, t = −2 или t = −3. Оба отрицательны — корней нет. Это видно и сразу: x<sup>4</sup> + 5x<sup>2</sup> + 6 ≥ 6 &gt; 0.', 't<sup>2</sup> + 5t + 6 = 0, t = −2 or t = −3. Both negative — no roots. You can see this at once: x<sup>4</sup> + 5x<sup>2</sup> + 6 ≥ 6 &gt; 0.') },
      { q: L('4x<sup>4</sup> − 9x<sup>2</sup> = 0', '4x<sup>4</sup> − 9x<sup>2</sup> = 0', '4x<sup>4</sup> − 9x<sup>2</sup> = 0'), s: L('Bu chala hol: x<sup>2</sup>(4x<sup>2</sup> − 9) = 0. x<sup>2</sup> = 0 ⇒ x = 0; 4x<sup>2</sup> = 9 ⇒ x = ±1,5. Javob: −1,5; 0; 1,5 (uchta ildiz).', 'Это неполный случай: x<sup>2</sup>(4x<sup>2</sup> − 9) = 0. x<sup>2</sup> = 0 ⇒ x = 0; 4x<sup>2</sup> = 9 ⇒ x = ±1,5. Ответ: −1,5; 0; 1,5 (три корня).', 'This is an incomplete case: x<sup>2</sup>(4x<sup>2</sup> − 9) = 0. x<sup>2</sup> = 0 ⇒ x = 0; 4x<sup>2</sup> = 9 ⇒ x = ±1.5. Answer: −1.5; 0; 1.5 (three roots).') },
      { q: L('(x<sup>2</sup> + x)<sup>2</sup> − 8(x<sup>2</sup> + x) + 12 = 0', '(x<sup>2</sup> + x)<sup>2</sup> − 8(x<sup>2</sup> + x) + 12 = 0', '(x<sup>2</sup> + x)<sup>2</sup> − 8(x<sup>2</sup> + x) + 12 = 0'), s: L('Bu bikvadrat emas, lekin x<sup>2</sup> + x takrorlanmoqda. t = x<sup>2</sup> + x: t<sup>2</sup> − 8t + 12 = 0, t = 2 yoki t = 6 (bu yerda t manfiy bo‘lishi ham mumkin edi!). x<sup>2</sup> + x − 2 = 0 ⇒ x = 1, −2; x<sup>2</sup> + x − 6 = 0 ⇒ x = 2, −3. Javob: −3; −2; 1; 2.', 'Это не биквадратное уравнение, но повторяется x<sup>2</sup> + x. t = x<sup>2</sup> + x: t<sup>2</sup> − 8t + 12 = 0, t = 2 или t = 6 (здесь t могло бы быть и отрицательным!). x<sup>2</sup> + x − 2 = 0 ⇒ x = 1, −2; x<sup>2</sup> + x − 6 = 0 ⇒ x = 2, −3. Ответ: −3; −2; 1; 2.', 'This is not biquadratic, but x<sup>2</sup> + x is repeated. Let t = x<sup>2</sup> + x: t<sup>2</sup> − 8t + 12 = 0, t = 2 or t = 6 (here t could even have been negative!). x<sup>2</sup> + x − 2 = 0 ⇒ x = 1, −2; x<sup>2</sup> + x − 6 = 0 ⇒ x = 2, −3. Answer: −3; −2; 1; 2.') }
    ] },
    { kind: 'table', h: L('t ildizlari va x ildizlari soni', 'Корни t и число корней x', 'Roots in t and number of roots in x'), table: { head: [L('Yordamchi tenglama ildizlari', 'Корни вспомогательного уравнения', 'Roots of the auxiliary equation'), L('x ildizlari soni', 'Число корней x', 'Number of x-roots'), L('Misol', 'Пример', 'Example')], rows: [
      [L('ikkalasi musbat', 'оба положительны', 'both positive'), '4', L('x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0', 'x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0', 'x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0')],
      [L('biri musbat, biri nol', 'один положителен, другой ноль', 'one positive, one zero'), '3', L('x<sup>4</sup> − 9x<sup>2</sup> = 0', 'x<sup>4</sup> − 9x<sup>2</sup> = 0', 'x<sup>4</sup> − 9x<sup>2</sup> = 0')],
      [L('biri musbat, biri manfiy', 'один положителен, другой отрицателен', 'one positive, one negative'), '2', L('x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0', 'x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0', 'x<sup>4</sup> + 3x<sup>2</sup> − 4 = 0')],
      [L('bitta musbat (D = 0)', 'один положительный (D = 0)', 'a single positive root (D = 0)'), '2', L('x<sup>4</sup> − 4x<sup>2</sup> + 4 = 0', 'x<sup>4</sup> − 4x<sup>2</sup> + 4 = 0', 'x<sup>4</sup> − 4x<sup>2</sup> + 4 = 0')],
      [L('t = 0 va manfiy', 't = 0 и отрицательный', 't = 0 and a negative one'), '1', L('x<sup>4</sup> + x<sup>2</sup> = 0', 'x<sup>4</sup> + x<sup>2</sup> = 0', 'x<sup>4</sup> + x<sup>2</sup> = 0')],
      [L('ikkalasi manfiy yoki D &lt; 0', 'оба отрицательны или D &lt; 0', 'both negative or D &lt; 0'), '0', L('x<sup>4</sup> + 5x<sup>2</sup> + 6 = 0', 'x<sup>4</sup> + 5x<sup>2</sup> + 6 = 0', 'x<sup>4</sup> + 5x<sup>2</sup> + 6 = 0')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>t ni javob deb yozish.</b> x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0 uchun «javob: 1; 4» — xato. Bular t ning qiymatlari; orqaga qaytish kerak: x = ±1, ±2.', '<b>Записать t в ответ.</b> Для x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0 ответ «1; 4» неверен. Это значения t; нужна обратная замена: x = ±1, ±2.', '<b>Writing t as the answer.</b> For x<sup>4</sup> − 5x<sup>2</sup> + 4 = 0, “answer: 1; 4” is wrong. Those are values of t; you must substitute back: x = ±1, ±2.'),
      L('<b>Manfiy t dan ildiz chiqarish.</b> t = −4 dan «x = ±2» deb yozish xato: (±2)<sup>2</sup> = 4 ≠ −4.', '<b>Извлекать корень из отрицательного t.</b> Из t = −4 писать «x = ±2» неверно: (±2)<sup>2</sup> = 4 ≠ −4.', '<b>Taking the root of a negative t.</b> Writing “x = ±2” from t = −4 is wrong: (±2)<sup>2</sup> = 4 ≠ −4.'),
      L('<b>Manfiy ildizlarni unutish.</b> x<sup>2</sup> = 9 dan faqat x = 3 ni olish — ikki ildizni yo‘qotish.', '<b>Забыть отрицательные корни.</b> Из x<sup>2</sup> = 9 взять только x = 3 — значит потерять корень.', '<b>Forgetting negative roots.</b> Taking only x = 3 from x<sup>2</sup> = 9 loses a root.'),
      L('<b>Har qanday almashtirishda t ≥ 0 deb o‘ylash.</b> t = x<sup>2</sup> + x yoki t = x − 1 kabi almashtirishlarda t manfiy bo‘lishi mumkin. Shartni har gal alohida aniqlang.', '<b>Считать t ≥ 0 при любой замене.</b> При заменах вроде t = x<sup>2</sup> + x или t = x − 1 значение t может быть отрицательным. Условие нужно выяснять каждый раз.', '<b>Assuming t ≥ 0 for every substitution.</b> With substitutions like t = x<sup>2</sup> + x or t = x − 1, t may be negative. Work out the condition each time.')
    ] },
    { kind: 'life', h: L('Hayotda almashtirish usuli', 'Метод замены в жизни', 'Substitution in real life'), p: [
      L('<b>Geometriya.</b> To‘g‘ri burchakli uchburchakning gipotenuzasi 5, katetlari ko‘paytmasi 12 bo‘lsin. Katetni x deb olsak, ikkinchisi <sup>12</sup>/<sub>x</sub> va Pifagor teoremasidan x<sup>2</sup> + <sup>144</sup>/<sub>x<sup>2</sup></sub> = 25, ya’ni x<sup>4</sup> − 25x<sup>2</sup> + 144 = 0 — bikvadrat tenglama! t = 9 yoki 16, katetlar 3 va 4.',
        '<b>Геометрия.</b> Гипотенуза прямоугольного треугольника равна 5, а произведение катетов 12. Обозначив катет x, второй будет <sup>12</sup>/<sub>x</sub>, и по теореме Пифагора x<sup>2</sup> + <sup>144</sup>/<sub>x<sup>2</sup></sub> = 25, то есть x<sup>4</sup> − 25x<sup>2</sup> + 144 = 0 — биквадратное уравнение! t = 9 или 16, катеты 3 и 4.',
        '<b>Geometry.</b> A right triangle has hypotenuse 5 and the product of its legs is 12. Calling one leg x, the other is <sup>12</sup>/<sub>x</sub>, and Pythagoras gives x<sup>2</sup> + <sup>144</sup>/<sub>x<sup>2</sup></sub> = 25, i.e. x<sup>4</sup> − 25x<sup>2</sup> + 144 = 0 — a biquadratic! t = 9 or 16, so the legs are 3 and 4.'),
      L('<b>Fizika va muhandislik.</b> Tebranishlar, ko‘priklar va binolarning rezonansini o‘rganishda chastotalar ko‘pincha bikvadrat tenglamadan topiladi: tenglamada chastotaning faqat kvadrati va to‘rtinchi darajasi qatnashadi. Muhandislar binoning xavfli chastotalarini aynan shunday hisoblaydi.',
        '<b>Физика и инженерия.</b> При изучении колебаний, резонанса мостов и зданий частоты часто находят из биквадратного уравнения: в нём участвуют только квадрат и четвёртая степень частоты. Именно так инженеры вычисляют опасные частоты здания.',
        '<b>Physics and engineering.</b> When studying vibrations and the resonance of bridges and buildings, frequencies are often found from a biquadratic equation that contains only the square and the fourth power of the frequency. This is how engineers calculate a building’s dangerous frequencies.'),
      L('<b>Hayotiy ko‘nikma.</b> Almashtirish g‘oyasi faqat matematikada emas: murakkab masalani tanish qismlarga ajratish, avval sodda masalani yechish va keyin asl savolga qaytish — dasturlashda ham, kundalik rejalashtirishda ham foydali fikrlash usuli.',
        '<b>Жизненный навык.</b> Идея замены полезна не только в математике: разбить сложную задачу на знакомые части, сначала решить простую задачу, а потом вернуться к исходному вопросу — полезный способ мышления и в программировании, и в повседневном планировании.',
        '<b>A life skill.</b> The idea of substitution is useful beyond maths: break a hard problem into familiar parts, solve the simpler problem first and then return to the original question — a valuable way of thinking in programming and in everyday planning alike.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Ferrari to‘rtinchi darajali tenglamani yechganda atigi 20 yoshlarda bo‘lgan. U Kardanoning shogirdi edi.', 'Феррари решил уравнение четвёртой степени, когда ему было около 20 лет. Он был учеником Кардано.', 'Ferrari solved the quartic equation when he was only about 20. He was Cardano’s student.'),
      L('Bikvadrat tenglama grafigi y = ax<sup>4</sup> + bx<sup>2</sup> + c Oy o‘qiga nisbatan simmetrik — «W» yoki «M» harfiga o‘xshash shakl.', 'График y = ax<sup>4</sup> + bx<sup>2</sup> + c симметричен относительно оси Oy и часто похож на букву «W» или «M».', 'The graph of y = ax<sup>4</sup> + bx<sup>2</sup> + c is symmetric about the y-axis and often looks like the letter “W” or “M”.'),
      L('Beshinchi darajali tenglamalar uchun bunday almashtirish umumiy holda ishlamaydi — buni Abel va Galua isbotlagan.', 'Для уравнений пятой степени подобная замена в общем случае не работает — это доказали Абель и Галуа.', 'For fifth-degree equations no such substitution works in general — Abel and Galois proved this.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), ex: [
      { q: L('x<sup>4</sup> − 10x<sup>2</sup> + 9 = 0', 'x<sup>4</sup> − 10x<sup>2</sup> + 9 = 0', 'x<sup>4</sup> − 10x<sup>2</sup> + 9 = 0'), s: L('t = 1 yoki 9 ⇒ x = ±1, ±3.', 't = 1 или 9 ⇒ x = ±1, ±3.', 't = 1 or 9 ⇒ x = ±1, ±3.') },
      { q: L('x<sup>4</sup> − 3x<sup>2</sup> − 4 = 0', 'x<sup>4</sup> − 3x<sup>2</sup> − 4 = 0', 'x<sup>4</sup> − 3x<sup>2</sup> − 4 = 0'), s: L('t = 4 yoki −1; faqat t = 4 ⇒ x = ±2.', 't = 4 или −1; годится t = 4 ⇒ x = ±2.', 't = 4 or −1; only t = 4 works ⇒ x = ±2.') },
      { q: L('x<sup>4</sup> + 2x<sup>2</sup> + 1 = 0', 'x<sup>4</sup> + 2x<sup>2</sup> + 1 = 0', 'x<sup>4</sup> + 2x<sup>2</sup> + 1 = 0'), s: L('(x<sup>2</sup> + 1)<sup>2</sup> = 0, t = −1 &lt; 0 — ildiz yo‘q.', '(x<sup>2</sup> + 1)<sup>2</sup> = 0, t = −1 &lt; 0 — корней нет.', '(x<sup>2</sup> + 1)<sup>2</sup> = 0, t = −1 &lt; 0 — no roots.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Bikvadrat tenglama: ax<sup>4</sup> + bx<sup>2</sup> + c = 0, a ≠ 0.', 'Биквадратное уравнение: ax<sup>4</sup> + bx<sup>2</sup> + c = 0, a ≠ 0.', 'A biquadratic equation is ax<sup>4</sup> + bx<sup>2</sup> + c = 0, a ≠ 0.'),
      L('t = x<sup>2</sup> almashtirishi uni at<sup>2</sup> + bt + c = 0 ga keltiradi; t ≥ 0 bo‘lishi shart.', 'Замена t = x<sup>2</sup> сводит его к at<sup>2</sup> + bt + c = 0; обязательно t ≥ 0.', 'The substitution t = x<sup>2</sup> reduces it to at<sup>2</sup> + bt + c = 0; we need t ≥ 0.'),
      L('Har bir musbat t ikki ildiz beradi: x = ±√t; t = 0 — bitta ildiz x = 0; manfiy t tashlanadi.', 'Каждое положительное t даёт два корня x = ±√t; t = 0 даёт x = 0; отрицательные t отбрасываются.', 'Each positive t gives two roots x = ±√t; t = 0 gives x = 0; negative t are discarded.'),
      L('Bikvadrat tenglamaning ildizlari 0 tadan 4 tagacha va ±x juft-juft bo‘ladi.', 'Корней от 0 до 4, и они идут парами ±x.', 'There are 0 to 4 roots, and they come in ±x pairs.'),
      L('Takrorlanuvchi ifodani almashtirish boshqa tenglamalarni ham kvadrat tenglamaga keltiradi.', 'Замена повторяющегося выражения сводит к квадратным и другие уравнения.', 'Replacing a repeated expression reduces other equations to quadratics too.'),
      L('Javobda x ni yozing, t ni emas!', 'В ответ пишите x, а не t!', 'Write x in the answer, not t!')
    ] }
  ] });

  // ---------- t16. Kvadrat tenglamalar yordamida masalalar yechish ----------
  T.add(P, 't16', { sections: [
    { kind: 'intro', h: L('Hayotiy savoldan tenglamaga', 'От жизненного вопроса к уравнению', 'From a real question to an equation'), p: [
      L('Kvadrat tenglamani yechishni bilish — ishning yarmi xolos. Haqiqiy hayotda hech kim bizga «x<sup>2</sup> + 7x − 60 = 0 ni yeching» demaydi. Aksincha, savol so‘zlar bilan beriladi: «Gilam yuzi 60 m<sup>2</sup>, uzunligi enidan 7 m ko‘p. O‘lchamlari qanday?» Bunday savolni tenglama tiliga tarjima qilish — <b>matematik model tuzish</b> deyiladi.',
        'Уметь решать квадратное уравнение — лишь половина дела. В реальной жизни никто не скажет нам «решите x<sup>2</sup> + 7x − 60 = 0». Наоборот, вопрос задаётся словами: «Площадь ковра 60 м<sup>2</sup>, длина на 7 м больше ширины. Каковы размеры?» Перевод такого вопроса на язык уравнений называется <b>построением математической модели</b>.',
        'Knowing how to solve a quadratic is only half the job. In real life nobody says “solve x<sup>2</sup> + 7x − 60 = 0”. Instead, the question comes in words: “A carpet has an area of 60 m<sup>2</sup> and is 7 m longer than it is wide. What are its dimensions?” Translating such a question into an equation is called <b>building a mathematical model</b>.'),
      L('Bu mavzuda yuzalar, harakat, sonlar va musobaqalar haqidagi masalalarni kvadrat tenglamalar orqali yechamiz. Biz yangi va muhim bir narsani ham bilib olamiz: tenglamaning har bir ildizi masala javobi bo‘lavermaydi. Masalan, uzunlik manfiy bo‘lmaydi, odamlar soni kasr bo‘lmaydi. Shuning uchun har bir ildizni <b>masala sharti</b> bilan tekshirish shart.',
        'В этой теме мы будем решать задачи о площадях, движении, числах и соревнованиях с помощью квадратных уравнений. Мы узнаем и новую важную вещь: не каждый корень уравнения является ответом задачи. Например, длина не бывает отрицательной, а количество людей — дробным. Поэтому каждый корень обязательно проверяется <b>по условию задачи</b>.',
        'In this topic we solve problems about areas, motion, numbers and tournaments using quadratic equations. We also learn something new and important: not every root of the equation answers the problem. A length cannot be negative, and a number of people cannot be a fraction. So every root must be checked <b>against the conditions</b> of the problem.'),
      L('Matematik model tuzish ko‘nikmasi muhandis, iqtisodchi, dasturchi va olim uchun eng qadrli ko‘nikmalardan biri hisoblanadi.',
        'Умение строить математические модели — одно из самых ценных умений инженера, экономиста, программиста и учёного.',
        'The ability to build mathematical models is one of the most valuable skills for an engineer, economist, programmer or scientist.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), list: [
      L('<b>Noma’lum</b> — masalada izlanayotgan kattalik yoki u bilan bog‘liq kattalik; uni x bilan belgilaymiz va birligini yozamiz (cm, km/h, kishi).', '<b>Неизвестное</b> — искомая величина или связанная с ней; обозначаем её x и указываем единицу (см, км/ч, человек).', 'The <b>unknown</b> is the quantity we are looking for, or one linked to it; we call it x and state its unit (cm, km/h, people).'),
      L('<b>Matematik model</b> — masala shartini ifodalovchi tenglama. U masaladagi ikki xil usulda hisoblangan bir xil kattalikni tenglashtirishdan hosil bo‘ladi.', '<b>Математическая модель</b> — уравнение, выражающее условие задачи. Оно получается, когда одну и ту же величину, вычисленную двумя способами, приравнивают.', 'The <b>mathematical model</b> is an equation expressing the conditions. It arises when the same quantity, computed in two different ways, is set equal to itself.'),
      L('<b>Tabiiy cheklovlar</b> — masala ma’nosidan kelib chiqadigan shartlar: uzunlik, vaqt, tezlik musbat; odamlar, buyumlar soni natural son; foiz 0 dan 100 gacha va hokazo.', '<b>Естественные ограничения</b> — условия, вытекающие из смысла задачи: длина, время, скорость положительны; число людей и предметов натуральное; процент от 0 до 100 и т. д.', '<b>Natural restrictions</b> are conditions that follow from the meaning of the problem: lengths, times and speeds are positive; numbers of people and objects are natural numbers; a percentage lies between 0 and 100, and so on.'),
      L('<b>Masalaga mos kelmaydigan ildiz</b> — tenglamani qanoatlantiradigan, ammo cheklovlarga zid bo‘lgan ildiz. U javobga yozilmaydi, lekin uni nima uchun tashlaganingizni tushuntirish kerak.', '<b>Корень, не подходящий по смыслу</b> — корень, который удовлетворяет уравнению, но противоречит ограничениям. В ответ он не записывается, но нужно объяснить, почему он отброшен.', 'A <b>root that does not fit</b> satisfies the equation but violates the restrictions. It is not written in the answer, but you must explain why it was rejected.')
    ] },
    { kind: 'history', h: L('Tarixdan: Bhaskaraning maymunlari', 'Из истории: обезьяны Бхаскары', 'From history: Bhaskara’s monkeys'), p: [
      L('XII asrda hind matematigi Bhaskara II qiziga atab «Lilavati» nomli kitob yozgan. Unda masalalar she’r shaklida berilgan. Mashhur masalalardan biri maymunlar to‘dasi haqida: to‘daning beshdan biridan uchtasi kam bo‘lgan sonning kvadratiga teng miqdordagi maymun g‘orga kirib ketgan, yana bitta maymun daraxt shoxida ko‘rinib turibdi. To‘dada nechta maymun bor?',
        'В XII веке индийский математик Бхаскара II написал книгу «Лилавати», посвящённую своей дочери. Задачи в ней изложены в стихах. Одна из знаменитых — о стае обезьян: в пещеру ушло столько обезьян, сколько составляет квадрат числа, на три меньшего пятой части стаи, а ещё одна обезьяна видна на ветке дерева. Сколько обезьян в стае?',
        'In the 12th century the Indian mathematician Bhaskara II wrote a book called “Lilavati”, dedicated to his daughter, with problems in verse. A famous one is about a troop of monkeys: a number of monkeys equal to the square of (one fifth of the troop minus three) went into a cave, and one more monkey is seen on a branch. How many monkeys are in the troop?'),
      L('Tenglama: (<sup>x</sup>/<sub>5</sub> − 3)<sup>2</sup> + 1 = x, ya’ni x<sup>2</sup> − 55x + 250 = 0. Ildizlari 50 va 5. Bhaskara ikkinchi ildizni tashladi: x = 5 bo‘lsa, <sup>x</sup>/<sub>5</sub> − 3 = −2 — manfiy maymunlar soni ma’noga ega emas. Bu tarixdagi «masalaga mos kelmaydigan ildizni» ongli ravishda tashlashning eng mashhur namunalaridan biri. Javob: 50 ta maymun.',
        'Уравнение: (<sup>x</sup>/<sub>5</sub> − 3)<sup>2</sup> + 1 = x, то есть x<sup>2</sup> − 55x + 250 = 0. Корни 50 и 5. Бхаскара отбросил второй: при x = 5 получаем <sup>x</sup>/<sub>5</sub> − 3 = −2 — отрицательное число обезьян смысла не имеет. Это один из самых известных в истории примеров сознательного отбрасывания «неподходящего» корня. Ответ: 50 обезьян.',
        'The equation is (<sup>x</sup>/<sub>5</sub> − 3)<sup>2</sup> + 1 = x, i.e. x<sup>2</sup> − 55x + 250 = 0, with roots 50 and 5. Bhaskara rejected the second: for x = 5, <sup>x</sup>/<sub>5</sub> − 3 = −2 — a negative number of monkeys makes no sense. This is one of history’s best-known examples of deliberately rejecting a root that does not fit. Answer: 50 monkeys.'),
      L('Undan ancha oldin, III asrda Iskandariyalik Diofant «Arifmetika» kitobida ko‘plab so‘zli masalalarni tenglamaga keltirgan va ulardan faqat musbat ratsional javoblarni qabul qilgan.',
        'Задолго до этого, в III веке, Диофант Александрийский в «Арифметике» сводил множество текстовых задач к уравнениям и принимал из них только положительные рациональные ответы.',
        'Long before that, in the 3rd century, Diophantus of Alexandria in his “Arithmetica” turned many word problems into equations and accepted only positive rational answers.')
    ] },
    { kind: 'steps', h: L('Masala yechish rejasi', 'План решения задачи', 'A plan for solving problems'), list: [
      L('<b>1. Tushunish.</b> Shartni diqqat bilan o‘qing, nima berilgan va nima so‘ralayotganini yozing. Iloji bo‘lsa, rasm yoki jadval chizing.', '<b>1. Понять.</b> Внимательно прочитайте условие, выпишите, что дано и что требуется. По возможности сделайте рисунок или таблицу.', '<b>1. Understand.</b> Read carefully and write down what is given and what is asked. If possible, draw a picture or a table.'),
      L('<b>2. Noma’lumni tanlash.</b> Bir kattalikni x deb belgilang (birligi bilan) va qolganlarini x orqali ifodalang.', '<b>2. Выбрать неизвестное.</b> Обозначьте одну величину через x (с единицей измерения) и выразите остальные через x.', '<b>2. Choose the unknown.</b> Call one quantity x (with its unit) and express the others in terms of x.'),
      L('<b>3. Tenglama tuzish.</b> Bir kattalikni ikki usulda ifodalab, ularni tenglashtiring.', '<b>3. Составить уравнение.</b> Выразите одну и ту же величину двумя способами и приравняйте.', '<b>3. Form the equation.</b> Express one quantity in two ways and set them equal.'),
      L('<b>4. Yechish.</b> Tenglamani standart ko‘rinishga keltiring va ildizlarini toping.', '<b>4. Решить.</b> Приведите уравнение к стандартному виду и найдите корни.', '<b>4. Solve.</b> Bring the equation to standard form and find its roots.'),
      L('<b>5. Tekshirish va tanlash.</b> Har bir ildizni tabiiy cheklovlar bilan solishtiring, mos kelmaydiganini tashlang.', '<b>5. Проверить и отобрать.</b> Сравните каждый корень с естественными ограничениями, неподходящие отбросьте.', '<b>5. Check and select.</b> Compare each root with the natural restrictions and reject those that do not fit.'),
      L('<b>6. Javob.</b> Aynan so‘ralgan savolga birliklari bilan javob bering (ba’zan x emas, balki 2x yoki x + 7 so‘raladi).', '<b>6. Ответ.</b> Ответьте именно на заданный вопрос, с единицами измерения (иногда спрашивают не x, а 2x или x + 7).', '<b>6. Answer.</b> Answer exactly the question asked, with units (sometimes it asks not for x but for 2x or x + 7).')
    ] },
    { kind: 'example', h: L('Yuza va son masalalari', 'Задачи на площадь и числа', 'Area and number problems'), ex: [
      { q: L('To‘g‘ri to‘rtburchak yuzi 60 cm<sup>2</sup>, bir tomoni ikkinchisidan 7 cm uzun. Tomonlarini toping.', 'Площадь прямоугольника 60 см<sup>2</sup>, одна сторона на 7 см длиннее другой. Найдите стороны.', 'A rectangle has area 60 cm<sup>2</sup> and one side is 7 cm longer than the other. Find the sides.'), s: L('Qisqa tomon x cm, uzuni x + 7 cm. x(x + 7) = 60 ⇒ x<sup>2</sup> + 7x − 60 = 0 ⇒ D = 49 + 240 = 289 = 17<sup>2</sup> ⇒ x = (−7 ± 17) : 2 ⇒ x = 5 yoki x = −12. Uzunlik manfiy bo‘lmaydi, demak x = 5. Javob: 5 cm va 12 cm.', 'Меньшая сторона x см, большая x + 7 см. x(x + 7) = 60 ⇒ x<sup>2</sup> + 7x − 60 = 0 ⇒ D = 49 + 240 = 289 = 17<sup>2</sup> ⇒ x = (−7 ± 17) : 2 ⇒ x = 5 или x = −12. Длина не бывает отрицательной, значит, x = 5. Ответ: 5 см и 12 см.', 'Let the shorter side be x cm, the longer x + 7 cm. x(x + 7) = 60 ⇒ x<sup>2</sup> + 7x − 60 = 0 ⇒ D = 49 + 240 = 289 = 17<sup>2</sup> ⇒ x = (−7 ± 17) : 2 ⇒ x = 5 or x = −12. A length cannot be negative, so x = 5. Answer: 5 cm and 12 cm.') },
      { q: L('Ikki ketma-ket natural sonning ko‘paytmasi 156. Sonlarni toping.', 'Произведение двух последовательных натуральных чисел равно 156. Найдите числа.', 'Two consecutive natural numbers multiply to 156. Find them.'), s: L('x(x + 1) = 156 ⇒ x<sup>2</sup> + x − 156 = 0 ⇒ D = 1 + 624 = 625 ⇒ x = (−1 ± 25) : 2 ⇒ 12 yoki −13. −13 natural emas. Javob: 12 va 13.', 'x(x + 1) = 156 ⇒ x<sup>2</sup> + x − 156 = 0 ⇒ D = 1 + 624 = 625 ⇒ x = (−1 ± 25) : 2 ⇒ 12 или −13. −13 не натуральное. Ответ: 12 и 13.', 'x(x + 1) = 156 ⇒ x<sup>2</sup> + x − 156 = 0 ⇒ D = 1 + 624 = 625 ⇒ x = (−1 ± 25) : 2 ⇒ 12 or −13. −13 is not natural. Answer: 12 and 13.') },
      { q: L('8 m × 6 m gulzor atrofida bir xil kenglikdagi yo‘lak qilindi. Gulzor va yo‘lakning umumiy yuzi 120 m<sup>2</sup>. Yo‘lak kengligi qancha?', 'Вокруг клумбы 8 м × 6 м сделали дорожку одинаковой ширины. Общая площадь клумбы и дорожки 120 м<sup>2</sup>. Какова ширина дорожки?', 'A path of constant width is laid around an 8 m × 6 m flower bed. The bed and path together cover 120 m<sup>2</sup>. How wide is the path?'), s: L('Kenglik x m. Tashqi o‘lchamlar (8 + 2x) va (6 + 2x). (8 + 2x)(6 + 2x) = 120 ⇒ 4x<sup>2</sup> + 28x − 72 = 0 ⇒ x<sup>2</sup> + 7x − 18 = 0 ⇒ x = 2 yoki −9. Javob: 2 m.', 'Ширина x м. Внешние размеры (8 + 2x) и (6 + 2x). (8 + 2x)(6 + 2x) = 120 ⇒ 4x<sup>2</sup> + 28x − 72 = 0 ⇒ x<sup>2</sup> + 7x − 18 = 0 ⇒ x = 2 или −9. Ответ: 2 м.', 'Let the width be x m. The outer dimensions are (8 + 2x) and (6 + 2x). (8 + 2x)(6 + 2x) = 120 ⇒ 4x<sup>2</sup> + 28x − 72 = 0 ⇒ x<sup>2</sup> + 7x − 18 = 0 ⇒ x = 2 or −9. Answer: 2 m.') }
    ] },
    { kind: 'example', h: L('Harakat va musobaqa masalalari', 'Задачи на движение и турниры', 'Motion and tournament problems'), ex: [
      { q: L('Ikki velosipedchi bir vaqtda 60 km masofaga chiqdi. Birinchisining tezligi ikkinchisinikidan 5 km/h ko‘p va u manzilga 1 soat oldin yetdi. Tezliklarni toping.', 'Два велосипедиста одновременно выехали на 60 км. Скорость первого на 5 км/ч больше, и он приехал на 1 час раньше. Найдите скорости.', 'Two cyclists set off at the same time on a 60 km ride. The first is 5 km/h faster and arrives 1 hour earlier. Find their speeds.'), s: L('Ikkinchisi x km/h, birinchisi x + 5 km/h. Vaqtlar: <sup>60</sup>/<sub>x</sub> va <sup>60</sup>/<sub>(x + 5)</sub>. <sup>60</sup>/<sub>x</sub> − <sup>60</sup>/<sub>(x + 5)</sub> = 1. x(x + 5) ga ko‘paytiramiz: 60(x + 5) − 60x = x<sup>2</sup> + 5x ⇒ x<sup>2</sup> + 5x − 300 = 0 ⇒ D = 1225 = 35<sup>2</sup> ⇒ x = 15 yoki −20. Javob: 15 km/h va 20 km/h (vaqtlar 4 h va 3 h ✓).', 'Второй x км/ч, первый x + 5 км/ч. Время: <sup>60</sup>/<sub>x</sub> и <sup>60</sup>/<sub>(x + 5)</sub>. <sup>60</sup>/<sub>x</sub> − <sup>60</sup>/<sub>(x + 5)</sub> = 1. Умножим на x(x + 5): 60(x + 5) − 60x = x<sup>2</sup> + 5x ⇒ x<sup>2</sup> + 5x − 300 = 0 ⇒ D = 1225 = 35<sup>2</sup> ⇒ x = 15 или −20. Ответ: 15 км/ч и 20 км/ч (время 4 ч и 3 ч ✓).', 'Let the second ride at x km/h, the first at x + 5 km/h. Times: <sup>60</sup>/<sub>x</sub> and <sup>60</sup>/<sub>(x + 5)</sub>. <sup>60</sup>/<sub>x</sub> − <sup>60</sup>/<sub>(x + 5)</sub> = 1. Multiply by x(x + 5): 60(x + 5) − 60x = x<sup>2</sup> + 5x ⇒ x<sup>2</sup> + 5x − 300 = 0 ⇒ D = 1225 = 35<sup>2</sup> ⇒ x = 15 or −20. Answer: 15 km/h and 20 km/h (times 4 h and 3 h ✓).') },
      { q: L('Shaxmat turnirida har bir ishtirokchi qolganlar bilan bir martadan o‘ynadi, jami 45 ta o‘yin bo‘ldi. Nechta ishtirokchi bo‘lgan?', 'В шахматном турнире каждый сыграл с каждым по одному разу, всего 45 партий. Сколько было участников?', 'In a chess tournament everyone played everyone else once, 45 games in total. How many players were there?'), s: L('n ishtirokchi bo‘lsa, o‘yinlar soni <sup>n(n − 1)</sup>/<sub>2</sub>. n(n − 1) = 90 ⇒ n<sup>2</sup> − n − 90 = 0 ⇒ D = 361 = 19<sup>2</sup> ⇒ n = 10 yoki −9. Javob: 10 ishtirokchi.', 'Если участников n, партий <sup>n(n − 1)</sup>/<sub>2</sub>. n(n − 1) = 90 ⇒ n<sup>2</sup> − n − 90 = 0 ⇒ D = 361 = 19<sup>2</sup> ⇒ n = 10 или −9. Ответ: 10 участников.', 'With n players there are <sup>n(n − 1)</sup>/<sub>2</sub> games. n(n − 1) = 90 ⇒ n<sup>2</sup> − n − 90 = 0 ⇒ D = 361 = 19<sup>2</sup> ⇒ n = 10 or −9. Answer: 10 players.') }
    ] },
    { kind: 'table', h: L('Masala turlari va modellar', 'Типы задач и модели', 'Problem types and models'), table: { head: [L('Masala turi', 'Тип задачи', 'Problem type'), L('Asosiy bog‘lanish', 'Основная связь', 'Key relation'), L('Odatiy tenglama', 'Типичное уравнение', 'Typical equation')], rows: [
      [L('Yuza', 'Площадь', 'Area'), L('S = a · b', 'S = a · b', 'S = a · b'), L('x(x + d) = S', 'x(x + d) = S', 'x(x + d) = S')],
      [L('Harakat', 'Движение', 'Motion'), L('t = s : v', 't = s : v', 't = s : v'), L('s/x − s/(x + d) = Δt', 's/x − s/(x + d) = Δt', 's/x − s/(x + d) = Δt')],
      [L('Ketma-ket sonlar', 'Последовательные числа', 'Consecutive numbers'), L('n va n + 1', 'n и n + 1', 'n and n + 1'), L('n(n + 1) = P', 'n(n + 1) = P', 'n(n + 1) = P')],
      [L('Turnir, qo‘l berish', 'Турнир, рукопожатия', 'Tournament, handshakes'), L('juftliklar soni', 'число пар', 'number of pairs'), L('n(n − 1) : 2 = k', 'n(n − 1) : 2 = k', 'n(n − 1) : 2 = k')],
      [L('Tushish, otish', 'Падение, бросок', 'Falling, throwing'), L('h = v<sub>0</sub>t − 5t<sup>2</sup>', 'h = v<sub>0</sub>t − 5t<sup>2</sup>', 'h = v<sub>0</sub>t − 5t<sup>2</sup>'), L('5t<sup>2</sup> − v<sub>0</sub>t + h = 0', '5t<sup>2</sup> − v<sub>0</sub>t + h = 0', '5t<sup>2</sup> − v<sub>0</sub>t + h = 0')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Ikkala ildizni javobga yozish.</b> «Tomonlar 5 va −12» — xato. Manfiy uzunlik yo‘q; har bir ildiz shart bilan tekshiriladi.', '<b>Записать в ответ оба корня.</b> «Стороны 5 и −12» — ошибка. Отрицательной длины не бывает; каждый корень проверяется по условию.', '<b>Writing both roots as the answer.</b> “The sides are 5 and −12” is wrong. There is no negative length; check each root against the conditions.'),
      L('<b>So‘ralmagan narsaga javob berish.</b> Agar ikkala tomon so‘ralsa, faqat x = 5 ni yozish — chala javob; x + 7 = 12 ham kerak.', '<b>Ответить не на тот вопрос.</b> Если спрашивают обе стороны, написать только x = 5 — неполный ответ; нужно и x + 7 = 12.', '<b>Answering the wrong question.</b> If both sides are asked for, writing only x = 5 is incomplete; x + 7 = 12 is needed too.'),
      L('<b>Birliklarni aralashtirish.</b> Tezlik km/h da, vaqt esa daqiqada bo‘lsa, avval bir xil birlikka o‘tkazing: 20 daqiqa = <sup>1</sup>/<sub>3</sub> soat.', '<b>Смешивать единицы.</b> Если скорость в км/ч, а время в минутах, сначала переведите: 20 минут = <sup>1</sup>/<sub>3</sub> часа.', '<b>Mixing units.</b> If speed is in km/h and time in minutes, convert first: 20 minutes = <sup>1</sup>/<sub>3</sub> hour.'),
      L('<b>Qaysi vaqt katta ekanini adashtirish.</b> Tezroq yurgan kam vaqt sarflaydi: sekinning vaqtidan tezning vaqtini ayirish kerak, aksincha emas.', '<b>Перепутать, какое время больше.</b> Кто едет быстрее, тратит меньше времени: из времени медленного вычитают время быстрого, а не наоборот.', '<b>Mixing up which time is larger.</b> The faster one takes less time: subtract the faster time from the slower one, not the other way round.'),
      L('<b>Tekshiruvsiz yakunlash.</b> Javobni masala matniga qo‘yib, barcha shartlar bajarilishini tekshiring.', '<b>Закончить без проверки.</b> Подставьте ответ в текст задачи и убедитесь, что выполнены все условия.', '<b>Finishing without checking.</b> Put the answer back into the story and make sure every condition holds.')
    ] },
    { kind: 'life', h: L('Hayotda kvadrat modellar', 'Квадратные модели в жизни', 'Quadratic models in life'), p: [
      L('<b>Ta’mirlash.</b> Xonaga gilam tanlashda, devorga kafel yotqizishda yoki hovliga plitka terishda o‘lchamlar va yuzalar o‘rtasidagi bog‘lanish ko‘pincha kvadrat tenglamaga olib keladi, ayniqsa chekka (ramka, yo‘lak) bo‘lsa.', '<b>Ремонт.</b> При выборе ковра, укладке плитки на стену или во дворе связь между размерами и площадью часто приводит к квадратному уравнению, особенно если есть кайма (рамка, дорожка).', '<b>Home improvement.</b> Choosing a carpet, tiling a wall or paving a yard, the link between dimensions and area often leads to a quadratic, especially when there is a border (a frame or a path).'),
      L('<b>Biznes.</b> Kichik nonvoyxona non narxini oshirsa, xaridorlar kamayadi. Agar har 500 so‘mlik oshirishda kuniga 20 ta non kam sotilsa, tushum narx va sotuv sonining ko‘paytmasi — kvadrat ifoda bo‘ladi. Tushum ma’lum miqdorga yetishi uchun qanday narx kerakligini kvadrat tenglama ko‘rsatadi.', '<b>Бизнес.</b> Если маленькая пекарня поднимает цену хлеба, покупателей становится меньше. Если при каждом повышении на 500 сумов продаётся на 20 лепёшек в день меньше, выручка — произведение цены на количество — будет квадратным выражением. Какая цена даст нужную выручку, покажет квадратное уравнение.', '<b>Business.</b> If a small bakery raises the price of bread, customers drop off. If each 500-sum rise means 20 fewer loaves sold per day, the takings — price times quantity — form a quadratic expression. Which price gives a target income is answered by a quadratic equation.'),
      L('<b>Sport.</b> Basketbolchi to‘pni qachon va qaysi balandlikda savatga yetkazishini, futbolchi uzoq zarbada to‘p qayerga tushishini — bularning hammasi h = v<sub>0</sub>t − 5t<sup>2</sup> ko‘rinishidagi model bilan hisoblanadi.', '<b>Спорт.</b> Когда и на какой высоте мяч баскетболиста долетит до корзины, куда упадёт мяч после дальнего удара футболиста — всё это рассчитывается моделью вида h = v<sub>0</sub>t − 5t<sup>2</sup>.', '<b>Sport.</b> When and at what height a basketball reaches the hoop, or where a long football kick lands — all of this is computed with a model like h = v<sub>0</sub>t − 5t<sup>2</sup>.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('«Lilavati» kitobi shunchalik mashhur bo‘lganki, Hindistonda u bir necha asr davomida asosiy arifmetika darsligi bo‘lib xizmat qilgan va 1587-yilda fors tiliga tarjima qilingan.', 'Книга «Лилавати» была настолько популярна, что в Индии несколько веков служила основным учебником арифметики, а в 1587 году её перевели на персидский язык.', '“Lilavati” was so popular that it served as the main arithmetic textbook in India for several centuries, and in 1587 it was translated into Persian.'),
      L('Ko‘plab olimpiada masalalari aynan «tenglama tuzish» ko‘nikmasini tekshiradi: masalaning qiyin qismi yechish emas, balki to‘g‘ri modelni topishdir.', 'Многие олимпиадные задачи проверяют именно умение составить уравнение: трудная часть — не решить, а найти правильную модель.', 'Many olympiad problems test exactly the skill of forming an equation: the hard part is not solving, but finding the right model.'),
      L('Qadimgi Misrning Rind papirusida (taxminan miloddan avvalgi 1650-yil) non va pivoni taqsimlash haqida so‘zli masalalar bor — bular dunyodagi eng qadimgi «matn masalalari»dan.', 'В древнеегипетском папирусе Ринда (около 1650 г. до н. э.) есть текстовые задачи о дележе хлеба и пива — одни из древнейших «текстовых задач» в мире.', 'The ancient Egyptian Rhind Papyrus (about 1650 BC) contains word problems about sharing bread and beer — some of the oldest “word problems” in the world.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), ex: [
      { q: L('Kvadrat yuzi 81 cm<sup>2</sup>. Tomoni qancha?', 'Площадь квадрата 81 см<sup>2</sup>. Чему равна сторона?', 'A square has area 81 cm<sup>2</sup>. How long is its side?'), s: L('x<sup>2</sup> = 81, x = ±9; uzunlik musbat: 9 cm.', 'x<sup>2</sup> = 81, x = ±9; длина положительна: 9 см.', 'x<sup>2</sup> = 81, x = ±9; a length is positive: 9 cm.') },
      { q: L('Bir son ikkinchisidan 3 ga katta, ko‘paytmasi 40. Sonlarni toping.', 'Одно число на 3 больше другого, их произведение 40. Найдите числа.', 'One number is 3 more than another and their product is 40. Find them.'), s: L('x(x + 3) = 40 ⇒ x = 5 yoki −8. Ikki juft: 5 va 8 yoki −8 va −5 (shart sonlarni natural demagan).', 'x(x + 3) = 40 ⇒ x = 5 или −8. Две пары: 5 и 8 либо −8 и −5 (в условии не сказано, что числа натуральные).', 'x(x + 3) = 40 ⇒ x = 5 or −8. Two pairs: 5 and 8, or −8 and −5 (the problem did not say the numbers are natural).') },
      { q: L('Sinfdagi har bir o‘quvchi boshqa har biriga bittadan otkritka berdi, jami 600 ta. Sinfda necha o‘quvchi?', 'Каждый ученик класса подарил каждому другому по открытке, всего 600 открыток. Сколько учеников?', 'Every pupil in a class gave every other pupil a card, 600 cards in all. How many pupils?'), s: L('n(n − 1) = 600 ⇒ n = 25 (−24 yaroqsiz).', 'n(n − 1) = 600 ⇒ n = 25 (−24 не годится).', 'n(n − 1) = 600 ⇒ n = 25 (−24 is rejected).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('So‘zli masalani tenglamaga tarjima qilish — matematik model tuzish.', 'Перевод текстовой задачи в уравнение — построение математической модели.', 'Turning a word problem into an equation means building a mathematical model.'),
      L('Reja: tushunish → noma’lum → tenglama → yechish → tekshirish → javob.', 'План: понять → неизвестное → уравнение → решение → проверка → ответ.', 'Plan: understand → unknown → equation → solve → check → answer.'),
      L('Tenglamaning har bir ildizi masala javobi bo‘lavermaydi: tabiiy cheklovlarni tekshiring.', 'Не каждый корень уравнения — ответ задачи: проверяйте естественные ограничения.', 'Not every root answers the problem: check the natural restrictions.'),
      L('Javobda aynan so‘ralgan kattaliklarni birliklari bilan yozing.', 'В ответе указывайте именно искомые величины с единицами.', 'Give exactly the quantities asked for, with units.'),
      L('Bhaskara «Lilavati»da maymunlar masalasining mos kelmaydigan ildizini tashlagan.', 'Бхаскара в «Лилавати» отбросил неподходящий корень задачи об обезьянах.', 'In “Lilavati” Bhaskara rejected the unsuitable root of the monkey problem.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t17. Ma’lumotlarni tasvirlash ----------
  T.add(P, 't17', { sections: [
    { kind: 'intro', h: L('Raqamlar o‘zi gapirmaydi', 'Числа сами не говорят', 'Numbers do not speak for themselves'), p: [
      L('Sinf rahbari 30 nafar o‘quvchidan sevimli sport turini so‘radi va daftariga javoblarni ketma-ket yozib chiqdi: «futbol, shaxmat, futbol, kurash, basketbol, futbol…». Bunday uzun ro‘yxatga qarab, qaysi sport eng mashhur ekanini darhol aytish qiyin. Ammo javoblarni jadvalga yig‘ib, ustunli diagramma chizsak, hamma narsa bir qarashda ko‘rinadi.',
        'Классный руководитель спросил 30 учеников о любимом виде спорта и записал ответы подряд: «футбол, шахматы, футбол, борьба, баскетбол, футбол…». Глядя на такой длинный список, трудно сразу сказать, какой спорт самый популярный. Но если собрать ответы в таблицу и построить столбчатую диаграмму, всё видно с одного взгляда.',
        'A class teacher asked 30 pupils about their favourite sport and wrote the answers down one after another: “football, chess, football, wrestling, basketball, football…”. Looking at such a long list, it is hard to say at once which sport is most popular. But collect the answers in a table and draw a bar chart, and everything is clear at a glance.'),
      L('Bugun dunyoda har soniyada ulkan hajmda ma’lumot yig‘iladi: ob-havo, savdo, sog‘liq, sport, ijtimoiy tarmoqlar. Bu ma’lumotlarni tushunarli ko‘rinishga keltirish — <b>statistika</b> fanining birinchi vazifasi. Bu mavzuda chastotalar jadvalini tuzishni, ustunli, chiziqli va doiraviy diagrammalarni chizish va o‘qishni, shuningdek, diagramma qanday qilib aldashi mumkinligini o‘rganamiz.',
        'Сегодня в мире каждую секунду собирается огромный объём данных: погода, торговля, здоровье, спорт, социальные сети. Представить эти данные в понятном виде — первая задача <b>статистики</b>. В этой теме мы научимся составлять таблицу частот, строить и читать столбчатые, линейные и круговые диаграммы, а также узнаем, как диаграмма может обманывать.',
        'Today the world collects huge amounts of data every second: weather, trade, health, sport, social media. Presenting this data clearly is the first task of <b>statistics</b>. In this topic we learn to build a frequency table, to draw and read bar charts, line graphs and pie charts, and to spot how a chart can mislead.'),
      L('Yaxshi diagramma minglab so‘zdan ko‘ra ko‘proq narsani aytadi, yomon diagramma esa haqiqatni yashirishi mumkin.',
        'Хорошая диаграмма говорит больше тысячи слов, а плохая может скрыть правду.',
        'A good chart says more than a thousand words; a bad one can hide the truth.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key terms'), list: [
      L('<b>Ma’lumotlar</b> (dalillar) — kuzatish yoki so‘rov natijasida yig‘ilgan qiymatlar. Ular <b>sonli</b> (bo‘y, baho, harorat) yoki <b>sifatiy</b> (rang, sport turi, shahar) bo‘ladi.', '<b>Данные</b> — значения, собранные при наблюдении или опросе. Они бывают <b>числовыми</b> (рост, оценка, температура) и <b>качественными</b> (цвет, вид спорта, город).', '<b>Data</b> are values collected by observation or survey. They can be <b>numerical</b> (height, mark, temperature) or <b>categorical</b> (colour, sport, city).'),
      L('<b>Kuzatuvlar soni</b> n — jami yig‘ilgan qiymatlar soni (masalan, so‘ralgan o‘quvchilar soni).', '<b>Объём выборки</b> n — общее число собранных значений (например, число опрошенных учеников).', 'The <b>number of observations</b> n is how many values were collected in total (for example, how many pupils were asked).'),
      L('<b>Chastota</b> — biror qiymatning ma’lumotlarda necha marta uchragani. Barcha chastotalar yig‘indisi n ga teng.', '<b>Частота</b> — сколько раз значение встречается в данных. Сумма всех частот равна n.', 'The <b>frequency</b> of a value is how many times it occurs in the data. All the frequencies add up to n.'),
      L('<b>Nisbiy chastota</b> — chastotaning n ga nisbati, odatda foizda: <sup>chastota</sup>/<sub>n</sub> · 100%. Barcha nisbiy chastotalar yig‘indisi 100%.', '<b>Относительная частота</b> — отношение частоты к n, обычно в процентах: <sup>частота</sup>/<sub>n</sub> · 100%. Сумма всех относительных частот — 100%.', 'The <b>relative frequency</b> is the frequency divided by n, usually as a percentage: <sup>frequency</sup>/<sub>n</sub> · 100%. All relative frequencies add up to 100%.'),
      L('<b>Chastotalar jadvali</b> — har bir qiymat va uning chastotasi yozilgan jadval. Qiymatlar ko‘p bo‘lsa, ular <b>oraliqlarga</b> guruhlanadi (masalan, 150–155 cm, 155–160 cm).', '<b>Таблица частот</b> — таблица, где для каждого значения указана его частота. Если значений много, их группируют по <b>интервалам</b> (например, 150–155 см, 155–160 см).', 'A <b>frequency table</b> lists each value with its frequency. If there are many values, they are grouped into <b>intervals</b> (for example 150–155 cm, 155–160 cm).')
    ] },
    { kind: 'history', h: L('Tarixdan: Pleyfer va Florens Naytingeyl', 'Из истории: Плейфер и Флоренс Найтингейл', 'From history: Playfair and Florence Nightingale'), p: [
      L('Ma’lumotlarni rasm bilan ko‘rsatish g‘oyasi nisbatan yosh. Ustunli va chiziqli diagrammalarni 1786-yilda shotlandiyalik muhandis Uilyam Pleyfer Angliya savdosi haqidagi kitobida birinchi bo‘lib qo‘llagan, 1801-yilda esa u doiraviy diagrammani ham taklif qilgan. Ungacha raqamlar faqat uzun jadvallarda yozilardi.',
        'Идея изображать данные рисунком сравнительно молода. Столбчатые и линейные диаграммы впервые применил шотландский инженер Уильям Плейфер в 1786 году в книге о торговле Англии, а в 1801 году он предложил и круговую диаграмму. До этого числа записывали только в длинных таблицах.',
        'The idea of showing data as a picture is fairly young. The Scottish engineer William Playfair first used bar charts and line graphs in 1786 in a book on English trade, and in 1801 he also proposed the pie chart. Before that, numbers were only written in long tables.'),
      L('Diagrammalar kuchini dunyoga eng yorqin ko‘rsatgan inson — ingliz hamshirasi Florens Naytingeyl. Qrim urushi (1853–1856) paytida u harbiy kasalxonalarda askarlarning ko‘pchiligi jang yaralaridan emas, balki iflos sharoit va yuqumli kasalliklardan halok bo‘layotganini aniqladi. 1858-yilda u o‘limlar sabablarini oyma-oy ko‘rsatuvchi rangli «qutbiy diagramma» chizdi. Bu rasm hukumat a’zolariga quruq jadvallardan ko‘ra kuchliroq ta’sir qildi va kasalxonalarda gigiyena islohotlari boshlandi. Naytingeyl 1859-yilda Qirollik statistika jamiyatiga a’zo bo‘lgan birinchi ayol bo‘ldi.',
        'Ярче всех силу диаграмм показала миру английская медсестра Флоренс Найтингейл. Во время Крымской войны (1853–1856) она выяснила, что большинство солдат в военных госпиталях гибнут не от боевых ран, а от антисанитарии и инфекций. В 1858 году она построила цветную «полярную диаграмму», показывающую причины смертей по месяцам. Этот рисунок подействовал на членов правительства сильнее сухих таблиц, и в госпиталях начались гигиенические реформы. В 1859 году Найтингейл стала первой женщиной — членом Королевского статистического общества.',
        'The person who showed the world the power of charts most vividly was the English nurse Florence Nightingale. During the Crimean War (1853–1856) she found that most soldiers in military hospitals died not of battle wounds but of filth and infection. In 1858 she drew a coloured “polar area diagram” showing the causes of death month by month. The picture moved government ministers far more than dry tables, and hygiene reforms began in the hospitals. In 1859 Nightingale became the first woman elected to the Royal Statistical Society.')
    ] },
    { kind: 'rule', h: L('Qaysi diagrammani tanlash kerak?', 'Какую диаграмму выбрать?', 'Which chart should you choose?'), p: [
      L('<b>Ustunli diagramma</b> turli toifalarni taqqoslash uchun qulay: har bir toifaga balandligi chastotaga teng ustun chiziladi. Ustunlar bir xil kenglikda va oraliqda bo‘lishi, vertikal o‘q esa noldan boshlanishi kerak.', '<b>Столбчатая диаграмма</b> удобна для сравнения категорий: для каждой категории строится столбец высотой, равной частоте. Столбцы должны быть одинаковой ширины и с равными промежутками, а вертикальная ось — начинаться с нуля.', 'A <b>bar chart</b> is good for comparing categories: each category gets a bar whose height equals its frequency. Bars should have equal widths and gaps, and the vertical axis should start at zero.'),
      L('<b>Chiziqli diagramma</b> (grafik) vaqt bo‘yicha o‘zgarishni ko‘rsatadi: gorizontal o‘qda vaqt (kunlar, oylar, yillar), vertikal o‘qda qiymat; nuqtalar kesmalar bilan tutashtiriladi. Uning yordamida o‘sish, kamayish va tendensiyalar ko‘rinadi.', '<b>Линейная диаграмма</b> (график) показывает изменение во времени: по горизонтали — время (дни, месяцы, годы), по вертикали — значение; точки соединяют отрезками. По ней видны рост, спад и тенденции.', 'A <b>line graph</b> shows change over time: time (days, months, years) on the horizontal axis, the value on the vertical axis, with points joined by segments. It reveals rises, falls and trends.'),
      L('<b>Doiraviy diagramma</b> butunning qismlarini ko‘rsatadi. Har bir qism uchun markaziy burchak = nisbiy chastota · 360°. Masalan, 25% ga 90° to‘g‘ri keladi. Burchaklar yig‘indisi 360° bo‘lishi shart. Qismlar 5–6 tadan ko‘p bo‘lsa, doiraviy diagramma o‘qishga noqulay bo‘lib qoladi.', '<b>Круговая диаграмма</b> показывает части целого. Для каждой части центральный угол = относительная частота · 360°. Например, 25% соответствует 90°. Сумма углов обязательно 360°. Если частей больше 5–6, круговую диаграмму трудно читать.', 'A <b>pie chart</b> shows parts of a whole. For each part, the central angle = relative frequency · 360°. For instance, 25% corresponds to 90°. The angles must add up to 360°. With more than 5–6 parts, a pie chart becomes hard to read.'),
      L('<b>Gistogramma</b> — guruhlangan sonli ma’lumotlar (masalan, bo‘ylar oraliqlari) uchun ustunlar orasida bo‘shliq qoldirilmaydigan ustunli diagramma.', '<b>Гистограмма</b> — столбчатая диаграмма для сгруппированных числовых данных (например, интервалов роста), в которой столбцы стоят вплотную.', 'A <b>histogram</b> is a bar chart for grouped numerical data (such as height intervals) in which the bars touch, with no gaps.')
    ] },
    { kind: 'steps', h: L('Chastotalar jadvali va doiraviy diagramma tuzish', 'Как составить таблицу частот и круговую диаграмму', 'Building a frequency table and a pie chart'), list: [
      L('<b>1.</b> Barcha turli qiymatlarni yozib chiqing (tartiblab).', '<b>1.</b> Выпишите все различные значения (по порядку).', '<b>1.</b> List all the different values (in order).'),
      L('<b>2.</b> Ma’lumotlarni ko‘zdan kechirib, har bir qiymat uchun belgi (|) qo‘ying — har beshta belgini to‘plam qilib chizish sanashni osonlashtiradi.', '<b>2.</b> Просматривая данные, ставьте отметку (|) у каждого значения — группировка отметок по пять облегчает счёт.', '<b>2.</b> Go through the data and make a tally mark (|) for each value — grouping tallies in fives makes counting easier.'),
      L('<b>3.</b> Belgilarni sanab, chastotalarni yozing va yig‘indisi n ga tengligini tekshiring.', '<b>3.</b> Подсчитайте отметки, запишите частоты и проверьте, что их сумма равна n.', '<b>3.</b> Count the tallies, write the frequencies and check that they add up to n.'),
      L('<b>4.</b> Nisbiy chastotalarni hisoblang: chastota : n · 100%.', '<b>4.</b> Вычислите относительные частоты: частота : n · 100%.', '<b>4.</b> Work out the relative frequencies: frequency : n · 100%.'),
      L('<b>5.</b> Doiraviy diagramma uchun burchaklarni toping: chastota : n · 360°. Yig‘indini tekshiring (360°).', '<b>5.</b> Для круговой диаграммы найдите углы: частота : n · 360°. Проверьте сумму (360°).', '<b>5.</b> For a pie chart, find the angles: frequency : n · 360°. Check the total (360°).'),
      L('<b>6.</b> Diagrammaga sarlavha, o‘q nomlari va izoh (legenda) qo‘shing.', '<b>6.</b> Добавьте к диаграмме заголовок, подписи осей и легенду.', '<b>6.</b> Give the chart a title, axis labels and a key (legend).')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('20 o‘quvchining nazorat ishi baholari: 5, 4, 4, 3, 5, 4, 2, 5, 4, 3, 4, 5, 3, 4, 5, 4, 3, 5, 4, 3. Chastotalar jadvalini tuzing.', 'Оценки 20 учеников за контрольную: 5, 4, 4, 3, 5, 4, 2, 5, 4, 3, 4, 5, 3, 4, 5, 4, 3, 5, 4, 3. Составьте таблицу частот.', 'Test marks of 20 pupils: 5, 4, 4, 3, 5, 4, 2, 5, 4, 3, 4, 5, 3, 4, 5, 4, 3, 5, 4, 3. Make a frequency table.'), s: L('Sanaymiz: «5» — 6 marta, «4» — 8 marta, «3» — 5 marta, «2» — 1 marta. Tekshirish: 6 + 8 + 5 + 1 = 20 ✓. Nisbiy chastotalar: 30%, 40%, 25%, 5% (yig‘indi 100% ✓).', 'Считаем: «5» — 6 раз, «4» — 8 раз, «3» — 5 раз, «2» — 1 раз. Проверка: 6 + 8 + 5 + 1 = 20 ✓. Относительные частоты: 30%, 40%, 25%, 5% (сумма 100% ✓).', 'Counting: “5” — 6 times, “4” — 8 times, “3” — 5 times, “2” — once. Check: 6 + 8 + 5 + 1 = 20 ✓. Relative frequencies: 30%, 40%, 25%, 5% (total 100% ✓).') },
      { q: L('Shu ma’lumotlar uchun doiraviy diagramma burchaklarini toping.', 'Найдите углы круговой диаграммы для этих данных.', 'Find the pie-chart angles for this data.'), s: L('«5»: 0,30 · 360° = 108°; «4»: 0,40 · 360° = 144°; «3»: 0,25 · 360° = 90°; «2»: 0,05 · 360° = 18°. Yig‘indi: 108 + 144 + 90 + 18 = 360° ✓.', '«5»: 0,30 · 360° = 108°; «4»: 0,40 · 360° = 144°; «3»: 0,25 · 360° = 90°; «2»: 0,05 · 360° = 18°. Сумма: 108 + 144 + 90 + 18 = 360° ✓.', '“5”: 0.30 · 360° = 108°; “4”: 0.40 · 360° = 144°; “3”: 0.25 · 360° = 90°; “2”: 0.05 · 360° = 18°. Total: 108 + 144 + 90 + 18 = 360° ✓.') },
      { q: L('Haftalik o‘rtacha harorat: dush. 12°, sesh. 14°, chor. 15°, pay. 11°, juma 9°, shan. 13°, yak. 16°. Qaysi diagramma mos va nima ko‘rinadi?', 'Средняя температура за неделю: пн 12°, вт 14°, ср 15°, чт 11°, пт 9°, сб 13°, вс 16°. Какая диаграмма подходит и что видно?', 'Average temperatures for a week: Mon 12°, Tue 14°, Wed 15°, Thu 11°, Fri 9°, Sat 13°, Sun 16°. Which chart fits and what does it show?'), s: L('Vaqt bo‘yicha o‘zgarish — chiziqli diagramma. Grafikda chorshanbagacha isish, juma kuni eng sovuq (9°) pasayish va dam olish kunlari keskin isish (yakshanba 16°) ko‘rinadi. Eng katta kunlik o‘zgarish: jumadan shanbaga +4°.', 'Изменение во времени — линейная диаграмма. На графике видно потепление до среды, спад до самого холодного дня — пятницы (9°) и резкое потепление в выходные (воскресенье 16°). Наибольшее изменение за день: с пятницы на субботу, +4°.', 'Change over time calls for a line graph. It shows warming until Wednesday, a drop to the coldest day, Friday (9°), and a sharp warm-up at the weekend (Sunday 16°). The biggest one-day change is Friday to Saturday, +4°.') }
    ] },
    { kind: 'table', h: L('Diagramma turlari', 'Виды диаграмм', 'Types of chart'), table: { head: [L('Diagramma', 'Диаграмма', 'Chart'), L('Nima uchun', 'Для чего', 'Used for'), L('Misol', 'Пример', 'Example')], rows: [
      [L('Ustunli', 'Столбчатая', 'Bar chart'), L('toifalarni taqqoslash', 'сравнение категорий', 'comparing categories'), L('sevimli sport turlari', 'любимые виды спорта', 'favourite sports')],
      [L('Chiziqli', 'Линейная', 'Line graph'), L('vaqt bo‘yicha o‘zgarish', 'изменение во времени', 'change over time'), L('oylik harorat', 'температура по месяцам', 'monthly temperature')],
      [L('Doiraviy', 'Круговая', 'Pie chart'), L('butunning ulushlari', 'доли целого', 'shares of a whole'), L('oilaviy byudjet', 'семейный бюджет', 'a family budget')],
      [L('Gistogramma', 'Гистограмма', 'Histogram'), L('guruhlangan sonli ma’lumot', 'сгруппированные числовые данные', 'grouped numerical data'), L('o‘quvchilar bo‘yi', 'рост учеников', 'pupils’ heights')],
      [L('Piktogramma', 'Пиктограмма', 'Pictogram'), L('sodda, ko‘rgazmali taqqoslash', 'простое наглядное сравнение', 'simple visual comparison'), L('sotilgan muzqaymoqlar', 'проданное мороженое', 'ice creams sold')]
    ] }, after: [
      L('Gistogramma uchun oraliqlarni tanlash ham muhim. Masalan, 30 o‘quvchining bo‘yi 142 cm dan 171 cm gacha bo‘lsa, kengligi 5 cm bo‘lgan oraliqlar qulay: 140–145, 145–150, …, 170–175. Oraliqlar bir xil kenglikda bo‘lishi va bir-birini qoplamasligi kerak: chegaradagi qiymat (masalan, 145 cm) faqat bitta oraliqqa, odatda o‘ngdagisiga kiritiladi. Oraliqlar juda ko‘p bo‘lsa, diagramma «tishli taroq»ga o‘xshab qoladi, juda kam bo‘lsa — muhim tafsilotlar yo‘qoladi. Odatda 5–10 ta oraliq yetarli.', 'Для гистограммы важно и выбрать интервалы. Например, если рост 30 учеников от 142 см до 171 см, удобны интервалы шириной 5 см: 140–145, 145–150, …, 170–175. Интервалы должны быть одинаковой ширины и не перекрываться: граничное значение (например, 145 см) относят только к одному интервалу, обычно к правому. Если интервалов слишком много, диаграмма похожа на «расчёску», если слишком мало — теряются важные детали. Обычно хватает 5–10 интервалов.', 'For a histogram, choosing the intervals matters too. If 30 pupils are between 142 cm and 171 cm tall, intervals 5 cm wide work well: 140–145, 145–150, …, 170–175. Intervals must be equally wide and must not overlap: a boundary value (say 145 cm) goes into just one interval, usually the right-hand one. Too many intervals make the chart look like a comb; too few hide important detail. Usually 5–10 intervals are enough.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar va diagramma «aldovlari»', 'Типичные ошибки и «обманы» диаграмм', 'Common mistakes and misleading charts'), list: [
      L('<b>O‘q noldan boshlanmagan.</b> Agar vertikal o‘q 95 dan boshlansa, 96 va 98 qiymatlar orasidagi kichik farq ulkan ko‘rinadi. Reklamalarda bu hiyla tez-tez uchraydi.', '<b>Ось начинается не с нуля.</b> Если вертикальная ось начинается с 95, маленькая разница между 96 и 98 выглядит огромной. В рекламе этот приём встречается часто.', '<b>The axis does not start at zero.</b> If the vertical axis starts at 95, the small gap between 96 and 98 looks huge. Adverts use this trick often.'),
      L('<b>Foizlar yig‘indisi 100% emas.</b> Doiraviy diagrammada ulushlar 100% (burchaklar 360°) ga teng bo‘lmasa, unda xato bor.', '<b>Сумма процентов не 100%.</b> Если доли на круговой диаграмме не дают 100% (углы — 360°), в ней ошибка.', '<b>Percentages not adding to 100%.</b> If the shares in a pie chart do not total 100% (angles 360°), something is wrong.'),
      L('<b>Noto‘g‘ri diagramma turi.</b> Sport turlari uchun chiziqli diagramma ma’nosiz: «futbol» va «shaxmat» orasida «o‘sish» bo‘lmaydi.', '<b>Неверный вид диаграммы.</b> Линейная диаграмма для видов спорта бессмысленна: между «футболом» и «шахматами» нет «роста».', '<b>The wrong type of chart.</b> A line graph for sports makes no sense: there is no “growth” between “football” and “chess”.'),
      L('<b>Uch o‘lchamli bezaklar.</b> 3D doiraviy diagrammada oldingi bo‘laklar kattaroq ko‘rinadi va haqiqiy ulushlarni buzib ko‘rsatadi.', '<b>Трёхмерные украшения.</b> На 3D-круговой диаграмме передние секторы кажутся больше и искажают реальные доли.', '<b>3D decoration.</b> In a 3D pie chart the front slices look bigger and distort the real shares.'),
      L('<b>Sarlavha va birliklarsiz diagramma.</b> «Nima o‘lchangan va qaysi birlikda?» degan savolga javob bo‘lmasa, diagramma foydasiz.', '<b>Диаграмма без заголовка и единиц.</b> Если нет ответа на вопрос «что измерено и в каких единицах?», диаграмма бесполезна.', '<b>A chart without a title or units.</b> If it does not say what was measured and in what units, the chart is useless.')
    ] },
    { kind: 'life', h: L('Diagrammalar hayotda', 'Диаграммы в жизни', 'Charts in everyday life'), p: [
      L('<b>Sog‘liq.</b> Shifokorlar bolaning bo‘yi va vaznini o‘sish grafiklarida kuzatadi. Aqlli soat esa kunlik qadamlar va uyqu soatlarini ustunli diagrammada ko‘rsatadi — siz bir qarashda qaysi kuni kam harakat qilganingizni bilasiz.', '<b>Здоровье.</b> Врачи следят за ростом и весом ребёнка по графикам роста. Умные часы показывают шаги за день и часы сна столбчатой диаграммой — с одного взгляда видно, в какой день вы мало двигались.', '<b>Health.</b> Doctors track a child’s height and weight on growth charts. A smartwatch shows daily steps and hours of sleep as a bar chart — at a glance you see which day you moved too little.'),
      L('<b>Iqtisod va yangiliklar.</b> Valyuta kursi, narxlar va aholining o‘sishi chiziqli grafiklarda beriladi. Saylov natijalari va oilaviy xarajatlar tarkibi esa ko‘pincha doiraviy diagrammada ko‘rsatiladi.', '<b>Экономика и новости.</b> Курс валют, цены и рост населения показывают на линейных графиках. Результаты выборов и структуру семейных расходов часто показывают круговыми диаграммами.', '<b>Economics and news.</b> Exchange rates, prices and population growth are shown as line graphs. Election results and the breakdown of family spending often appear as pie charts.'),
      L('<b>Maktab loyihalari.</b> Sinfda so‘rov o‘tkazib (sevimli kitob, maktabga kelish usuli, uyqu vaqti), natijani diagramma bilan taqdim etish — statistikani amalda o‘rganishning eng yaxshi usuli.', '<b>Школьные проекты.</b> Провести опрос в классе (любимая книга, способ добраться до школы, время сна) и представить результат диаграммой — лучший способ изучить статистику на практике.', '<b>School projects.</b> Running a class survey (favourite book, how you get to school, bedtime) and presenting the results as a chart is the best way to learn statistics in practice.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('1869-yilda fransuz muhandisi Sharl Minar Napoleon armiyasining Rossiyaga yurishini bitta xaritada tasvirladi: chiziq qalinligi askarlar sonini, rangi esa yo‘nalishni ko‘rsatadi. Bu rasm hozir ham tarixdagi eng yaxshi diagrammalardan biri deb hisoblanadi.', 'В 1869 году французский инженер Шарль Минар изобразил поход армии Наполеона на Россию одной картой: толщина линии показывает число солдат, цвет — направление. Этот рисунок и сейчас считают одной из лучших диаграмм в истории.', 'In 1869 the French engineer Charles Minard drew Napoleon’s march on Russia as a single map: the width of the line shows the number of soldiers and its colour the direction. It is still considered one of the best charts ever made.'),
      L('Naytingeyl diagrammasi ko‘rinishi tufayli ba’zan «xo‘roz toji» deb ham ataladi.', 'Диаграмму Найтингейл из-за её вида иногда называют «петушиным гребнем».', 'Because of its shape, Nightingale’s diagram is sometimes called a “coxcomb”.'),
      L('Butunjahon statistika kuni har besh yilda bir marta, 20-oktabr kuni nishonlanadi (2010, 2015, 2020, 2025-yillar).', 'Всемирный день статистики отмечается раз в пять лет, 20 октября (2010, 2015, 2020, 2025 годы).', 'World Statistics Day is celebrated once every five years, on 20 October (2010, 2015, 2020, 2025).')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), ex: [
      { q: L('So‘rovda 40 kishi qatnashdi, 10 tasi «choy»ni tanladi. Doiraviy diagrammada bu qism burchagi qancha?', 'В опросе участвовали 40 человек, 10 выбрали «чай». Каков угол этого сектора на круговой диаграмме?', 'In a survey of 40 people, 10 chose “tea”. What is the angle of this slice in a pie chart?'), s: L('10 : 40 = 25%, burchak 0,25 · 360° = 90°.', '10 : 40 = 25%, угол 0,25 · 360° = 90°.', '10 : 40 = 25%, angle 0.25 · 360° = 90°.') },
      { q: L('Chastotalar: 3, 7, 5, x. Kuzatuvlar soni 20. x = ?', 'Частоты: 3, 7, 5, x. Объём выборки 20. x = ?', 'Frequencies: 3, 7, 5, x. There are 20 observations. x = ?'), s: L('3 + 7 + 5 + x = 20, x = 5.', '3 + 7 + 5 + x = 20, x = 5.', '3 + 7 + 5 + x = 20, x = 5.') },
      { q: L('Shahar aholisining 10 yil davomidagi o‘zgarishini qaysi diagramma bilan ko‘rsatgan ma’qul?', 'Какой диаграммой лучше показать изменение населения города за 10 лет?', 'Which chart best shows how a city’s population changed over 10 years?'), s: L('Chiziqli diagramma — vaqt bo‘yicha o‘zgarish.', 'Линейной — это изменение во времени.', 'A line graph — it is change over time.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Chastota — qiymat necha marta uchragani; chastotalar yig‘indisi = kuzatuvlar soni n.', 'Частота — сколько раз встречается значение; сумма частот = объём выборки n.', 'Frequency is how often a value occurs; the frequencies add up to n.'),
      L('Nisbiy chastota = chastota : n · 100%; yig‘indisi 100%.', 'Относительная частота = частота : n · 100%; их сумма 100%.', 'Relative frequency = frequency : n · 100%; they total 100%.'),
      L('Ustunli — taqqoslash, chiziqli — vaqt bo‘yicha o‘zgarish, doiraviy — ulushlar.', 'Столбчатая — сравнение, линейная — изменение во времени, круговая — доли.', 'Bar chart — comparison, line graph — change over time, pie chart — shares.'),
      L('Doiraviy diagrammada burchak = nisbiy chastota · 360°.', 'На круговой диаграмме угол = относительная частота · 360°.', 'In a pie chart, angle = relative frequency · 360°.'),
      L('O‘qlarni noldan boshlang, sarlavha va birliklarni yozing — diagramma aldamasin.', 'Начинайте оси с нуля, подписывайте заголовок и единицы — чтобы диаграмма не обманывала.', 'Start axes at zero and label the title and units, so the chart does not mislead.'),
      L('Pleyfer diagrammalarni ixtiro qildi, Naytingeyl ular yordamida minglab hayotlarni saqlab qoldi.', 'Плейфер изобрёл диаграммы, а Найтингейл с их помощью спасла тысячи жизней.', 'Playfair invented charts, and Nightingale used them to save thousands of lives.')
    ] }
  ] });

  // ---------- t18. O‘rta qiymat, moda va mediana ----------
  T.add(P, 't18', { sections: [
    { kind: 'intro', h: L('Bitta son bilan butun ma’lumotni ifodalash', 'Описать все данные одним числом', 'Describing all the data with one number'), p: [
      L('Futbol jamoasi murabbiyi «o‘yinchilarimizning o‘rtacha bo‘yi 178 cm» deydi. Maktab direktori «sinfdagi eng ko‘p uchragan baho — 4» deydi. Statistika idorasi esa «aholining yarmi 30 yoshdan kichik» deb e’lon qiladi. Bu uch gapda uch xil son ishlatilgan: <b>o‘rta qiymat</b>, <b>moda</b> va <b>mediana</b>. Ularning hammasi bitta savolga javob beradi: ma’lumotlarning «markazi», «odatiy qiymati» qayerda?',
        'Тренер футбольной команды говорит: «средний рост наших игроков — 178 см». Директор школы говорит: «самая частая оценка в классе — 4». Статистическое управление сообщает: «половина населения моложе 30 лет». В этих трёх фразах использованы три разных числа: <b>среднее</b>, <b>мода</b> и <b>медиана</b>. Все они отвечают на один вопрос: где «центр» данных, какое значение «типичное»?',
        'A football coach says “our players’ average height is 178 cm”. A head teacher says “the most common mark in the class is 4”. The statistics office announces “half the population is under 30”. These three statements use three different numbers: the <b>mean</b>, the <b>mode</b> and the <b>median</b>. They all answer one question: where is the “centre” of the data, what value is “typical”?'),
      L('Nega bitta o‘rtacha yetarli emas? Chunki har bir o‘lchov o‘ziga xos kuchli va zaif tomonlarga ega. Masalan, kichik firmada to‘rt ishchi oyiga 4 mln so‘mdan, direktor esa 36 mln so‘m olsa, «o‘rtacha maosh 10 mln so‘m» degan gap to‘g‘ri, lekin juda aldamchi: aslida hech bir ishchi bunday maosh olmaydi. Bu mavzuda har bir o‘lchovni qachon ishlatish kerakligini o‘rganamiz.',
        'Почему одного среднего недостаточно? Потому что у каждой меры свои сильные и слабые стороны. Например, если в маленькой фирме четыре работника получают по 4 млн сумов в месяц, а директор — 36 млн, то фраза «средняя зарплата 10 млн сумов» верна, но очень обманчива: на самом деле никто из работников столько не получает. В этой теме мы узнаем, когда какую меру использовать.',
        'Why is one average not enough? Because each measure has its own strengths and weaknesses. For example, if in a small firm four workers earn 4 million sum a month and the director earns 36 million, then “the average salary is 10 million sum” is true but very misleading: in fact no worker earns that much. In this topic we learn when to use which measure.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), list: [
      L('<b>O‘rta arifmetik qiymat</b> (o‘rtacha) — barcha qiymatlar yig‘indisining ular soniga nisbati: x̄ = (x<sub>1</sub> + x<sub>2</sub> + … + x<sub>n</sub>) : n.', '<b>Среднее арифметическое</b> (среднее) — отношение суммы всех значений к их количеству: x̄ = (x<sub>1</sub> + x<sub>2</sub> + … + x<sub>n</sub>) : n.', 'The <b>arithmetic mean</b> (average) is the sum of all values divided by how many there are: x̄ = (x<sub>1</sub> + x<sub>2</sub> + … + x<sub>n</sub>) : n.'),
      L('<b>Moda</b> — ma’lumotlarda eng ko‘p uchraydigan qiymat. Modalar bir nechta bo‘lishi yoki umuman bo‘lmasligi mumkin (barcha qiymatlar bir martadan uchrasa).', '<b>Мода</b> — значение, которое встречается в данных чаще всего. Мод может быть несколько или не быть вовсе (если все значения встречаются по одному разу).', 'The <b>mode</b> is the value that occurs most often. There may be several modes, or none at all (if every value occurs once).'),
      L('<b>Mediana</b> — o‘sish tartibida joylashtirilgan qatorning o‘rtasidagi qiymat. n toq bo‘lsa — aynan o‘rtadagi son (<sup>(n + 1)</sup>/<sub>2</sub>-o‘rindagi), n juft bo‘lsa — o‘rtadagi ikki sonning o‘rta arifmetigi.', '<b>Медиана</b> — значение в середине ряда, упорядоченного по возрастанию. Если n нечётно — ровно среднее число (на месте <sup>(n + 1)</sup>/<sub>2</sub>), если n чётно — среднее арифметическое двух средних чисел.', 'The <b>median</b> is the middle value of the list sorted in increasing order. If n is odd, it is the exact middle number (in position <sup>(n + 1)</sup>/<sub>2</sub>); if n is even, it is the mean of the two middle numbers.'),
      L('<b>Qator kengligi</b> (размах) — eng katta va eng kichik qiymatlar ayirmasi. U ma’lumotlarning qanchalik «tarqoq» ekanini ko‘rsatadi.', '<b>Размах</b> — разность наибольшего и наименьшего значений. Он показывает, насколько данные «разбросаны».', 'The <b>range</b> is the difference between the largest and smallest values. It shows how spread out the data are.')
    ], after: [
      L('Masalan, 2, 3, 3, 7, 10 qatori uchun: o‘rtacha (2 + 3 + 3 + 7 + 10) : 5 = 25 : 5 = 5; moda 3 (ikki marta uchraydi); mediana 3 (beshta sonning uchinchisi); qator kengligi 10 − 2 = 8.', 'Например, для ряда 2, 3, 3, 7, 10: среднее (2 + 3 + 3 + 7 + 10) : 5 = 25 : 5 = 5; мода 3 (встречается дважды); медиана 3 (третье из пяти чисел); размах 10 − 2 = 8.', 'For example, for 2, 3, 3, 7, 10: mean (2 + 3 + 3 + 7 + 10) : 5 = 25 : 5 = 5; mode 3 (it appears twice); median 3 (the third of five numbers); range 10 − 2 = 8.')
    ] },
    { kind: 'history', h: L('Tarixdan: astronomlar va «olomon donoligi»', 'Из истории: астрономы и «мудрость толпы»', 'From history: astronomers and the “wisdom of crowds”'), p: [
      L('O‘rtachani birinchi bo‘lib muntazam ishlatganlar astronomlar edi. Ular bitta yulduz holatini bir necha marta o‘lchab, natijalar biroz farq qilishini ko‘rishgan. Qaysi birini tanlash kerak? Asta-sekin o‘lchovlarning o‘rtachasini olish eng ishonchli yo‘l ekani tushunildi: tasodifiy xatolar bir-birini qisman yo‘qqa chiqaradi. Abu Rayhon Beruniy ham o‘z asarlarida takroriy kuzatishlar va ehtiyotkor hisob-kitobga katta e’tibor bergan, XVI asrda daniyalik Tixo Brage esa takroriy o‘lchovlarni birlashtirishni odatiy usulga aylantirgan.',
        'Первыми систематически использовали среднее астрономы. Измеряя положение одной звезды несколько раз, они видели, что результаты немного различаются. Какой выбрать? Постепенно поняли, что надёжнее всего брать среднее измерений: случайные ошибки частично гасят друг друга. Абу Райхан Бируни в своих трудах уделял большое внимание повторным наблюдениям и тщательным расчётам, а в XVI веке датчанин Тихо Браге сделал объединение повторных измерений обычной практикой.',
        'Astronomers were the first to use the mean systematically. Measuring the position of a star several times, they saw that the results differed slightly. Which one to choose? Gradually they realised that taking the average of the measurements is most reliable, because random errors partly cancel out. Abu Rayhan al-Biruni paid great attention in his works to repeated observation and careful calculation, and in the 16th century the Dane Tycho Brahe made combining repeated measurements standard practice.'),
      L('1907-yilda ingliz olimi Frensis Golton qishloq yarmarkasida qiziq tajriba haqida yozdi. Taxminan 800 kishi so‘yilgan buqaning go‘shti qancha tortishini taxmin qilgan. Har bir alohida taxmin ko‘pincha noto‘g‘ri edi, ammo barcha taxminlarning <b>medianasi</b> — 1207 funt — haqiqiy og‘irlikdan (1198 funt) bor-yo‘g‘i 1% ga farq qilgan! Golton medianani tanlagan, chunki u juda g‘alati taxminlarga (masalan, hazil uchun aytilgan raqamlarga) kam ta’sirlanadi. Bu hodisa keyinchalik «olomon donoligi» deb ataldi.',
        'В 1907 году английский учёный Фрэнсис Гальтон описал любопытный опыт на сельской ярмарке. Около 800 человек угадывали, сколько будет весить мясо забитого быка. Отдельные догадки часто были неверны, но <b>медиана</b> всех догадок — 1207 фунтов — отличалась от настоящего веса (1198 фунтов) меньше чем на 1%! Гальтон выбрал медиану, потому что на неё мало влияют странные догадки (например, названные в шутку). Позже это явление назвали «мудростью толпы».',
        'In 1907 the English scientist Francis Galton wrote about a curious experiment at a country fair. About 800 people guessed how much the meat of a slaughtered ox would weigh. Individual guesses were often wrong, but the <b>median</b> of all the guesses — 1207 pounds — was within 1% of the true weight (1198 pounds)! Galton chose the median because it is barely affected by wild guesses (such as joke answers). The effect later became known as the “wisdom of crowds”.')
    ] },
    { kind: 'rule', h: L('Hisoblash qoidalari va xossalar', 'Правила вычисления и свойства', 'Rules and properties'), p: [
      L('<b>Chastotalar jadvalidan o‘rtacha.</b> Agar x<sub>1</sub> qiymat f<sub>1</sub> marta, x<sub>2</sub> qiymat f<sub>2</sub> marta va hokazo uchrasa, x̄ = (x<sub>1</sub>f<sub>1</sub> + x<sub>2</sub>f<sub>2</sub> + …) : (f<sub>1</sub> + f<sub>2</sub> + …). Bu <b>tortilgan o‘rtacha</b> deyiladi: har bir qiymat necha marta uchrasa, shuncha «vazn» bilan qatnashadi.', '<b>Среднее по таблице частот.</b> Если значение x<sub>1</sub> встречается f<sub>1</sub> раз, x<sub>2</sub> — f<sub>2</sub> раз и т. д., то x̄ = (x<sub>1</sub>f<sub>1</sub> + x<sub>2</sub>f<sub>2</sub> + …) : (f<sub>1</sub> + f<sub>2</sub> + …). Это <b>взвешенное среднее</b>: каждое значение входит с «весом», равным его частоте.', '<b>Mean from a frequency table.</b> If value x<sub>1</sub> occurs f<sub>1</sub> times, x<sub>2</sub> occurs f<sub>2</sub> times and so on, then x̄ = (x<sub>1</sub>f<sub>1</sub> + x<sub>2</sub>f<sub>2</sub> + …) : (f<sub>1</sub> + f<sub>2</sub> + …). This is the <b>weighted mean</b>: each value counts with a “weight” equal to its frequency.'),
      L('<b>O‘rtachaning xossalari.</b> Agar barcha qiymatlarga bir xil c son qo‘shilsa, o‘rtacha ham c ga ortadi; barcha qiymatlar k marta oshirilsa, o‘rtacha ham k marta oshadi. Qiymatlarning o‘rtachadan chetlanishlari yig‘indisi doimo nolga teng: (x<sub>1</sub> − x̄) + … + (x<sub>n</sub> − x̄) = 0. Shuning uchun o‘rtacha — ma’lumotlarning «muvozanat nuqtasi».', '<b>Свойства среднего.</b> Если ко всем значениям прибавить одно и то же число c, среднее тоже увеличится на c; если все значения увеличить в k раз, среднее увеличится в k раз. Сумма отклонений значений от среднего всегда равна нулю: (x<sub>1</sub> − x̄) + … + (x<sub>n</sub> − x̄) = 0. Поэтому среднее — «точка равновесия» данных.', '<b>Properties of the mean.</b> If the same number c is added to every value, the mean also increases by c; if every value is multiplied by k, so is the mean. The deviations from the mean always add up to zero: (x<sub>1</sub> − x̄) + … + (x<sub>n</sub> − x̄) = 0. That is why the mean is the “balance point” of the data.'),
      L('<b>Chetga chiqqan qiymatlar.</b> Boshqalardan keskin farq qiladigan qiymat o‘rtachani kuchli siljitadi, mediana va modaga esa deyarli ta’sir qilmaydi. Shuning uchun maosh, uy narxi kabi ma’lumotlarda ko‘pincha mediana beriladi. Moda esa sifatiy ma’lumotlar uchun yagona mos o‘lchov: «eng mashhur rang» uchun o‘rtacha hisoblab bo‘lmaydi.', '<b>Выбросы.</b> Значение, резко отличающееся от остальных, сильно сдвигает среднее, но почти не влияет на медиану и моду. Поэтому для зарплат, цен на жильё и т. п. часто указывают медиану. А мода — единственная подходящая мера для качественных данных: для «самого популярного цвета» среднее не посчитать.', '<b>Outliers.</b> A value far from the others shifts the mean a lot but hardly affects the median or mode. That is why the median is often quoted for salaries, house prices and the like. The mode is the only suitable measure for categorical data: you cannot average “the most popular colour”.')
    ] },
    { kind: 'steps', h: L('Medianani topish tartibi', 'Как найти медиану', 'How to find the median'), list: [
      L('<b>1.</b> Qiymatlarni o‘sish tartibida yozing (takrorlanganlarini ham!).', '<b>1.</b> Запишите значения по возрастанию (включая повторяющиеся!).', '<b>1.</b> Write the values in increasing order (including repeats!).'),
      L('<b>2.</b> Qiymatlar sonini n ni sanang.', '<b>2.</b> Подсчитайте число значений n.', '<b>2.</b> Count the number of values n.'),
      L('<b>3.</b> n toq bo‘lsa, mediana — <sup>(n + 1)</sup>/<sub>2</sub>-o‘rindagi son.', '<b>3.</b> Если n нечётно, медиана — число на месте <sup>(n + 1)</sup>/<sub>2</sub>.', '<b>3.</b> If n is odd, the median is the number in position <sup>(n + 1)</sup>/<sub>2</sub>.'),
      L('<b>4.</b> n juft bo‘lsa, <sup>n</sup>/<sub>2</sub>- va (<sup>n</sup>/<sub>2</sub> + 1)-o‘rindagi sonlarning o‘rta arifmetigini oling.', '<b>4.</b> Если n чётно, возьмите среднее арифметическое чисел на местах <sup>n</sup>/<sub>2</sub> и <sup>n</sup>/<sub>2</sub> + 1.', '<b>4.</b> If n is even, take the mean of the numbers in positions <sup>n</sup>/<sub>2</sub> and <sup>n</sup>/<sub>2</sub> + 1.'),
      L('<b>5.</b> Tekshiring: medianadan chapda va o‘ngda qiymatlar soni teng bo‘lishi kerak.', '<b>5.</b> Проверьте: слева и справа от медианы должно быть поровну значений.', '<b>5.</b> Check: there should be as many values to the left of the median as to the right.')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('4, 8, 1, 6, 9, 2 qatorning o‘rtachasi, medianasi va qator kengligini toping.', 'Найдите среднее, медиану и размах ряда 4, 8, 1, 6, 9, 2.', 'Find the mean, median and range of 4, 8, 1, 6, 9, 2.'), s: L('Yig‘indi 30, n = 6, o‘rtacha 5. Tartiblaymiz: 1, 2, 4, 6, 8, 9. n juft, o‘rtadagilar 4 va 6, mediana (4 + 6) : 2 = 5. Kenglik 9 − 1 = 8. Moda yo‘q.', 'Сумма 30, n = 6, среднее 5. Упорядочим: 1, 2, 4, 6, 8, 9. n чётно, средние числа 4 и 6, медиана (4 + 6) : 2 = 5. Размах 9 − 1 = 8. Моды нет.', 'Sum 30, n = 6, mean 5. Sorted: 1, 2, 4, 6, 8, 9. n is even; the middle numbers are 4 and 6, so the median is (4 + 6) : 2 = 5. Range 9 − 1 = 8. There is no mode.') },
      { q: L('Baholar jadvali: «5» — 6, «4» — 8, «3» — 5, «2» — 1 (20 o‘quvchi). O‘rtacha, moda va medianani toping.', 'Таблица оценок: «5» — 6, «4» — 8, «3» — 5, «2» — 1 (20 учеников). Найдите среднее, моду и медиану.', 'Mark table: “5” — 6, “4” — 8, “3” — 5, “2” — 1 (20 pupils). Find the mean, mode and median.'), s: L('O‘rtacha = (5 · 6 + 4 · 8 + 3 · 5 + 2 · 1) : 20 = 79 : 20 = 3,95. Moda 4 (eng katta chastota 8). Mediana: tartiblangan qatorda 10- va 11-o‘rindagi sonlar. Boshidan: «2» — 1-o‘rin, «3» — 2–6, «4» — 7–14. Ikkalasi ham 4, mediana 4.', 'Среднее = (5 · 6 + 4 · 8 + 3 · 5 + 2 · 1) : 20 = 79 : 20 = 3,95. Мода 4 (наибольшая частота 8). Медиана: в упорядоченном ряду числа на 10-м и 11-м местах. С начала: «2» — 1-е место, «3» — 2–6, «4» — 7–14. Оба числа равны 4, медиана 4.', 'Mean = (5 · 6 + 4 · 8 + 3 · 5 + 2 · 1) : 20 = 79 : 20 = 3.95. Mode 4 (highest frequency, 8). Median: positions 10 and 11 of the sorted list. From the start: “2” — position 1, “3” — 2–6, “4” — 7–14. Both are 4, so the median is 4.') },
      { q: L('Firmada maoshlar (mln so‘m): 4, 4, 4, 4, 36. Qaysi o‘lchov «odatiy» maoshni yaxshiroq ko‘rsatadi?', 'Зарплаты в фирме (млн сумов): 4, 4, 4, 4, 36. Какая мера лучше показывает «типичную» зарплату?', 'Salaries in a firm (million sum): 4, 4, 4, 4, 36. Which measure better shows the “typical” salary?'), s: L('O‘rtacha = 52 : 5 = 10,4 — hech kimning maoshiga yaqin emas. Mediana = 4, moda = 4 — odatiy ishchi maoshini to‘g‘ri ko‘rsatadi. 36 — chetga chiqqan qiymat.', 'Среднее = 52 : 5 = 10,4 — ни у кого нет такой зарплаты. Медиана = 4, мода = 4 — верно показывают типичную зарплату. 36 — выброс.', 'Mean = 52 : 5 = 10.4 — close to nobody’s salary. Median = 4 and mode = 4 correctly show a typical worker’s pay. 36 is an outlier.') },
      { q: L('Besh nazorat ishining o‘rtacha bahosi 4. To‘rttasi 3, 4, 5, 4. Beshinchisi qancha?', 'Средняя оценка за пять контрольных — 4. Четыре из них 3, 4, 5, 4. Какова пятая?', 'The mean of five test marks is 4. Four of them are 3, 4, 5, 4. What is the fifth?'), s: L('Yig‘indi 5 · 4 = 20 bo‘lishi kerak. 3 + 4 + 5 + 4 = 16, demak, beshinchisi 20 − 16 = 4.', 'Сумма должна быть 5 · 4 = 20. 3 + 4 + 5 + 4 = 16, значит, пятая оценка 20 − 16 = 4.', 'The total must be 5 · 4 = 20. 3 + 4 + 5 + 4 = 16, so the fifth mark is 20 − 16 = 4.') }
    ] },
    { kind: 'table', h: L('Uchta o‘lchovni taqqoslash', 'Сравнение трёх мер', 'Comparing the three measures'), table: { head: [L('O‘lchov', 'Мера', 'Measure'), L('Afzalligi', 'Достоинство', 'Strength'), L('Kamchiligi', 'Недостаток', 'Weakness'), L('Qachon qulay', 'Когда удобна', 'Best for')], rows: [
      [L('O‘rtacha', 'Среднее', 'Mean'), L('barcha qiymatlarni hisobga oladi', 'учитывает все значения', 'uses every value'), L('chetga chiqqan qiymatga sezgir', 'чувствительно к выбросам', 'sensitive to outliers'), L('baholar, harorat, o‘lchovlar', 'оценки, температура, измерения', 'marks, temperatures, measurements')],
      [L('Mediana', 'Медиана', 'Median'), L('chetga chiqqan qiymatga chidamli', 'устойчива к выбросам', 'resistant to outliers'), L('tartiblash kerak', 'нужно упорядочивать', 'needs sorting'), L('maosh, uy narxlari', 'зарплаты, цены жилья', 'salaries, house prices')],
      [L('Moda', 'Мода', 'Mode'), L('sifatiy ma’lumotda ham ishlaydi', 'работает и для качественных данных', 'works for categorical data'), L('bir nechta yoki yo‘q bo‘lishi mumkin', 'может быть несколько или не быть', 'may be several or none'), L('kiyim o‘lchami, mashhur tanlov', 'размер одежды, популярный выбор', 'clothing sizes, popular choice')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Tartiblamay mediana olish.</b> 7, 1, 9 qatori uchun mediana 1 emas: tartiblab 1, 7, 9 → mediana 7.', '<b>Брать медиану без упорядочивания.</b> Для ряда 7, 1, 9 медиана не 1: упорядочим 1, 7, 9 → медиана 7.', '<b>Taking the median without sorting.</b> For 7, 1, 9 the median is not 1: sorted, 1, 7, 9 → the median is 7.'),
      L('<b>Takrorlanuvchi qiymatlarni bir marta yozish.</b> 2, 3, 3, 7, 10 ni «2, 3, 7, 10» deb qisqartirish medianani ham, o‘rtachani ham buzadi.', '<b>Записывать повторы один раз.</b> Сократить 2, 3, 3, 7, 10 до «2, 3, 7, 10» — значит исказить и медиану, и среднее.', '<b>Writing repeated values once.</b> Shortening 2, 3, 3, 7, 10 to “2, 3, 7, 10” spoils both the median and the mean.'),
      L('<b>Modani chastota bilan adashtirish.</b> «4» baho 8 marta uchrasa, moda 4, 8 emas.', '<b>Путать моду с частотой.</b> Если оценка «4» встречается 8 раз, мода — 4, а не 8.', '<b>Confusing the mode with its frequency.</b> If the mark “4” occurs 8 times, the mode is 4, not 8.'),
      L('<b>Jadvaldan o‘rtachani noto‘g‘ri hisoblash.</b> (5 + 4 + 3 + 2) : 4 = 3,5 — xato; chastotalarni hisobga olish kerak: 79 : 20 = 3,95.', '<b>Неверно считать среднее по таблице.</b> (5 + 4 + 3 + 2) : 4 = 3,5 — ошибка; нужно учитывать частоты: 79 : 20 = 3,95.', '<b>Averaging a table wrongly.</b> (5 + 4 + 3 + 2) : 4 = 3.5 is wrong; the frequencies must be used: 79 : 20 = 3.95.'),
      L('<b>Juft n da bitta o‘rta sonni olish.</b> 1, 2, 4, 6, 8, 9 uchun mediana 4 ham, 6 ham emas, balki 5.', '<b>При чётном n брать одно среднее число.</b> Для 1, 2, 4, 6, 8, 9 медиана не 4 и не 6, а 5.', '<b>Taking just one middle number when n is even.</b> For 1, 2, 4, 6, 8, 9 the median is neither 4 nor 6, but 5.')
    ] },
    { kind: 'life', h: L('O‘rtacha ko‘rsatkichlar hayotda', 'Средние показатели в жизни', 'Averages in real life'), p: [
      L('<b>Ta’lim.</b> Choraklik baho ko‘pincha joriy baholarning o‘rtachasi asosida qo‘yiladi. Agar sizda 5, 5, 4, 3 bo‘lsa, o‘rtacha 4,25 — bitta yaxshi baho natijani sezilarli yaxshilashi mumkin. Oldindan hisoblab, qaysi baho kerakligini bilib olish mumkin.', '<b>Учёба.</b> Четвертная оценка часто ставится по среднему текущих оценок. Если у вас 5, 5, 4, 3, среднее 4,25 — одна хорошая оценка может заметно улучшить результат. Можно заранее рассчитать, какая оценка нужна.', '<b>School.</b> A term grade is often based on the mean of your marks. With 5, 5, 4, 3 the mean is 4.25 — one more good mark can raise it noticeably. You can work out in advance which mark you need.'),
      L('<b>Savdo.</b> Kiyim do‘koni egasi uchun o‘rtacha o‘lcham emas, balki <b>moda</b> muhim: eng ko‘p sotiladigan o‘lchamdagi ko‘ylakdan ko‘proq olib kelish kerak. «O‘rtacha oyoq kiyimi o‘lchami 38,7» — foydasiz ma’lumot, chunki bunday o‘lcham yo‘q.', '<b>Торговля.</b> Владельцу магазина одежды важен не средний размер, а <b>мода</b>: рубашек самого ходового размера надо завезти больше. «Средний размер обуви 38,7» — бесполезная информация, такого размера нет.', '<b>Retail.</b> For a clothes shop owner the <b>mode</b> matters, not the mean: stock more shirts in the best-selling size. “The average shoe size is 38.7” is useless — no such size exists.'),
      L('<b>Iqtisod va ob-havo.</b> Davlat statistikasi aholining median daromadini e’lon qiladi, chunki bir nechta juda boy odamlar o‘rtachani sun’iy ravishda oshiradi. Ob-havo ma’lumotlarida esa «iyulning o‘rtacha harorati» ko‘p yillik o‘lchovlarning o‘rtachasi sifatida hisoblanadi.', '<b>Экономика и погода.</b> Государственная статистика публикует медианный доход населения, ведь несколько очень богатых людей искусственно завышают среднее. А в сводках погоды «средняя температура июля» — среднее многолетних измерений.', '<b>Economics and weather.</b> National statistics report median income, because a few very rich people inflate the mean artificially. In weather records, “the average July temperature” is the mean of many years of measurements.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Deyarli barcha odamlarning oyoqlari soni «o‘rtachadan ko‘p»! Chunki ba’zi odamlar oyog‘ini yo‘qotgan, shuning uchun o‘rtacha 2 dan biroz kam, ko‘pchilikda esa 2 ta oyoq bor. Moda va mediana esa aniq 2.', 'Почти у всех людей «больше среднего» ног! Ведь некоторые люди лишились ноги, поэтому среднее чуть меньше 2, а у большинства ног две. Мода и медиана при этом ровно 2.', 'Almost everyone has “more than the average” number of legs! Because some people have lost a leg, the mean is slightly below 2, while most people have two. The mode and median are exactly 2.'),
      L('Golton tajribasidan keyin ko‘plab tadqiqotlar ko‘rsatdiki, katta guruhning medianaviy taxmini ko‘pincha alohida ekspert taxminidan aniqroq bo‘ladi.', 'После опыта Гальтона многие исследования показали, что медианная догадка большой группы часто точнее догадки отдельного эксперта.', 'Since Galton’s experiment, many studies have shown that a large group’s median guess is often more accurate than a single expert’s.'),
      L('«Mediana» so‘zi lotincha medius — «o‘rtadagi» so‘zidan olingan.', 'Слово «медиана» происходит от латинского medius — «средний».', 'The word “median” comes from the Latin medius, “middle”.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), ex: [
      { q: L('4, 4, 5, 6, 4 — moda va mediana?', '4, 4, 5, 6, 4 — мода и медиана?', '4, 4, 5, 6, 4 — mode and median?'), s: L('Moda 4. Tartiblaymiz: 4, 4, 4, 5, 6 — mediana 4.', 'Мода 4. Упорядочим: 4, 4, 4, 5, 6 — медиана 4.', 'Mode 4. Sorted: 4, 4, 4, 5, 6 — median 4.') },
      { q: L('1, 2, 3, 4 — mediana?', '1, 2, 3, 4 — медиана?', '1, 2, 3, 4 — median?'), s: L('(2 + 3) : 2 = 2,5.', '(2 + 3) : 2 = 2,5.', '(2 + 3) : 2 = 2.5.') },
      { q: L('10, 12, 14 qatorining har bir soniga 5 qo‘shildi. Yangi o‘rtacha?', 'К каждому числу ряда 10, 12, 14 прибавили 5. Новое среднее?', '5 is added to each of 10, 12, 14. What is the new mean?'), s: L('Eski o‘rtacha 12, yangisi 12 + 5 = 17.', 'Старое среднее 12, новое 12 + 5 = 17.', 'The old mean is 12; the new one is 12 + 5 = 17.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('O‘rtacha = yig‘indi : soni; jadvaldan — tortilgan o‘rtacha.', 'Среднее = сумма : количество; по таблице — взвешенное среднее.', 'Mean = sum : count; from a table, use the weighted mean.'),
      L('Moda — eng ko‘p uchraydigan qiymat; sifatiy ma’lumotlar uchun ham ishlaydi.', 'Мода — самое частое значение; работает и для качественных данных.', 'Mode — the most frequent value; it works for categorical data too.'),
      L('Mediana — tartiblangan qatorning o‘rtasi; juft n da ikki o‘rta sonning o‘rtachasi.', 'Медиана — середина упорядоченного ряда; при чётном n — среднее двух средних чисел.', 'Median — the middle of the sorted list; for even n, the mean of the two middle numbers.'),
      L('Chetga chiqqan qiymatlar o‘rtachani siljitadi, medianani deyarli o‘zgartirmaydi.', 'Выбросы сдвигают среднее, но почти не меняют медиану.', 'Outliers shift the mean but barely move the median.'),
      L('Qator kengligi = eng katta − eng kichik qiymat.', 'Размах = наибольшее − наименьшее значение.', 'Range = largest − smallest value.'),
      L('Golton tajribasi: ko‘pchilik taxminlarining medianasi haqiqatga juda yaqin bo‘ladi.', 'Опыт Гальтона: медиана догадок многих людей очень близка к истине.', 'Galton’s experiment: the median of many guesses is very close to the truth.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '8-1';

  // ---------- t19. Kombinatorikaning asosiy qoidasi. Tanlash usuli ----------
  T.add(P, 't19', { sections: [
    { kind: 'intro', h: L('Nechta usul bor?', 'Сколько существует способов?', 'How many ways are there?'), p: [
      L('Ertalab shkafingizda 3 ta ko‘ylak va 4 ta shim bor. Nechta turli kiyim to‘plamini tuzish mumkin? Telefon paroli 4 ta raqamdan iborat bo‘lsa, nechta turli parol bor? Sinfdagi 25 o‘quvchidan sardor va uning o‘rinbosarini necha usulda tanlash mumkin? Bunday savollarga javob beradigan matematika bo‘limi <b>kombinatorika</b> deyiladi — u «sanamasdan sanash» san’atidir.',
        'Утром в шкафу у вас 3 рубашки и 4 пары брюк. Сколько разных комплектов одежды можно составить? Если пароль телефона состоит из 4 цифр, сколько существует разных паролей? Сколькими способами можно выбрать из 25 учеников класса старосту и его заместителя? Раздел математики, отвечающий на такие вопросы, называется <b>комбинаторикой</b> — это искусство «считать, не перечисляя».',
        'In the morning your wardrobe holds 3 shirts and 4 pairs of trousers. How many different outfits can you make? If a phone PIN has 4 digits, how many different PINs are there? In how many ways can a class of 25 choose a captain and a vice-captain? The branch of mathematics that answers such questions is called <b>combinatorics</b> — the art of “counting without listing”.'),
      L('Kichik masalalarda barcha variantlarni birma-bir yozib chiqish mumkin. Ammo variantlar soni tez o‘sadi: 10 ta kitobni javonga 3 628 800 usulda terish mumkin! Bunday sonlarni ro‘yxat bilan sanab bo‘lmaydi. Shuning uchun bu mavzuda ikki narsani o‘rganamiz: variantlarni <b>tartibli ro‘yxat</b> va <b>daraxt</b> yordamida hech birini o‘tkazib yubormasdan sanash hamda katta sonlarni tez hisoblaydigan <b>ko‘paytirish qoidasi</b>.',
        'В небольших задачах можно выписать все варианты по одному. Но число вариантов растёт очень быстро: 10 книг можно расставить на полке 3 628 800 способами! Такие числа перечислением не сосчитать. Поэтому в этой теме мы изучим две вещи: как перебирать варианты с помощью <b>упорядоченного списка</b> и <b>дерева</b>, ничего не пропуская, и <b>правило произведения</b>, которое быстро считает большие количества.',
        'In small problems you can write out every option one by one. But the number of options grows very fast: 10 books can be arranged on a shelf in 3,628,800 ways! Numbers like that cannot be counted by listing. So in this topic we learn two things: how to list options systematically with an <b>ordered list</b> and a <b>tree</b> so that nothing is missed, and the <b>multiplication rule</b>, which counts large numbers quickly.')
    ] },
    { kind: 'def', h: L('Asosiy qoidalar va tushunchalar', 'Основные правила и понятия', 'Basic rules and ideas'), list: [
      L('<b>Ko‘paytirish qoidasi.</b> Agar birinchi tanlovni m usulda, undan keyin (har qanday birinchi tanlovdan so‘ng) ikkinchi tanlovni n usulda qilish mumkin bo‘lsa, ikkalasini birga ketma-ket m · n usulda qilish mumkin. Qoida istalgan sondagi bosqichlar uchun ham o‘rinli: m · n · k · …', '<b>Правило произведения.</b> Если первый выбор можно сделать m способами, а после него (при любом первом выборе) второй — n способами, то оба выбора подряд можно сделать m · n способами. Правило верно и для любого числа шагов: m · n · k · …', '<b>Multiplication rule.</b> If a first choice can be made in m ways and then (after any first choice) a second in n ways, the two together can be made in m · n ways. The rule works for any number of stages: m · n · k · …'),
      L('<b>Qo‘shish qoidasi.</b> Agar tanlov yo birinchi guruhdan (m usul), yo ikkinchi guruhdan (n usul) qilinsa va guruhlar kesishmasa, jami m + n usul bor. «Va» — ko‘paytirish, «yoki» — qo‘shish.', '<b>Правило суммы.</b> Если выбор делается либо из первой группы (m способов), либо из второй (n способов), и группы не пересекаются, всего m + n способов. «И» — умножение, «или» — сложение.', '<b>Addition rule.</b> If a choice is made either from a first group (m ways) or from a second group (n ways), and the groups do not overlap, there are m + n ways in total. “And” means multiply, “or” means add.'),
      L('<b>O‘rin almashtirishlar.</b> n ta turli narsani qatorga terish usullari soni n! = 1 · 2 · 3 · … · n («en faktorial»). Kelishuv bo‘yicha 0! = 1.', '<b>Перестановки.</b> Число способов расставить в ряд n различных предметов: n! = 1 · 2 · 3 · … · n («эн факториал»). По соглашению 0! = 1.', '<b>Permutations.</b> The number of ways to arrange n different objects in a row is n! = 1 · 2 · 3 · … · n (“n factorial”). By convention, 0! = 1.'),
      L('<b>Tartibli tanlash (o‘rinlashtirish).</b> n ta narsadan k tasini tartib bilan tanlash: A<sub>n</sub><sup>k</sup> = n(n − 1)(n − 2)…(n − k + 1) — k ta ko‘paytuvchi.', '<b>Упорядоченный выбор (размещения).</b> Выбрать k предметов из n с учётом порядка: A<sub>n</sub><sup>k</sup> = n(n − 1)(n − 2)…(n − k + 1) — k множителей.', '<b>Ordered selection (arrangements).</b> Choosing k of n objects where order matters: A<sub>n</sub><sup>k</sup> = n(n − 1)(n − 2)…(n − k + 1) — k factors.'),
      L('<b>Tartibsiz juftliklar.</b> n ta narsadan 2 tasini tartibsiz tanlash: C<sub>n</sub><sup>2</sup> = <sup>n(n − 1)</sup>/<sub>2</sub>.', '<b>Неупорядоченные пары.</b> Выбрать 2 предмета из n без учёта порядка: C<sub>n</sub><sup>2</sup> = <sup>n(n − 1)</sup>/<sub>2</sub>.', '<b>Unordered pairs.</b> Choosing 2 of n objects where order does not matter: C<sub>n</sub><sup>2</sup> = <sup>n(n − 1)</sup>/<sub>2</sub>.')
    ] },
    { kind: 'history', h: L('Tarixdan: Bhaskaradan Paskal va Fermagacha', 'Из истории: от Бхаскары до Паскаля и Ферма', 'From history: from Bhaskara to Pascal and Fermat'), p: [
      L('Sanash masalalari qadim zamonlardan qiziqtirgan. XII asrda Bhaskara II «Lilavati»da shunday masala bergan: to‘rt qo‘lli Vishnu xudosi to‘rt qo‘lida to‘rt xil narsani (gurzi, chig‘anoq, lotus va disk) tutadi — nechta turli ko‘rinishi bor? Javob: 4! = 24. Pascal uchburchagi deb ataladigan sonlar jadvalini esa X–XI asrlarda fors matematigi al-Karajiy va keyinroq Umar Xayyom, XIII asrda xitoylik Yan Xuy bilishgan.',
        'Задачи на подсчёт интересовали людей с древности. В XII веке Бхаскара II в «Лилавати» предложил задачу: четырёхрукий бог Вишну держит в четырёх руках четыре разных предмета (булаву, раковину, лотос и диск) — сколько различных изображений возможно? Ответ: 4! = 24. Таблицу чисел, которую мы называем треугольником Паскаля, знали ещё в X–XI веках персидский математик аль-Караджи, позже Омар Хайям, а в XIII веке — китаец Ян Хуэй.',
        'Counting problems have fascinated people since ancient times. In the 12th century Bhaskara II asked in “Lilavati”: the four-armed god Vishnu holds four different objects (a mace, a conch, a lotus and a discus) in his four hands — how many different images are possible? Answer: 4! = 24. The table of numbers we call Pascal’s triangle was known in the 10th–11th centuries to the Persian mathematician al-Karaji, later to Omar Khayyam, and in the 13th century to the Chinese scholar Yang Hui.'),
      L('Kombinatorika va ehtimollar nazariyasi alohida fan sifatida 1654-yilda tug‘ildi. Fransuz zodagoni shevalye de Mere matematik Blez Paskalga savol berdi: agar ikki o‘yinchi o‘yinni oxiriga yetkazmasdan to‘xtatsa, tikilgan pulni qanday adolatli bo‘lish kerak? Paskal bu haqda Per Ferma bilan xat yozisha boshladi. Ular o‘yin qanday davom etishi mumkin bo‘lgan barcha variantlarni sanab chiqishdi va har bir o‘yinchining yutish imkoniyatini topishdi. Bu yozishmalar zamonaviy ehtimollar nazariyasining boshlanishi hisoblanadi.',
        'Комбинаторика и теория вероятностей как отдельная наука родились в 1654 году. Французский дворянин шевалье де Мере задал математику Блезу Паскалю вопрос: если двое игроков прервали игру, не доиграв, как справедливо разделить ставку? Паскаль начал переписку об этом с Пьером Ферма. Они перебрали все варианты возможного продолжения игры и нашли шансы каждого игрока на победу. Эта переписка считается началом современной теории вероятностей.',
        'Combinatorics and probability were born as a science in 1654. The French nobleman Chevalier de Méré asked the mathematician Blaise Pascal: if two players stop a game before it is finished, how should the stake be divided fairly? Pascal began a correspondence about it with Pierre de Fermat. They listed every way the game could have continued and found each player’s chance of winning. These letters are regarded as the beginning of modern probability theory.')
    ] },
    { kind: 'rule', h: L('Nega ko‘paytiramiz?', 'Почему умножаем?', 'Why do we multiply?'), p: [
      L('3 ta ko‘ylak (K<sub>1</sub>, K<sub>2</sub>, K<sub>3</sub>) va 4 ta shim (S<sub>1</sub>, …, S<sub>4</sub>) uchun jadval chizamiz: qatorlar — ko‘ylaklar, ustunlar — shimlar. Har bir katak bitta to‘plam. Jadvalda 3 ta qator va 4 ta ustun, demak, 3 · 4 = 12 katak. Ko‘paytirish qoidasi — aynan to‘g‘ri to‘rtburchak shaklidagi jadvaldagi kataklarni sanash.',
        'Для 3 рубашек (Р<sub>1</sub>, Р<sub>2</sub>, Р<sub>3</sub>) и 4 брюк (Б<sub>1</sub>, …, Б<sub>4</sub>) нарисуем таблицу: строки — рубашки, столбцы — брюки. Каждая клетка — один комплект. В таблице 3 строки и 4 столбца, значит, 3 · 4 = 12 клеток. Правило произведения — это и есть подсчёт клеток прямоугольной таблицы.',
        'For 3 shirts (S<sub>1</sub>, S<sub>2</sub>, S<sub>3</sub>) and 4 pairs of trousers (T<sub>1</sub>, …, T<sub>4</sub>) draw a table: rows for shirts, columns for trousers. Each cell is one outfit. There are 3 rows and 4 columns, so 3 · 4 = 12 cells. The multiplication rule is exactly counting the cells of a rectangular table.'),
      L('<b>n! formulasi.</b> n ta narsani n ta o‘ringa teramiz. Birinchi o‘ringa istalgan n tadan birini qo‘yish mumkin, ikkinchisiga — qolgan (n − 1) tadan birini, uchinchisiga — (n − 2) tadan va hokazo, oxirgisiga — qolgan yagona narsani. Ko‘paytirish qoidasi bo‘yicha n · (n − 1) · … · 2 · 1 = n!.',
        '<b>Формула n!.</b> Расставляем n предметов по n местам. На первое место можно поставить любой из n, на второе — любой из оставшихся (n − 1), на третье — из (n − 2) и т. д., на последнее — единственный оставшийся. По правилу произведения получаем n · (n − 1) · … · 2 · 1 = n!.',
        '<b>The n! formula.</b> Place n objects into n positions. The first position can take any of the n, the second any of the remaining (n − 1), the third any of (n − 2), and so on, and the last takes the only one left. By the multiplication rule this gives n · (n − 1) · … · 2 · 1 = n!.'),
      L('<b>Juftliklar formulasi.</b> n kishidan tartib bilan ikki kishini (masalan, sardor va o‘rinbosarni) n(n − 1) usulda tanlash mumkin. Agar tartib muhim bo‘lmasa (masalan, qo‘l berib ko‘rishish), har bir juftlik ikki marta sanalgan: (A, B) va (B, A). Shuning uchun 2 ga bo‘lamiz: <sup>n(n − 1)</sup>/<sub>2</sub>.',
        '<b>Формула пар.</b> Из n человек двоих с учётом порядка (например, старосту и заместителя) можно выбрать n(n − 1) способами. Если порядок неважен (например, рукопожатие), каждая пара посчитана дважды: (A, B) и (B, A). Поэтому делим на 2: <sup>n(n − 1)</sup>/<sub>2</sub>.',
        '<b>The pairs formula.</b> From n people, two can be chosen in order (say, a captain and a vice-captain) in n(n − 1) ways. If order does not matter (a handshake, for example), each pair has been counted twice: (A, B) and (B, A). So we divide by 2: <sup>n(n − 1)</sup>/<sub>2</sub>.')
    ] },
    { kind: 'steps', h: L('Variantlarni tanlash (sanab chiqish) usuli', 'Метод перебора вариантов', 'Listing options systematically'), list: [
      L('<b>1.</b> Har bir variant nimadan iborat ekanini aniqlang (masalan, «uch xonali son», «ko‘ylak + shim»).', '<b>1.</b> Определите, из чего состоит каждый вариант (например, «трёхзначное число», «рубашка + брюки»).', '<b>1.</b> Decide what each option consists of (e.g. “a three-digit number”, “shirt + trousers”).'),
      L('<b>2.</b> Tartib muhimmi yoki yo‘qmi, takrorlash mumkinmi yoki yo‘qmi — aniqlang.', '<b>2.</b> Выясните, важен ли порядок и допускаются ли повторения.', '<b>2.</b> Decide whether order matters and whether repeats are allowed.'),
      L('<b>3.</b> Variantlarni qat’iy tartibda yozing: lug‘atdagi kabi (alfavit yoki o‘sish tartibida) yoki <b>variantlar daraxti</b>ni chizing — har bir bosqichda shoxlar tanlovlarni bildiradi.', '<b>3.</b> Выписывайте варианты в строгом порядке — как в словаре (по алфавиту или по возрастанию), или нарисуйте <b>дерево вариантов</b>: на каждом шаге ветви означают возможные выборы.', '<b>3.</b> Write the options in a strict order — like a dictionary (alphabetically or increasing), or draw a <b>tree diagram</b> in which the branches at each stage are the possible choices.'),
      L('<b>4.</b> Daraxt barglari (oxirgi shoxlar) sonini sanang — bu javob. Ko‘paytirish qoidasi bilan tekshiring.', '<b>4.</b> Сосчитайте листья дерева (последние ветви) — это ответ. Проверьте правилом произведения.', '<b>4.</b> Count the leaves of the tree (the final branches) — that is the answer. Check it with the multiplication rule.'),
      L('<b>5.</b> Shartga mos kelmaydiganlarni (masalan, 0 bilan boshlanadigan «sonlar»ni) chiqarib tashlang.', '<b>5.</b> Исключите варианты, не подходящие по условию (например, «числа», начинающиеся с 0).', '<b>5.</b> Remove options that break the conditions (e.g. “numbers” starting with 0).')
    ] },
    { kind: 'example', h: L('Yechilgan misollar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('1, 2, 3 raqamlaridan, raqamlar takrorlanmaydigan, nechta uch xonali son tuzish mumkin? Ularni sanab chiqing.', 'Сколько трёхзначных чисел без повторения цифр можно составить из цифр 1, 2, 3? Выпишите их.', 'How many three-digit numbers with no repeated digits can be made from 1, 2, 3? List them.'), s: L('O‘sish tartibida: 123, 132, 213, 231, 312, 321 — jami 6 ta. Ko‘paytirish qoidasi: 3 · 2 · 1 = 3! = 6 ✓.', 'По возрастанию: 123, 132, 213, 231, 312, 321 — всего 6. По правилу произведения: 3 · 2 · 1 = 3! = 6 ✓.', 'In increasing order: 123, 132, 213, 231, 312, 321 — 6 in all. By the multiplication rule: 3 · 2 · 1 = 3! = 6 ✓.') },
      { q: L('Agar raqamlar takrorlanishi mumkin bo‘lsa-chi?', 'А если цифры могут повторяться?', 'And if digits may repeat?'), s: L('Har bir xonaga 3 ta raqamdan istalgani: 3 · 3 · 3 = 27 ta son (111, 112, …, 333).', 'В каждый разряд — любая из 3 цифр: 3 · 3 · 3 = 27 чисел (111, 112, …, 333).', 'Each place can take any of the 3 digits: 3 · 3 · 3 = 27 numbers (111, 112, …, 333).') },
      { q: L('Yugurishda 8 sportchi qatnashadi. Oltin, kumush va bronza medallar necha usulda taqsimlanishi mumkin?', 'В забеге 8 спортсменов. Сколькими способами можно распределить золото, серебро и бронзу?', 'Eight athletes run a race. In how many ways can gold, silver and bronze be awarded?'), s: L('Tartib muhim, takror yo‘q: A<sub>8</sub><sup>3</sup> = 8 · 7 · 6 = 336.', 'Порядок важен, повторов нет: A<sub>8</sub><sup>3</sup> = 8 · 7 · 6 = 336.', 'Order matters, no repeats: A<sub>8</sub><sup>3</sup> = 8 · 7 · 6 = 336.') },
      { q: L('5 kishi bir-biri bilan qo‘l berib ko‘rishdi. Necha marta qo‘l berildi?', '5 человек пожали друг другу руки. Сколько было рукопожатий?', 'Five people all shake hands with each other. How many handshakes?'), s: L('Tartib muhim emas: <sup>5 · 4</sup>/<sub>2</sub> = 10. Tekshirish (sanab chiqish): AB, AC, AD, AE, BC, BD, BE, CD, CE, DE — 10 ta ✓.', 'Порядок неважен: <sup>5 · 4</sup>/<sub>2</sub> = 10. Проверка перебором: AB, AC, AD, AE, BC, BD, BE, CD, CE, DE — 10 ✓.', 'Order does not matter: <sup>5 · 4</sup>/<sub>2</sub> = 10. Check by listing: AB, AC, AD, AE, BC, BD, BE, CD, CE, DE — 10 ✓.') },
      { q: L('0, 1, 2, 3 raqamlaridan raqamlari takrorlanmaydigan nechta ikki xonali son bor?', 'Сколько двузначных чисел с разными цифрами можно составить из цифр 0, 1, 2, 3?', 'How many two-digit numbers with different digits can be made from 0, 1, 2, 3?'), s: L('Birinchi raqam 0 bo‘lmaydi: 3 usul (1, 2, 3). Ikkinchisi — qolgan 3 raqamdan biri (endi 0 ham mumkin): 3 usul. Jami 3 · 3 = 9: 10, 12, 13, 20, 21, 23, 30, 31, 32.', 'Первая цифра не 0: 3 способа (1, 2, 3). Вторая — любая из оставшихся 3 (теперь и 0): 3 способа. Всего 3 · 3 = 9: 10, 12, 13, 20, 21, 23, 30, 31, 32.', 'The first digit cannot be 0: 3 ways (1, 2, 3). The second is any of the remaining 3 digits (0 is now allowed): 3 ways. Total 3 · 3 = 9: 10, 12, 13, 20, 21, 23, 30, 31, 32.') }
    ] },
    { kind: 'table', h: L('Faktoriallar jadvali', 'Таблица факториалов', 'Table of factorials'), p: [
      L('Faktorial juda tez o‘sadi: har bir keyingi qiymat oldingisini yangi songa ko‘paytirib topiladi, (n + 1)! = n! · (n + 1).', 'Факториал растёт очень быстро: каждое следующее значение получается умножением предыдущего на новое число, (n + 1)! = n! · (n + 1).', 'Factorials grow very fast: each value is the previous one times the next number, (n + 1)! = n! · (n + 1).')
    ], table: { head: [L('n', 'n', 'n'), L('n!', 'n!', 'n!'), L('Ma’nosi', 'Смысл', 'Meaning')], rows: [
      ['1', '1', L('bitta narsa — bitta tartib', 'один предмет — один порядок', 'one object — one order')],
      ['3', '6', L('3 kitobni javonga terish', 'расставить 3 книги', 'arranging 3 books')],
      ['4', '24', L('Vishnu masalasi (Bhaskara)', 'задача о Вишну (Бхаскара)', 'Vishnu problem (Bhaskara)')],
      ['5', '120', L('5 o‘quvchini qatorga turg‘izish', 'построить в ряд 5 учеников', 'lining up 5 pupils')],
      ['6', '720', L('6 ta mehmonni stolga o‘tqazish', 'рассадить 6 гостей', 'seating 6 guests')],
      ['8', '40320', L('8 o‘quvchini 8 ta stulga o‘tqazish', 'рассадить 8 учеников на 8 стульев', 'seating 8 pupils on 8 chairs')],
      ['10', '3628800', L('10 kitobni javonga terish', 'расставить 10 книг', 'arranging 10 books')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Ko‘paytirish o‘rniga qo‘shish.</b> 3 ko‘ylak va 4 shimdan to‘plamlar 3 + 4 = 7 emas, 3 · 4 = 12. «Va» — ko‘paytirish!', '<b>Складывать вместо умножения.</b> Комплектов из 3 рубашек и 4 брюк не 3 + 4 = 7, а 3 · 4 = 12. «И» — умножение!', '<b>Adding instead of multiplying.</b> Outfits from 3 shirts and 4 trousers number not 3 + 4 = 7 but 3 · 4 = 12. “And” means multiply!'),
      L('<b>Tartibni noto‘g‘ri hisobga olish.</b> Qo‘l berishlar uchun 5 · 4 = 20 — xato, har bir juftlik ikki marta sanalgan; to‘g‘risi 10. Medallar uchun esa tartib muhim va 2 ga bo‘linmaydi.', '<b>Неверно учесть порядок.</b> Для рукопожатий 5 · 4 = 20 — ошибка, каждая пара посчитана дважды; верно 10. А для медалей порядок важен, и делить на 2 не нужно.', '<b>Handling order wrongly.</b> For handshakes 5 · 4 = 20 is wrong — each pair is counted twice; the answer is 10. For medals, order does matter, so do not divide by 2.'),
      L('<b>Nol bilan boshlanadigan sonlarni sanash.</b> «012» ikki xonali son, uch xonali emas. Birinchi xonaga 0 qo‘yib bo‘lmaydi.', '<b>Считать числа, начинающиеся с нуля.</b> «012» — двузначное число, а не трёхзначное. Ноль нельзя ставить в первый разряд.', '<b>Counting numbers that start with zero.</b> “012” is a two-digit number, not a three-digit one. Zero cannot go in the first place.'),
      L('<b>Takrorlanish shartini e’tiborsiz qoldirish.</b> PIN-kodda raqamlar takrorlanishi mumkin (10<sup>4</sup> = 10 000), sinf sardori va o‘rinbosari esa bir odam bo‘lolmaydi (25 · 24).', '<b>Игнорировать условие о повторениях.</b> В PIN-коде цифры могут повторяться (10<sup>4</sup> = 10 000), а староста и заместитель не могут быть одним человеком (25 · 24).', '<b>Ignoring the repetition condition.</b> In a PIN digits may repeat (10<sup>4</sup> = 10,000), but a captain and vice-captain cannot be the same person (25 · 24).'),
      L('<b>Tartibsiz sanab chiqish.</b> Variantlarni tasodifiy yozsangiz, ba’zilarini ikki marta yozasiz yoki o‘tkazib yuborasiz. Har doim tizimli tartib yoki daraxtdan foydalaning.', '<b>Беспорядочный перебор.</b> Если выписывать варианты как попало, одни повторятся, другие пропадут. Всегда используйте систематический порядок или дерево.', '<b>Listing at random.</b> If you write options in no order, you will repeat some and miss others. Always use a systematic order or a tree.')
    ] },
    { kind: 'life', h: L('Kombinatorika hayotda', 'Комбинаторика в жизни', 'Combinatorics in everyday life'), p: [
      L('<b>Parollar va xavfsizlik.</b> 4 xonali raqamli PIN-kodning 10 000 varianti bor, 6 xonalisining — 1 000 000. Agar parolda 26 ta kichik lotin harfi va 10 raqam (jami 36 belgi) ishlatilsa, 8 belgili parollar soni 36<sup>8</sup> ≈ 2,8 trillion! Shuning uchun uzun va turli belgilardan iborat parol xavfsizroq.', '<b>Пароли и безопасность.</b> У 4-значного PIN-кода 10 000 вариантов, у 6-значного — 1 000 000. Если в пароле используются 26 строчных латинских букв и 10 цифр (всего 36 символов), то 8-символьных паролей 36<sup>8</sup> ≈ 2,8 триллиона! Поэтому длинный пароль из разных символов надёжнее.', '<b>Passwords and security.</b> A 4-digit PIN has 10,000 possibilities, a 6-digit one 1,000,000. If a password uses 26 lowercase Latin letters and 10 digits (36 symbols), there are 36<sup>8</sup> ≈ 2.8 trillion 8-character passwords! That is why a long password with varied symbols is safer.'),
      L('<b>Avtomobil raqamlari.</b> Davlat raqamlari harflar va raqamlar kombinatsiyasidan tuziladi. Raqamlar tizimini loyihalaganda, mamlakatdagi barcha avtomobillar uchun yetarli kombinatsiya bo‘lishi ko‘paytirish qoidasi bilan hisoblanadi.', '<b>Автомобильные номера.</b> Госномера составляются из комбинаций букв и цифр. При проектировании системы номеров правилом произведения проверяют, хватит ли комбинаций на все автомобили страны.', '<b>Car number plates.</b> Plates are made from combinations of letters and digits. When a numbering system is designed, the multiplication rule is used to check there are enough combinations for every car in the country.'),
      L('<b>Sport va menyu.</b> Turnir jadvalini tuzishda o‘yinlar soni <sup>n(n − 1)</sup>/<sub>2</sub> formulasi bilan topiladi. Oshxona menyusida 4 ta birinchi taom, 5 ta ikkinchi taom va 3 ta ichimlik bo‘lsa, 4 · 5 · 3 = 60 xil tushlik tanlash mumkin.', '<b>Спорт и меню.</b> При составлении расписания турнира число матчей находят по формуле <sup>n(n − 1)</sup>/<sub>2</sub>. Если в меню столовой 4 первых блюда, 5 вторых и 3 напитка, можно выбрать 4 · 5 · 3 = 60 разных обедов.', '<b>Sport and menus.</b> When drawing up a tournament schedule, the number of matches comes from <sup>n(n − 1)</sup>/<sub>2</sub>. If a canteen offers 4 starters, 5 main courses and 3 drinks, you can choose 4 · 5 · 3 = 60 different lunches.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('52 ta o‘yin kartasini aralashtirish usullari soni 52! ≈ 8 · 10<sup>67</sup>. Bu shunchalik katta sonki, yaxshi aralashtirilgan har bir dasta, ehtimol, tarixda hech qachon takrorlanmagan.', 'Число способов перетасовать колоду из 52 карт — 52! ≈ 8 · 10<sup>67</sup>. Это так много, что каждая хорошо перетасованная колода, скорее всего, никогда в истории не повторялась.', 'The number of ways to shuffle a 52-card deck is 52! ≈ 8 · 10<sup>67</sup>. It is so huge that every well-shuffled deck has very likely never occurred before in history.'),
      L('Rubik kubigining turli holatlari soni taxminan 43 kvintillion (4,3 · 10<sup>19</sup>), ammo istalgan holatdan uni 20 ta harakatdan ko‘p bo‘lmagan holda yig‘ish mumkinligi 2010-yilda isbotlangan.', 'У кубика Рубика около 43 квинтиллионов (4,3 · 10<sup>19</sup>) различных положений, но в 2010 году доказали, что из любого положения его можно собрать не более чем за 20 ходов.', 'A Rubik’s cube has about 43 quintillion (4.3 · 10<sup>19</sup>) positions, yet in 2010 it was proved that any position can be solved in at most 20 moves.'),
      L('«!» belgisini faktorial uchun 1808-yilda fransuz matematigi Kristian Kramp taklif qilgan.', 'Знак «!» для факториала предложил в 1808 году французский математик Кристиан Крамп.', 'The “!” sign for factorial was proposed in 1808 by the French mathematician Christian Kramp.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверь себя', 'Try it yourself'), ex: [
      { q: L('4! = ?', '4! = ?', '4! = ?'), s: L('1 · 2 · 3 · 4 = 24.', '1 · 2 · 3 · 4 = 24.', '1 · 2 · 3 · 4 = 24.') },
      { q: L('25 o‘quvchidan sardor va o‘rinbosarni necha usulda tanlash mumkin?', 'Сколькими способами можно выбрать из 25 учеников старосту и заместителя?', 'In how many ways can a captain and vice-captain be chosen from 25 pupils?'), s: L('Tartib muhim: 25 · 24 = 600.', 'Порядок важен: 25 · 24 = 600.', 'Order matters: 25 · 24 = 600.') },
      { q: L('Futbol turnirida 6 jamoa bir-biri bilan bir martadan o‘ynaydi. Nechta o‘yin?', 'В футбольном турнире 6 команд играют друг с другом по разу. Сколько матчей?', 'Six teams in a football tournament each play each other once. How many matches?'), s: L('<sup>6 · 5</sup>/<sub>2</sub> = 15.', '<sup>6 · 5</sup>/<sub>2</sub> = 15.', '<sup>6 · 5</sup>/<sub>2</sub> = 15.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ko‘paytirish qoidasi: m usul «va» n usul — m · n usul.', 'Правило произведения: m способов «и» n способов — m · n способов.', 'Multiplication rule: m ways “and” n ways gives m · n ways.'),
      L('Qo‘shish qoidasi: m usul «yoki» n usul (kesishmasa) — m + n usul.', 'Правило суммы: m способов «или» n способов (без пересечения) — m + n способов.', 'Addition rule: m ways “or” n ways (no overlap) gives m + n ways.'),
      L('n ta narsani qatorga terish: n! = 1 · 2 · … · n.', 'Расстановка n предметов в ряд: n! = 1 · 2 · … · n.', 'Arranging n objects in a row: n! = 1 · 2 · … · n.'),
      L('n tadan k tasini tartib bilan: n(n − 1)…(n − k + 1); tartibsiz juftliklar: n(n − 1) : 2.', 'k из n с порядком: n(n − 1)…(n − k + 1); пары без порядка: n(n − 1) : 2.', 'k of n in order: n(n − 1)…(n − k + 1); unordered pairs: n(n − 1) : 2.'),
      L('Kichik masalalarda variantlarni tartibli ro‘yxat yoki daraxt bilan sanab chiqing.', 'В небольших задачах перебирайте варианты упорядоченным списком или деревом.', 'In small problems, list the options with an ordered list or a tree.'),
      L('Kombinatorika fan sifatida 1654-yilda Paskal va Ferma yozishmalarida shakllangan.', 'Как наука комбинаторика сложилась в переписке Паскаля и Ферма в 1654 году.', 'Combinatorics took shape as a science in the 1654 letters of Pascal and Fermat.')
    ] }
  ] });
})(this);
